def test_repair() -> None:
    """Почти расслышанное слово команды чинится по словарю.

    С живого робота: «поставь будильник на 18 часов» приехало как «поставь
    ВОДИЛЬНИК на 18 часов». Правило мимо такого прошло, фраза уехала модели,
    та честно поставила будильник с названием «водильник», и робот объявил
    «Водильник поставлен на восемнадцать часов». Уверенность распознавания
    при этом была хорошая, -0.39, — то есть барьером такое не ловится.

    Приём подсмотрен у Home Assistant с его speech-to-phrase и у Алисы с её
    классификаторами: вопрос не «что человек сказал», а «на какую из фраз,
    которые я умею, это похоже». Мы делаем то же по словам.
    """
    section("починка почти расслышанных команд")
    from robot_voice.intents import repair

    check("водильник", repair("поставь водильник на 18 часов"),
          "поставь будильник на 18 часов")
    check("таймир", repair("поставь таймир на 5 минут"),
          "поставь таймер на 5 минут")
    check("постав", repair("постав будильник"), "поставь будильник")

    m = parse("поставь водильник на 18 часов")
    check("починенное доезжает до правила", m.tool if m else None, "set_alarm")

    # А вот чего чинить нельзя.
    check("короткое слово не трогаем", repair("что там со следом"),
          "что там со следом")
    check("двусмысленное не трогаем", repair("астанови таймер"), "астанови таймер")
    check("чужие слова целы", repair("добавь в список сгущенку"),
          "добавь в список сгущенку")
    # Главное: у «напомни» и «добавь» внутри едет речь человека, и первый
    # заход разбора обязан отработать до всякой починки.
    m = parse("напомни завтра в восемь позвонить в поликлинику")
    check("текст напоминания не тронут", m.args["text"] if m else None,
          "позвонить в поликлинику")
    m = parse("добавь в список сгущенку")
    check("пункт списка не тронут", m.args["item"] if m else None, "сгущенку")


def test_looped() -> None:
    """Зацикленный бред не должен доходить до модели.

    На живом роботе пришло «Ууууу…» на двести двадцать знаков — с ВЫСОКОЙ
    уверенностью (−0.07), поэтому барьер по уверенности его пропустил. Дальше
    мусор ушёл в языковую модель, та выдала восемь тысяч токенов, робот молчал
    полминуты и потерял две тысячи кадров звука. Одна мусорная фраза выводила
    его из строя.
    """
    from robot_voice.stt import зациклилось

    section("зацикливание распознавания")
    for текст, ждём, имя in (
        ("У" * 220, True, "петля из живого лога"),
        ("сантиметров, " * 30, True, "повтор подсказки"),
        ("а" * 60, True, "одна буква до упора"),
        ("х" * 45 + " вперёд", True, "склеенное слово"),
        # А это настоящая речь, и терять её нельзя.
        ("Кузя, привет!", False, "обычная фраза"),
        ("Ммм, дай подумать", False, "мычание"),
        ("Ааа, понял!", False, "восклицание"),
        ("стоп стоп стоп", False, "повтор слова — так и говорят"),
        ("нет нет нет", False, "и ещё один"),
        ("Кузя, проедь вперёд два метра и потом развернись налево",
         False, "длинная команда целиком"),
        ("", False, "пусто"),
    ):
        check(f"«{имя}»", зациклилось(текст), ждём)


def test_made_up() -> None:
    """Заученные концовки роликов — это не речь, а память Whisper.

    С живого робота за один вечер: «Спасибо за внимание!», «С вами был Игорь
    Негода», причём с приличной уверенностью -0.73 и -0.91. Робот отвечал на
    них вслух — то есть разговаривал с холодильником. Барьером уверенности
    такое не ловится: модель не сомневается, она вспоминает субтитры, на
    которых её учили.
    """
    section("выдумки Whisper на тишине")
    from robot_voice.stt import made_up

    for phrase in ["Спасибо за внимание!", "С вами был Игорь Негода.",
                   "Продолжение следует...", "Субтитры сделал DimaTorzok",
                   "спасибо за внимание"]:
        check(f"«{phrase}» — выдумка", made_up(phrase), True)
    # А это живая речь, и глушить её нельзя.
    for phrase in ["Спасибо!", "Спасибо, Кузя", "Продолжи таймер",
                   "Кузя, вперёд", "с вами всё хорошо?"]:
        check(f"«{phrase}» — речь", made_up(phrase), False)


def test_speakable() -> None:
    """Смайлики голосом не передать, и читать их вслух не надо.

    Модель ставит их охотно. На живом роботе целым предложением вышло одно
    «😄» — Кузя честно попытался его произнести.
    """
    section("картинки не звучат")
    from robot_voice.tts import speakable

    check("один смайлик", speakable("😄"), "")
    check("смайлик в конце", speakable("Пожалуйста! 😊"), "Пожалуйста!")
    check("смайлик посреди", speakable("Всё хорошо 👍 правда"), "Всё хорошо правда")
    check("обычную речь не трогаем", speakable("Привет, Игорь!"), "Привет, Игорь!")
    # --- цифры вслух ------------------------------------------------------
    # Инструменты и так проговаривают числа словами. Но между инструментом и
    # динамиком стоит МОДЕЛЬ, и она пересказывает результат по-своему:
    #
    #     вызываю weather({'day': 'сейчас'})
    #     робот: В Калининграде сейчас 16 градусов, ясно, ветер 11 м/с.
    #
    # Синтез на цифрах спотыкается, и человек слышит пропущенную цифру —
    # ровно эта жалоба и пришла с живого робота.
    check("часы читаются часами, а не двоеточием",
          speakable("Сейчас 19:12 — время ужина"),
          "Сейчас девятнадцать часов двенадцать минут — время ужина")
    check("ровный час — без минут",
          speakable("Будильник на 7:00"), "Будильник на семь часов")
    check("градусы и метры в секунду",
          speakable("Сейчас 16 градусов, ветер 11 м/с."),
          "Сейчас шестнадцать градусов, ветер одиннадцать метров в секунду.")
    # Единица обязана согласоваться с числом: «23 градусА», не «градусОВ».
    # Слышно сразу, и звучит как речь иностранца.
    check("единица согласована с числом",
          speakable("Сейчас 23 °C, вчера был 21 °C, позавчера 1 °C."),
          "Сейчас двадцать три градуса, вчера был двадцать один градус, "
          "позавчера один градус.")
    check("проценты тоже", speakable("Заряд 85%."), "Заряд восемьдесят пять процентов.")
    check("дробь читается как вольты у батареи",
          speakable("около 0,4 метра"), "около ноль и четыре метра")
    check("минус не теряется", speakable("минус 3 градуса"), "минус три градуса")
    # Большое число cardinal не умеет и честно оставляет цифрами: сказать
    # «две тысячи двадцать шестой» мы не можем, а испортить — легко.
    check("год оставлен цифрами",
          speakable("Дом 2026 года"), "Дом 2026 года")


def test_people() -> None:
    """Личное дело: робот должен помнить, с кем говорит, и уметь забыть.

    Разделение труда с ПК: слепки голосов там, где считаются, — на
    компьютере. Дела здесь, потому что нужны в разговоре и тогда, когда
    компьютер выключен.
    """
    section("личные дела")
    from robot_voice.people import FACTS_LIMIT, People

    store = Path(tempfile.mkdtemp()) / "люди.json"
    people = People(store)

    check("не узнан — запоминать некому", people.remember("", "любит чай"),
          "Я пока не знаю, кто ты. Скажи «запомни мой голос».")
    check("запомнили", people.remember("Игорь", "любит крепкий чай"), "Запомнил.")
    check("дубль не копим", people.remember("Игорь", "Любит крепкий чай"),
          "Это я уже про тебя знаю.")
    people.met("Игорь")
    check("встречу отметили", people.card("Игорь")["разговоров"], 1)

    check("справка для модели", people.brief("Игорь"),
          "Сейчас с тобой говорит Игорь. Что ты о нём знаешь: любит крепкий чай.")
    check("незнакомцу справки нет", people.brief(""), "")
    check("вслух", people.tell("Игорь"),
          "Про тебя знаю вот что. Любит крепкий чай.")

    check("пережило перезапуск", People(store).card("Игорь")["разговоров"], 1)
    check("стёрли", people.forget("Игорь"), "Всё стёр.")
    check("и правда стёрли", People(store).known(), [])


def test_notes_about_people() -> None:
    """Конспект: робот дописывает дело сам, но поручения этим не вытесняет.

    Человек не диктует роботу анкету — он просто разговаривает. Значит,
    подмечать надо самому. Но у таких заметок два свойства: они врут чаще и
    накапливаются быстрее, поэтому вытесняться должны первыми, а объявлять о
    них вслух не надо вовсе — иначе каждая реплика кончается «записал».
    """
    section("робот ведёт конспект сам")
    from robot_voice.people import FACTS_LIMIT, People

    store = Path(tempfile.mkdtemp()) / "люди.json"
    people = People(store)

    check("подмеченное не объявляется вслух",
          people.remember("Игорь", "работает по ночам", asked=False),
          "Записал в память, вслух не говори.")
    check("по просьбе — объявляется",
          people.remember("Игорь", "любит крепкий чай"), "Запомнил.")
    check("обрывок не записываем",
          people.remember("Игорь", "ага", asked=False), "Слишком коротко, не записал.")
    check("незнакомца не записываем",
          people.remember("", "что-то важное", asked=False),
          "Не знаю, кто говорит — записывать некуда.")

    # Повтор своими словами — не новая запись. Но если формулировка подробнее,
    # берём её: робот вернулся к теме и уточнил.
    check("тот же факт другими словами",
          people.remember("Игорь", "чай крепкий любит", asked=False),
          "Это я уже про тебя знаю.")
    check("подробность дописалась",
          people.remember("Игорь", "любит крепкий чай по утрам", asked=False),
          "Это я уже про тебя знаю.")
    check("и заменила прежнее", "любит крепкий чай по утрам" in people.facts("Игорь"),
          True)
    # А вот это — РАЗНОЕ, хоть и похоже на восемьдесят процентов букв. Слить их
    # в одну запись значит потерять то, ради чего дело и заводилось.
    people.remember("Игорь", "любит кофе", asked=False)
    check("похожее, но другое — отдельно", len(people.facts("Игорь")), 3)

    # Просьба запомнить то, что робот уже подметил сам, превращает заметку в
    # поручение: вытеснять её больше нельзя.
    people.remember("Игорь", "работает по ночам")
    подмеченных = [f for f in people.card("Игорь")["факты"] if f.get("сам")]
    check("просьба закрепила заметку",
          any(f["что"] == "работает по ночам" for f in подмеченных), False)

    # Дело не растёт без предела — оно уезжает в каждый запрос. И вытесняется
    # сначала подмеченное, а не то, что человек просил запомнить.
    for i in range(FACTS_LIMIT + 5):
        people.remember("Игорь", f"подметил мелочь про случай {i}", asked=False)
    check("дело не растёт без предела",
          len(people.card("Игорь")["факты"]), FACTS_LIMIT)
    check("поручение уцелело", "работает по ночам" in people.facts("Игорь"), True)
    check("и уточнённое поручение тоже",
          "любит крепкий чай по утрам" in people.facts("Игорь"), True)
    # А подмеченное «любит кофе» вытеснено — и правильно: это была догадка
    # робота, а не просьба человека.
    check("догадка уступила место", "любит кофе" in people.facts("Игорь"), False)

    # Старый формат — простые строки. Дело человека терять из-за смены формата
    # нельзя: там записи, которые он роботу диктовал.
    store.write_text('{"Настя": {"факты": ["любит гулять"], "разговоров": 3}}', "utf-8")
    старое = People(store)
    check("старое дело читается", старое.facts("Настя"), ["любит гулять"])
    старое.remember("Настя", "учится в институте", asked=False)
    check("и дополняется", старое.facts("Настя"),
          ["любит гулять", "учится в институте"])


def test_meeting() -> None:
    """Знакомство без обряда: имя со слуха и команды про самого человека."""
    section("знакомство")
    from robot_voice.app import _person_name

    for phrase, name in [("меня зовут Игорь", "Игорь"), ("я Игорь", "Игорь"),
                         ("Игорь", "Игорь"), ("это Настя", "Настя"),
                         ("Игорь Петрович", "Игорь")]:
        check(f"«{phrase}»", _person_name(phrase), name)
    # А это не имена. «меНЯ зовут» когда-то давало «Зовут» — границы слов важны.
    for phrase in ["ладно", "не скажу", "а я не скажу тебе имя вовсе никогда", ""]:
        check(f"«{phrase}» — не имя", _person_name(phrase), "")

    # Команда — не знакомство. «вперёд проедь на метр» это ровно четыре слова,
    # под ограничение длины не попадало, и первое слово уходило в имя: на живом
    # роботе человек стал зваться «Вперёд», а поездка не состоялась. Фраза
    # должна уйти дальше по конвейеру и выполниться.
    from robot_voice.app import Meeting
    встреча = Meeting("")
    встреча.asking = True
    сказано: list[str] = []
    голос = types.SimpleNamespace(say=lambda t, **kw: сказано.append(t))
    check("команду вместо имени не принимаем",
          встреча.name_is("вперёд проедь на метр", "голос 2", голос, None), False)
    check("и молча — переспрашивать тут нечего", сказано, [])
    встреча.asking = True
    check("а настоящее имя принимаем",
          встреча.name_is("меня зовут Настя", "голос 2", голос,
                          types.SimpleNamespace(rename=lambda *a: None)), True)

    # Команды про самого человека разбираются правилами, а не моделью: «забудь
    # про меня» должно стирать дело, а не отвечать «хорошо, забыл». И правила
    # обязаны переживать пунктуацию Whisper: на живом роботе «запомни, мой
    # голос» не сработало, робот спросил модель, и та заявила, что голоса
    # запоминать не умеет.
    from robot_voice.app import (_FORGET_ME, _KNOW_ME, _MY_NAME, _REMEMBER,
                                 _WHAT_ABOUT_ME, _WHO_AM_I, _bare)

    def бьётся(rule, phrase: str) -> bool:
        return bool(rule.match(_bare(phrase)))

    for phrase in ["запомни мой голос", "запомни, мой голос", "запомнишь мой голос",
                   "давай знакомиться", "познакомимся", "узнавай меня"]:
        check(f"«{phrase}» — знакомство", бьётся(_KNOW_ME, phrase), True)
    for phrase in ["кто я", "кто я?", "ты меня узнал?", "узнаешь меня"]:
        check(f"«{phrase}» — кто я", бьётся(_WHO_AM_I, phrase), True)
    for phrase in ["что ты обо мне знаешь?", "что ты помнишь", "— Что ты знаешь обо мне?"]:
        check(f"«{phrase}» — что знаешь", бьётся(_WHAT_ABOUT_ME, phrase), True)
    check("забудь про меня", бьётся(_FORGET_ME, "забудь про меня"), True)
    check("сотри моё дело", бьётся(_FORGET_ME, "сотри моё дело"), True)
    check("запомни, что я люблю чай",
          _REMEMBER.match(_bare("запомни, что я люблю чай")).group(1), "я люблю чай")
    check("меня зовут Игорь", бьётся(_MY_NAME, "меня зовут Игорь"), True)
    # И чего эти правила ловить не должны.
    check("«забудь» одно — это не про меня", бьётся(_FORGET_ME, "забудь"), False)
    check("«кто ты» — не «кто я»", бьётся(_WHO_AM_I, "кто ты"), False)


def test_auto_meeting() -> None:
    """Голос заводится сам, имя приходит потом — и архив едет за ним.

    Обряд знакомства («скажи три фразы») выкинут: на живом роботе он не
    сработал ни разу, а по существу лишний — людям не приходит в голову
    представляться пылесосу. Гость приходит, разговаривает, робот заводит на
    него дело под кличкой и копит заметки. Назвался — кличка стала именем
    вместе со всем архивом. Не назвался — и ладно.
    """
    section("голос заводится сам")
    from robot_voice.app import Meeting
    from robot_voice.people import People

    # Отложенное имя не должно сгорать, когда отправить его нечем. Метка
    # пуста в трёх штатных случаях (мгновенный приказ, спящий ПК, выключенное
    # узнавание голоса) — и раньше поле обнулялось ДО проверки, то есть имя
    # пропадало навсегда, а человеку заводилось второе дело.
    отложено = Meeting("")
    отложено._name_next = "Игорь"
    отложено.confirm("")
    check("имя пережило фразу без метки", отложено._name_next, "Игорь")

    store = Path(tempfile.mkdtemp()) / "люди.json"
    people = People(store)

    # Гость поговорил, робот записал за ним пару наблюдений — ещё не зная имени.
    people.met("голос 1")
    people.remember("голос 1", "приехал из Москвы", asked=False)
    check("безымянного видно", people.nameless("голос 1"), True)
    check("модель понимает, что имени нет", people.brief("голос 1"),
          "Ты узнаёшь этот голос, но имени не знаешь. "
          "Что ты о нём знаешь: приехал из Москвы.")

    # Назвался — архив переезжает целиком.
    people.rename("голос 1", "Настя")
    check("кличка исчезла", "голос 1" in people.cards, False)
    check("заметки уцелели", people.facts("Настя"), ["приехал из Москвы"])
    check("и счётчик встреч", people.card("Настя")["разговоров"], 1)
    check("теперь с именем", people.nameless("Настя"), False)

    # Если под именем уже было дело, два сливаются, ничего не теряя.
    people.remember("Настя", "любит чай")
    people.met("голос 7")
    people.remember("голос 7", "работает в школе", asked=False)
    people.rename("голос 7", "Настя")
    check("дела слились", sorted(people.facts("Настя")),
          ["любит чай", "приехал из Москвы", "работает в школе"])
    check("встречи сложились", people.card("Настя")["разговоров"], 2)

    # Робот спрашивает имя один раз и не раньше третьего разговора: раньше
    # навязчиво, позже глупо — человек уже всё рассказал.
    meeting = Meeting("")
    people.met("голос 9")
    check("после первого разговора молчим",
          meeting.time_to_ask("голос 9", people), False)
    people.met("голос 9")
    people.met("голос 9")
    check("после третьего спрашиваем",
          meeting.time_to_ask("голос 9", people), True)
    meeting.asking = True
    check("пока спрашиваем — второй раз не лезем",
          meeting.time_to_ask("голос 9", people), False)
    # У кого имя есть, того не переспрашиваем никогда.
    for _ in range(5):
        people.met("Настя")
    check("названного не переспрашиваем",
          Meeting("").time_to_ask("Настя", people), False)


def test_ascii_out() -> None:
    """В заголовках и адресах запросов не должно быть кириллицы.

    Дважды на одни грабли. Сначала имя человека в адресе — «?имя=Игорь», — и
    знакомство падало молча: робот говорил «не вышло запомнить голос», а
    запрос не уходил вовсе. Потом кириллица в User-Agent, и курс валют
    отвечал «сервис не ответил», хотя до сервиса дело не доходило.

    Причина одна: строку запроса и заголовки HTTP кодирует в latin-1, и любая
    русская буква роняет отправку. Ошибка при этом маскируется под отказ
    чужого сервиса — то есть ищут её не там.
    """
    section("наружу — только латиница")
    import ast
    import re

    here = Path(__file__).resolve().parent
    files = sorted((here / "robot_voice").glob("*.py"))
    плохие: list[str] = []
    for path in files:
        дерево = ast.parse(path.read_text(), str(path))
        # Постоянные модуля: значение заголовка чаще пишут через имя, а не
        # строкой на месте. Ровно так и было с User-Agent, из-за чего первая
        # версия этой проверки ничего не нашла.
        постоянные = {
            цель.id: узел.value.value
            for узел in дерево.body
            if isinstance(узел, ast.Assign) and isinstance(узел.value, ast.Constant)
            and isinstance(узел.value.value, str)
            for цель in узел.targets if isinstance(цель, ast.Name)
        }

        def строкой(узел):
            """Значение узла, если это строка или имя известной постоянной."""
            if isinstance(узел, ast.Constant) and isinstance(узел.value, str):
                return узел.value
            if isinstance(узел, ast.Name):
                return постоянные.get(узел.id)
            return None

        for узел in ast.walk(дерево):
            # Заголовки: {"User-Agent": ...} и любые другие пары в headers.
            if isinstance(узел, ast.Dict):
                for ключ, значение in zip(узел.keys, узел.values):
                    имя = строкой(ключ)
                    если = строкой(значение)
                    if имя is None or если is None:
                        continue
                    if "-" not in имя or " " in имя:
                        continue        # это не заголовок, а обычный словарь
                    # Имя заголовка всегда латиницей — так устроен HTTP. Ключ
                    # с кириллицей это обычные данные: «лос-анджелес» в списке
                    # часовых поясов дефис имеет, а заголовком не является.
                    if not имя.isascii():
                        continue
                    пара = f"{имя}: {если}"
                    if not пара.isascii():
                        плохие.append(f"{path.name}: заголовок {пара!r}")
            # Куски адресов: «?имя=» и «&name=». Регулярки и строки документации
            # сюда попадать не должны, поэтому требуем именно вид параметра
            # сразу за знаком вопроса и запрещаем всё, чем пишут шаблоны.
            if isinstance(узел, ast.Constant) and isinstance(узел.value, str):
                текст = узел.value
                похоже = re.search(r"[?&][^\s?&=]+=", текст)
                шаблон = "(?" in текст or "\\" in текст or len(текст) > 200
                if похоже and not шаблон and not текст.isascii():
                    плохие.append(f"{path.name}: адрес {текст!r}")
    check("кириллицы в заголовках и адресах нет", sorted(set(плохие)), [])


def test_wake_word() -> None:
    """Имя робота Whisper пишет как попало — ловить надо все варианты.

    С живого робота за один вечер: «Хузя», «Куля», «Куся», «Культа». Половина
    обращений проходила мимо, и человек повторял всё громче. Порог измерен на
    этих самых вариантах: они дают 0.75, а обычные слова — не выше 0.67.
    Между ними чистый зазор, по нему и режем.
    """
    section("варианты имени")
    from robot_voice.app import _strip_wake_word

    имена = ("кузя", "кузь", "куся", "кузи", "кузьма")
    порог = Config().wake_ratio
    for phrase in ["Кузя, привет", "Хузя, привет", "Куля, привет",
                   "Куся, привет", "Гузя, привет"]:
        check(f"«{phrase}» — это ко мне",
              _strip_wake_word(phrase, имена, порог), "привет")
    # А это обычные слова, и робот не должен на них просыпаться.
    for phrase in ["куда мне идти", "коля пришёл", "кухня большая",
                   "кузов машины", "пуля просвистела", "муза пришла"]:
        check(f"«{phrase}» — не имя", _strip_wake_word(phrase, имена, порог), None)

    # Кусок, нарезанный по длине: двадцать секунд комнаты, где обращение может
    # стоять в самом конце. Правило трёх слов писалось для реплик и здесь
    # только мешает — человек звал, а робот молчал.
    комната = ("шорты вон там лежат футболку одень а зачем ну скажи ей "
               "одеться кузя поезжай вперёд")
    check("в срезе комнаты имя ищется до конца",
          _strip_wake_word(комната, имена, порог, anywhere=True),
          "поезжай вперёд")
    check("а по обычному правилу — не находится",
          _strip_wake_word(комната, имена, порог), None)
    check("нет имени — нет обращения",
          _strip_wake_word("мама рядом стоит я сказала нет",
                           имена, порог, anywhere=True), None)
    # Имя услышано звуком, а распознавание написало его неузнаваемо. Запись
    # начинается на самом имени, значит первое слово — это оно. С живого
    # робота: «Кузя, включи музыку» приехало как «Друзья, включи музыку», и
    # правило про музыку из-за лишнего слова не сработало.
    from robot_voice.app import _без_обращения
    check("искажённое имя снимается", _без_обращения("Друзья, включи музыку."),
          "включи музыку")
    check("и настоящее тоже", _без_обращения("Кузя, включи музыку."),
          "включи музыку")
    check("без запятой не трогаем", _без_обращения("вперёд на метр"),
          "вперёд на метр")
    check("одно слово не съедаем", _без_обращения("стоп"), "стоп")

    check("имя последним словом — команда пустая",
          _strip_wake_word("что вы меня спрашиваете кузя",
                           имена, порог, anywhere=True), "")

    # С живого робота: два предложения слиплись в одно распознавание, имя
    # оказалось шестым словом — и обращение ушло в «не мне». Правило трёх слов
    # должно считаться от начала КАЖДОГО предложения.
    check("имя во втором предложении — это ко мне",
          _strip_wake_word("Сойдите, пожалуйста, с кровати, Арина. Кузя, привет.",
                           имена, порог),
          "привет")
    # Человек зовёт несколько раз подряд, не дождавшись ответа. Настоящее
    # обращение — свежее: первое робот уже проспал.
    check("из нескольких обращений берётся последнее",
          _strip_wake_word("Кузя, сделай звук на пять. Кузя, включи музыку.",
                           имена, порог),
          "включи музыку")
    check("упоминание в середине предложения — не обращение",
          _strip_wake_word("вчера мы с тобой и кузя ходили гулять", имена, порог),
          None)

    # Голое «Кузя!» отдельным предложением: просьба идёт СЛЕДОМ, а не внутри.
    # С живого робота — робот отвечал «Да?» и терял и музыку, и зигзаг.
    check("голое имя — команда берётся из следующего предложения",
          _strip_wake_word("Кузя! Включи музыку.", имена, порог),
          "Включи музыку")
    check("и в срезе комнаты тоже",
          _strip_wake_word("Кузя, а сделай зигзаг. Кузя! Сделай зигзаг.",
                           имена, порог),
          "Сделай зигзаг")
    check("одно только имя — это переспрос, а не команда",
          _strip_wake_word("Кузя!", имена, порог), "")


def test_not_for_me() -> None:
    """В открытом окне робот не должен вступать в чужой разговор.

    С живого робота: после «Кузя, привет» окно оставалось открытым двадцать
    секунд, и в него попало «Иди уже, Рома! Рома, пиши!» и «Виктор, как дела
    у тебя?» — телевизор и разговор с другим человеком. Робот честно ответил
    обоим. Отличить чужую речь от своей по звуку мы не умеем, но обращение по
    чужому имени — признак надёжный и дешёвый.
    """
    section("зовут не меня")
    from robot_voice.app import _NOT_A_NAME, _VOCATIVE, _clean_token

    def чужое(text: str) -> bool:
        m = _VOCATIVE.match(text.strip())
        return bool(m) and _clean_token(m.group(1)) not in _NOT_A_NAME

    for phrase in ["Виктор, как дела у тебя?", "Рома, пиши!",
                   "Наташа, ты идёшь?", "Серёжа, где ключи"]:
        check(f"«{phrase}» — не мне", чужое(phrase), True)
    # А это фразы, которые начинаются похоже, но обращены к роботу.
    for phrase in ["Ладно, поехали", "Хорошо, поставь таймер", "Так, что там",
                   "Стоп, стоп", "Погоди, не надо", "Спасибо, всё",
                   "поставь таймер на пять минут", "Сколько времени?"]:
        check(f"«{phrase}» — мне", чужое(phrase), False)


def test_remote_voice() -> None:
    """Голос берём с ПК, но немым от его выключения не становимся.

    Синтез уехал на ПК ради двух вещей: там silero вместо piper — с
    ударениями, омографами и вопросительной интонацией, — и там он считается
    в разы быстрее, чем на Cortex-A55 робота. Но ПК выключают, и тогда робот
    обязан договорить своим голосом, а не замолчать посреди фразы.
    """
    section("голос с ПК и отступление на свой")
    import http.server
    import io
    import threading as thr
    import wave

    from robot_voice.tts import RemoteVoice, _as_wav

    просили: list[dict] = []

    class Ответчик(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            body = json.loads(self.rfile.read(
                int(self.headers.get("Content-Length") or 0)))
            просили.append(body)
            if body.get("text") == "молчу":
                self.send_response(500)
                self.end_headers()
                return
            wav = _as_wav(b"\x00\x01" * 240, 24000)
            self.send_response(200)
            self.send_header("Content-Type", "audio/wav")
            self.send_header("Content-Length", str(len(wav)))
            self.end_headers()
            self.wfile.write(wav)

        def log_message(self, *a):
            pass

    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Ответчик)
    thr.Thread(target=srv.serve_forever, daemon=True).start()
    url = f"http://127.0.0.1:{srv.server_address[1]}"
    try:
        store = Path(tempfile.mkdtemp())
        voice = RemoteVoice(url, "eugene", PhraseCache(store, "пк"))
        pcm = voice.raw("Привет!")
        check("звук пришёл", len(pcm), 480)
        check("частота с ПК", voice.rate, 24000)
        check("голос попросили", просили[-1], {"text": "Привет!", "voice": "eugene"})

        # Второй раз ту же фразу у ПК не спрашиваем: она уже на диске.
        было = len(просили)
        check("из кэша", voice.raw("Привет!"), pcm)
        check("ПК не тревожили", len(просили), было)

        # ПК ответил отказом — робот отступает и час туда не ходит, иначе
        # каждая фраза начиналась бы с ожидания мёртвого сервера.
        check("отказ — говорим сами", voice.raw("молчу"), None)
        check("и больше не стучимся", voice.alive(), False)

        # Выключенный ПК — то же самое, но без ответа вовсе.
        мёртвый = RemoteVoice("http://127.0.0.1:1", "eugene")
        check("выключенный ПК", мёртвый.raw("Привет!"), None)

        # Заголовок, который мы шлём пульту, должен быть настоящим wav.
        with wave.open(io.BytesIO(_as_wav(pcm, voice.rate))) as w:
            check("пульту уходит верная частота", w.getframerate(), 24000)
    finally:
        srv.shutdown()


def test_unsure_does_not_drive() -> None:
    """Неуверенно расслышанная фраза не должна двигать робота.

    На живом роботе whisper услышал «Кузяка идла», модель домыслила из этого
    «влево», и робот поехал. Имя при этом совпало, так что проверка «звали ли
    по имени» не спасла — нужна вторая, про уверенность распознавания.

    Так устроено у всех, у кого команда может что-то сдвинуть: Home Assistant
    не пускает в модель то, что разобрал сам, а Алиса перед разговорной веткой
    прогоняет реплику через отдельный классификатор.
    """
    section("неуверенное распознавание не двигает робота")
    from robot_voice.app import Addressed

    store = Path(tempfile.mkdtemp())
    ros = types.SimpleNamespace(voltage=12.4, moving=False, busy=False,
                                connected=True, drive=lambda *a, **k: None,
                                stop_motion=lambda: None)
    addressed = Addressed()
    tools = {t.name: t for t in build_tools(
        ros, Timers(lambda *a, **k: None, store=store / "t.json"),
        addressed=addressed)}

    addressed.by_name, addressed.sure = True, True
    check("уверенно и по имени — едем",
          tools["drive"]({"direction": "вперёд"}).startswith("Еду"), True)

    addressed.sure = False
    check("расслышали плохо — не едем",
          tools["drive"]({"direction": "вперёд"}),
          "Не уверен, что расслышал. Повтори-ка.")
    check("и разворот тоже",
          tools["turn"]({"direction": "влево"}),
          "Не уверен, что расслышал. Повтори-ка.")
    check("и маршрут тоже",
          tools["route"]({"steps": [{"move": "вперёд"}, {"turn": "влево"}]}),
          "Не уверен, что расслышал. Повтори-ка.")

    addressed.by_name, addressed.sure = False, True
    check("без имени не едем",
          tools["drive"]({"direction": "вперёд"}),
          "Позови меня по имени — тогда поеду.")
    # Второй отказ подряд — коротко. Полную формулу робот уже произнёс,
    # повторять её каждые полминуты и значит «говорить казённо».
    check("а второй раз за минуту — в два слова",
          tools["drive"]({"direction": "вперёд"}), "Только по имени.")
    check("отказ виден снаружи", addressed.отказ, "Только по имени.")

    # «Стоп» не должен ни от чего зависеть: он останавливает, а не запускает.
    addressed.by_name = addressed.sure = False
    check("стоп работает всегда", tools["stop"]({}).endswith("."), True)


def test_route() -> None:
    """Фигуру робот собирает сам, а не ищет в списке готовых сценариев.

    Правил на все случаи не напасёшься: «проедь кругом», «зигзагом», «обойди
    стол», «нарисуй восьмёрку» — каждое новое правило ловит ровно одну
    формулировку и молчит на соседней. Поэтому шаги придумывает модель, а код
    отвечает только за пределы и за то, что «стоп» обрывает всё разом.
    """
    section("свобода движений: маршрут придумывает модель")
    from robot_voice.app import Addressed
    from robot_voice.tools import (DRIVE_SPEED, MAX_DISTANCE, TURN_SPEED,
                                   ШАГОВ_МАКС)

    store = Path(tempfile.mkdtemp())
    маршруты: list[list[dict]] = []
    ros = types.SimpleNamespace(
        voltage=12.4, moving=False, busy=False, connected=True,
        drive=lambda *a, **k: None, stop_motion=lambda: None,
        run_route=lambda шаги: маршруты.append(шаги))
    addressed = Addressed()
    tools = {t.name: t for t in build_tools(
        ros, Timers(lambda *a, **k: None, store=store / "t.json"),
        addressed=addressed)}

    зигзаг = [
        {"move": "вперёд", "distance": 0.4},
        {"turn": "влево", "degrees": 45},
        {"move": "вперёд", "distance": 0.4},
        {"turn": "вправо", "degrees": 45},
    ]
    ответ = tools["route"]({"steps": зигзаг, "name": "зигзаг"})
    check("сказал словом человека, а не по-роботски",
          ответ.startswith("Делаю зигзаг, четыре шага."), True)
    # Дальномера в этой сборке нет, и робот обязан про это сказать. Маршрут
    # едет до полутора минут, его пишет модель, а не человек, — и ехать всё
    # это время без единой проверки пути, ничего не сказав, нельзя.
    check("и предупредил, что едет вслепую", "вслепую" in ответ, True)
    check("шаги ушли на шасси", len(маршруты[-1]), 4)
    check("первый шаг едет вперёд", маршруты[-1][0]["x"] > 0, True)
    check("второй шаг крутится влево", маршруты[-1][1]["wz"] > 0, True)
    check("а вправо — в другую сторону", маршруты[-1][3]["wz"] < 0, True)

    # Ехать и поворачивать одним шагом — это дуга, из дуг складывается круг.
    # Ни колёса, ни разворот при этом не должны выйти за свой предел: иначе
    # шасси упрётся в собственный потолок и фигура поедет вкривь.
    tools["route"]({"steps": [{"move": "вперёд", "distance": 0.5,
                               "turn": "влево", "degrees": 90}] * 4,
                    "name": "круг"})
    дуга = маршруты[-1][0]
    check("дуга едет", дуга["путь"] > 0, True)
    check("и одновременно крутится", дуга["угол"] > 0, True)
    check("скорость хода в пределах", abs(дуга["x"]) <= DRIVE_SPEED + 1e-9, True)
    check("скорость разворота тоже", abs(дуга["wz"]) <= TURN_SPEED + 1e-9, True)

    # Пределы. Модель вольна придумать что угодно, но робот живёт в комнате.
    длинный = tools["route"]({"steps": [{"move": "вперёд", "distance": 0.1}] * 30})
    check("длинный маршрут обрезан", len(маршруты[-1]), ШАГОВ_МАКС)
    check("и об этом сказано вслух", "предел" in длинный, True)
    check("шаг длиннее предела укорочен",
          tools["route"]({"steps": [{"move": "вперёд", "distance": 99},
                                    {"turn": "влево"}]})
          and маршруты[-1][0]["путь"], MAX_DISTANCE)

    check("пустой маршрут — отказ",
          tools["route"]({"steps": []}), "Маршрут пустой — перечисли шаги.")
    check("шаг ни о чём — отказ",
          tools["route"]({"steps": [{}]}),
          "В шаге маршрута нет ни move, ни turn.")
    check("непонятное направление — отказ",
          tools["route"]({"steps": [{"move": "вверх"}]}).startswith("Не понял"),
          True)
    # Модель однажды пришлёт число строкой — падать на этом целым инструментом
    # незачем, у шага есть разумное умолчание.
    tools["route"]({"steps": [{"move": "вперёд", "distance": ""},
                              {"turn": "влево", "degrees": "сорок"}]})
    check("мусор вместо числа не роняет маршрут", len(маршруты[-1]), 2)

    # Шаг уезжает в шасси как есть, распакованный по именам. Разойдись эти
    # имена с _motion_loop — маршрут упадёт уже на живом роботе, в потоке,
    # где ошибку видно только в журнале.
    import inspect

    from robot_voice.ros import Ros
    поля = set(inspect.signature(Ros._motion_loop).parameters) - {"self"}
    check("шаг маршрута подходит шасси по именам",
          set(маршруты[-1][0]) <= поля, True)

    # И то же самое, что у drive: без имени не едем никуда, даже фигурой.
    addressed.by_name = False
    было = len(маршруты)
    check("без имени маршрут не поедет",
          tools["route"]({"steps": зигзаг}), "Позови меня по имени — тогда поеду.")
    check("и на шасси ничего не ушло", len(маршруты), было)

    # Сокращённый отказ считает время по time.monotonic(), а тот идёт от
    # ЗАГРУЗКИ машины. В первую минуту после включения он сам меньше
    # ПОВТОР_ОТКАЗА, и робот, не сказав ещё ни слова, считал, что уже
    # объяснял. Поймано на CI, где машина всегда свежая; на роботе это первая
    # минута после включения питания — ровно тогда, когда человек проверяет,
    # ожил ли он. Здесь эта минута воспроизводится честно.
    import time as _time

    from robot_voice import tools as _tools
    _tools.time = types.SimpleNamespace(monotonic=lambda: 3.0, time=_time.time,
                                        sleep=_time.sleep)
    try:
        только_включились = Addressed()
        только_включились.by_name = False
        свежий = {t.name: t for t in build_tools(
            ros, Timers(lambda *a, **k: None, store=store / "t2.json"),
            addressed=только_включились)}
        check("через три секунды после загрузки отказ всё равно полный",
              свежий["drive"]({"direction": "вперёд"}),
              "Позови меня по имени — тогда поеду.")
        check("а второй подряд — уже короткий",
              свежий["drive"]({"direction": "вперёд"}), "Только по имени.")
    finally:
        _tools.time = _time


def test_no_broken_promise() -> None:
    """Обещание поездки и отказ в ней не звучат одной фразой.

    Живой случай, из-за которого разговор выглядел глупее всего. Человек
    сказал что-то в открытом окне разговора, не позвав робота по имени;
    модель успела написать «Еду вперёд на метр», инструмент отказал, модель
    пересказала отказ своими словами — и робот произнёс вслух «Еду вперёд на
    метр. Похоже, нужно обратиться ко мне по имени». Поехал или нет — по этой
    фразе понять нельзя.
    """
    import contextlib as _c

    section("обещание поездки без поездки не звучит")
    from robot_voice import app
    from robot_voice.app import Addressed

    произнесено: list[str] = []

    class Поток:
        def feed(self, текст: str) -> None:
            произнесено.append(текст)

        def close(self) -> None:
            pass

    class FakeVoice:
        speaker = types.SimpleNamespace(stream=lambda **kw: Поток(), last_said="")

        def say(self, text, **kw):
            произнесено.append(text)
            return 1

        def hold(self):
            return _c.nullcontext()

        def quiet(self):
            return _c.nullcontext()

        def status(self, *a, **k):
            pass

    store = Path(tempfile.mkdtemp())
    ros = types.SimpleNamespace(voltage=12.4, moving=False, busy=False,
                                connected=True, drive=lambda *a, **k: None,
                                stop_motion=lambda: None,
                                run_route=lambda шаги: None)
    addressed = Addressed()
    tools = {t.name: t for t in build_tools(
        ros, Timers(lambda *a, **k: None, store=store / "t.json"),
        addressed=addressed)}

    class Обещающий:
        """Модель ровно с тем поведением, что было в журнале робота."""

        last_talk = 0.0

        def __init__(self) -> None:
            self.позвал: list[str] = []

        def reply(self, text, on_text, smart=False):
            on_text("Еду вперёд на метр. ")
            self.позвал = ["drive"]
            tools["drive"]({"direction": "вперёд"})
            on_text("Похоже, нужно обратиться ко мне по имени. ")
            on_text("Скажи: «Кузя, поезжай вперёд».")
            return ""

        def reset(self) -> None:
            pass

    addressed.by_name, addressed.sure = False, True
    addressed.отказ = ""
    app._respond("а поезжай-ка вперёд", Обещающий(), FakeVoice(),
                 addressed=addressed)
    сказанное = " ".join(произнесено)
    check("обещание поездки не прозвучало", "Еду вперёд" in сказанное, False)
    check("нотация про имя — тоже", "обратиться" in сказанное, False)
    check("а прозвучал ровно отказ, одной строкой",
          [с.strip() for с in произнесено], ["Позови меня по имени — тогда поеду."])

    # Когда ехать можно, ничего этого нет: ответ идёт как раньше, потоком.
    произнесено.clear()
    addressed.by_name = addressed.sure = True
    addressed.отказ = ""

    class Обычный(Обещающий):
        def reply(self, text, on_text, smart=False):
            self.позвал = ["drive"]
            tools["drive"]({"direction": "вперёд"})
            on_text("Еду вперёд на метр.")
            return "Еду вперёд на метр."

    app._respond("поезжай вперёд", Обычный(), FakeVoice(), addressed=addressed)
    check("по имени робот говорит как обычно",
          [с.strip() for с in произнесено], ["Еду вперёд на метр."])


def прогон_фраз(схема, шумно: bool = False, с_флагами: bool = False) -> list:
    """Схема — список (речь?, сколько кадров). Возвращает длины фраз.

    Живой Listener без микрофона: детектор речи подменён заранее известной
    последовательностью ответов, а кадры — тишиной нужной длины.
    """
    import threading as th
    from collections import deque

    import numpy as np

    from robot_voice import audio

    кадры, признаки = [], []
    for речь, n in схема:
        for _ in range(n):
            кадры.append(np.zeros(160, dtype=np.int16))
            признаки.append(речь)
    подряд = iter(признаки)
    l = audio.Listener.__new__(audio.Listener)
    l.pump = types.SimpleNamespace(start=lambda: None,
                                   frames=lambda: iter(кадры))
    l.sample_rate = 16000
    l.vad = types.SimpleNamespace(is_speech=lambda *a: next(подряд))
    l.silence_frames, l._min_speech = 35, 15            # 700 мс, 300 мс
    l.max_speech_frames = 1000                          # 20 с
    l._start, l.preroll = 2, deque(maxlen=15)
    l._noisy = шумно
    l._muted = th.Event()
    l.long_chunk = False
    l.wake_heard = False
    l.on_wake = None
    l.spotter = None            # запасной режим: режем по паузам
    l.command_frames = 1000
    куски = []
    for w in l.utterances():
        куски.append((round((len(w) - 44) / 2 / 16000, 1), l.long_chunk))
    return [(д, длинный) for д, длинный in куски] if с_флагами else [
        д for д, _ in куски]


def test_odometry() -> None:
    """Движение кончается по одометрии, а не по секундомеру.

    По секундомеру «полметра» — это «две с половиной секунды на такой-то
    скорости». Разгон при этом никто не считает, шасси недобирает скорость, и
    робот проезжает меньше обещанного: разворот «на сто восемьдесят» выходит
    градусов на сто двадцать. На живом роботе это и выглядело как
    «разворачивается чуть-чуть».
    """
    import math
    import types as _t

    from robot_voice.ros import Ros

    section("движение по одометрии")

    class Шасси(Ros):
        """Шасси, которое даёт шесть десятых от заказанной скорости."""

        def __init__(self) -> None:
            super().__init__("ws://нет")
            self.x = self.yaw = 0.0
            self._шаг = time.monotonic()
            self._odom, self._odom_at = (0.0, 0.0, 0.0), time.monotonic()

        def _send(self, что) -> None:
            pass

        def publish_twist(self, x=0.0, y=0.0, wz=0.0) -> None:
            сейчас = time.monotonic()
            прошло, self._шаг = сейчас - self._шаг, сейчас
            self.x += x * 0.6 * прошло
            self.yaw += wz * 0.6 * прошло
            self._odom, self._odom_at = (self.x, 0.0, self.yaw), сейчас

    робот = Шасси()
    робот.drive(0.0, 0.0, 1.0, 3.14, угол=math.pi)
    робот._motion.join(15)
    повернулся = math.degrees(робот.yaw)
    check("развернулся на сто восемьдесят, а не на сто двадцать",
          170 <= повернулся <= 195, True)

    поездка = Шасси()
    поездка.drive(0.2, 0.0, 0.0, 10.0, путь=2.0)
    поездка._motion.join(40)
    check("проехал два метра, а не полтора",
          1.9 <= поездка.x <= 2.2, True)

    # Одометрии нет — едем по секундомеру, как раньше. Молчащее шасси не
    # должно останавливать робота навсегда.
    class Немой(Шасси):
        @property
        def odom(self):
            return None

    немой = Немой()
    начало = time.monotonic()
    немой.drive(0.2, 0.0, 0.0, 0.5, путь=2.0)
    немой._motion.join(10)
    check("без одометрии кончает по секундомеру",
          time.monotonic() - начало < 3.0, True)


def test_motion_queue() -> None:
    """Движения идут по очереди, а не отменяют друг друга.

    «Проедь вперёд, а потом назад» кончалось одним движением назад: модель
    звала оба инструмента в одну и ту же секунду, а второй вызов первым делом
    отменял первый. Робот дёргался и уезжал не туда — человек видел, что
    сложные просьбы он не выполняет.
    """
    import types as _t

    from robot_voice.ros import Ros

    section("очередь движений")

    class Шасси(Ros):
        def __init__(self) -> None:
            super().__init__("ws://нет")
            self.x = self.yaw = 0.0
            self._шаг = time.monotonic()
            self._odom, self._odom_at = (0.0, 0.0, 0.0), time.monotonic()
            self.куда: list[int] = []

        def _send(self, что) -> None:
            pass

        def publish_twist(self, x=0.0, y=0.0, wz=0.0) -> None:
            сейчас = time.monotonic()
            прошло, self._шаг = сейчас - self._шаг, сейчас
            self.x += x * прошло
            self._odom, self._odom_at = (self.x, 0.0, self.yaw), сейчас
            if abs(x) > 1e-3:
                self.куда.append(1 if x > 0 else -1)

    робот = Шасси()
    робот.drive(0.2, 0.0, 0.0, 5.0, путь=0.4)      # вперёд
    робот.drive(-0.2, 0.0, 0.0, 5.0, путь=0.4)     # и следом назад
    робот._motion.join(30)
    check("вперёд робот всё-таки поехал", 1 in робот.куда, True)
    check("и назад тоже", -1 in робот.куда, True)
    check("и вернулся примерно на место", abs(робот.x) < 0.15, True)

    # А «стоп» обязан обрывать движение немедленно, а не ждать очереди: это
    # единственная команда, которую человек говорит, когда уже страшно.
    стоп = Шасси()
    стоп.drive(0.2, 0.0, 0.0, 30.0, путь=5.0)
    время = time.monotonic()
    стоп.stop_motion()
    check("«стоп» не ждёт очереди", time.monotonic() - время < 3.0, True)
    check("и движение прекратилось", стоп.moving, False)

    # --- маршрут: несколько шагов одной программой ---
    #
    # Собрать фигуру из отдельных вызовов drive нельзя: каждый ждёт предыдущий
    # в очереди, и двенадцать шагов заняли бы главный цикл на всю поездку —
    # робот перестал бы слышать «стоп» ровно там, где он нужнее всего.
    def шаг(x: float, путь: float = 0.2) -> dict:
        return {"x": x, "y": 0.0, "wz": 0.0, "duration": 5.0,
                "путь": путь, "угол": 0.0}

    фигура = Шасси()
    фигура.run_route([шаг(0.2), шаг(-0.2), шаг(0.2)])
    check("управление вернулось сразу, робот едет", фигура.moving, True)
    фигура._motion.join(40)
    check("все шаги проехались", sorted(set(фигура.куда)), [-1, 1])
    check("и маршрут кончился сам", фигура.moving, False)

    # «Стоп» посреди маршрута снимает всю программу, а не одно её колено.
    # Иначе робот встанет на полсекунды и поедет дальше по своим делам —
    # человек в этот момент уже кричит «стоп» второй раз.
    оборвали = Шасси()
    оборвали.run_route([шаг(0.2, путь=5.0), шаг(-0.2, путь=5.0)])
    time.sleep(0.3)
    оборвали.stop_motion()
    оборвали._motion.join(5)
    check("после «стоп» маршрут не продолжился", оборвали.moving, False)
    check("и второе колено не поехало", -1 in оборвали.куда, False)


def test_порожек_не_обрыв() -> None:
    """Робот перестал замирать навсегда, въехав на дверной порожек.

    Норма пола замораживается при запуске и с тех пор считается истиной. А
    наклон датчика меняется не от отвёртки, а от езды: колёсная база WD550
    всего 19.5 см, и подъём передних колёс на 17 мм — обычный дверной
    порожек, стык пола, край ковра — даёт крен в пять градусов. Датчик стоит
    на передней кромке, значит при крене ещё и поднимается, и нижние ряды
    начинают смотреть ДАЛЬШЕ, чем помнит норма.

    Дальше «обрыв», отказ ехать — и выйти из этого робот не мог: кадр не
    меняется, счётчик обрыва не сбрасывается, переучивание звалось только по
    смене галок в пульте. Робот замирал на пороге НАВСЕГДА, причём молча:
    жалоба на «вечное препятствие» считает близкие зоны, а не обрыв.

    Чинится сверкой наклона, а НЕ подменой обрыва плоскостью. Разница
    принципиальная: наверху лестницы нижняя площадка — тоже горизонтальная
    плоскость, подгонка может сесть на неё, и тогда «все замеры совпадают с
    полом», обрыва нет, робот съезжает со ступеней. Обменять «встал на
    пороге» на «поехал с лестницы» нельзя ни при каком приоритете.
    """
    section("порожек — не обрыв")
    import math
    import tempfile as _tmp
    from pathlib import Path as _Path

    from robot_voice import plane, tof

    ВЫСОТА = 0.13
    оси = plane.направления()

    def кадр(наклон_град: float) -> list[list[float]]:
        """Пустая ровная комната, датчик наклонён вниз на столько градусов."""
        накл = math.radians(наклон_град)
        сетка = [[0.0] * 8 for _ in range(8)]
        for р in range(8):
            for к in range(8):
                x, y, z = оси[р][к]
                xп = x * math.cos(накл) + z * math.sin(накл)
                zп = -x * math.sin(накл) + z * math.cos(накл)
                д = []
                if zп < -1e-6:
                    д.append(-ВЫСОТА / zп)
                if xп > 1e-6:
                    д.append(3.0 / xп)
                живые = [м for м in д if 0.05 < м <= 3.5]
                сетка[р][к] = min(живые) if живые else 0.0
        return сетка

    with _tmp.TemporaryDirectory() as дом:
        def датчик() -> tof.Дальномер:
            д = tof.Дальномер.__new__(tof.Дальномер)
            д._взгляд = tof.Взгляд([[0.0] * 8 for _ in range(8)], 0.0)
            д._замок = threading.Lock()
            д.пол = tof.Пол(_Path(дом) / "пол.json")
            д.разворот = False
            д.ищем_обрыв = True
            д._подряд = д._обрыв_подряд = 0
            д._переучили = 0.0
            д._мешает_с = 0.0
            д._прочитано = 1e9          # галки не перечитываем
            д._зеркало = д._вверхногами = д._поперёк = False
            д._на_разворот = []
            д._выложено = 1e9
            д._жаловался = 0.0
            д._жалоба = ""
            д._сырьё = b""
            д.свои = []                 # своих деталей в кадре нет
            д.обрыв_разрешён = True
            return д

        # Робот стоит ровно, учит пол.
        ровно = кадр(12.0)
        д = датчик()

        # ПЕРВЫЙ ЖЕ КАДР, и это отдельная беда, найденная попутно.
        #
        # `учить` возвращает False и пока копятся двадцать кадров, и когда
        # норма посчитана и отвергнута. Снаружи стояло «вернул False и нормы
        # нет — значит пол не в кадре, перестаём пробовать», и на первом же
        # кадре это истинно ВСЕГДА. Защита от обрыва выключалась через сотую
        # долю секунды после запуска.
        #
        # На роботе, у которого файл нормы уже лежал на диске, это не
        # проявлялось — норма грузилась, ветка обучения не входила вовсе. А
        # на НОВОМ роботе обрыв не искался никогда, и файл нормы не появлялся
        # никогда, то есть перезапуск этого не чинил.
        д._принять([ряд[:] for ряд in ровно])
        check("на первом кадре обрыв искать не бросаем", д.ищем_обрыв, True)
        check("и норма ещё копится", д.пол.норма, None)
        check("но это не отказ", д.пол.отказался, False)

        for _ in range(tof.УЧИТЬ_КАДРОВ + 2):
            д._принять([ряд[:] for ряд in ровно])
        check("пол выучен", д.пол.норма is not None, True)
        check("и наклон при нём записан", д.пол.наклон is not None, True)
        check("наклон выведен верно", abs(д.пол.наклон - 12.0) < 2.0, True)
        check("на ровном полу обрыва нет", д.взгляд().обрыв, 0)

        # Тот же робот въехал передними колёсами на порожек: нос задрался на
        # пять градусов, датчик смотрит вниз уже не на 12, а на 7.
        порожек = кадр(7.0)
        д._переучили = 0.0
        # Кадров нужно столько, чтобы хватило И на «обрыв подряд», И на
        # «наклон сбит устойчиво»: один сбитый замер — это шум подгонки, а не
        # порожек. Мерено на живом роботе: на ровном полу подгонка гуляет до
        # одиннадцати градусов.
        for _ in range(max(tof.КАДРОВ_ПОДРЯД, tof.НАКЛОН_ПОДРЯД) + 1):
            д._принять([ряд[:] for ряд in порожек])
        check("норма забыта — она снята в другой геометрии",
              д.пол.норма, None)
        check("и обрыв не объявлен", д.взгляд().обрыв, 0)

        # И РОБОТ ЕДЕТ. Это то самое, ради чего всё затевалось: раньше он
        # здесь вставал и не мог тронуться уже никогда.
        for _ in range(tof.УЧИТЬ_КАДРОВ + 2):
            д._принять([ряд[:] for ряд in порожек])
        можно, почему = д.взгляд().ехать_можно()
        check("на порожке робот едет", можно, True)
        check("и обрыв по-прежнему ищется", д.ищем_обрыв, True)
        check("и не жалуется на обрыв", "пола нет" in почему, False)
        check("а норму переучил под новый наклон",
              д.пол.норма is not None and abs(д.пол.наклон - 7.0) < 2.0, True)

        # --- отказ, который нельзя отменить, это поломка ------------------
        # У поиска обрыва было два ВЕЧНЫХ выключателя: «где верх — не понял»
        # и «пол не выучился». Обратно включало только переучивание, а оно
        # звалось из одного места — смены галок разворота в пульте.
        #
        # Робота включили носом в стену, пола в кадре нет, защита выключилась.
        # Робота унесли в комнату, где пол виден в каждом кадре, — защита так
        # и осталась выключенной. Дальше настоящий край: обрыв 0, «ехать
        # можно». Робот съезжает с лестницы, и разрешение выдаёт его
        # собственный сторож.
        сдавшийся = датчик()
        сдавшийся.ищем_обрыв = False        # как после «где верх — не понял»
        сдавшийся.обрыв_разрешён = True
        сдавшийся._переучили = 0.0
        for _ in range(tof.УЧИТЬ_КАДРОВ + 3):
            сдавшийся._принять([ряд[:] for ряд in ровно])
        check("увидев пол снова, робот возвращает поиск обрыва",
              сдавшийся.ищем_обрыв, True)
        check("и норму переучивает", сдавшийся.пол.норма is not None, True)

        обрыв_после = [ряд[:] for ряд in ровно]
        for р in tof.ОБРЫВ_РЯДЫ:
            for к in range(8):
                обрыв_после[р][к] = 0.0
        for _ in range(tof.КАДРОВ_ПОДРЯД + 1):
            сдавшийся._принять([ряд[:] for ряд in обрыв_после])
        check("и край теперь видит", сдавшийся.взгляд().ехать_можно()[0], False)

        # ЗЕРКАЛЬНАЯ ПРОВЕРКА, И ОНА ГЛАВНАЯ. Настоящий обрыв — пол пропал, а
        # робот стоит ровно, наклон не менялся. Норму трогать нельзя, обрыв
        # обязан сработать. Иначе мы обменяли бы стояние на пороге на съезд
        # с лестницы.
        край = датчик()
        for _ in range(tof.УЧИТЬ_КАДРОВ + 2):
            край._принять([ряд[:] for ряд in ровно])
        check("на краю: пол сперва выучен", край.пол.норма is not None, True)

        обрыв = [ряд[:] for ряд in ровно]
        for р in tof.ОБРЫВ_РЯДЫ:
            for к in range(8):
                обрыв[р][к] = 0.0        # за краем луч не возвращается вовсе
        for _ in range(tof.КАДРОВ_ПОДРЯД + 1):
            край._принять([ряд[:] for ряд in обрыв])
        check("норма НЕ забыта: наклон не менялся",
              край.пол.норма is not None, True)
        check("обрыв объявлен", край.взгляд().обрыв >= tof.КАДРОВ_ПОДРЯД, True)
        можно, почему = край.взгляд().ехать_можно()
        check("и робот не едет", можно, False)
        check("и говорит про пол", "пола нет" in почему, True)


def test_одометрия_замолчала() -> None:
    """Замолчавшая на ходу одометрия больше не превращает метр в сорок секунд.

    Поездка по одометрии кончается, когда та насчитает заказанный путь. На
    случай, если одометрия соврёт, стоит предохранитель по секундомеру —
    ВТРОЕ дольше заказанного, потому что разгон съедает время.

    А если одометрия не соврала, а замолчала совсем — узел упал, шасси
    отвалилось, — цикл просто шёл дальше и публиковал ту же скорость до этого
    предохранителя. Команда «три метра» (пятнадцать секунд) превращалась в
    сорок пять секунд хода. Молча: выход по предохранителю ничего не
    объявляет, и человек видел только робота, уехавшего втрое дальше.

    Теперь остаток считается по ПУТИ, а не по duration. Разница существенна:
    секундомер врёт в меньшую сторону — разгон никто не считает, — и остаток
    по нему систематически недоезжал бы, то есть робот снова врал бы, только
    в другую сторону.
    """
    section("одометрия замолчала на ходу")
    import types

    from robot_voice.ros import Ros

    class Шасси(Ros):
        """Едет и честно считает пройденное. Одометрию можно оборвать."""

        def __init__(self) -> None:
            super().__init__("ws://нет")
            self.x = 0.0
            self._шаг = time.monotonic()
            self._odom, self._odom_at = (0.0, 0.0, 0.0), time.monotonic()
            self.молчит = False
            self.ходов = 0

        def _send(self, что) -> bool:
            return True

        def publish_twist(self, x=0.0, y=0.0, wz=0.0) -> None:
            сейчас = time.monotonic()
            прошло, self._шаг = сейчас - self._шаг, сейчас
            self.x += x * прошло
            if abs(x) > 1e-3:
                self.ходов += 1
            if not self.молчит:
                self._odom = (self.x, 0.0, 0.0)
                self._odom_at = сейчас

        @property
        def odom(self):
            return None if self.молчит else self._odom

    # Обрываем одометрию сразу: робот не должен ехать втрое дольше заказанного.
    робот = Шасси()
    робот.молчит = True
    начало = time.monotonic()
    робот.drive(0.2, 0.0, 0.0, 1.0, путь=0.2)
    робот._motion.join(30)
    прошло = time.monotonic() - начало
    check("без одометрии доезжаем по остатку пути, а не втрое дольше",
          прошло < 2.5, True)
    check("и ехать всё-таки ехали", робот.ходов > 0, True)

    # --- упёрлись ---------------------------------------------------------
    # Колёса крутятся, команда уходит, а робот стоит — значит упёрся: задом в
    # стену, которую дальномер не видит по построению, колесом в порожек,
    # шнуром за ножку стула. Раньше этого не замечал никто: одометрия
    # читалась ровно для двух вопросов — сколько проехали и на сколько
    # повернулись, — а «заказано против фактического» не сравнивалось нигде.
    # Робот сорок пять секунд толкал стену и молчал.
    class Упёртый(Шасси):
        def publish_twist(self, x=0.0, y=0.0, wz=0.0) -> None:
            # Команда уходит, одометрия свежая, а координаты стоят.
            self._odom_at = time.monotonic()
            if abs(x) > 1e-3:
                self.ходов += 1

    упёртый = Упёртый()
    сказано: list[str] = []
    упёртый.объявить = сказано.append
    начало = time.monotonic()
    упёртый.drive(0.2, 0.0, 0.0, 30.0, путь=3.0)
    упёртый._motion.join(30)
    прошло = time.monotonic() - начало
    check("упор замечен, а не сорок пять секунд толкания",
          прошло < 5.0, True)
    check("и причина названа", "упёрся" in упёртый.прервано, True)
    check("и сказана вслух",
          any("упёрся" in ф.lower() for ф in сказано), True)

    # Зеркально: едущий робот упёртым не считается. Иначе каждая нормальная
    # поездка обрывалась бы через полторы секунды.
    едущий = Шасси()
    едущий.drive(0.2, 0.0, 0.0, 6.0, путь=0.4)
    едущий._motion.join(30)
    check("нормальная поездка не считается упором", едущий.прервано, "")
    check("и доехала", едущий.x >= 0.35, True)

    # А если одометрия вернулась — укорочение снимается, и поездка идёт до
    # конца по-настоящему. Кратковременный провал приёма не должен навсегда
    # обрезать поездку.
    вернулась = Шасси()
    вернулась.молчит = True

    def оживить() -> None:
        time.sleep(0.4)
        вернулась.молчит = False

    threading.Thread(target=оживить, daemon=True).start()
    вернулась.drive(0.2, 0.0, 0.0, 6.0, путь=0.5)
    вернулась._motion.join(30)
    check("вернувшаяся одометрия снимает укорочение",
          вернулась.x >= 0.45, True)


def test_слежка_упреждает() -> None:
    """Робот целится туда, куда человек идёт, а не туда, где он был.

    До сих пор следование было чистой пропорцией: увидели пеленг — повернули
    настолько же. Это работает, пока цель стоит, и опаздывает ровно на время
    цепочки, как только она пошла. Цепочка длинная: кадр дальномера до 100 мс,
    круг цикла 67 мс, разгон колёс. За треть секунды человек, идущий 1.2 м/с,
    уходит на сорок сантиметров — на повороте коридора ровно та разница,
    после которой он оказывается за краем поля зрения.

    Главная тонкость и главная ловушка: пеленг меняется по двум причинам
    сразу — человек идёт И робот поворачивается. Разность замеров смешивает
    их. Упреждать по ней значило бы принимать собственный доворот за движение
    человека и раскачивать робота вместо того, чтобы вести. Свою скорость мы
    знаем точно — сами её и подали, — и вычитаем.
    """
    section("упреждение: целимся туда, куда идёт")
    import math

    from robot_voice import follow

    # --- человек уходит влево, робот стоит --------------------------------
    слежка = follow.Слежка()
    угол = 0.0
    for _ in range(30):                 # две секунды по 1/15
        угол += math.radians(15) * follow.ШАГ    # 15°/с влево
        слежка.обновить(1.5, угол, follow.ШАГ)
    check("поворот цели опознан",
          abs(math.degrees(слежка.поворот_цели) - 15) < 3, True)
    check("и целимся с упреждением", слежка.упредить(угол) > угол, True)
    check("ровно на путь за время цепочки",
          abs(слежка.упредить(угол) - угол
              - слежка.поворот_цели * follow.УПРЕЖДЕНИЕ) < 1e-9, True)

    # --- человек стоит, а робот доворачивается ---------------------------
    # Пеленг при этом меняется ровно так же, как в первом случае, — и вот
    # здесь прежняя разность замеров соврала бы. Собственный поворот обязан
    # вычитаться, иначе робот принимает своё движение за чужое.
    свой = follow.Слежка()
    угол = math.radians(-30)
    # Пеленг отсчитывается в осях РОБОТА. Робот поворачивает влево (+) —
    # неподвижная цель уезжает вправо, то есть пеленг убывает ровно на
    # столько же. Отсюда и знак: свой поворот входит в оценку с плюсом.
    наш_поворот = math.radians(-15)
    for _ in range(30):
        угол -= наш_поворот * follow.ШАГ
        свой.обновить(1.5, угол, follow.ШАГ, наш_поворот=наш_поворот)
    check("собственный доворот движением человека не считается",
          abs(свой.поворот_цели) < math.radians(2), True)
    check("и упреждения не добавляется",
          abs(свой.упредить(угол) - угол) < math.radians(1), True)

    # --- одиночный промах дальномера робота не разворачивает --------------
    # Промах смещает пеленг на целую колонку; делённый на шаг цикла, он
    # превращается в «человек летит десять радиан в секунду».
    дёрганая = follow.Слежка()
    дёрганая.обновить(1.5, 0.0, follow.ШАГ)
    дёрганая.обновить(1.5, math.radians(45), follow.ШАГ)
    check("выброс упреждения ограничен",
          abs(дёрганая.упредить(0.0)) <= follow.УПРЕЖДАЕМ_НЕ_БОЛЬШЕ + 1e-9, True)

    # --- дистанция растёт со скоростью человека ---------------------------
    # Не вежливость, а тормозной путь: робот за быстрым человеком и сам едет
    # быстро, а тормозной путь растёт как квадрат скорости.
    стоит = follow.Слежка()
    check("перед стоящим держим обычную дистанцию",
          стоит.дистанция(), follow.ДЕРЖАТЬ)

    быстрый = follow.Слежка()
    д = 1.0
    for _ in range(60):
        д += 1.2 * follow.ШАГ           # уходит 1.2 м/с, робот стоит
        быстрый.обновить(д, 0.0, follow.ШАГ)
    check("за быстрым держимся дальше", быстрый.дистанция() > follow.ДЕРЖАТЬ, True)
    check("но не бесконечно далеко",
          быстрый.дистанция() <= follow.ДЕРЖАТЬ_МАКС, True)

    # Человек идёт НА робота — дистанция не уменьшается. Подпускать ближе
    # того, кто сам приближается, незачем.
    навстречу = follow.Слежка()
    д = 2.0
    for _ in range(60):
        д -= 1.0 * follow.ШАГ
        навстречу.обновить(д, 0.0, follow.ШАГ)
    check("на идущего навстречу дистанцию не сокращаем",
          навстречу.дистанция(), follow.ДЕРЖАТЬ)

    # --- пороги едут вместе с дистанцией ----------------------------------
    # Иначе «стоим» и «трогаемся» разъехались бы с целью: робот держал бы
    # полтора метра и при этом считал бы, что стоит слишком близко.
    вперёд, _ = follow.как_ехать(1.4, 0.0, свободно=2.0, держать=1.0)
    check("при дистанции 1.0 с 1.4 м робот едет", вперёд > 0, True)
    вперёд, _ = follow.как_ехать(1.4, 0.0, свободно=2.0, держать=1.5)
    check("при дистанции 1.5 с тех же 1.4 м — стоит", вперёд, 0.0)

    # Дистанцию ниже «стоять ближе» опустить нельзя: пороги схлопнулись бы, и
    # робот заездил бы человека вплотную.
    вперёд, _ = follow.как_ехать(0.5, 0.0, свободно=2.0, держать=0.1)
    check("вплотную не подъезжаем, что бы ни просили", вперёд, 0.0)

    # --- цель потерялась — счёт начинается заново -------------------------
    # Разность через две секунды описывает не скорость, а телепортацию.
    рваная = follow.Слежка()
    рваная.обновить(1.0, 0.0, follow.ШАГ)
    рваная.обновить(3.0, math.radians(40), 5.0)
    check("после долгого перерыва скорость не выдумывается",
          (рваная.поворот_цели, рваная.скорость_цели), (0.0, 0.0))


def test_карта_помнит_за_спиной() -> None:
    """Робот перестал двигаться вслепую там, где память может подсказать.

    mapping.py была написана, подробно объяснена, проверена — И НИ К ЧЕМУ НЕ
    ПОДКЛЮЧЕНА. Это нашёл аудит движения. Худший род мёртвого кода: файл,
    который уверенно рассказывает, зачем он нужен, и ни одной строки, которая
    бы его звала.

    А нужен он ровно за тем, чего у робота нет физически, — за обзором.
    Дальномер видит шестьдесят градусов вперёд. Задний ход, боковой ход и
    разворот на месте совершались НАУГАД: сторож пути судил только «x > 0» и
    честно писал, что про заднее полушарие не знает ничего. Между тем задний
    ход без датчиков — единственный юридически доказанный механизм травмы
    среди тротуарных роботов: машина поехала назад и сбила стоявшего там
    человека.

    Не знать — не то же самое, что не помнить. Стул (или ребёнок), который
    был перед роботом секунду назад, никуда не делся оттого, что робот
    отвернулся.
    """
    section("карта помнит то, что за спиной")
    import math
    import types

    from robot_voice import follow, mapping

    # Робот в начале координат, смотрит по +x. Кладём препятствие ЗА ним и
    # даём карте это увидеть: разворачиваем робота, чтобы дальномер туда
    # посмотрел, потом возвращаем курс.
    карта = mapping.Карта()

    def кадр(дистанция: float) -> list[list[float]]:
        г = [[0.0] * 8 for _ in range(8)]
        for р in mapping.РЯДЫ:
            for к in range(3, 5):
                г[р][к] = дистанция
        return г

    # Смотрим назад (курс π) и видим что-то в 40 см.
    карта.добавить(кадр(0.40), (0.0, 0.0, math.pi))
    # Повернулись обратно — препятствие ушло из поля зрения, но не из памяти.
    карта.поза = (0.0, 0.0, 0.0)
    сзади = карта.ближайшее((math.pi, math.radians(70)))
    check("память держит то, что за спиной", 0.3 < сзади < 0.55, True)
    check("а спереди пусто", карта.ближайшее((0.0, math.radians(70))),
          mapping.ВЕРИМ_ДО)

    можно, почему = карта.можно_ехать(-0.2, 0.0, 0.0)
    check("задний ход запрещён", можно, False)
    check("и сказано, почему", "сзади" in почему, True)
    check("вперёд при этом ехать можно", карта.можно_ехать(0.2, 0.0, 0.0)[0], True)
    check("разворот тоже запрещён — корпус заметает круг",
          карта.можно_ехать(0.0, 0.0, 0.8)[0], False)

    # Пустая карта не запрещает ничего: незнание — не разрешение, но и не
    # запрет, а робот, которому нельзя двигаться до первой карты, не работает.
    чистая = mapping.Карта()
    check("пустая карта не запирает робота",
          чистая.можно_ехать(-0.2, 0.0, 0.0)[0], True)

    # --- поворот по памяти, а не по догадке -------------------------------
    # Раньше скорость поворота выводилась из того, что видно ВПЕРЕДИ: «если
    # впереди тесно, то и вокруг, наверное, тоже». Догадка не нужна, когда
    # есть число.
    check("вокруг просторно — крутимся живо",
          follow.поворот_по_виду(0.3, вокруг=3.0), follow.ПОВОРОТ_МАКС)
    check("вокруг тесно — медленно",
          follow.поворот_по_виду(3.0, вокруг=0.5) < follow.ПОВОРОТ_МАКС, True)
    check("занято внутри круга корпуса — не крутимся вовсе",
          follow.поворот_по_виду(3.0, вокруг=mapping.РАДИУС_КОРПУСА - 0.05), 0.0)
    check("нет карты — судим по фронту, как раньше",
          follow.поворот_по_виду(3.0, вокруг=0.0),
          follow.поворот_по_виду(3.0))

    # И это доходит до колёс: как_ехать обязана вернуть ноль поворота.
    _, поворот = follow.как_ехать(2.0, math.radians(30), свободно=2.0,
                                  вокруг=mapping.РАДИУС_КОРПУСА - 0.05)
    check("в тесноте робот не доворачивается к человеку", поворот, 0.0)

    # --- карта кормится сеткой БЕЗ ПОЛА -----------------------------------
    # Сырая дала бы ту же беду, что и следованию: при наклоне датчика вниз
    # ряды 2-5 упираются в пол на 0.3-0.9 м, и робот мгновенно оброс бы
    # стеной вплотную — навсегда и со всех сторон, по которым проехал.
    корень = Path(__file__).resolve().parent.parent
    исходник = (корень / "voice" / "robot_voice" / "app.py").read_text(
        encoding="utf-8")
    check("карта в app.py вообще подключена", "mapping.Карта()" in исходник, True)
    check("и кормится сеткой без пола",
          "карта.добавить(чистая" in исходник, True)
    check("а слепые направления сторожатся картой",
          "ros.сторож_вслепую" in исходник, True)

    # --- слепой сторож правда обрывает поездку ----------------------------
    from robot_voice.ros import Ros

    ros = Ros.__new__(Ros)
    ros._lock = threading.Lock()
    ros._motion_cancel = threading.Event()
    ros._odom = None
    ros._odom_at = 0.0
    ros._свои_нули = 0
    ros._не_ушло = 0
    ros._кричали_про_связь = False
    ros.прервано = ""
    ros.сторож = None
    сказано: list[str] = []
    ros.объявить = сказано.append
    команды: list[tuple] = []
    ros._send = lambda с: bool(команды.append(
        (с["msg"]["linear"]["x"], с["msg"]["angular"]["z"])) or True)
    ros.сторож_вслепую = lambda x, y, wz: карта.можно_ехать(x, y, wz)

    ros._motion_loop(-0.2, 0.0, 0.0, 5.0)
    check("назад робот не поехал", [x for x, _ in команды if x], [])
    check("и сказал, почему", any("не поеду" in ф.lower() for ф in сказано), True)

    # Вперёд слепой сторож не мешает: туда смотрит дальномер, и это его дело.
    команды.clear()
    ros.прервано = ""
    ros._motion_loop(0.2, 0.0, 0.0, 0.2)
    check("вперёд едем как ни в чём не бывало",
          any(x > 0 for x, _ in команды), True)


def test_глаза_и_пеленг_не_одно() -> None:
    """Камера и детектор людей — разные предметы и разные имена.

    В app.py имя `глаза` было занято дважды: сперва камерой (camera.Глаза),
    четырьмя строками ниже — детектором людей (vision_track.Глазомер).
    Присваивание молча затёрло камеру. Объект Глаза терял последнюю ссылку и
    уходил в мусор вместе с переданным ему дальномером, а в build_tools
    уезжал уже Глазомер.

    Наружу это вышло так: инструмент look_around («что ты видишь»)
    регистрировался и показывался модели, а на вызове отвечал «'Глазомер'
    object has no attribute 'посмотреть'». Падение гасилось общим except в
    Tool.__call__, модель видела текст отказа и выкручивалась по памяти —
    человек спрашивал «что ты видишь» и получал уверенный вымысел. Заодно
    молча отваливался счёт расхода на картинки: кадры в облако шли как
    бесплатные.

    Ни одной ошибки при этом не возникало. Два разных предмета звались одним
    словом, и питон честно оставил последний.

    Проверяем РАЗБОРОМ ИСХОДНИКА, а не запуском: app.main лезет в железо и в
    сеть, на сборочной машине его не поднять. Разбор при этом отвечает ровно
    на нужный вопрос — что куда присвоено.
    """
    section("камера и пеленг — разные предметы")
    import ast

    корень = Path(__file__).resolve().parent.parent
    дерево = ast.parse((корень / "voice" / "robot_voice" / "app.py").read_text(
        encoding="utf-8"))

    имена: dict[str, str] = {}          # что создано → каким именем зовётся
    подписка = ""                       # кого отдали в ros.людей_видно
    раздатчик = ""                      # …или как зовут функцию-раздатчик
    в_инструменты = ""                  # что уехало как eyes=

    def кого_зовут(узел) -> str:
        цель = узел.func
        if isinstance(цель, ast.Attribute):
            return цель.attr
        if isinstance(цель, ast.Name):
            return цель.id
        return ""

    for узел in ast.walk(дерево):
        if isinstance(узел, ast.Assign) and isinstance(узел.value, ast.Call):
            что = кого_зовут(узел.value)
            if что in ("Глаза", "Глазомер"):
                for куда in узел.targets:
                    if isinstance(куда, ast.Name):
                        имена[что] = куда.id
        if isinstance(узел, ast.Assign):
            for куда in узел.targets:
                if not (isinstance(куда, ast.Attribute)
                        and куда.attr == "людей_видно"):
                    continue
                # Прямо: ros.людей_видно = пеленг.принять
                if (isinstance(узел.value, ast.Attribute)
                        and узел.value.attr == "принять"
                        and isinstance(узел.value.value, ast.Name)):
                    подписка = узел.value.value.id
                # Через раздатчик: ros.людей_видно = детекция. Подписка одна,
                # а потребителей у неё теперь двое — пеленг и сторож падений,
                # — и раздаёт их своя функция. Проверять надо по-прежнему то
                # же самое: доходят ли детекции до детектора. Поэтому идём
                # внутрь раздатчика, а не отменяем проверку.
                elif isinstance(узел.value, ast.Name):
                    раздатчик = узел.value.id
        if isinstance(узел, ast.Call) and кого_зовут(узел) == "build_tools":
            for довод in узел.keywords:
                if довод.arg == "eyes" and isinstance(довод.value, ast.Name):
                    в_инструменты = довод.value.id

    check("камера в app.py создаётся", "Глаза" in имена, True)
    check("детектор людей тоже", "Глазомер" in имена, True)
    check("и зовутся они РАЗНЫМИ именами",
          имена.get("Глаза") != имена.get("Глазомер"), True)
    # Раздатчик — это по-прежнему «детекции уходят детектору», просто через
    # одну функцию. Смотрим, кого он зовёт: если пеленга там нет, следование
    # ослепнет ровно так же, как ослепла бы камера от затёртого имени.
    if not подписка and раздатчик:
        for узел in ast.walk(дерево):
            if not (isinstance(узел, ast.FunctionDef)
                    and узел.name == раздатчик):
                continue
            зовут = {у.func.value.id for у in ast.walk(узел)
                     if isinstance(у, ast.Call)
                     and isinstance(у.func, ast.Attribute)
                     and у.func.attr == "принять"
                     and isinstance(у.func.value, ast.Name)}
            if имена.get("Глазомер") in зовут:
                подписка = имена["Глазомер"]
            check("раздатчик кормит и сторожа падений",
                  any(и != имена.get("Глазомер") for и in зовут), True)
    check("детекции уходят детектору", подписка, имена.get("Глазомер"))
    check("а инструментам отдаётся камера", в_инструменты, имена.get("Глаза"))

    # И тот же вопрос с другой стороны: подсунуть в build_tools не тот предмет
    # и убедиться, что неработающего инструмента модели не покажут. Раньше
    # показывали — и это хуже, чем не показать вовсе: модель зовёт то, что
    # видит, получает отказ и начинает сочинять.
    from robot_voice import tools as инструменты
    from robot_voice import vision_track

    собрано = инструменты.build_tools(None, None, eyes=vision_track.Глазомер())
    check("сломанные глаза модели не показываются",
          [и for и in собрано if и.name == "look_around"], [])

    class Зрячий:
        def посмотреть(self, вопрос: str = "") -> str:
            return "вижу стол"

    собрано = инструменты.build_tools(None, None, eyes=Зрячий())
    гляделка = [и for и in собрано if и.name == "look_around"]
    check("настоящие глаза показываются", len(гляделка), 1)
    check("и работают", гляделка[0].run(), "вижу стол")


def test_следование_видит_пол() -> None:
    """Следование больше не принимает собственный пол за человека.

    ЭТО ТА САМАЯ ЖИВАЯ ЖАЛОБА: «он вообще не едет за мной». Разобрана до
    причины, и причина оказалась не в скорости и не в потере цели.

    Следование ищет ближайшее крупное пятно. Сетку оно брало сырую, все
    восемь рядов. А при наклоне датчика вниз на 10-15°, как записано в
    docs/hardware.md моей же рукой, нижние ряды упираются в пол на 0.2-0.5 м.
    Для «ближайшего крупного пятна» это и есть ближайшее крупное пятно:
    десятки зон, одна и та же дистанция в любой комнате, независимо от того,
    где стоит человек.

    Дальше всё следует само: 0.3 м ближе, чем СТОЯТЬ_БЛИЖЕ=0.75, значит
    вперёд — ноль. Робот не ехал НИКОГДА. Сторож при этом молчал (его
    спрашивают только когда вперёд>0), камера подменяла лишь угол, а начать()
    искал цель на той же сырой сетке — то есть ветка «Не вижу тебя, встань
    передо мной» была недостижима, и робот отвечал «Иду за тобой» в пустой
    комнате.

    Ровно та же беда уже чинилась в стороже пути и объяснена в plane.py. В
    следовании её не чинили: там она выглядела не как «стою и жалуюсь», а как
    «сказал, что иду, и молчу».

    Кадры здесь строятся НАСТОЯЩЕЙ геометрией — через plane.направления, по
    высоте и наклону из docs/hardware.md, — а не рисуются руками. Прежние
    проверки следования пола не содержали ни в одном кадре, поэтому и
    пропустили это целиком.
    """
    section("следование не идёт за полом")
    import math

    from robot_voice import follow, plane, tof

    ВЫСОТА = 0.13          # метры над полом, docs/hardware.md
    НАКЛОН = 12.0          # градусов вниз, середина рекомендованного 10-15

    оси = plane.направления()

    def кадр(человек: float | None = None, стена: float = 3.0):
        """Что увидит датчик: пол, стена и, может быть, человек.

        Человек — вертикальный столб шириной в две колонки по центру,
        от щиколоток до пояса.
        """
        накл = math.radians(НАКЛОН)
        # Разворот осей на наклон вниз: датчик смотрит не по горизонту.
        сетка = [[0.0] * 8 for _ in range(8)]
        for р in range(8):
            for к in range(8):
                x, y, z = оси[р][к]
                # Поворот вокруг оси y на НАКЛОН вниз.
                xп = x * math.cos(накл) + z * math.sin(накл)
                zп = -x * math.sin(накл) + z * math.cos(накл)
                yп = y
                дистанции = []
                # Пол: z = -ВЫСОТА.
                if zп < -1e-6:
                    дистанции.append(-ВЫСОТА / zп)
                # Стена впереди.
                if xп > 1e-6:
                    дистанции.append(стена / xп)
                    # Человек: столб на дистанции `человек` по x.
                    if человек is not None:
                        д = человек / xп
                        по_боку = abs(yп * д)
                        по_высоте = ВЫСОТА + zп * д
                        if по_боку < 0.25 and 0.05 < по_высоте < 0.9:
                            дистанции.append(д)
                живые = [д for д in дистанции if 0.05 < д <= 3.5]
                сетка[р][к] = min(живые) if живые else 0.0
        return сетка

    # --- как было: сырая сетка даёт пол ----------------------------------
    пустая_комната = кадр(человек=None)
    пол_как_цель = follow.найти_цель(пустая_комната)
    check("на сырой сетке цель находится в пустой комнате",
          пол_как_цель is not None, True)
    check("и это пол, ближе чем «стоять ближе»",
          пол_как_цель[0] < follow.СТОЯТЬ_БЛИЖЕ, True)
    вперёд, _ = follow.как_ехать(пол_как_цель[0], пол_как_цель[1], 0.0)
    check("то есть робот не ехал бы никуда", вперёд, 0.0)

    # --- как стало: пол вычеркнут ----------------------------------------
    пустой_взгляд = tof.Взгляд(пустая_комната, time.monotonic())
    check("плоскость пола находится", пустой_взгляд.плоскость is not None, True)
    check("и наклон датчика выведен верно",
          abs(пустой_взгляд.плоскость.наклон - НАКЛОН) < 2.0, True)
    check("в пустой комнате цели больше нет",
          follow.найти_цель(follow.без_пола(пустой_взгляд)), None)

    # --- человек на разных дистанциях -------------------------------------
    # Главное: ответ обязан ЗАВИСЕТЬ от того, где человек. На сырой сетке он
    # был одинаков для 1.0, 1.6 и 2.0 м — это и есть признак того, что робот
    # смотрел на пол, а не на человека.
    for метры in (1.0, 1.5, 2.0):
        взгляд = tof.Взгляд(кадр(человек=метры), time.monotonic())
        цель = follow.найти_цель(follow.без_пола(взгляд))
        check(f"человек в {метры} м найден", цель is not None, True)
        if цель is None:
            continue
        check(f"и дистанция похожа на правду ({цель[0]:.2f} м)",
              abs(цель[0] - метры) < 0.35, True)
        check("и пеленг почти по курсу", abs(math.degrees(цель[1])) < 8, True)
        вперёд, _ = follow.как_ехать(цель[0], цель[1], 1.5)
        # Между СТОЯТЬ_БЛИЖЕ и ЕХАТЬ_ДАЛЬШЕ робот стоит нарочно: без этого
        # зазора он дёргался бы на месте, пока человек стоит. Поэтому едем
        # только с тех дистанций, которые дальше зазора.
        if метры >= follow.ЕХАТЬ_ДАЛЬШЕ:
            check(f"робот с {метры} м едет вперёд", вперёд > 0, True)

    # --- начать() больше не врёт ------------------------------------------
    # Раньше пол всегда давал цель, ветка «Не вижу тебя» была недостижима, и
    # робот отвечал «Иду за тобой» в пустой комнате, после чего пять минут
    # стоял. Обещание, которого он не может выполнить, хуже отказа.
    import types

    пустой = types.SimpleNamespace(
        взгляд=lambda: tof.Взгляд(кадр(человек=None), time.monotonic()),
        мешает=lambda: "")
    колёса = types.SimpleNamespace(publish_twist=lambda *a: None,
                                   stop_motion=lambda: None, voltage=12.4)
    молчун = follow.Следование(колёса, пустой)
    check("в пустой комнате робот честно отказывается",
          "Не вижу тебя" in молчун.начать(), True)
    check("и никуда не пошёл", молчун.идёт, False)

    с_человеком = types.SimpleNamespace(
        взгляд=lambda: tof.Взгляд(кадр(человек=1.5), time.monotonic()),
        мешает=lambda: "")
    видящий = follow.Следование(колёса, с_человеком)
    check("а с человеком перед носом — соглашается",
          "Иду за тобой" in видящий.начать(), True)
    видящий.хватит("проверка")

    # Дальномер видит шестьдесят градусов, камера — сто тридцать. Человек,
    # стоящий чуть в стороне, для дальномера не существует, а на картинке он
    # посреди кадра. Отказывать ему значит требовать встать по линейке там,
    # где робот и так прекрасно его видит.
    #
    # Раньше эта развилка была не нужна и её не было: цель находилась всегда,
    # потому что ею оказывался пол. Вычеркнув пол, мы сделали отказ настоящим.
    камерой = follow.Следование(
        колёса, пустой,
        глаза=types.SimpleNamespace(свежий=True, угол=0.4, далеко_ли=1.5,
                                    забыть=lambda: None,
                                    сверить=lambda м: None))
    check("человека сбоку робот берёт по камере",
          "Иду за тобой" in камерой.начать(), True)
    камерой.хватит("проверка")

    # --- плоскость не нашлась — не гадаем ---------------------------------
    # Не зная, где пол, отличить человека от пола нечем, и «ближайшее пятно»
    # снова окажется полом. Пусть лучше робот скажет «не вижу»: неправда про
    # то, что он кого-то ведёт, дороже отказа.
    слепой = tof.Взгляд([[0.0] * 8 for _ in range(8)], time.monotonic())
    check("без плоскости сетка пустая",
          any(д for ряд in follow.без_пола(слепой) for д in ряд), False)


def test_кто_крутит_колёса() -> None:
    """У колёс один хозяин, и кнопка СТОП достаёт до каждого.

    Здесь чинится настоящая дыра в безопасности, найденная аудитом движения.
    Кнопка СТОП в пульте работает не проводом, а так: пульт публикует нули в
    /cmd_vel, робот их видит и понимает как «остановись». Понимание начиналось
    с вопроса «а мы вообще едем?» — и `moving` отвечал «нет», потому что знал
    только про drive(). Следование крутится своим потоком.

    То есть ВО ВРЕМЯ СЛЕДОВАНИЯ АВАРИЙНАЯ КНОПКА НЕ РАБОТАЛА ВОВСЕ. Ни одной
    ошибки в журнале, ни одного признака снаружи: человек жмёт, робот едет.
    А следование — единственный режим, в котором робот сам едет за человеком
    и в котором кнопка нужнее всего.

    Вторая половина той же дыры — распознавание своих нулей. Оно было по
    часам: «ноль моложе полусекунды — наш». При поездке это работало, потому
    что едущий робот публикует ненулевые скорости. А следование, стоя перед
    остановившимся человеком, публикует нули пятнадцать раз в секунду — и
    окно не закрывалось никогда, съедая любую кнопку.
    """
    section("кто крутит колёса")
    import threading as th
    import types

    from robot_voice.ros import Ros

    def шасси() -> tuple[Ros, list]:
        ros = Ros("ws://нет")
        ушло: list = []
        ros._send = lambda сообщение: (ушло.append(сообщение), True)[1]
        return ros, ушло

    def ноль(ros: Ros) -> None:
        """Как будто в /cmd_vel пришёл ноль — от пульта или эхом от себя."""
        ros._on_message(None, json.dumps({
            "op": "publish", "topic": "/cmd_vel",
            "msg": {"linear": {"x": 0.0, "y": 0.0, "z": 0.0},
                    "angular": {"x": 0.0, "y": 0.0, "z": 0.0}}}))

    # --- свои нули считаются штуками, а не по часам ----------------------
    ros, _ = шасси()
    остановлен: list[str] = []
    едет = {"да": True}
    ros.завести_движитель("проверка", lambda: едет["да"],
                          lambda почему: остановлен.append(почему))

    check("движитель делает робота едущим", ros.moving, True)

    # Робот стоит перед человеком и пятнадцать раз в секунду говорит шасси
    # «стою». Каждый такой ноль вернётся эхом, и съесть их надо все.
    for _ in range(20):
        ros.publish_twist()
    for _ in range(20):
        ноль(ros)
    check("на своё эхо не останавливаемся", остановлен, [])

    # А вот двадцать первый ноль послали не мы. Это кнопка.
    ноль(ros)
    check("чужой ноль останавливает всех", len(остановлен), 1)

    # Пульт шлёт пять нулей подряд — по одному стопу на каждый, и все доходят.
    остановлен.clear()
    for _ in range(5):
        ноль(ros)
    check("кнопка не тонет в собственных нулях", len(остановлен), 5)

    # --- ноль, не ушедший в закрытый сокет, в долг не пишется ------------
    # Иначе долг съел бы ровно столько же нажатий кнопки — молча.
    глухой, _ = шасси()
    глухой._send = lambda сообщение: False
    глухой.завести_движитель("проверка", lambda: True,
                             lambda почему: остановлен.append(почему))
    остановлен.clear()
    for _ in range(3):
        глухой.publish_twist()
    ноль(глухой)
    check("непосланный ноль не съедает кнопку", len(остановлен), 1)

    # Обрыв связи тоже обнуляет долг: наши нули до подписчика не дошли.
    порванный, _ = шасси()
    порванный.завести_движитель("проверка", lambda: True,
                                lambda почему: остановлен.append(почему))
    остановлен.clear()
    for _ in range(3):
        порванный.publish_twist()
    порванный._on_close(None)
    ноль(порванный)
    check("после обрыва связи кнопка работает сразу", len(остановлен), 1)

    # --- следование заявлено как движитель и останавливается кнопкой -----
    from robot_voice import follow

    пусто = [[0.0] * 8 for _ in range(8)]
    человек = [[0.0] * 8 for _ in range(8)]
    for р in range(2, 6):
        for к in range(3, 5):
            человек[р][к] = 1.6                 # стоит в полутора метрах
    тоф = types.SimpleNamespace(
        взгляд=lambda: types.SimpleNamespace(свежий=True, сетка=человек,
                                             сетка_без_пола=человек,
                                             свободно_впереди=1.6),
        мешает=lambda: "")

    живой, команды = шасси()
    ведомый = follow.Следование(живой, тоф)
    живой.завести_движитель("следование", lambda: ведомый.идёт,
                            lambda почему: ведомый.хватит(почему, ждать=False))
    check("до команды робот стоит", живой.moving, False)

    ответ = ведомый.начать()
    check("следование началось", "Иду за тобой" in ответ, True)
    time.sleep(0.3)
    check("и робот считается едущим", живой.moving, True)
    ходы = [с["msg"]["linear"]["x"] for с in команды]
    check("колёса правда крутятся", any(x > 1e-3 for x in ходы), True)

    # Человек жмёт СТОП. Съедаем ровно то эхо, что робот успел послать сам, а
    # дальше — кнопка. Столько нулей, сколько шлёт настоящий пульт.
    свои = sum(1 for с in команды
               if abs(с["msg"]["linear"]["x"]) + abs(с["msg"]["angular"]["z"]) <= 1e-3)
    for _ in range(свои):
        ноль(живой)
    for _ in range(5):
        ноль(живой)
    ведомый._поток.join(timeout=2)
    check("кнопка СТОП прекращает следование", ведомый.идёт, False)
    check("и причина названа", ведомый.почему_кончилось, "кнопка стоп")

    # Последнее слово в топик — ноль: шасси держит последнюю скорость, пока
    # ему не скажут иначе.
    хвост = команды[-1]["msg"]
    check("и колёса остановлены",
          abs(хвост["linear"]["x"]) + abs(хвост["angular"]["z"]) < 1e-6, True)

    # --- новая команда на колёса отбирает их у следования ----------------
    # Два потока по пятнадцать раз в секунду в один топик — это не «кто-то
    # победит», это робот, едущий в среднее направление.
    второй, _ = шасси()
    ведомый2 = follow.Следование(второй, тоф)
    второй.завести_движитель("следование", lambda: ведомый2.идёт,
                             lambda почему: ведомый2.хватит(почему, ждать=False))
    ведомый2.начать()
    time.sleep(0.2)
    check("следование идёт", ведомый2.идёт, True)
    второй.drive(0.2, 0.0, 0.0, 0.2)
    ведомый2._поток.join(timeout=2)
    check("команда «проедь» отбирает колёса", ведомый2.идёт, False)
    второй._motion.join(timeout=5)

    # --- отмена проверяется вплотную к публикации ------------------------
    # Между началом круга и подачей скорости проходят миллисекунды, и «стоп»,
    # пришедший в этот зазор, раньше давал ещё один шаг вперёд.
    третий, ходы3 = шасси()
    ведомый3 = follow.Следование(третий, тоф)
    ведомый3._стоп.set()
    check("после «стоп» скорость не уходит", ведомый3._крутить(0.5, 0.0), False)
    check("и в топик ничего не написано", ходы3, [])

    # --- следование без ros собирается и не падает -----------------------
    # Ros может не быть вовсе (запуск без шасси), и заявлять движитель тогда
    # некому — но сам класс обязан собираться.
    сирота = follow.Следование(None, None)
    check("без шасси следование не начинается",
          "дальномера нет" in сирота.начать(), True)


def test_мёртвая_рука() -> None:
    """Колёса встают, если тот, кто их крутил, замолчал.

    В коде робота с самого начала стояло утверждение: «шасси ждёт /cmd_vel
    непрерывно — при паузе оно само тормозит». Оно НЕВЕРНО для драйвера.
    В turn_on_wheeltec_robot Cmd_Vel_Callback пакует пришедший Twist в кадр
    для STM32 и пишет в серийник — и всё. Ни таймера, ни отметки времени, ни
    повторной посылки нуля; единственное обнуление в деструкторе, а он при
    kill -9 или segfault не зовётся.

    Значит буквально: последняя посланная скорость действует, пока не придёт
    следующая. Робот, у которого посреди поездки умер голосовой сервис,
    продолжает ехать.

    Отсюда две вещи, обе проверяются здесь. Первая — сторож мёртвой руки:
    отдельный процесс, который сам публикует нули, увидев тишину после хода.
    Отдельный процесс, а не поток: защищаемся мы как раз от смерти того
    процесса, и сторож внутри охраняемого охраняет ровно ничего.

    Вторая — честный крик. Порванная посреди хода связь оставляет шасси с
    последней дошедшей скоростью, и «стоп» тем же путём тоже не дойдёт.
    Сделать отсюда можно ровно одно: сказать вслух, потому что человек рядом
    и есть последний сторож.
    """
    section("мёртвая рука")
    import importlib.util
    import types

    корень = Path(__file__).resolve().parent.parent
    спец = importlib.util.spec_from_file_location(
        "cmd_vel_watchdog", корень / "scripts" / "cmd_vel_watchdog.py")
    сторожок = importlib.util.module_from_spec(спец)
    спец.loader.exec_module(сторожок)

    def письмо(x: float, wz: float = 0.0) -> str:
        return json.dumps({
            "op": "publish", "topic": "/cmd_vel",
            "msg": {"linear": {"x": x, "y": 0.0, "z": 0.0},
                    "angular": {"x": 0.0, "y": 0.0, "z": wz}}})

    сторож = сторожок.Сторож("ws://нет")
    послано: list = []
    сторож._послать = lambda что: (послано.append(что), True)[1]
    сторожок.ТИШИНА_ДО_СТОПА = 0.2

    поток = threading.Thread(target=сторож.сторожить, daemon=True)
    поток.start()

    # Никто никуда не едет — сторожу делать нечего.
    time.sleep(0.4)
    check("на стоящего робота сторож не лезет", послано, [])

    # Робот едет и издатель жив: команды идут пятнадцать раз в секунду.
    конец = time.monotonic() + 0.5
    while time.monotonic() < конец:
        сторож._сообщение(None, письмо(0.2))
        time.sleep(1 / 15)
    check("живого издателя сторож не трогает", послано, [])

    # Издатель умер. Через ТИШИНА_ДО_СТОПА колёса обязаны встать.
    time.sleep(сторожок.ТИШИНА_ДО_СТОПА + 0.3)
    нули = [п for п in послано if п.get("op") == "publish"
            and abs(п["msg"]["linear"]["x"]) + abs(п["msg"]["angular"]["z"]) < 1e-9]
    check("умолкшего издателя сторож перебивает нулём", bool(нули), True)
    check("и шлёт их несколько — пакет может потеряться",
          len(нули) >= сторожок.НУЛЕЙ, True)

    # Свой же ноль вернулся эхом — тревога снимается, и сторож не долбит в
    # топик вечно. Иначе он забил бы канал и мешал бы новой команде.
    послано.clear()
    сторож._сообщение(None, письмо(0.0))
    time.sleep(сторожок.ТИШИНА_ДО_СТОПА + 0.3)
    check("после остановки сторож замолкает", послано, [])

    # Поворот на месте — тоже ход. Робот, крутящийся на месте после смерти
    # издателя, опаснее едущего: он заметает углами корпуса сектор, которого
    # не видит вовсе.
    послано.clear()
    сторож._сообщение(None, письмо(0.0, wz=0.8))
    time.sleep(сторожок.ТИШИНА_ДО_СТОПА + 0.3)
    check("брошенный поворот тоже останавливается", bool(послано), True)

    сторож.стоп()
    поток.join(timeout=2)

    # --- порванная связь: робот кричит, а не молчит ----------------------
    from robot_voice.ros import Ros

    оборванный = Ros("ws://нет")
    сказано: list[str] = []
    оборванный.объявить = сказано.append
    оборванный._send = lambda что: False        # ничего не уходит

    # Пока стоим — молчим: неработающие колёса стоящего робота не опасны, и
    # робот, причитающий о связи посреди тишины, надоест за день.
    for _ in range(10):
        оборванный.publish_twist()
    check("на стоянке про связь не причитаем", сказано, [])

    for _ in range(10):
        оборванный.publish_twist(0.2, 0.0, 0.0)
    time.sleep(0.3)
    check("про потерю связи на ходу робот говорит", len(сказано), 1)
    check("и говорит понятно", "выключи" in сказано[0].lower(), True)

    # Говорит ОДИН раз, а не пятнадцать в секунду.
    for _ in range(30):
        оборванный.publish_twist(0.2, 0.0, 0.0)
    time.sleep(0.3)
    check("но не тараторит", len(сказано), 1)

    # Связь вернулась — тревога снимается, и следующий обрыв снова будет
    # услышан. Без сброса робот смолчал бы во второй раз.
    оборванный._send = lambda что: True
    оборванный.publish_twist(0.2, 0.0, 0.0)
    оборванный._send = lambda что: False
    for _ in range(10):
        оборванный.publish_twist(0.2, 0.0, 0.0)
    time.sleep(0.3)
    check("второй обрыв тоже слышен", len(сказано), 2)

    # --- утверждение про самоторможение вычищено из кода -----------------
    # Оно было неверным и load-bearing: на нём держалась уверенность, что
    # упавший сервис не оставит робота едущим. Комментарий, уверенно врущий
    # про физику, хуже отсутствия комментария.
    исходник = (корень / "voice" / "robot_voice" / "ros.py").read_text(
        encoding="utf-8")
    check("в коде больше не написано, что шасси тормозит само",
          "при паузе оно само тормозит" in исходник, False)
    check("и сказано, чем проверить на роботе",
          "check_deadman" in исходник, True)


def test_slicing() -> None:
    """Нарезка на фразы: что уезжает в распознавание, а что нет.

    Два порога тут не работали вовсе. Одиночный щелчок проходил как секунда
    почти-тишины, потому что «речевыми» считались и предбуфер, и семьсот
    миллисекунд тишины на конце. А непрерывный шум длиннее двадцати секунд
    не отбрасывался, а отдавался как обычная фраза — и робот замолкал на
    минуту, потому что распознавание идёт втрое дольше самого звука.
    """
    section("нарезка на фразы")
    прогон = прогон_фраз

    # Признак «микрофон на связи». Сервер робота подсыпает ровные нули, чтобы
    # соединение не уснуло, и по «кадры идут» источник выглядел живым всегда:
    # робот бодро сообщал «микрофон на связи» и при закрытой вкладке.
    from robot_voice.audio import BrowserSource, Pump
    источник = BrowserSource("http://тест", 16000)
    насос = Pump(источник)
    насос.online = True
    check("одна тишина — микрофон не считается живым", насос.alive, False)
    источник._real_at = __import__("time").monotonic()
    check("пришёл настоящий звук — живой", насос.alive, True)
    check("источник без своего мнения не мешает",
          Pump(types.SimpleNamespace()).alive, False)

    check("одиночный щелчок отброшен",
          прогон([(False, 20), (True, 2), (False, 40)]), [])
    check("настоящая фраза проходит",
          len(прогон([(False, 20), (True, 50), (False, 40)])), 1)
    # Раньше такой кусок выбрасывался целиком. В живой квартире люди говорят
    # не умолкая, паузы в полсекунды не случается по двадцать секунд кряду — и
    # вместе с чужим разговором выбрасывалось обращение к роботу, если оно
    # прозвучало внутри. Теперь кусок уходит в разбор с пометкой.
    check("двадцать секунд без паузы приезжают куском",
          прогон([(True, 1000), (False, 40)]), [10.0])
    check("и помечены как срез комнаты",
          прогон([(True, 1000), (False, 40)], с_флагами=True), [(10.0, True)])
    check("обычная фраза срезом не считается",
          прогон([(False, 20), (True, 50), (False, 40)], с_флагами=True)[0][1],
          False)
    check("после длинного куска слух возвращается",
          прогон([(True, 1000), (False, 40), (True, 50), (False, 40)])[-1] < 2.0,
          True)


def test_stop_while_thinking() -> None:
    """«Стоп», сказанный пока робот думает, не должен пропадать.

    Главный цикл в это время висит в разговоре с моделью и фраз не читает, а
    модель могла уже отправить робота ехать — поездка длится до пятнадцати
    секунд. Мгновенной остановки тут нет и не обещается, но потерять команду
    совсем нельзя.
    """
    section("«стоп» из паузы не теряется")
    from robot_voice.app import _caught_stop

    stopped: list[str] = []
    ros = types.SimpleNamespace(moving=True,
                                stop_motion=lambda: stopped.append("стоп"))
    # Распознаватель тут простой: что подсунули, то и «услышал».
    ears = types.SimpleNamespace(transcribe=lambda wav: wav.decode())

    check("«стоп» пойман", _caught_stop("стоп".encode(), ears, ros), True)
    check("колёса встали", stopped, ["стоп"])

    stopped.clear()
    check("обычная фраза не останавливает",
          _caught_stop("а сколько времени".encode(), ears, ros), False)
    check("мусор не останавливает", _caught_stop("...".encode(), ears, ros), False)
    check("пустой хвост не разбираем", _caught_stop(b"", ears, ros), False)

    ros.moving = False
    check("стоим — разбирать нечего", _caught_stop("стоп".encode(), ears, ros), False)
    check("лишних остановок не было", stopped, [])

    # Сбой распознавания не должен ронять ответ: это происходит в блоке,
    # который выполняется уже после того, как робот всё сказал.
    падучий = types.SimpleNamespace(
        transcribe=lambda wav: (_ for _ in ()).throw(RuntimeError("нет связи")))
    ros.moving = True
    check("сбой распознавания не роняет", _caught_stop("звук".encode(), падучий, ros), False)


def test_wake_stream() -> None:
    """Имя ловится на потоке, и до него паузы не ждём вовсе.

    Прежняя нарезка резала по паузам и искала имя в расшифровке. В комнате, где
    разговаривают не умолкая, паузы не случается, кусок рос до предела длины —
    и робот отзывался через столько секунд, сколько этот предел. Со стороны
    выглядело как «пропускает восемь команд из десяти».
    """
    import threading as th
    from collections import deque

    import numpy as np

    from robot_voice import audio
    from robot_voice.wake import sounds_like_wake

    section("ловля имени на потоке")

    # Нечёткое сравнение переехало в wake.py — проверяем, что не растеряло
    # варианты, ради которых заводилось.
    имена = ("кузя", "кузь", "куся")
    for слово in ("кузя", "хузя", "куся", "кузь"):
        check(f"«{слово}» — имя", sounds_like_wake(слово, имена, 0.75), True)
    for слово in ("кухня", "коля", "пуля", ""):
        check(f"«{слово}» — не имя", sounds_like_wake(слово, имена, 0.75), False)

    def прогон(до_имени: int, команда, command_frames: int = 100,
               имя_прозвучит: bool = True, приказ_на: int = 0,
               приказ: str = "стоп", спешим=None):
        """До имени — сколько кадров шумит комната; команда — (речь?, кадров).

        Разделено намеренно: детектор имени и детектор речи вызываются в разные
        моменты, и общий список признаков между ними разъезжается. Здесь у
        каждого свой отсчёт, как и в жизни.
        """
        признаки = []
        for речь, n in команда:
            признаки.extend([речь] * n)
        кадры = [np.zeros(160, dtype=np.int16)
                 for _ in range(до_имени + len(признаки))]
        подряд = iter(признаки)
        счётчик = {"n": 0}
        сбросов = {"n": 0}

        приказов = {"n": 0}

        class Ухо:
            def услышал(self, frame):
                счётчик["n"] += 1
                return имя_прозвучит and счётчик["n"] == до_имени

            def команда(self, frame):
                приказов["n"] += 1
                return приказ if приказов["n"] == приказ_на else ""

            def сбросить(self):
                сбросов["n"] += 1

        l = audio.Listener.__new__(audio.Listener)
        l.pump = types.SimpleNamespace(start=lambda: None,
                                       frames=lambda: iter(кадры))
        l.sample_rate = 16000
        l.vad = types.SimpleNamespace(is_speech=lambda *a: next(подряд))
        l.silence_frames, l._min_speech = 35, 15
        l.max_speech_frames = 1000
        l._start, l.preroll = 2, deque(maxlen=15)
        l._noisy = False
        l._muted = th.Event()
        l.long_chunk = False
        l.wake_heard = False
        l.on_wake = None
        l.instant = ""
        l.spotter = Ухо()
        # Спешить есть куда: иначе мгновенный слой закрыт и приказы не ловятся
        # вовсе — отдельный случай проверяется ниже.
        l.спешим = спешим
        l.command_frames = command_frames
        # Определителя конца реплики тут нет намеренно: эта проверка про
        # нарезку по тишине, и она обязана работать без него — иначе
        # отсутствующая модель означала бы онемевшего робота.
        l.конец_реплики = None
        куски, приказы = [], []
        for w in l.utterances():
            куски.append(round((len(w) - 44) / 2 / 16000, 1))
            приказы.append(l.instant)
        return куски, l.wake_heard, сбросов["n"], приказы

    # Двести кадров непрерывной речи до имени: прежняя нарезка застряла бы в
    # них до самого предела длины и отозвалась бы через двадцать секунд. Здесь
    # они просто проходят мимо, а команда за именем приезжает по своей паузе.
    куски, услышано, _, _ = прогон(200, [(True, 50), (False, 40)])
    check("команда после имени приехала", len(куски), 1)
    check("и помечена как названная по имени", услышано, True)

    # Услышали имя — музыку надо приглушить НЕМЕДЛЕННО, ещё до распознавания:
    # человек уже говорит, и перекрикивать песню он не должен.
    from robot_voice.music import Player

    class ТихийПульт:
        def __init__(self): self.громкости = []
        def громкость(self, доля): self.громкости.append(доля); return True
        def поток(self, адрес): return True
        def трек(self, адрес, название=""): return True
        def сыграно(self): return 0

    пульт = ТихийПульт()
    плеер = Player(пульт, громкость=0.8)
    плеер.приглушить(True)
    check("позвали — музыка убавилась", пульт.громкости[-1] < 0.8, True)
    сколько = len(пульт.громкости)
    плеер.приглушить(True)
    check("повторный зов не дёргает громкость заново",
          len(пульт.громкости), сколько)
    плеер.приглушить(False)
    check("ход кончился — вернулась ровно та же", пульт.громкости[-1], 0.8)

    # Короткий приказ сразу за именем не должен ждать ни паузы, ни ПК: «стоп»
    # для едущего робота — это лишний метр проезда за каждую секунду.
    from robot_voice.wake import МГНОВЕННЫЕ
    куски, _, _, приказы = прогон(10, [(True, 200), (False, 40)], приказ_на=3)
    check("приказ оборвал запись, не дожидаясь паузы", len(куски), 1)
    check("и приехал готовой фразой", приказы[0], "стоп")
    check("запись коротка — распознавать нечего", куски[0] < 0.5, True)

    # Обычная фраза приказом не считается: признак должен быть пуст, иначе
    # распознавание пропустят и робот выполнит не то.
    _, _, _, приказы = прогон(10, [(True, 50), (False, 40)], приказ_на=0)
    check("без приказа признак пуст", приказы[0], "")

    # Робот стоит — мгновенный слой закрыт целиком. Он затевался ради «стоп»
    # едущему, а на стоящем даёт только ложные срабатывания: словарь у
    # детектора узкий, и Vosk обязан впихнуть в него любой звук. На живом
    # роботе «Кузя, что ты ВИдишь» трижды подряд услышалось как «ТИше», и
    # робот убавлял громкость вместо ответа.
    куски, _, _, приказы = прогон(10, [(True, 200), (False, 40)],
                                  приказ_на=3, спешим=lambda: False)
    check("стоящий робот приказов не ловит", приказы[0], "")
    check("фраза записана целиком и поедет распознаваться",
          куски[0] > 0.5, True)

    # А едущий — ловит, и это единственное, ради чего слой существует.
    _, _, _, приказы = прогон(10, [(True, 200), (False, 40)],
                              приказ_на=3, спешим=lambda: True)
    check("едущий робот приказ ловит", приказы[0], "стоп")

    # В мгновенном слое только срочное. «Тише» и «следующая» оттуда убраны:
    # опоздание там незаметно, а ложное срабатывание сбивает разговор.
    check("громкость и музыка мгновенными не считаются",
          sorted(set(МГНОВЕННЫЕ.values())), ["замолчи", "стоп"])

    # Правила обязаны понимать то, что отдаёт детектор: иначе приказ
    # опознан, а выполнить его нечем — и фраза молча уйдёт модели.
    from robot_voice import intents
    не_понято = sorted({ф for ф in МГНОВЕННЫЕ.values()
                        if intents.parse(ф) is None})
    check("все мгновенные приказы разбираются правилами", не_понято, [])

    # Не позвали — не слушаем, сколько бы в комнате ни говорили.
    куски, услышано, _, _ = прогон(500, [(True, 50), (False, 40)],
                                   имя_прозвучит=False)
    check("без имени ничего не отдаём", куски, [])
    check("и признак не поднят", услышано, False)

    # Команда кончается по паузе — это единственное, ради чего тут нужен
    # детектор речи. Вторая фраза без нового имени наружу не идёт.
    куски, _, _, _ = прогон(5, [(True, 50), (False, 40), (True, 50), (False, 40)])
    check("одно имя — одна команда", len(куски), 1)

    # Длинная команда упирается в свой предел. Но это предел ОДНОЙ реплики, а
    # не времени, через которое робот отзовётся, — в этом вся разница.
    куски, _, _, _ = прогон(5, [(True, 300), (False, 40)], command_frames=100)
    check("слишком длинная команда обрезается", len(куски), 1)
    check("обрезана по своему пределу, а не по паузе", куски[0] < 1.5, True)


def test_sound_cards() -> None:
    """Робот должен слушать и говорить именно в ту карту, которую назвали.

    Пока карта была одна, «по умолчанию» работало само. С USB-микрофоном их
    две, и умолчание превращается в лотерею: ALSA отдаёт ту, что первой
    попалась. Проверяется, что заданное устройство доезжает до arecord и до
    aplay, а не теряется по дороге.
    """
    section("выбор звуковой карты")
    from robot_voice.audio import LocalSource, make_source
    from robot_voice.tts import Speaker, aplay_cmd

    check("без устройства -D нет", "-D" in aplay_cmd(16000), False)
    check("с устройством -D есть",
          aplay_cmd(16000, "plughw:1,0")[-3:], ["-D", "plughw:1,0", "-"])
    check("пробелы вокруг имени не ломают команду",
          "-D" in aplay_cmd(16000, "  "), False)
    check("частота на месте", "16000" in aplay_cmd(16000, "plughw:1,0"), True)

    источник = make_source("local", "", 16000, mic_device="plughw:0,0")
    check("микрофон дошёл до источника",
          (isinstance(источник, LocalSource), источник.device),
          (True, "plughw:0,0"))
    # Пусто — не «никакая карта», а системная: иначе arecord получил бы -D ""
    # и не запустился вовсе.
    check("без имени слушаем умолчание",
          make_source("local", "", 16000).device, "default")
    check("пробелы — тоже умолчание",
          make_source("local", "", 16000, mic_device="  ").device, "default")
    check("браузеру устройство ни к чему",
          hasattr(make_source("browser", "", 16000, mic_device="plughw:0,0"),
                  "device"),
          False)

    # Speaker без piper выключается, но устройство запомнить обязан: иначе
    # правка «поставил ReSpeaker» тихо не доедет до aplay.
    динамик = Speaker(Path("нет-такого-голоса.onnx"), audio_out="local",
                      spk_device="plughw:1,0")
    check("динамик запомнил карту", динамик.spk_device, "plughw:1,0")


def test_barge_in() -> None:
    """Человек может перебить длинную реплику словом «хватит».

    Жалоба с живого робота: «когда робот говорит, он меня не слушает — на
    большой фразе хочется его прервать». И правда: микрофон на время реплики
    заглушён, потому что аппаратного эхоподавления нет и на полном словаре
    робот распознаёт собственный голос.

    Одно ухо теперь открыто: отдельный распознаватель на десяток слов. Это
    работает без эхоподавления по трём причинам, и здесь проверяются все три.
    """
    section("перебить говорящего робота")
    import threading as th
    from collections import deque

    import numpy as np

    from robot_voice import audio
    from robot_voice.wake import ПЕРЕБИВАНИЕ, clean_token

    # 1. Словарь узкий, и в нём есть то, чем люди перебивают на самом деле.
    for слово in ("хватит", "стоп", "замолчи", "тихо", "погоди", "всё"):
        check(f"«{слово}» перебивает", слово in ПЕРЕБИВАНИЕ, True)
    check("словарь остался маленьким", len(ПЕРЕБИВАНИЕ) <= 15, True)

    # --- «стоп» едущему роботу останавливает КОЛЁСА, а не только речь -----
    # Дыру завело само перебивание, и она из худших. Робот, едущий и говорящий
    # одновременно, на крик «стоп» послушно замолкал и ЕХАЛ ДАЛЬШЕ: микрофон
    # в это время заглушён, обычный путь команды закрыт, а перебивание
    # касалось только речи.
    колёсные = [с for с, ч in ПЕРЕБИВАНИЕ.items() if ч == "колёса"]
    for слово in ("стоп", "стой", "хватит"):
        check(f"«{слово}» останавливает колёса",
              ПЕРЕБИВАНИЕ.get(слово), "колёса")
    # А «ясно» и «понял» — это «замолчи», а не «стой». Человек услышал
    # достаточно; тормозить робота посреди поездки он не просил.
    for слово in ("ясно", "понял", "всё", "тихо"):
        check(f"«{слово}» просит только замолчать",
              ПЕРЕБИВАНИЕ.get(слово), "молчи")
    check("останавливающих слов несколько", len(колёсные) >= 3, True)

    # 2. САМОЕ ВАЖНОЕ: слово, которое робот произносит сам, не годится.
    # Без этой проверки рассказ про умения останавливал бы сам себя — в нём
    # есть строка «могу остановиться по слову стоп». Берём живой текст.
    рассказ = ("Я умею ездить по квартире и разворачиваться, могу "
               "остановиться по слову стоп.")
    своё = {clean_token(с) for с in рассказ.lower().split()}
    самоубийство = [с for с in ПЕРЕБИВАНИЕ if с in своё]
    check("в рассказе про умения есть слово перебивания", самоубийство, ["стоп"])
    # А значит проверка обязана его отсеять — иначе робот немеет на первой фразе.
    check("и оно отсеивается как своё",
          [с for с in ПЕРЕБИВАНИЕ if с in своё and с not in своё], [])

    # 3. Второй читатель звука не мешает первому: обычная нарезка на фразы
    # должна получить те же кадры, что и раньше.
    насос = audio.Pump.__new__(audio.Pump)
    насос._frames = deque(maxlen=10)
    насос._ready = th.Condition()
    насос._всего = 0
    насос._stop = False
    for i in range(4):
        насос._frames.append(np.array([i], dtype=np.int16))
        насос._всего += 1
    было = 0
    свежак, было = насос.свежие(было)
    check("второй читатель видит накопленное", len(свежак), 4)
    свежак, было = насос.свежие(было)
    check("и не видит его дважды", свежак, [])
    насос._frames.append(np.array([9], dtype=np.int16))
    насос._всего += 1
    свежак, было = насос.свежие(было)
    check("а новый кадр видит", [int(к[0]) for к in свежак], [9])
    # Кадры остались на месте: обычная нарезка их ещё не читала.
    check("первому читателю ничего не досталось из очереди",
          len(насос._frames), 5)

    # Кольцевая очередь переполнилась, пока перебивание не смотрело: отдаём
    # что есть, а не падаем и не выдумываем. Курсор при этом обязан
    # догнать реальность, иначе отставание останется навсегда.
    for i in range(20):
        насос._frames.append(np.array([100 + i], dtype=np.int16))
        насос._всего += 1
    свежак, было = насос.свежие(было)
    check("после переполнения берём что есть", len(свежак), 10)
    check("и курсор догнал", было, насос._всего)


def test_поток_связи_не_заклинить() -> None:
    """Никто из подписчиков не смеет заблокировать поток связи с шасси.

    Это самый дорогой инвариант во всём роботе, и он невидим глазом. По
    одному вебсокету идут: отклики колёс, эхо /cmd_vel (единственный путь
    кнопки СТОП), детекции людей, жесты и вещи. Разбирает их ОДИН поток. Если
    обработчик в нём заговорит — а `voice.say` держит замок на всю длину
    реплики, — робот на это время перестанет слышать шасси и кнопку «стоп».

    Хуже того, `cancel_motion` в этом же потоке ждёт подтверждения, которое
    приходит по нему же: он сам себе не даст его принять и провисит до
    таймаута.

    Поэтому правило: обработчик разбирает сообщение и, если надо что-то
    сделать, отдаёт это отдельному потоку. Проверяется разбором исходника, а
    не запуском: app.main лезет в железо и в сеть.
    """
    section("поток связи с шасси не заклинить")
    import ast

    ОПАСНЫЕ = {"say", "cancel_motion", "stop_motion", "sleep", "join",
               "хватит", "начать", "перебили", "status"}

    корень = Path(__file__).resolve().parent.parent
    дерево = ast.parse((корень / "voice" / "robot_voice" / "app.py").read_text(
        encoding="utf-8"))

    подписчики = {}
    for у in ast.walk(дерево):
        if not isinstance(у, ast.Assign):
            continue
        for куда in у.targets:
            if (isinstance(куда, ast.Attribute)
                    and куда.attr.endswith("_видно")):
                подписчики[куда.attr] = у.value

    check("подписчики на месте", sorted(подписчики),
          ["вещи_видно", "жесты_видно", "людей_видно"])

    функции = {у.name: у for у in ast.walk(дерево)
               if isinstance(у, ast.FunctionDef)}

    def грехи(имя: str):
        """Опасные вызовы ВНЕ вложенной функции (то есть в самом потоке)."""
        узел = функции.get(имя)
        if узел is None:
            return None
        внутри = set()
        for в in ast.walk(узел):
            if isinstance(в, ast.FunctionDef) and в is not узел:
                внутри |= {id(x) for x in ast.walk(в)}
        найдено = []
        for в in ast.walk(узел):
            if not isinstance(в, ast.Call) or id(в) in внутри:
                continue
            зовут = в.func.attr if isinstance(в.func, ast.Attribute) else (
                в.func.id if isinstance(в.func, ast.Name) else "")
            if зовут in ОПАСНЫЕ:
                найдено.append(f"{зовут}:{в.lineno}")
        return найдено

    # Разбор сообщения — можно. Всё, что ждёт, говорит или тормозит колёса, —
    # только из отдельного потока.
    for имя in ("детекция", "человек_упал", "жест_показали"):
        found = грехи(имя)
        check(f"{имя} не блокирует поток связи", found, [])

    # А те, кто ДОЛЖЕН что-то делать, обязаны заводить поток. Иначе проверка
    # выше проходила бы просто оттого, что обработчик ничего не делает.
    for имя in ("человек_упал", "жест_показали"):
        узел = функции.get(имя)
        есть_поток = any(isinstance(в, ast.Call)
                         and "Thread" in ast.unparse(в.func)
                         for в in ast.walk(узел))
        check(f"{имя} отдаёт работу отдельному потоку", есть_поток, True)

    # И в самом ros.py каждый подписчик обёрнут: сбой разбора чужого
    # сообщения не имеет права уронить связь, по которой ходит «стоп».
    ros_дерево = ast.parse((корень / "voice" / "robot_voice" / "ros.py")
                           .read_text(encoding="utf-8"))
    сообщение = next(у for у in ast.walk(ros_дерево)
                     if isinstance(у, ast.FunctionDef) and у.name == "_on_message")
    зовут_подписчиков = [в for в in ast.walk(сообщение)
                         if isinstance(в, ast.Call)
                         and isinstance(в.func, ast.Name)
                         and в.func.id == "если_есть"]
    check("подписчиков зовут трижды — люди, жесты, вещи",
          len(зовут_подписчиков), 3)
    защищены = sum(1 for т in ast.walk(сообщение) if isinstance(т, ast.Try)
                   for в in ast.walk(т)
                   if isinstance(в, ast.Call) and isinstance(в.func, ast.Name)
                   and в.func.id == "если_есть")
    check("и каждый обёрнут в try", защищены, len(зовут_подписчиков))


def test_выключатели() -> None:
    """Сторож падений и жесты выключены, и обе половины выключателя сходятся.

    Выключены не из-за качества, а потому что робот и человек учатся
    одновременно: каждая штука, которая сама трогает колёса и сама
    заговаривает, добавляется к списку того, что может удивить, и понять, кто
    именно виноват, становится труднее. Пока не отлажено следование — лишнее
    мешает.

    ГЛАВНОЕ ЗДЕСЬ — ЧТО ПОЛОВИН ДВЕ. У жестов выключатель гасит и слушателя в
    app.py, и два узла BPU в launch. Погасить только слушателя — плата
    продолжит считать две сети тридцать раз в секунду, а результат никто не
    прочтёт. Погасить только узлы — робот будет ждать топика, которого нет.
    Разъехаться этим половинам нельзя, поэтому имя переменной проверяется в
    обоих файлах.
    """
    section("выключатели: падения и жесты")
    import ast

    корень = Path(__file__).resolve().parent.parent
    настройки = (корень / "voice" / "robot_voice" / "config.py").read_text(
        encoding="utf-8")
    приложение = (корень / "voice" / "robot_voice" / "app.py").read_text(
        encoding="utf-8")
    запуск = (корень / "scripts" / "mono2d_no_web.launch.py").read_text(
        encoding="utf-8")

    # По умолчанию — выключено. Не «забыли включить», а решение.
    for имя in ("ROBOT_FALLDOWN", "ROBOT_GESTURES"):
        check(f"{имя} по умолчанию выключен",
              f'_env("{имя}", "0") == "1"' in настройки, True)

    # Слушатели заводятся только по флагу.
    check("сторож падений за флагом", "cfg.сторож_падений" in приложение, True)
    check("жесты за флагом", "cfg.жесты" in приложение, True)

    # И ВТОРАЯ ПОЛОВИНА: узлы BPU гасятся той же переменной.
    check("узлы жестов гасятся тем же именем",
          "ROBOT_GESTURES" in запуск, True)

    # Никакого второго имени для того же выключателя быть не должно: два имени
    # однажды разойдутся, и плата будет считать то, чего никто не слушает.
    имена_в_запуске = {с.value for с in ast.walk(ast.parse(запуск))
                       if isinstance(с, ast.Constant) and isinstance(с.value, str)
                       and с.value.startswith("ROBOT_")}
    check("в запуске ровно одна переменная про жесты",
          sorted(имена_в_запуске), ["ROBOT_GESTURES"])

    # Выключено — не удалено. Код и разбор обязаны остаться на месте: включать
    # обратно правкой одной строки, а не переписыванием заново.
    for модуль in ("falldown", "gestures"):
        check(f"{модуль}.py на месте",
              (корень / "voice" / "robot_voice" / f"{модуль}.py").exists(), True)

    # И разбор внутри них по-прежнему рабочий — проверки выше это и делают.
    from robot_voice import falldown, gestures
    check("сторож падений собирается", falldown.Сторож() is not None, True)
    check("жесты собираются", gestures.Жесты() is not None, True)


def test_дневник() -> None:
    """Память робота о самом себе — то, на чём он будет учиться.

    Навыки — это память о ПРОСЬБАХ: собрал новое действие, сделал, запомнил.
    Дневник — память о СЕБЕ. Без него робот не знает про себя ничего: каждый
    вечер просят одно и то же — не заметил; на кухне срывается всегда, а в
    коридоре никогда — не выучил. Порог наклона дальномера оказался вчетверо
    ниже собственного шума, и нашлось это только потому, что человек прислал
    журнал руками.

    Дневник — не журнал. Журнал построчный и для человека; его нельзя ни
    сложить, ни спросить «сколько раз за неделю». Дневник для СЧЁТА.
    """
    section("дневник робота")
    import tempfile

    from robot_voice import diary

    часы = [1_700_000_000.0]
    файл = Path(tempfile.mkdtemp()) / "дневник.jsonl"
    д = diary.Дневник(файл, часы=lambda: часы[0])

    д.записать("запуск", версия="abc123")
    д.записать("реплика", команда="включи радио", как="правило", мс=1400)
    д.записать("следование", итог="потерял", сорвалось=True, секунд=12.0,
               x=1.5, y=0.3)
    check("записи легли", len(д.всё()), 3)
    check("поля на месте", д.всё()[1]["команда"], "включи радио")
    # Двойное время: настенное может соврать (у платы нет батарейки часов, на
    # живом роботе разъезжалось на пять часов), а порядок внутри запуска — нет.
    check("настенное время есть", д.всё()[0]["когда"], round(часы[0], 1))
    check("и время от старта тоже", "от_старта" in д.всё()[0], True)
    # Пустые поля не пишем: дневник читается роботом, и «итог: null» в каждой
    # строке — это только место и шум.
    check("пустое поле не записано", "версия" in д.всё()[1], False)

    свод = д.свод(24)
    check("свод считает всё", свод["всего"], 3)
    check("и по видам", свод["по_видам"]["реплика"], 1)
    check("и срывы", свод["срывов"], 1)

    # Старое отсекается по времени, а не по «сколько влезло».
    часы[0] += 25 * 3600
    check("вчерашнее не попадает в сутки", д.свод(24)["всего"], 0)
    check("но за двое суток видно", д.свод(48)["всего"], 3)

    # --- повторы: ради этого дневник и заводился ------------------------
    д2 = diary.Дневник(Path(tempfile.mkdtemp()) / "д.jsonl",
                       часы=lambda: часы[0])
    # Четыре вечера подряд в один и тот же час.
    for день in range(4):
        часы[0] = 1_700_000_000.0 + день * 24 * 3600
        д2.записать("реплика", команда="включи радио")
        д2.записать("реплика", команда=f"который час {день}")
    часы[0] = 1_700_000_000.0 + 4 * 24 * 3600
    повторы = д2.повторы(часов=24 * 7, хватит=3)
    check("повтор замечен", [п["повод"] for п in повторы], ["включи радио"])
    check("и посчитан", повторы[0]["раз"], 4)
    check("разовое не считается за привычку",
          any("который час" in п["повод"] for п in повторы), False)

    # ВРЕМЯ МОЖЕТ ВРАТЬ. У платы нет батарейки часов: если сети при загрузке
    # не было, время остаётся каким попало. Предлагать расписание по такому
    # времени — значит будить человека не тогда.
    д3 = diary.Дневник(Path(tempfile.mkdtemp()) / "д.jsonl",
                       часы=lambda: часы[0])
    настоящее = часы[0]
    часы[0] = 100.0                     # часы уехали в 1970-й
    for _ in range(5):
        д3.записать("реплика", команда="включи радио")
    часы[0] = настоящее
    check("по нелепому времени привычек не выдумываем",
          д3.повторы(часов=24 * 365 * 60, хватит=3), [])

    # --- подрезка --------------------------------------------------------
    д4 = diary.Дневник(Path(tempfile.mkdtemp()) / "д.jsonl",
                       часы=lambda: часы[0], предел=50)
    for i in range(120):
        д4.записать("реплика", команда=f"раз {i}")
    д4.подрезать()
    осталось = д4.всё()
    check("подрезано до предела", len(осталось), 50)
    check("оставлено СВЕЖЕЕ, а не первое попавшееся",
          осталось[-1]["команда"], "раз 119")

    # --- ничего не роняет ------------------------------------------------
    # Дневник вспомогательный. Робот, упавший из-за того, что не смог
    # записать про себя строчку, хуже робота без дневника.
    # Путь ВНУТРИ файла, а не просто несуществующий: несуществующий каталог
    # дневник создаёт сам, и под root он создастся даже там, где не должен.
    # /dev/null — файл, каталогом ему не стать никогда.
    д5 = diary.Дневник(Path("/dev/null/д.jsonl"), часы=lambda: часы[0])
    try:
        д5.записать("реплика", команда="в никуда")
        упало = False
    except Exception:                       # noqa: BLE001
        упало = True
    check("некуда писать — не падаем", упало, False)
    check("и читается это как пусто", д5.всё(), [])

    # Битая строка от выключения питания посреди записи не должна унести
    # с собой остальные.
    with open(файл, "a", encoding="utf-8") as f:
        f.write('{"что": "оборва')
    check("битая строка пропускается, целые остаются", len(д.всё()), 3)

    # Длинные реплики режем: дневник для счёта, а не стенограмма.
    д.записать("реплика", команда="я" * 500)
    check("длинное укорочено", len(д.всё()[-1]["команда"]) <= diary.ДЛИНА + 1,
          True)

    # Версия кода — чтобы «срывы участились» стало вопросом с ответом:
    # изменилась квартира или изменился робот.
    check("версию кода читаем без запуска git",
          isinstance(diary.сборка(), str), True)


def test_следование_не_ждёт_на_речи() -> None:
    """Цикл следования не имеет права ждать, пока робот договорит.

    Найдено на живом роботе, и виноват был я. `voice.say` ждёт, пока реплика
    отзвучит целиком, а звали его ПРЯМО ИЗ ЦИКЛА следования. Фраза «Ты
    слишком близко, я так не поеду. Отойди на пару шагов» звучит около
    четырёх секунд — всё это время в /cmd_vel не уходило ни одной команды.

    Сторож мёртвой руки видит полсекунды тишины и делает ровно то, для чего
    заведён: считает, что тот, кто крутил колёса, умер, и шлёт нули. Робот
    принимает нули за чужой стоп и гасит следование. В журнале это выглядело
    так: «Иду за тобой» в 16:16:18, «Ты слишком близко» в 16:16:20, три нуля
    в ту же секунду, «следование кончилось: кнопка стоп» — при том, что
    кнопки никто не трогал. И так каждый раз.

    Сторож при этом ПРАВ. Неправ цикл. Поэтому речь посреди поездки уезжает в
    свой поток, а блокирующая остаётся только там, где цикл и так кончается.
    """
    section("следование не ждёт на речи")
    import ast

    корень = Path(__file__).resolve().parent.parent
    дерево = ast.parse((корень / "voice" / "robot_voice" / "follow.py")
                       .read_text(encoding="utf-8"))

    вести = next(у for у in ast.walk(дерево)
                 if isinstance(у, ast.FunctionDef) and у.name == "_вести")

    def говорит(узел):
        """Все вызовы блокирующего self.говорить внутри узла."""
        найдено = []
        for в in ast.walk(узел):
            if (isinstance(в, ast.Call) and isinstance(в.func, ast.Attribute)
                    and в.func.attr == "говорить"
                    and isinstance(в.func.value, ast.Name)
                    and в.func.value.id == "self"):
                найдено.append(в)
        return найдено

    циклы = [у for у in ast.walk(вести) if isinstance(у, ast.While)]
    check("цикл следования найден", len(циклы), 1)
    цикл = циклы[0]

    # Блокирующая речь внутри цикла допустима ТОЛЬКО там, где следом идёт
    # выход: там колёса всё равно останавливаются, и ждать уже нечего.
    def уходим_сразу(узел, вызов) -> bool:
        for в in ast.walk(узел):
            тело = getattr(в, "body", None)
            if not isinstance(тело, list):
                continue
            for i, шаг in enumerate(тело):
                if вызов not in list(ast.walk(шаг)):
                    continue
                # Возврат в этом же или следующем предложении.
                хвост = тело[i:i + 3]
                if any(isinstance(х, ast.Return) for х in хвост):
                    return True
        return False

    грехи = [в.lineno for в in говорит(цикл) if not уходим_сразу(цикл, в)]
    check("в цикле нет речи, на которой можно застрять", грехи, [])

    # И тот, кто говорит на ходу, обязан уходить в свой поток — иначе
    # проверка выше проходила бы, а беда осталась.
    на_ходу = next((у for у in ast.walk(дерево)
                    if isinstance(у, ast.FunctionDef)
                    and у.name == "сказать_на_ходу"), None)
    check("говорилка на ходу есть", на_ходу is not None, True)
    в_потоке = any(isinstance(в, ast.Call) and "Thread" in ast.unparse(в.func)
                   for в in ast.walk(на_ходу))
    check("и она заводит поток", в_потоке, True)

    # Живая проверка: говорилка, которая спит секунду, не должна задержать
    # того, кто её позвал.
    from robot_voice.follow import Следование

    ведомый = Следование.__new__(Следование)
    ведомый.говорить = lambda текст: time.sleep(1.0)
    начало = time.monotonic()
    ведомый.сказать_на_ходу("проверка")
    прошло = time.monotonic() - начало
    check("зовущий не ждёт конца реплики", прошло < 0.2, True)
    check("пустое не говорим вовсе", ведомый.сказать_на_ходу(""), None)


def test_кровать_сбоку_не_мешает() -> None:
    """Стоящее СБОКУ не должно считаться препятствием по курсу.

    С живого робота, сетка из пульта. Слева стена, справа кровать, по
    тридцать сантиметров вбок; впереди — пустая комната. Нижние два ряда
    видят пол (0.2-0.4 м), середина пуста, а крайние колонки показывают
    0.6-0.7 м во всех рядах сразу.

    `впереди` брал минимум по ВСЕМ колонкам и выдавал 0.64 м. Робот
    отказывался ехать вперёд по пустому полу, потому что рядом с ним стояла
    кровать — мимо которой он проезжает каждый день. И то же число уходило в
    следование как «человек в 0.65 м», из-за чего он вечно просил отойти.

    Датчик видит шестьдесят градусов, то есть по тридцать в каждую сторону.
    Крайняя колонка смотрит ВБОК, а не по курсу: луч 0.65 м под тридцатью
    градусами отходит от оси всего на 0.29 м. Робот, едущий прямо, заметает
    полосу шириной с себя — вот её и надо смотреть.
    """
    section("кровать сбоку — не препятствие впереди")
    import math

    from robot_voice import tof as д

    # Геометрия: та же функция, которой пользуются и «впереди», и сторож.
    check("середина смотрит вперёд", round(д.отступ_вбок(3, 1.0), 2), 0.07)
    check("край смотрит вбок", round(д.отступ_вбок(7, 1.0), 2), 0.44)
    check("и чем дальше луч, тем сильнее вбок",
          д.отступ_вбок(7, 2.0) > д.отступ_вбок(7, 1.0), True)
    check("угол симметричен",
          round(д.отступ_вбок(0, 1.3), 3), round(д.отступ_вбок(7, 1.3), 3))

    # Кровать в крайней колонке — мимо. Коробка по курсу — мешает.
    check("кровать справа в 0.65 м — проеду мимо",
          д.отступ_вбок(7, 0.65) > д.КОРИДОР, True)
    check("стена слева в 0.9 м — проеду мимо",
          д.отступ_вбок(0, 0.9) > д.КОРИДОР, True)
    check("коробка прямо по курсу — мешает",
          д.отступ_вбок(3, 0.5) <= д.КОРИДОР, True)
    check("и далёкий стул по курсу — тоже",
          д.отступ_вбок(4, 2.0) <= д.КОРИДОР, True)

    # А теперь на НАСТОЯЩЕЙ сетке с робота.
    П = д.НЕ_ИЗМЕРИЛ
    сетка = [
        [0.9, П, П, П, П, П, П, П],
        [0.9, П, П, П, П, П, П, 0.7],
        [1.0, П, П, П, П, П, П, 0.7],
        [1.0, П, П, П, П, П, 0.9, 0.6],
        [1.0, П, П, П, П, П, П, 0.7],
        [0.8, П, П, П, П, П, П, 0.7],
        [0.3, 0.3, 0.4, 0.4, 0.4, 0.4, 0.4, 0.3],
        [0.2, 0.3, 0.3, 0.3, 0.3, 0.3, 0.3, 0.2],
    ]
    взгляд = д.Взгляд.__new__(д.Взгляд)
    взгляд.сетка = сетка
    взгляд._без_пола = сетка          # пол здесь не при чём: смотрим ряды 2-5
    впереди = взгляд.впереди
    check("на живой сетке путь свободен", впереди, д.НЕ_ИЗМЕРИЛ)

    # Ставим коробку прямо по курсу — обязана найтись.
    с_коробкой = [ряд[:] for ряд in сетка]
    с_коробкой[3][4] = 0.5
    взгляд2 = д.Взгляд.__new__(д.Взгляд)
    взгляд2.сетка = с_коробкой
    взгляд2._без_пола = с_коробкой
    check("а коробку по курсу вижу", взгляд2.впереди, 0.5)

    # И проверка, что геометрия у сторожа и у «впереди» ОДНА. Две копии
    # одной формулы однажды разойдутся, и разойдутся тихо.
    for к in range(8):
        for л in (0.4, 0.65, 1.0, 2.0):
            check(f"сторож и взгляд согласны (к={к}, л={л})",
                  взгляд._в_коридоре(л, к), д.отступ_вбок(к, л) <= д.КОРИДОР)
    _ = math


def test_камера_ведёт_дальномер_меряет() -> None:
    """Камера решает, ГДЕ человек; дальномер — СКОЛЬКО до него метров.

    Дальномер не знает, что перед ним. Он берёт ближайшее крупное пятно и
    называет его целью, а в жилой комнате ближайшее пятно почти никогда не
    человек.

    С живого робота: слева стена, справа кровать, по тридцать сантиметров
    вбок. Человек ходил в полутора метрах, а «до человека» в журнале прыгало
    0.55 → 1.00 → 0.68 → 0.54 за секунды — дальномер по очереди мерил то
    человека, то мебель. При этом `вперёд` было НУЛЁМ во всех строках без
    исключения: робот трогается, только когда цель дальше желаемой дистанции,
    а мебель всегда ближе. То есть следование не могло работать в принципе.

    Камера же знает, что перед ней человек, и видит сто тридцать градусов
    против шестидесяти. Отсюда разделение: камера говорит куда, дальномер —
    сколько. Каждый делает то, что умеет.
    """
    section("камера ведёт, дальномер меряет")
    import math

    from robot_voice import follow as ф

    # Колонка под углом — обратная к пеленгу дальномера.
    check("середина смотрит вперёд", ф.колонка_под_углом(0.0) in (3, 4), True)
    check("левее — меньший номер",
          ф.колонка_под_углом(math.radians(20)) < 3, True)
    check("правее — больший", ф.колонка_под_углом(math.radians(-20)) > 4, True)
    check("за краем не вылезаем",
          (ф.колонка_под_углом(math.radians(90)),
           ф.колонка_под_углом(math.radians(-90))), (0, 7))

    # Комната как у Игоря: стена слева (0.9), кровать справа (0.65),
    # человек в полутора метрах чуть левее середины.
    П = 0.0
    комната = [[0.9, П, 1.5, П, П, П, П, 0.65] for _ in range(6)]
    комната += [[П] * 8, [П] * 8]

    без_камеры = ф.найти_цель(комната)
    check("без камеры дальномер хватает мебель",
          round(без_камеры[0], 2), 0.65)
    check("и показывает вправо, где кровать", без_камеры[1] < 0, True)

    с_камерой = ф.найти_цель(комната, math.radians(11.25))
    check("с камерой находит человека", round(с_камерой[0], 2), 1.5)
    check("и пеленг влево, где он и стоит", с_камерой[1] > 0, True)

    # ВОТ РАДИ ЧЕГО ВСЁ. Робот едет вперёд, только когда цель дальше
    # желаемой дистанции. С мебелью в 0.65 м это не случается никогда.
    check("до мебели ближе, чем надо держаться",
          без_камеры[0] < ф.ДЕРЖАТЬ, True)
    check("а до человека — дальше, значит поедем",
          с_камерой[0] > ф.ДЕРЖАТЬ, True)

    # Камера показала туда, где дальномер ничего не видит, — не выдумываем
    # цель на пустом месте, а честно откатываемся на ближайшее пятно.
    пусто_там = ф.найти_цель(комната, math.radians(-3.75))
    check("камера мимо — берём что есть", пусто_там is not None, True)

    # И совсем без целей — None, а не догадка.
    check("пустая сетка — цели нет", ф.найти_цель([[П] * 8 for _ in range(8)]),
          None)


def test_позвали_по_имени_молчать_нельзя() -> None:
    """Позвали по имени — робот обязан ответить, что бы ни решила модель.

    У робота есть служебное слово: модель отвечает им, когда считает, что
    говорили не с ней. Это верно для открытого разговора — робот слышит чужую
    беседу и правильно молчит.

    Но с живого робота: «проснулся по имени» в 16:39:40, «человек: Найди
    меня», и следом «модель говорит, что фраза не мне — молчу». Так три раза
    подряд, на «Найди меня» и «Ты меня видишь?». Человек звал по имени и не
    получал НИЧЕГО — со стороны робот просто сломан, и понять почему нельзя
    ничем, кроме журнала.

    Четырёхмиллиардная модель на ПК путается в этом слове чаще облачной. А
    ответ здесь уже известен и без неё: если имя прозвучало, обращались к
    роботу. Полагаться на догадку там, где есть факт, незачем.
    """
    section("позвали по имени — молчать нельзя")
    import ast

    корень = Path(__file__).resolve().parent.parent
    дерево = ast.parse((корень / "voice" / "robot_voice" / "app.py")
                       .read_text(encoding="utf-8"))

    # Ищем ветку «не мне» и проверяем, что внутри неё есть развилка по имени.
    нашли = []
    for узел in ast.walk(дерево):
        if not isinstance(узел, ast.If):
            continue
        текст = ast.unparse(узел.test)
        if "МИМО" not in текст:
            continue
        тело = ast.unparse(узел)
        нашли.append(тело)
    check("ветка «не мне» на месте", len(нашли), 1)
    ветка = нашли[0]
    check("в ней есть развилка по имени", "by_name" in ветка, True)
    check("и по имени мы НЕ молчим", 'мимо[0] = False' in ветка, True)
    check("а переспрашиваем", "Повтори" in ветка, True)

    # Порядок важен: сначала проверка имени, потом молчание. Наоборот —
    # молчание случится раньше, чем до имени дойдёт очередь.
    check("имя проверяется раньше молчания",
          ветка.index("by_name") < ветка.index("молчу"), True)


def test_расстояние_по_росту() -> None:
    """Расстояние до человека — по размеру его рамки, как это делают все.

    Из простой оптики: предмет высотой H на расстоянии d занимает в кадре
    h = f·H/d пикселей, где f — фокусное в пикселях, а оно считается из поля
    зрения камеры. Значит d = f·H/h. Никакого дальномера.

    ЗАЧЕМ, ЕСЛИ ЕСТЬ РАССТОЯНИЕ ПО НОГАМ. Тот способ хитрее и в теории
    точнее, но требует, чтобы дальномер и камера сперва договорились: пары
    «пиксель ног — метры» собираются, только когда оба видят одного
    человека. На живом роботе они не договорились ни разу — за одну минуту
    журнала четыре переучивания подряд, «промах 15%» и «горизонт на -946-м
    пикселе», то есть заведомая чушь.

    Точный способ, который не работает, хуже приблизительного, который
    работает. Рамка есть в каждом кадре, где детектор нашёл человека.
    """
    section("расстояние по росту")

    from robot_voice import vision_track as вижу

    мерка = вижу.Дальномер_по_росту(ширина_кадра=640.0, поле=130.0)
    # Фокусное — чистая геометрия, а не подгонка.
    check("фокус посчитан из поля зрения", round(мерка.фокус), 149)

    # Работает С ПЕРВОГО КАДРА, без обучения. Это и есть главное отличие.
    for д in (1.0, 1.5, 2.0, 3.0):
        h = мерка.фокус * мерка.РОСТ / д
        check(f"человек на {д} м", round(мерка.сколько(h), 2), д)

    # И не отвечает там, где ответ был бы выдумкой.
    check("рамка в два пикселя — не знаю", мерка.сколько(2.0), 0.0)
    check("рамки нет — не знаю", мерка.сколько(0.0), 0.0)
    check("во весь кадр — ближе, чем бывает", мерка.сколько(2000.0), 0.0)

    # Дальномер подтверждает — рост уточняется под ЭТОГО человека.
    низкий = 1.3
    for _ in range(мерка.ПАР_ХВАТИТ + 2):
        for д in (1.0, 1.5, 2.0):
            мерка.запомнить(мерка.фокус * низкий / д, д)
    check("рост уточнён под человека", abs(мерка.рост - низкий) < 0.1, True)
    check("и расстояние стало точным",
          round(мерка.сколько(мерка.фокус * низкий / 2.0), 2), 2.0)

    # А нелепому росту не верим: это ошибка разбора, а не человек.
    мерка2 = вижу.Дальномер_по_росту()
    for _ in range(мерка2.ПАР_ХВАТИТ + 2):
        мерка2.запомнить(мерка2.фокус * 5.0 / 2.0, 2.0)
    check("пятиметровому человеку не верим", мерка2.рост, мерка2.РОСТ)

    # --- рамка, обрезанная краем кадра ----------------------------------
    # Ближе метра человек в кадр целиком не влезает. Его рамка упирается в
    # нижний край, и её высота говорит уже не о росте, а о том, где кончился
    # кадр. Без этой проверки робот считал бы человека ДАЛЁКИМ ровно тогда,
    # когда тот ближе всего, — и поехал бы на него.
    глаз = вижу.Глазомер(ширина_кадра=640.0, поле=130.0)
    целая = {"targets": [{"type": "body", "track_id": 1, "rois": [
        {"type": "body", "rect": {"x_offset": 300, "width": 60,
                                  "y_offset": 100, "height": 200}}]}]}
    глаз.принять(целая)
    check("целую рамку берём", глаз.высота_рамки, 200.0)
    check("и расстояние по ней есть", глаз.далеко_ли > 0, True)

    обрезанная = {"targets": [{"type": "body", "track_id": 1, "rois": [
        {"type": "body", "rect": {"x_offset": 300, "width": 60,
                                  "y_offset": 100, "height": 400}}]}]}
    глаз.принять(обрезанная)
    check("обрезанную краем кадра не берём", глаз.высота_рамки, 0.0)

    # Разбор высоты понимает те же три записи, что и разбор ширины.
    check("углы", вижу.высота_рамки({"y_offset": 10, "height": 90}), (90.0, 100.0))
    check("две точки", вижу.высота_рамки({"y1": 10, "y2": 100}), (90.0, 100.0))
    check("чужое не разбираем", вижу.высота_рамки({"нечто": 1}), None)


def test_планировщик_объезжает() -> None:
    """Робот должен ОБХОДИТЬ препятствия, а не только стоять перед ними.

    До сих пор скорость и поворот считались простой пропорцией — «человек
    правее, крути правее; дальше, значит езжай», — а препятствие впереди
    просто обнуляло скорость. Обойти робот не умел вовсе. Для комнаты это
    приговор: стул, косяк, угол дивана — это не «стой», а «прими левее».

    Проверяем не отдельные числа, а ПОВЕДЕНИЕ: прокатываем робота по кругам
    цикла и смотрим, доехал он или встал. Числа в оценке подбирались ровно
    этими прогонами, и проверять их надо тем же, чем подбирали.
    """
    section("планировщик объезжает")
    import math

    from robot_voice import planner as п

    # --- геометрия -------------------------------------------------------
    # Дуга, а не отрезок: робот с ненулевым поворотом едет по окружности.
    x, y, курс = п.проехать(0.4, 0.0, 1.0)
    check("прямо — по прямой", (round(x, 2), round(y, 2)), (0.4, 0.0))
    x, y, курс = п.проехать(0.4, 1.0, 1.0)
    check("с поворотом — вбок ушли", y > 0.1, True)
    check("и курс изменился", round(курс, 2), 1.0)

    # Корпус — прямоугольник, а не круг: круг радиуса 0.30 не пролезает в
    # щель, в которую тележка проходит спокойно.
    зазор = п.влезаем(0.0, 0.0, 0.0, [(0.0, 0.30)], п.ПОЛУШИРИНА, п.ПОЛУДЛИНА)
    check("сбоку в 30 см — проходим", зазор > 0, True)
    зазор = п.влезаем(0.0, 0.0, 0.0, [(0.0, 0.10)], п.ПОЛУШИРИНА, п.ПОЛУДЛИНА)
    check("сбоку в 10 см — корпус внутри", зазор < 0, True)

    # --- цель не препятствие --------------------------------------------
    # Дальномер не знает, что перед ним, и человек для него обычное пятно.
    человек = [(1.5, 0.0), (1.5, 0.1)]
    check("человека из препятствий вычёркиваем",
          п.без_цели(человек, 1.5, 0.0), [])
    стул = [(0.7, 0.0)]
    check("а стул на пути остаётся",
          п.без_цели(стул + человек, 1.5, 0.0), стул)

    # --- поведение на прогонах ------------------------------------------
    def прогон(преграды, цель_x=3.0, шагов=150):
        """Крутим цикл и смотрим, доехал ли. Возвращает (как, метры, крюк).

        Тележка здесь РАЗГОНЯЕТСЯ, а не прыгает на заданную скорость: ровно
        так же, как в живом цикле следования, и ровно так же, как эти дуги
        прокатывает сам планировщик. Раньше здесь стояло `было_v = v` и
        мгновенный шаг — то есть проверка гоняла робота, которого не
        существует, и на нём одинаково хорошо выглядели бы и честный
        планировщик, и тот, что обещает недостижимые дуги.
        """
        шаг_с = 1 / 15
        x = y = курс = 0.0
        было_v = было_w = 0.0
        встал = 0
        крюк = 0.0
        for _ in range(шагов):
            cos, sin = math.cos(-курс), math.sin(-курс)
            точки = [((тx - x) * cos - (тy - y) * sin,
                      (тx - x) * sin + (тy - y) * cos) for тx, тy in преграды]
            цx, цy = цель_x - x, 0.0 - y
            мx = цx * cos - цy * sin
            мy = цx * sin + цy * cos
            до = math.hypot(мx, мy)
            if до < 0.35:
                return "доехал", x, крюк
            v, w, _ = п.выбрать(до, math.atan2(мy, мx), точки, 0.4, 1.0,
                                было_v, было_w)
            if v < 0.01 and abs(w) < 0.01:
                встал += 1
                if встал > 15:
                    return "встал", x, крюк
            else:
                встал = 0
            было_v = п.придержать(было_v, v, шаг_с, п.РАЗГОН, п.СБРОС)
            было_w = п.придержать(было_w, w, шаг_с,
                                  п.РАЗГОН_ПОВОРОТА, п.РАЗГОН_ПОВОРОТА)
            x, y, курс = п._шагнуть(x, y, курс, было_v, было_w, шаг_с)
            крюк = max(крюк, abs(y))
        return "не успел", x, крюк

    как, метры, крюк = прогон([])
    check("в пустой комнате доезжает", как, "доехал")
    check("и не виляет", abs(крюк) < 0.05, True)

    # СТУЛ ТОЧНО ПО ОСЕВОЙ — ловушка симметрии: влево и вправо одинаково
    # хороши, и робот раньше предпочитал «прямо, но медленно», подползал на
    # полметра и вставал. Оттуда объехать уже нельзя: тележке шириной сорок
    # сантиметров нужно место для дуги.
    как, метры, крюк = прогон([(1.2, d) for d in (-0.12, 0.0, 0.12)])
    check("стул по осевой — обходит", как, "доехал")
    # Крюк вырос с девяти сантиметров до полуметра, и это не ухудшение.
    # Девять сантиметров получались на прежней, невозможной модели: тележка
    # там мгновенно прыгала на заданную скорость и могла свернуть впритык.
    # С честным разгоном и штрафом, который видит стул заранее, робот
    # начинает отворачивать метром раньше и объезжает шире — то есть так,
    # как он поедет на самом деле.
    check("и крюк в пределах комнаты", 0.02 < abs(крюк) < 0.7, True)

    как, _, _ = прогон([(1.2, 0.15 + d) for d in (-0.12, 0.0, 0.12)])
    check("стул чуть в стороне — тоже обходит", как, "доехал")

    # ЩЕЛЬ. Настоящая комната Игоря: стена и кровать по тридцать два
    # сантиметра вбок. Робот обязан пройти между ними, а не встать.
    щель = ([(x / 10, 0.32) for x in range(3, 32)]
            + [(x / 10, -0.32) for x in range(3, 32)])
    как, метры, крюк = прогон(щель)
    check("между стеной и кроватью проходит", как, "доехал")

    # ТУПИК. Стена поперёк — ехать некуда, и это надо признать, а не
    # ковыряться. Пятиться нельзя: сзади слепая зона.
    как, метры, _ = прогон([(1.0, y / 10) for y in range(-10, 11)])
    check("в тупике встаёт", как, "встал")
    # Носом не упирается: до стены остаётся больше, чем запас поверх корпуса.
    # Считаем от НОСА, а не от центра — так понятнее, что именно проверяем.
    нос_до_стены = 1.0 - метры - п.ПОЛУДЛИНА
    check("и не упирается носом", нос_до_стены > п.ЗАПАС, True)

    # Никуда не годных дуг не бывает без причины: если все упёрлись, об этом
    # надо сказать, а не молча вернуть ноль.
    v, w, почему = п.выбрать(1.5, 0.0, [(0.3, y / 20) for y in range(-8, 9)],
                             0.4, 1.0)
    check("вплотную к стене стоим", (v, w), (0.0, 0.0))
    check("и объясняем почему", "упираются" in почему, True)


def test_планировщик_считает_ту_дугу_по_которой_поедет() -> None:
    """Проверенная дуга и проеханная дуга должны быть одной и той же.

    Это главная поправка после сверки с формулами DWA. Первая редакция
    прокатывала пробные дуги ПОСТОЯННОЙ скоростью, а колёса разгоняются:
    между планировщиком и ними стоит `придержать`. Расхождение выходило не
    косметическое — от неподвижности поворот набирается за треть секунды, а
    ход за секунду с лишним, то есть первый миг робот почти крутится на
    месте там, где проверялась пологая дуга. Проверено просторно, поехали в
    стену.

    Проверяем прямо: прокатываем планировщиком и отдельно «ведём» робота той
    же командой через тот же `придержать` — точки обязаны совпасть.
    """
    section("планировщик считает ту дугу, по которой поедет")
    import math

    from robot_voice import follow, planner as п

    # Одна и та же функция сглаживания у планировщика и у колёс.
    check("сглаживание общее", follow.придержать is п.придержать, True)
    check("разгон общий", follow.РАЗГОН, п.РАЗГОН)
    check("сброс общий", follow.ЗАМЕДЛЕНИЕ_ПЛАВНОЕ, п.СБРОС)
    check("торможение общее", follow.ЗАМЕДЛЕНИЕ, п.ТОРМОЖЕНИЕ)

    # Прокатка планировщика против честного ведения колёс.
    шаг = п.ГОРИЗОНТ / п.ШАГОВ
    x = y = курс = 0.0
    v, w = 0.0, 0.0
    свои = []
    for _ in range(п.ШАГОВ):
        v = п.придержать(v, 0.55, шаг, п.РАЗГОН, п.СБРОС)
        w = п.придержать(w, 0.6, шаг, п.РАЗГОН_ПОВОРОТА, п.РАЗГОН_ПОВОРОТА)
        x, y, курс = п._шагнуть(x, y, курс, v, w, шаг)
        свои.append((round(x, 4), round(y, 4)))
    его = [(round(x, 4), round(y, 4))
           for x, y, _к, хвост in п.прокатить(0.55, 0.6, 0.0, 0.0)
           if not хвост]
    check("ходовая часть дуги совпала", его, свои)

    # А постоянная скорость дала бы совсем другое место — то самое, из-за
    # которого всё и затевалось.
    было = п.проехать(0.55, 0.6, п.ГОРИЗОНТ)
    разошлись = math.hypot(было[0] - свои[-1][0], было[1] - свои[-1][1])
    check("а без разгона место вышло бы на четверть метра другим",
          round(разошлись, 2) >= 0.24, True)

    # ТОРМОЗНОЙ ХВОСТ. Это условие допустимости из DWA: годятся только те
    # скорости, на которых робот успевает остановиться.
    хвост = [т for т in п.прокатить(0.55, 0.0, 0.55, 0.0) if т[3]]
    check("у едущего хвост есть", len(хвост) > 0, True)
    путь_хвоста = хвост[-1][0] - п.ГОРИЗОНТ * 0.55
    check("и он примерно равен тормозному пути",
          abs(путь_хвоста - п.тормозной_путь(0.55)) < 0.06, True)
    check("у стоящего хвоста нет",
          [т for т in п.прокатить(0.0, 0.5, 0.0, 0.5) if т[3]], [])

    # Стена сразу за горизонтом. Прежний планировщик проверял полторы секунды
    # и был доволен; теперь дуга обязана уложиться вместе с торможением.
    стена = [(1.0, б / 10.0) for б in range(-6, 7)]
    v, w, _ = п.выбрать(3.0, 0.0, стена, 0.55, 1.0, было_вперёд=0.5)
    успеем = п.ГОРИЗОНТ * v + п.тормозной_путь(v) + п.ПОЛУДЛИНА
    check("перед близкой стеной не разгоняемся", успеем < 1.05, True)

    # РЕГУЛИРОВКА ПО КРИВИЗНЕ. Формула Nav2: круче порога — медленнее.
    check("пологий поворот не трогаем", п.по_кривизне(0.55, 0.2), 0.55)
    check("крутой — сбавляем", п.по_кривизне(0.55, 1.0) < 0.45, True)
    # И самое важное: на малом ходу регулировка не должна съедать сама себя.
    # Радиус r = v/w, значит чем медленнее едешь, тем круче выглядит тот же
    # поворот — без порога это петля, которая сводит скорость к нулю.
    check("на малом ходу не сводим к нулю",
          п.по_кривизне(0.16, 0.6) >= п.СБАВЛЯЕМ_НЕ_НИЖЕ, True)
    check("но и не разгоняем того, кто и так ползёт",
          п.по_кривизне(0.05, 1.0) <= 0.05, True)

    # НАГРАДА ЗА ХОД НЕ СМЕЕТ БЫТЬ ДОРОЖЕ ЦЕЛИ. Первая её редакция считалась
    # долей от разрешённой скорости — и на живом роботе вышло вот что:
    #
    #   до_человека 0.65 м … близко ДА … вперёд 0.28
    #
    # Потолок ведь не постоянный: когда ехать незачем, он падает, а награда,
    # делённая на маленький потолок, начинает стоить дороже метра приближения.
    # Робот поехал НА человека, стоящего ближе, чем разрешено подходить.
    далёкое = [(1.6, 0.5), (1.6, -0.5)]
    for потолок in (0.55, 0.4, 0.275, 0.15):
        v, _w, _п = п.выбрать(0.0, math.radians(-7), далёкое, потолок, 0.4)
        check(f"ехать некуда — стоим (потолок {потолок})", v, 0.0)

    # НАГРАДА ЗА ХОД — третье слагаемое формулы Фокса, которого не было.
    # Без него «ползти вперёд» выигрывает у любого настоящего объезда:
    # ползанье безопасно, просторно и всё-таки приближает.
    ползёт = 0
    for _ in range(1):
        стул = [(1.0, д) for д in (-0.12, 0.0, 0.12)]
        v, w, _ = п.выбрать(2.0, 0.0, стул, 0.55, 1.0,
                            было_вперёд=0.2, было_поворот=0.0)
        # Либо едем как следует, либо всерьёз отворачиваем. Ползти прямо на
        # стул — это не ответ.
        if v < 0.15 and abs(w) < 0.2:
            ползёт += 1
    check("перед стулом не ползёт прямо", ползёт, 0)

    # И ТО ЖЕ САМОЕ НА УРОВНЕ СЛЕДОВАНИЯ. Запрет «человек слишком близко»
    # должен доходить ДО планировщика, а не применяться после него: запрет,
    # который применяется после решения, — это не запрет. На живом роботе
    # планировщик получал вместо нуля запасной потолок и ехал.
    class _Взгляд:
        сетка = [[0.0] * 8 for _ in range(2)] + [[1.6] * 8 for _ in range(4)] \
            + [[0.0] * 8 for _ in range(2)]
        пол = None
        свободно_впереди = 1.6

    ведомый = follow.Следование.__new__(follow.Следование)
    ведомый.карта = None
    близко_нельзя = ведомый._спланировать(
        _Взгляд(), 0.65, math.radians(-7), 1.0, 0.0, 0.4, 0.0, 0.0,
        можно_вперёд=False)
    check("человек близко — планировщик вперёд не пускает",
          близко_нельзя is None or близко_нельзя[0] == 0.0, True)
    можно = ведомый._спланировать(
        _Взгляд(), 2.0, 0.0, 1.0, 0.4, 0.4, 0.0, 0.0, можно_вперёд=True)
    check("а когда можно — едет",
          можно is None or можно[0] > 0.0, True)


def test_сделано_пока_колёса_едут() -> None:
    """«Сделано», сказанное на ходу, — это враньё, и его надо ловить.

    С живого робота, маршрут «объезд квартиры»:

      18:06:32 маршрут 'объезд квартиры': 6 шагов, 35 с
      18:06:32 маршрут: шаг 1 из 6
      18:06:33 робот: Объезд квартиры сделан.
      18:06:35 сторож оборвал поездку: впереди что-то справа
      18:06:38 маршрут отменён на шаге 2 из 6

    Инструмент ответил честно — «Делаю объезд квартиры, 6 шагов». Соврала не
    машина, а пересказ: модель приняла «начал» за «сделал». Человек услышал
    успех, отвернулся и не увидел, как робот через пять секунд встал носом в
    мебель.

    Отличить враньё от честного отчёта по одному тексту нельзя — только по
    тому, едут ли колёса в момент, когда фраза готова.
    """
    section("«сделано», пока колёса едут")

    from robot_voice import intents

    сделано = ["Объезд квартиры сделан.", "Готово.", "Всё выполнил.",
               "Проехал метр.", "Доехал.", "Я на месте.", "Обошёл квартиру."]
    for фраза in сделано:
        check(f"ловим {фраза!r}", intents.обещает_готово(фраза), True)

    ещё_едет = ["Делаю объезд квартиры, 6 шагов.", "Еду вперёд.",
                "Иду за тобой. Скажи стоп, когда хватит.", "Поехал по маршруту.",
                "Хорошо.", "Стою: впереди что-то справа."]
    for фраза in ещё_едет:
        check(f"не путаем с {фраза!r}", intents.обещает_готово(фраза), False)

    # И проверка того, что мозг вообще запоминает ответ движения — без него
    # подменять враньё было бы нечем и робот сказал бы «Ещё еду» вместо
    # настоящего «Делаю объезд квартиры, 6 шагов».
    import ast
    import pathlib
    исходник = pathlib.Path(
        "voice/robot_voice/brain.py").read_text(encoding="utf-8")
    check("мозг помнит ответ движения",
          "ответ_инструмента" in исходник, True)
    приложение = pathlib.Path(
        "voice/robot_voice/app.py").read_text(encoding="utf-8")
    check("и приложение его спрашивает",
          "ответ_инструмента" in приложение, True)
    дерево = ast.parse(приложение)
    зовут = {у.attr for у in ast.walk(дерево) if isinstance(у, ast.Attribute)}
    check("а проверку зовёт по имени", "обещает_готово" in зовут, True)
    check("и смотрит, едут ли колёса", '"moving"' in приложение, True)


def test_застряли_и_молчим() -> None:
    """Робот обязан замечать, что скомандовал колёсам и не поехал.

    До сих пор он этого не проверял НИКОГДА. Одометрия приходит десять раз в
    секунду и уже используется картой, но ни одна часть кода не сравнивала
    «что велел» с «что вышло». Из-за этого любая беда с ходовой выглядела
    одинаково: робот стоит и молчит, а разбираться приходилось по журналу
    задним числом.
    """
    section("застряли — и не молчим")
    import math

    from robot_voice import progress

    class Часы:
        def __init__(self) -> None:
            self.т = 100.0

        def __call__(self) -> float:
            return self.т

        def тик(self, д=1 / 15) -> None:
            self.т += д

    def прогон(*, едет, крутится, вперёд=0.3, поворот=0.0, шум=0.0,
               секунд=4.0, только_первые=None):
        """`только_первые` — сколько кадров команда живёт; дальше нули."""
        import random
        random.seed(7)
        часы = Часы()
        ход = progress.Ход(часы=часы)
        x = y = курс = 0.0
        беда = ""
        for номер in range(int(секунд * 15)):
            v, w = вперёд, поворот
            if только_первые is not None and номер >= только_первые:
                v = w = 0.0
            if едет:
                x += v / 15
            if крутится:
                курс += w / 15
            x += random.uniform(-шум, шум)
            y += random.uniform(-шум, шум)
            курс += random.uniform(-шум, шум)
            ход.отметить(v, w, (x, y, курс))
            беда = беда or ход.беда()
            часы.тик()
        return беда

    check("едет как велено — молчим",
          прогон(едет=True, крутится=True), "")
    check("велено ехать, а колёса стоят — говорим",
          "велел ехать" in прогон(едет=False, крутится=False), True)
    check("велено крутиться на пределе, а не крутится — говорим",
          "велел крутиться" in прогон(едет=False, крутится=False,
                                      вперёд=0.0, поворот=1.0), True)
    check("крутится как велено — молчим",
          прогон(едет=False, крутится=True, вперёд=0.0, поворот=1.0), "")
    check("стоим и не велим — молчим",
          прогон(едет=False, крутится=False, вперёд=0.0, поворот=0.0), "")

    # ДВА СЛУЧАЯ С ЖИВОГО РОБОТА, на которых первая редакция сторожа
    # ошиблась. Оба — обычное следование, никакого застревания не было.
    #
    # Первый: команда 0.15 м/с мелькнула и сменилась нулём, потому что
    # человек подошёл ближе. Сумма за окно дала 0.16 м, порог был 0.15 — и
    # сторож объявил беду. Улика оказалась не уликой: шесть сантиметров в
    # секунду средних, от такого шасси и не должно тронуться.
    check("мелькнувшая команда — не улика",
          прогон(едет=False, крутится=False, вперёд=0.15, только_первые=10),
          "")
    # Второй: доворот 0.35 рад/с. Для колёс это три-пять сантиметров в
    # секунду — втрое меньше того, с чего меканум обязан тронуться.
    check("спокойный доворот — не улика",
          прогон(едет=False, крутится=False, вперёд=0.0, поворот=0.4), "")

    # ШУМ ОДОМЕТРИИ не должен выглядеть ездой. Ради этого смещение берётся
    # от края окна до края, а не суммой шагов: сумма шагов накапливает шум и
    # у неподвижного робота даёт сантиметры «хода».
    check("шум одометрии не выдаём за ход",
          "велел ехать" in прогон(едет=False, крутится=False, шум=0.001),
          True)

    # БЫСТРОЕ ВРАЩЕНИЕ через ±π. Разность курсов тут дала бы почти ноль, то
    # есть робот выглядел бы застрявшим ровно тогда, когда он заведомо нет.
    check("быстро крутящийся не считается застрявшим",
          прогон(едет=False, крутится=True, вперёд=0.0, поворот=3.0), "")

    # БЕЗ ОДОМЕТРИИ судить не по чему — молчим, а не выдумываем.
    часы = Часы()
    ход = progress.Ход(часы=часы)
    беда = ""
    for _ in range(60):
        ход.отметить(0.3, 0.0, None)
        беда = беда or ход.беда()
        часы.тик()
    check("нет одометрии — молчим", беда, "")

    # РАЗРЫВ во времени не должен склеиваться в окно: пауза — это не езда.
    часы = Часы()
    ход = progress.Ход(часы=часы)
    беда = ""
    for номер in range(60):
        ход.отметить(0.3, 0.0, (0.0, 0.0, 0.0))
        беда = беда or ход.беда()
        часы.тик()
        if номер == 30:
            часы.т += 3.0
    check("разрыв посреди окна не склеиваем", беда, "")

    # ЖАЛУЕМСЯ НЕ ЧАЩЕ РАЗА. Иначе робот забормочет одно и то же на каждом
    # кадре — цикл крутится пятнадцать раз в секунду.
    часы = Часы()
    ход = progress.Ход(часы=часы)
    сколько = 0
    for _ in range(15 * 8):
        ход.отметить(0.3, 0.0, (0.0, 0.0, 0.0))
        if ход.беда():
            сколько += 1
        часы.тик()
    check("за восемь секунд жалуемся один раз", сколько, 1)

    # И ГЛАВНОЕ: следование обязано этим сторожем пользоваться, а не просто
    # иметь его в соседнем файле.
    import ast
    import pathlib
    дерево = ast.parse(pathlib.Path(
        "voice/robot_voice/follow.py").read_text(encoding="utf-8"))
    зовут = {у.attr for у in ast.walk(дерево)
             if isinstance(у, ast.Attribute)}
    check("следование отмечает ход", "отметить" in зовут, True)
    check("следование спрашивает про беду", "беда" in зовут, True)
    _ = math


def test_цепочка_насквозь() -> None:
    """Аудит: json из ROS доходит до колёс, и ничего по дороге не теряется.

    Все прочие проверки берут кусок цепочки: разбор отдельно, решение
    отдельно, колёса отдельно. Так не ловится самое частое — стык. За этот
    вечер на живом роботе сломались именно стыки, ни разу не сами куски:
    подписка была одна, а потребителей стало двое; жест перебивал следование
    и писал в журнал чужую причину; отчёта о том, почему робот стоит, не было
    вовсе. Каждый кусок при этом работал.

    Поэтому здесь цепочка собирается ЦЕЛИКОМ и кормится настоящими
    сообщениями rosbridge — теми же строками, что приходят по вебсокету.
    """
    section("аудит: цепочка насквозь")
    import json as _json
    import math
    import threading

    from robot_voice import falldown, gestures, things
    from robot_voice.ros import Ros

    ros = Ros.__new__(Ros)
    ros._lock = threading.Lock()
    ros._motion_cancel = threading.Event()
    ros._odom = (2.0, 1.0, math.pi / 2)
    ros._odom_at = time.monotonic()
    ros._свои_нули = 0
    ros._не_ушло = 0
    ros._кричали_про_связь = False
    ros.прервано = ""
    ros.сторож = None
    ros.сторож_вслепую = None
    ros._движители = []
    ушло: list[dict] = []
    ros._send = lambda с: bool(ушло.append(с) or True)

    # --- собираем ровно то же, что собирает app.py -----------------------
    часы = [1000.0]
    тик = lambda: часы[0]                                    # noqa: E731

    пеленг = vision_track_модуль().Глазомер()
    упавшие: list[int] = []
    сторож_падений = falldown.Сторож(упал=упавшие.append, часы=тик)
    показанные: list[int] = []
    жесты_видок = gestures.Жесты(показал=lambda ж, _н: показанные.append(ж),
                                 часы=тик)
    вещи = things.Вещи(часы=тик)

    def детекция(сообщение):
        пеленг.принять(сообщение)
        сторож_падений.принять(сообщение)

    ros.людей_видно = детекция
    ros.жесты_видно = жесты_видок.принять
    ros.вещи_видно = lambda с: вещи.принять(с, ros.odom)

    def прислать(топик, сообщение):
        ros._on_message(None, _json.dumps(
            {"op": "publish", "topic": топик, "msg": сообщение}))

    # --- 1. детекции людей кормят ОБОИХ потребителей ---------------------
    точки = [{"x": 0.0, "y": 0.0} for _ in range(falldown.ТОЧЕК)]
    for пара, (x, y) in ((falldown.ПЛЕЧИ, (250, 400)),
                         (falldown.БЁДРА, (350, 405)),
                         (falldown.ЩИКОЛОТКИ, (470, 410))):
        точки[пара[0]] = {"x": x - 20.0, "y": y}
        точки[пара[1]] = {"x": x + 20.0, "y": y}
    for i, (x, y) in enumerate([(200 + i * 15, 385 + (i % 2) * 30)
                                for i in range(falldown.ТОЧЕК)]):
        if точки[i]["x"] == 0.0 and точки[i]["y"] == 0.0:
            точки[i] = {"x": float(x), "y": float(y)}

    человек = {"targets": [{
        "type": "person", "track_id": 4,
        "rois": [{"type": "body",
                  "rect": {"x_offset": 180, "y_offset": 380,
                           "width": 320, "height": 50}}],
        "points": [{"type": falldown.СКЕЛЕТ, "point": точки}],
    }]}
    прислать("/hobot_mono2d_body_detection", человек)
    check("пеленг получил детекцию", пеленг.свежий, True)
    check("и сторож падений — тоже",
          сторож_падений._показал, True)

    # Лежит достаточно долго — тревога. Это и есть проверка стыка: сюда
    # доехали и рамка тела, и скелет, и одно без другого решения не даёт.
    for _ in range(60):
        часы[0] += 0.1
        прислать("/hobot_mono2d_body_detection", человек)
    check("лежащий человек поднял тревогу", упавшие, [4])

    # --- 2. жест доходит и требует УДЕРЖАНИЯ ------------------------------
    ладонь = {"targets": [{"track_id": 7, "rois": [{"type": "hand"}],
                           "attributes": [{"type": "gesture",
                                           "value": gestures.ЛАДОНЬ}]}]}
    for _ in range(gestures.ПОДТВЕРЖДЕНИЙ[gestures.ЛАДОНЬ] + 4):
        часы[0] += 0.033
        прислать("/hobot_hand_gesture_detection", ладонь)
    check("мелькнувшая ладонь до колёс не доходит", показанные, [])
    часы[0] += gestures.ДЕРЖАТЬ[gestures.ЛАДОНЬ]
    прислать("/hobot_hand_gesture_detection", ладонь)
    check("удержанная — доходит", показанные, [gestures.ЛАДОНЬ])

    # --- 3. вещи запоминаются вместе с местом ----------------------------
    прислать("/perception/detection/dosod", {"targets": [
        {"type": "cup", "rois": [{"rect": {"x_offset": 300, "width": 40},
                                  "confidence": 0.9}]}]})
    встреча = вещи.найти("кружка")
    check("кружка запомнена", встреча is not None, True)
    check("и место взято из одометрии робота",
          (round(встреча.где[0], 1), round(встреча.где[1], 1)), (2.0, 1.0))

    # --- 4. мусор не рвёт связь ------------------------------------------
    # Сообщения приходят из ЧУЖИХ пакетов, и обновление любого из них может
    # поменять поле. Разбор обязан пережить это молча: по этому же соединению
    # ходит «стоп», и уронить его дороже, чем потерять детекцию.
    было_ушло = len(ушло)
    for топик in ("/hobot_mono2d_body_detection",
                  "/hobot_hand_gesture_detection",
                  "/perception/detection/dosod"):
        for мусор in ({}, {"targets": "не список"}, {"targets": [None, 7]},
                      {"targets": [{"points": "нет"}]},
                      {"targets": [{"attributes": [{"type": "gesture"}]}]}):
            прислать(топик, мусор)
    ros._on_message(None, "это вообще не json")
    ros._on_message(None, _json.dumps({"op": "publish", "topic": "/чужое"}))
    check("мусор разобран без падения", True, True)
    check("и лишнего в колёса не ушло", len(ушло), было_ушло)

    # --- 5. взгляд по запросу, а не потоком ------------------------------
    # Сеть поиска вещей считает 130 мс на кадр. Если бы мы просили кадр сами
    # по себе, она отобрала бы BPU у детектора людей, на котором держатся
    # следование, падения и стоп-ладонь.
    ушло.clear()
    ros.посмотреть()
    check("запрос кадра ушёл одним сообщением", len(ушло), 1)
    check("и это именно запрос взгляда",
          ушло[0].get("topic"), "/robot_ai/look")


def vision_track_модуль():
    from robot_voice import vision_track
    return vision_track


def test_вещи() -> None:
    """Что робот видел и где: «ты не видел мой телефон».

    Распознаёт DOSOD на BPU — восемьдесят классов COCO, из них много
    домашнего. Считает НЕ постоянно: один кадр стоит около ста тридцати
    миллисекунд платы, и постоянная работа отобрала бы BPU у детектора людей,
    на котором держатся следование, падения и остановка по ладони.
    """
    section("где моя кружка")
    import math

    from robot_voice import things as вещь

    # Человек спрашивает по-русски и в падежах, сеть отвечает по-английски.
    check("кружка", вещь.распознать("кружка"), "cup")
    check("кружку", вещь.распознать("кружку"), "cup")
    check("чашка — та же кружка", вещь.распознать("чашка"), "cup")
    check("телефон", вещь.распознать("телефон"), "cell phone")
    check("мобильник", вещь.распознать("мобильник"), "cell phone")
    check("по-английски тоже", вещь.распознать("laptop"), "laptop")
    check("книгу", вещь.распознать("книгу"), "book")
    # Нож и ножницы начинаются одинаково — проверка, что они не путаются.
    check("нож", вещь.распознать("нож"), "knife")
    check("ножницы", вещь.распознать("ножницы"), "scissors")
    # Список классов ЗАКРЫТЫЙ, и врать про это нельзя: человек пойдёт искать.
    check("тапок в списке нет", вещь.распознать("тапки"), "")
    check("пустое слово", вещь.распознать(""), "")
    check("обратно по-русски", вещь.назвать("cell phone"), "телефон")
    check("незнакомый класс как есть", вещь.назвать("wombat"), "wombat")

    # СОВПАДЕНИЕ БЕРЁМ САМОЕ ДЛИННОЕ, а не первое по словарю. Найдено
    # аудитом: у телевизора есть синоним «телек» с началом «теле», телевизор
    # в словаре стоит раньше телефона — и любая падежная форма телефона
    # цеплялась за него. На «ты не видел моего телефона» робот уверенно
    # отвечал про телевизор.
    for слово, ждём in (("телефона", "cell phone"), ("телефону", "cell phone"),
                        ("телефоном", "cell phone"), ("телевизора", "tv"),
                        ("телек", "tv")):
        check(f"«{слово}»", вещь.распознать(слово), ждём)

    # Короткие слова: «нож» и «кот» короче четырёх букв, и жёсткое дно в
    # четыре буквы означало бы, что «ножа» и «кота» не находятся вовсе.
    check("ножа", вещь.распознать("ножа"), "knife")
    check("кота", вещь.распознать("кота"), "cat")
    check("ножницами", вещь.распознать("ножницами"), "scissors")
    # И при этом чужое коротким совпадением не цепляется.
    for мимо in ("ложь", "ковёр", "кофе", "ключи"):
        check(f"«{мимо}» мимо словаря", вещь.распознать(мимо), "")

    # Весь словарь должен узнавать сам себя — иначе синоним, добавленный
    # завтра, молча перехватит чужие слова.
    промахи = [с for к, слова in вещь.ПО_РУССКИ.items() for с in слова
               if вещь.распознать(с) != к]
    check("словарь не спорит сам с собой", промахи, [])

    # --- разбор ответа сети ----------------------------------------------
    часы = [1000.0]
    память = вещь.Вещи(ширина_кадра=640.0, часы=lambda: часы[0])

    def ответ(класс, слева_направо, счёт=0.9):
        return {"targets": [{"type": класс, "rois": [
            {"rect": {"x_offset": слева_направо, "width": 80},
             "confidence": счёт}]}]}

    # Робот стоит в начале координат и смотрит вдоль оси X.
    память.принять(ответ("cup", 280), откуда=(0.0, 0.0, 0.0))
    встреча = память.найти("кружка")
    check("кружку запомнили", встреча is not None, True)
    check("почти по центру — угол мал", abs(встреча.угол) < math.radians(10), True)

    # Левее центра кадра — положительный угол, как у пеленга людей и у
    # дальномера. Две системы отсчёта в одной задаче однажды сложатся с
    # разными знаками, и робот поедет не туда.
    память.принять(ответ("book", 0), откуда=(0.0, 0.0, 0.0))
    check("слева — угол положительный", память.найти("книга").угол > 0, True)
    память.принять(ответ("book", 560), откуда=(0.0, 0.0, 0.0))
    check("справа — отрицательный", память.найти("книга").угол < 0, True)

    # Неуверенное не запоминаем: человек пойдёт в комнату проверять, и
    # «кажется, видел» там хуже, чем «не видел».
    память.принять(ответ("banana", 300, счёт=0.1), откуда=(0.0, 0.0, 0.0))
    check("неуверенное не помним", память.найти("банан"), None)

    # Место встречи — в тех же координатах, где робот ездит. Робот, стоявший
    # в (2, 1) и развёрнутый на 90°, видел вещь прямо перед собой: значит
    # смотреть надо на север, а не туда, куда робот смотрит сейчас.
    память.принять(ответ("cat", 320), откуда=(2.0, 1.0, math.pi / 2))
    кошка = память.найти("кот")
    x, y, куда = кошка.где
    check("точка встречи запомнена", (round(x, 2), round(y, 2)), (2.0, 1.0))
    check("и направление тоже",
          abs(куда - math.pi / 2) < math.radians(10), True)
    # Без одометрии направление не восстановить, и выдумывать его нельзя.
    память.принять(ответ("dog", 320), откуда=None)
    check("без одометрии места нет", память.найти("собака").где, None)

    # Что видно сейчас, а что уже память.
    check("кошка свежая", "cat" in [в.класс for в in память.видно()], True)
    часы[0] += 600.0
    check("через десять минут — уже не видно", память.видно(), [])
    check("но помним", память.найти("кошка") is not None, True)
    часы[0] += вещь.ПОМНИМ
    память.принять(ответ("cup", 320), откуда=(0.0, 0.0, 0.0))
    check("сутки спустя забыли", память.найти("кошка"), None)

    # Человеку нужно понять, идти ли проверять, а не число секунд.
    check("только что", вещь.когда_сказать(3), "только что")
    check("минуты", вещь.когда_сказать(600), "10 минут назад")
    check("давно", вещь.когда_сказать(30 * 3600), "давно")
    check("прямо перед носом", вещь.куда_сказать(0.0), "прямо передо мной")
    check("слева", вещь.куда_сказать(math.radians(30)), "слева от меня")
    check("справа", вещь.куда_сказать(-math.radians(30)), "справа от меня")

    # Мусор не должен ронять разбор: сообщение приходит из чужого пакета.
    for мусор in ({}, {"targets": "нет"}, {"targets": [None, 5]},
                  {"targets": [{"type": "cup"}]},
                  {"targets": [{"type": "cup", "rois": [{"rect": {}}]}]}):
        память.принять(мусор, откуда=None)
    check("мусор разобран без падения", True, True)


def test_жесты() -> None:
    """Ладонь — это «стоп», не проходящий через микрофон.

    Голос отказывает ровно тогда, когда нужнее всего: робот едет и шумит
    моторами, он же глушит микрофон на время своей реплики, человек в другом
    конце комнаты, ночью кричать нельзя. Жест обходит всю эту цепочку.

    Сами жесты считает BPU готовыми пакетами TogetheROS; здесь проверяется
    разбор их сообщения и решение по нескольким кадрам.
    """
    section("жесты рукой")

    from robot_voice import gestures as жест

    # Жест лежит в атрибуте цели, а не в отдельном поле.
    кадр = {"targets": [{"track_id": 3, "rois": [{"type": "hand"}],
                         "attributes": [{"type": "gesture",
                                         "value": жест.ЛАДОНЬ}]}]}
    check("ладонь разобрана", жест.жесты_в_кадре(кадр), [(3, жест.ЛАДОНЬ)])

    # Фон — это «жеста нет». Считать его жестом нельзя: он приходит в каждом
    # кадре, где рука видна, но ничего не показывает, и гасил бы набранные
    # подтверждения ровно как настоящий чужой жест.
    фон = {"targets": [{"track_id": 3, "attributes": [
        {"type": "gesture", "value": жест.ФОН}]}]}
    check("фон — не жест", жест.жесты_в_кадре(фон), [])
    check("чужие свойства не трогаем", жест.жесты_в_кадре(
        {"targets": [{"track_id": 1,
                      "attributes": [{"type": "age", "value": 30}]}]}), [])
    check("пустое сообщение", жест.жесты_в_кадре({}), [])

    # --- решение по кадрам ------------------------------------------------
    часы = [0.0]
    было: list[int] = []
    видок = жест.Жесты(показал=lambda ж, _н: было.append(ж),
                       часы=lambda: часы[0])

    def показать(что, номер=3, шаг=0.05):
        часы[0] += шаг
        видок.принять({"targets": [{"track_id": номер, "rois": [{"type": "hand"}],
                                    "attributes": [{"type": "gesture",
                                                    "value": что}]}]})

    # Один кадр — не жест: сеть ошибается, и на одном кадре робот дёргался бы.
    показать(жест.ЛАДОНЬ)
    check("один кадр ладони — ещё не стоп", было, [])

    # И НЕДОСТАТОЧНО НАБРАТЬ КАДРЫ — жест надо УДЕРЖАТЬ. Топик идёт на
    # тридцати кадрах в секунду, поэтому кадры набираются мгновенно; на живом
    # роботе случайно открытая ладонь идущего человека убила следование через
    # три секунды после старта, и робот не сдвинулся вовсе.
    for _ in range(жест.ПОДТВЕРЖДЕНИЙ[жест.ЛАДОНЬ] + 2):
        показать(жест.ЛАДОНЬ, шаг=0.01)
    check("кадров набрали, а держали мало — не стоп", было, [])

    # А вот когда и кадров хватает, и держали положенное — стоп.
    показать(жест.ЛАДОНЬ, шаг=жест.ДЕРЖАТЬ[жест.ЛАДОНЬ])
    check("удержанная ладонь — стоп", было, [жест.ЛАДОНЬ])

    # И не повторяется, пока рука поднята: человек не опускает её за один
    # кадр, и без паузы одна ладонь сработала бы десяток раз.
    for _ in range(10):
        показать(жест.ЛАДОНЬ)
    check("поднятая ладонь не долбит", было, [жест.ЛАДОНЬ])

    # Остальным жестам нужно больше: ложное «иди за мной» отправляет робота на
    # человека, который его не звал, и стоит дороже лишней остановки.
    было.clear()
    часы[0] += жест.МОЛЧИМ
    for _ in range(жест.ПОДТВЕРЖДЕНИЙ_ОБЫЧНО + 2):
        показать(жест.ПАЛЕЦ_ВВЕРХ, номер=5, шаг=0.01)
    check("пальцу вверх мелькнуть мало", было, [])
    показать(жест.ПАЛЕЦ_ВВЕРХ, номер=5, шаг=жест.ДЕРЖАТЬ_ОБЫЧНО)
    check("а удержанному — хватает", было, [жест.ПАЛЕЦ_ВВЕРХ])
    # Ладонь — путь к тормозам, и он обязан оставаться быстрее голоса.
    # Сказать «стоп» и быть расслышанным на этом роботе стоит полсекунды
    # тишины плюс восемьсот миллисекунд распознавания плюс дорогу до колёс:
    # мерено по его же журналу, полторы секунды с лишним.
    ГОЛОСОМ = 1.5
    check("ладонь быстрее голоса", жест.ДЕРЖАТЬ[жест.ЛАДОНЬ] < ГОЛОСОМ, True)
    check("и не медленнее прочих жестов",
          жест.ДЕРЖАТЬ[жест.ЛАДОНЬ] <= жест.ДЕРЖАТЬ_ОБЫЧНО, True)

    # Смена жеста обнуляет счёт: иначе три кадра ладони плюс один палец вверх
    # складывались бы в подтверждённый палец вверх.
    было.clear()
    часы[0] += жест.МОЛЧИМ
    видок2 = жест.Жесты(показал=lambda ж, _н: было.append(ж),
                        часы=lambda: часы[0])
    видок = видок2
    for _ in range(3):
        показать(жест.ОКЕЙ, номер=7)
    показать(жест.ПАЛЕЦ_ВВЕРХ, номер=7)
    check("смена жеста обнуляет счёт", было, [])

    # И срок годности: два случайных распознавания с разницей в минуту — это
    # не жест, который держали минуту.
    было.clear()
    видок = жест.Жесты(показал=lambda ж, _н: было.append(ж),
                       часы=lambda: часы[0])
    показать(жест.ЛАДОНЬ, номер=9)
    показать(жест.ЛАДОНЬ, номер=9, шаг=жест.НАБИРАЕМ_ЗА + 1.0)
    check("разнесённые во времени кадры не складываются", было, [])

    # Обработчик зовётся из потока связи с шасси — по нему же ходит «стоп».
    def взорвётся(*_):
        raise RuntimeError("нарочно")

    видок = жест.Жесты(показал=взорвётся, часы=lambda: часы[0])
    try:
        for _ in range(6):
            показать(жест.ЛАДОНЬ, номер=11)
        упало = False
    except RuntimeError:
        упало = True
    check("сбой обработчика не рвёт связь с шасси", упало, False)


def test_жесты_подняты_в_запуске() -> None:
    """Узлы жестов подключены к НАШЕЙ цепочке, а не к их запуску.

    hand_lmk_detection.launch.py первым делом подключает штатный
    mono2d_body_detection.launch.py — тот самый, который поднимает websocket и
    nginx на порту 8000, где живёт пульт. Один раз это уже стоило вечера:
    пульт не поднимался, в браузере отвечало «404 nginx/1.22.0», а nginx
    демонизировался и переживал остановку детектора.

    Вдобавок это был бы второй mono2d_body_detection и вторая попытка
    захватить USB-камеру, которую держать может только один процесс.
    """
    section("жесты не тянут за собой nginx")
    import ast

    корень = Path(__file__).resolve().parent.parent
    текст = (корень / "scripts" / "mono2d_no_web.launch.py").read_text(
        encoding="utf-8")
    дерево = ast.parse(текст)

    пакеты = set()
    включения = set()
    for узел in ast.walk(дерево):
        if isinstance(узел, ast.Call):
            цель = узел.func
            имя = цель.attr if isinstance(цель, ast.Attribute) else (
                цель.id if isinstance(цель, ast.Name) else "")
            if имя == "Node":
                for довод in узел.keywords:
                    if (довод.arg == "package"
                            and isinstance(довод.value, ast.Constant)):
                        пакеты.add(довод.value.value)
            if имя == "_включить" and узел.args:
                if isinstance(узел.args[0], ast.Constant):
                    включения.add(узел.args[0].value)

    check("узел точек кисти поднимается", "hand_lmk_detection" in пакеты, True)
    check("узел жестов поднимается", "hand_gesture_detection" in пакеты, True)
    # Вот это и есть суть проверки: их launch-файлы мы не подключаем.
    check("их запуски не подключены",
          включения & {"hand_lmk_detection", "hand_gesture_detection",
                       "mono2d_body_detection"}, set())
    # Ищем по строкам ИЗ РАЗБОРА, а не по тексту файла: в шапке про websocket
    # написано нарочно и подробно, и проверка по тексту ловила бы объяснение
    # вместо кода. В разборе комментариев нет — только то, что исполняется.
    строки = {у.value for у in ast.walk(дерево)
              if isinstance(у, ast.Constant) and isinstance(у.value, str)}
    check("websocket нигде не запускается",
          [с for с in строки if "websocket" in с], [])
    # Отсутствие пакетов не должно уносить с собой детектор людей: узел,
    # которого нет, роняет весь launch целиком.
    check("отсутствие жестов не роняет запуск", "def _есть(" in текст, True)


def test_наклон_меряет_свой_шум() -> None:
    """Порог сбоя наклона робот меряет сам, а не берёт из кода.

    Зашитые три градуса оказались МЕНЬШЕ шума замера. На живом роботе,
    стоящем неподвижно на ровном полу, подгонка плоскости выдавала 2°, -2°,
    1°, -3°, 0°, 6°, 9° — разброс до одиннадцати градусов. Норма пола при
    таком пороге выбрасывалась и училась заново каждые десять секунд, то есть
    готовой нормы у робота не было НИКОГДА.

    Подкрутить число было бы той же ошибкой, только позже: шум зависит от
    наклона датчика, мебели и пола, а проверить его можно только в той самой
    квартире. Поэтому робот меряет свой разброс и ставит порог от него.
    """
    section("наклон: порог из замера, а не из кода")

    from robot_voice import tof as д

    check("мало замеров — разброса нет", д.разброс([1.0, 2.0]), None)

    # Тихий пол: замеры кучно вокруг нуля.
    тихо = [0.0, 1.0, -1.0, 0.5, -0.5] * 6
    спокойный = д.разброс(тихо)
    check("на тихом полу разброс мал", спокойный <= 1.0, True)

    # Настоящие числа с робота Игоря — те самые, на которых всё сломалось.
    шумно = [2.0, -2.0, 1.0, -3.0, 0.0, 6.0, 9.0, -3.0, 2.0, -0.0,
             0.0, -3.0, -2.0, 9.0, 3.0, -1.0, 4.0, -4.0, 1.0, 6.0]
    измерен = д.разброс(шумно)
    check("на живых числах разброс заметный", измерен >= 2.0, True)

    # Один выброс не должен раздувать порог: считаем срединное отклонение, а
    # не стандартное. Иначе один дурной замер поднимал бы порог так, что
    # настоящий порожек перестал бы замечаться.
    с_выбросом = тихо + [90.0]
    check("выброс не раздувает разброс",
          д.разброс(с_выбросом) <= спокойный + 1.0, True)

    # Проверяем НАСТОЯЩУЮ функцию из кода, а не её копию здесь: формула,
    # скопированная в тест, однажды разойдётся с кодом и будет проверять
    # саму себя.
    порог = д.порог_наклона

    # И вот главное: на живых числах порог обязан оказаться ВЫШЕ их разброса.
    # Иначе повторится ровно то, что было, — переучивание каждые десять секунд.
    живой_порог = порог(шумно)
    гуляет = max(шумно) - min(шумно)
    check("порог выше типичного гуляния", живой_порог >= гуляет / 2.0, True)
    check("но не бесконечный", живой_порог <= д.НАКЛОН_НЕ_БОЛЬШЕ, True)
    check("на тихом полу порог не проваливается ниже дна",
          порог(тихо) >= д.НАКЛОН_НЕ_МЕНЬШЕ, True)
    # Пока шум не измерен — самый ЧУВСТВИТЕЛЬНЫЙ порог, а не самый терпимый.
    # Переучивание это аварийный выход из «застрял на порожке навсегда», и
    # закрывать его, пока мы ещё ничего не знаем, — худшее из двух.
    check("пока не намеряли — готовы переучиться",
          порог([1.0]), д.НАКЛОН_НЕ_МЕНЬШЕ)


def test_падение() -> None:
    """Человек упал — заметить по скелету, который и так приходит.

    Алгоритм взят у D-Robotics (hobot_falldown_detection) и переписан на
    питон: сам пакет мы не ставим, потому что он подписан ровно на тот топик,
    на который уже подписаны мы, и считает по нему сорок строк тригонометрии.

    Проверяем и две вещи, добавленные сверх оригинала: отброшенные нулевые
    точки и решение по времени, а не по одному кадру.
    """
    section("человек упал")
    import math

    from robot_voice import falldown as падение

    def тело(плечи=None, бёдра=None, щиколотки=None, *, голова=None,
             разброс=22.0, точек=падение.ТОЧЕК):
        """Скелет из 19 точек и рамка вокруг них — как отдаёт детектор.

        Строим ЦЕЛУЮ фигуру, а не три пары: второй признак смотрит на все
        точки сразу и на рамку, и три точки в пустом кадре его бы не
        проверили. Точки раскладываем по ломаной голова — плечи — бёдра —
        щиколотки и разносим поперёк неё, чтобы у фигуры была настоящая
        толщина, а у рамки — настоящая ширина.
        """
        узлы = [т for т in (голова, плечи, бёдра, щиколотки) if т is not None]
        if голова is None and плечи is not None and бёдра is not None:
            # Голова — продолжение линии плечи-бёдра назад, в любую сторону,
            # куда бы человек ни был повёрнут.
            dx, dy = плечи[0] - бёдра[0], плечи[1] - бёдра[1]
            длина = math.hypot(dx, dy) or 1.0
            узлы.insert(0, (плечи[0] + dx / длина * 60.0,
                            плечи[1] + dy / длина * 60.0))
        точки = [{"x": 0.0, "y": 0.0} for _ in range(точек)]
        if len(узлы) >= 2:
            for i in range(точек):
                доля = i / (точек - 1) * (len(узлы) - 1)
                к = min(int(доля), len(узлы) - 2)
                т = доля - к
                x = узлы[к][0] + (узлы[к + 1][0] - узлы[к][0]) * т
                y = узлы[к][1] + (узлы[к + 1][1] - узлы[к][1]) * т
                dx = узлы[к + 1][0] - узлы[к][0]
                dy = узлы[к + 1][1] - узлы[к][1]
                длина = math.hypot(dx, dy) or 1.0
                бок = разброс * (1 if i % 2 else -1)
                точки[i] = {"x": x - dy / длина * бок, "y": y + dx / длина * бок}
        # Три пары ставим точно там, где велено: середина обязана считаться
        # из двух точек, а не подставляться готовой.
        for пара, середина in ((падение.ПЛЕЧИ, плечи),
                               (падение.БЁДРА, бёдра),
                               (падение.ЩИКОЛОТКИ, щиколотки)):
            if середина is None:
                точки[пара[0]] = {"x": 0.0, "y": 0.0}
                точки[пара[1]] = {"x": 0.0, "y": 0.0}
                continue
            x, y = середина
            точки[пара[0]] = {"x": x - 20.0, "y": y}
            точки[пара[1]] = {"x": x + 20.0, "y": y}
        живые = [т for т in точки if т["x"] or т["y"]]
        рамка = None
        if живые:
            xs = [т["x"] for т in живые]
            ys = [т["y"] for т in живые]
            рамка = {"x_offset": min(xs), "y_offset": min(ys),
                     "width": max(1.0, max(xs) - min(xs)),
                     "height": max(1.0, max(ys) - min(ys))}
        return точки, рамка

    # Стоит: и корпус, и ноги почти вертикальны, и силуэт вчетверо выше ширины.
    стоит, рамка_стоя = тело(плечи=(320, 190), бёдра=(325, 300),
                             щиколотки=(320, 440))
    check("стоящий не лежит", падение.лежит(стоит, рамка_стоя), False)
    check("и силуэт у него высокий", падение.силуэт(рамка_стоя) < 1.0, True)

    # Лежит вдоль пола: оба отрезка горизонтальны, силуэт шире, чем выше.
    лежит, рамка_лёжа = тело(плечи=(250, 400), бёдра=(350, 405),
                             щиколотки=(470, 410))
    check("лежащий лежит", падение.лежит(лежит, рамка_лёжа), True)
    check("и силуэт у него широкий",
          падение.силуэт(рамка_лёжа) >= падение.ЛЕЖИТ_ШИРЕ, True)

    # Нагнулся за упавшей вилкой: корпус горизонтален, ноги вертикальны. По
    # одному корпусу он неотличим от лежащего — отличает РАЗБЕГ.
    нагнулся, рамка_согнут = тело(плечи=(250, 300), бёдра=(350, 320),
                                  щиколотки=(360, 460))
    check("нагнувшийся не упал", падение.лежит(нагнулся, рамка_согнут), False)

    # ВОТ РАДИ ЧЕГО ВТОРОЙ ПРИЗНАК. Это стоящий человек, у которого детектор
    # неудачно поставил три пары точек: по ним выходит «лежит». Ровно так
    # робот и ошибся трижды подряд на живом человеке. Силуэт при этом
    # остаётся высоким — и тревоги не будет.
    врут_точки, _ = тело(плечи=(250, 300), бёдра=(350, 320),
                         щиколотки=(450, 335))
    подробно = падение.разобрать(врут_точки, рамка_стоя)
    check("по точкам выходит «лежит»", подробно["по_точкам"], True)
    check("а по форме — нет", подробно["по_форме"], False)
    check("значит тревоги нет", подробно["лежит"], False)

    # --- медиана ----------------------------------------------------------
    # Замер на роботе: у СТОЯЩЕГО человека силуэт гулял от 0.38 до 1.52, ось
    # от 14° до 90°, а угол «бёдра — щиколотки» от 1° до 88°. Булев ответ по
    # такому кадру — подбрасывание монеты. Поэтому решение по медианам.
    check("медиана нечётной длины", падение.медиана([3, 1, 2]), 2)
    check("медиана чётной длины", падение.медиана([1, 2, 3, 4]), 2.5)
    check("дырки пропускаем", падение.медиана([None, 5, None, 7]), 6.0)
    check("совсем пусто", падение.медиана([None, None]), None)
    # Одно дикое значение медиану не двигает — в отличие от среднего.
    check("выброс не сдвигает медиану", падение.медиана([80, 82, 84, 1]), 81.0)

    лёжа_итог = {"корпус": 10.0, "ось": 8.0, "силуэт": 3.0, "замеров": 20}
    стоя_итог = {"корпус": 82.0, "ось": 82.0, "силуэт": 0.65, "замеров": 20}
    check("медианы лежащего — тревога", падение.лежит_по_итогу(лёжа_итог), True)
    check("медианы стоящего — нет", падение.лежит_по_итогу(стоя_итог), False)
    # Ровно те медианы, что сняты с живого стоящего человека.
    check("замеренный стоящий не поднимает тревогу",
          падение.лежит_по_итогу({"корпус": 82.0, "ось": 82.0,
                                  "силуэт": 0.65, "замеров": 475}), False)
    # И одного признака мало: широкий силуэт при вертикальном корпусе — это
    # человек, стоящий вплотную, а не лежащий.
    check("широкий силуэт сам по себе — не падение",
          падение.лежит_по_итогу({"корпус": 82.0, "ось": 20.0,
                                  "силуэт": 3.0, "замеров": 20}), False)

    # Детектор ставит (0, 0) там, где точку не нашёл. Оригинал нули не
    # отбрасывает — и стоящий человек, у которого не видно бёдер (стол,
    # спинка стула, тумбочка: для низкой камеры это каждый вечер), считается
    # у него упавшим. Проверено арифметикой: корпус 25.1°, ноги 54.0°,
    # разбег 28.9° — на порогах оригинала все три пройдены.
    без_бёдер, рамка_без = тело(плечи=(320, 190), щиколотки=(320, 440))
    к = падение.наклон((320.0, 150.0), (0.0, 0.0))
    н = падение.наклон((320.0, 440.0), (0.0, 0.0))
    check("у оригинала это выглядело бы падением",
          abs(к - н) <= 33.0 and к <= 48.0 and н <= 78.0, True)
    check("но точки в нуле — это «не знаю», а не «упал»",
          падение.лежит(без_бёдер, рамка_без), None)

    # Три исхода, а не два: «не вижу» не должно ни поднимать тревогу, ни
    # гасить уже набранные подтверждения.
    нет_ног, рамка_нет = тело(плечи=(250, 400), бёдра=(350, 405))
    check("нет щиколоток — не знаем", падение.лежит(нет_ног, рамка_нет), None)
    чужая, рамка_чужая = тело(плечи=(250, 400), бёдра=(350, 405),
                              щиколотки=(470, 410), точек=17)
    check("чужая модель — не судим", падение.лежит(чужая, рамка_чужая), None)
    check("мусор вместо точек", падение.лежит("нет"), None)
    check("мусор вместо рамки", падение.силуэт("нет"), None)

    # --- решение по времени ----------------------------------------------
    часы = [0.0]
    крики: list[int] = []
    сторож = падение.Сторож(упал=крики.append, часы=lambda: часы[0])

    def кадр(поза, шаг=0.1):
        точки, рамка = поза
        часы[0] += шаг
        сторож.принять({"targets": [{"track_id": 4,
                                     "rois": [{"type": "body", "rect": рамка}],
                                     "points": [
            {"type": падение.СКЕЛЕТ, "point": точки}]}]})

    лёжа = (лежит, рамка_лёжа)
    стоя = (стоит, рамка_стоя)
    полупусто = (без_бёдер, рамка_без)

    # Один кадр падением не является. И секунда — тоже: нагнуться и
    # распрямиться быстрее, чем ДЕРЖИТСЯ.
    for _ in range(10):
        кадр(лёжа)
    check("секунда лёжа — ещё не тревога", крики, [])

    # А вот когда окно набралось И ПО ВРЕМЕНИ, И ПО ЧИСЛУ ЗАМЕРОВ — тревога.
    # Ровно одна: кричать в каждом кадре значит быть выключенным в первый же
    # вечер.
    for _ in range(40):
        кадр(лёжа)
    check("пролежал дольше порога — тревога", крики, [4])
    for _ in range(50):
        кадр(лёжа)
    check("и только одна", крики, [4])

    # Пока лежит — повторяем, но не раньше МОЛЧИМ. И окно после тревоги
    # набирается заново: одного кадра через минуту недостаточно.
    часы[0] += падение.МОЛЧИМ
    кадр(лёжа)
    check("одного кадра после паузы мало", крики, [4])
    for _ in range(50):
        кадр(лёжа)
    check("а набранного окна — хватает", крики, [4, 4])

    # СТОЯЩИЙ НЕ ПОДНИМАЕТ ТРЕВОГУ, сколько бы его ни смотрели. Это та самая
    # проверка, которой не хватило: робот трижды сказал «ты упал» человеку,
    # который стоял.
    сторож = падение.Сторож(упал=крики.append, часы=lambda: часы[0])
    for _ in range(300):
        кадр(стоя)
    check("стоящего не объявляем упавшим", крики, [4, 4])

    # Встал посреди лежания — медиана уезжает, и тревоги нет. Проверяем не
    # «сбросился счётчик», а то, ради чего медиана и заведена: одиночные
    # кадры чужой позы не решают ничего, а устойчивая смена позы решает.
    сторож = падение.Сторож(упал=крики.append, часы=lambda: часы[0])
    for _ in range(10):
        кадр(лёжа)
    for _ in range(40):
        кадр(стоя)
    check("встал — тревоги нет", крики, [4, 4])

    # А ВОТ ОДИНОЧНЫЙ ДУРНОЙ КАДР НЕ ДОЛЖЕН МЕШАТЬ. Замер на роботе показал,
    # что признаки прыгают от кадра к кадру; если бы один кадр «стоит» гасил
    # накопленное, тревога не сработала бы никогда.
    сторож = падение.Сторож(упал=крики.append, часы=lambda: часы[0])
    for i in range(60):
        кадр(стоя if i % 7 == 0 else лёжа)
    check("редкий дурной кадр не мешает", крики, [4, 4, 4])

    # Непригодные кадры не гасят набранное: детектор в половине кадров может
    # не найти бёдра, и требовать сплошного ряда значит не сработать никогда.
    сторож = падение.Сторож(упал=крики.append, часы=lambda: часы[0])
    for _ in range(30):
        кадр(лёжа)
        кадр(полупусто)
    check("мигающий детектор не мешает", len(крики), 4)

    # Сторож зовётся из потока связи с шасси. Сбой обработчика не имеет права
    # уронить этот поток: по нему ходит «стоп».
    def взорвётся(_номер):
        raise RuntimeError("нарочно")

    сторож = падение.Сторож(упал=взорвётся, часы=lambda: часы[0])
    try:
        for _ in range(60):
            кадр(лёжа)
        упало = False
    except RuntimeError:
        упало = True
    check("сбой обработчика не рвёт связь с шасси", упало, False)


def test_vision_track() -> None:
    """Где человек в кадре — по детектору тела на BPU.

    Следование до сих пор велось одним дальномером: восемь колонок на
    шестьдесят градусов. Шаг человека вбок — и он вне поля зрения, шесть
    секунд, «Больше не иду». Так и было в живом журнале. У камеры сто тридцать
    градусов, и она удержит там, где дальномер уже потерял.

    Разбор сообщения намеренно терпимый: форму ai_msgs/PerceptionTargets мы
    живьём не видели, а версии таких пакетов расходятся в мелочах. Прибитый
    разбор означал бы, что обновление пакета молча ломает следование.
    """
    section("вижу человека камерой")
    import math

    from robot_voice import vision_track as вижу

    # Три вида записи рамки, и все три встречаются у пакетов этого семейства.
    for рамка in ({"x_offset": 800, "y_offset": 100, "width": 320, "height": 600},
                  {"x1": 800, "y1": 100, "x2": 1120, "y2": 700},
                  {"center_x": 960, "width": 320}):
        check(f"рамка {sorted(рамка)[0]} разобрана",
              вижу.середина_рамки(рамка), (960.0, 320.0))
    check("чужое не разбираем", вижу.середина_рамки({"нечто": 1}), None)

    # Из нескольких людей берём самого ШИРОКОГО: он ближе, а следовать надо за
    # тем, кто рядом, а не за прохожим в глубине кадра.
    двое = {"targets": [
        {"type": "body", "rois": [{"type": "body",
                                   "rect": {"x_offset": 100, "width": 80}}]},
        {"type": "body", "rois": [{"type": "body",
                                   "rect": {"x_offset": 900, "width": 400}}]},
    ]}
    найдено = вижу.найти_человека(двое)
    check("берём ближнего", найдено[:2], (1100.0, 400.0))

    # Но если своя цель уже выбрана — держим ЕЁ, даже когда чужая ближе.
    # Иначе на кухне робот переключался бы с человека на человека, стоило
    # кому-то пройти между ним и тем, за кем он шёл.
    свои = {"targets": [
        {"type": "person", "track_id": 7,
         "rois": [{"type": "body", "rect": {"x_offset": 100, "width": 80}}]},
        {"type": "person", "track_id": 9,
         "rois": [{"type": "body", "rect": {"x_offset": 900, "width": 400}}]},
    ]}
    check("своя цель важнее ближней",
          вижу.найти_человека(свои, держим=7)[2], 7)
    check("без своей берём ближнюю", вижу.найти_человека(свои)[2], 9)

    # Тело предпочитаем голове: по нему пеленг устойчивее, голова мотается.
    оба = {"targets": [{"type": "person", "track_id": 3, "rois": [
        {"type": "head", "rect": {"x_offset": 500, "width": 60}},
        {"type": "body", "rect": {"x_offset": 400, "width": 260}},
    ]}]}
    check("тело важнее головы", вижу.найти_человека(оба)[:2], (530.0, 260.0))

    # Рука и лицо человеком для следования не считаются: пеленг по кисти
    # уведёт робота в сторону от самого человека.
    рука = {"targets": [{"type": "hand", "rois": [
        {"type": "hand", "rect": {"x_offset": 100, "width": 80}}]}]}
    check("за рукой не идём", вижу.найти_человека(рука), None)
    check("пустое сообщение — никого", вижу.найти_человека({}), None)

    # --- пеленг ----------------------------------------------------------
    глаз = вижу.Глазомер(ширина_кадра=1920.0, поле=130.0)
    # Ширина по умолчанию — та, что публикует hobot_usb_cam (640), а не та,
    # что умеет камера (1920). Ошибка втрое здесь — это пеленг втрое мимо.
    check("умолчание ширины совпадает с детектором",
          вижу.Глазомер().ширина_кадра, 640.0)
    check("до первой детекции взгляд несвежий", глаз.свежий, False)

    глаз.принять({"image_width": 1920, "targets": [
        {"type": "body", "rois": [{"type": "body",
                                   "rect": {"x_offset": 860, "width": 200}}]}]})
    check("человек по центру — угол ноль", round(глаз.угол, 3), 0.0)
    check("и взгляд стал свежим", глаз.свежий, True)

    # Левее центра — положительный угол, как и у дальномера. Две системы
    # отсчёта в одной задаче однажды сложатся с разными знаками, и робот
    # поедет ОТ человека.
    глаз.принять({"image_width": 1920, "targets": [
        {"type": "body", "rois": [{"type": "body",
                                   "rect": {"x_offset": 0, "width": 200}}]}]})
    check("слева — угол положительный", глаз.угол > 0, True)
    глаз.принять({"image_width": 1920, "targets": [
        {"type": "body", "rois": [{"type": "body",
                                   "rect": {"x_offset": 1720, "width": 200}}]}]})
    check("справа — отрицательный", глаз.угол < 0, True)
    # На краю кадра угол не может превысить половину поля зрения камеры.
    check("угол в пределах поля камеры",
          abs(глаз.угол) <= math.radians(130.0) / 2 + 1e-6, True)

    # Ширину кадра берём из самого сообщения: считать пеленг по чужому
    # разрешению — промахиваться тем сильнее, чем дальше человек от центра.
    узкий = вижу.Глазомер(ширина_кадра=1920.0)
    узкий.принять({"image_width": 640, "targets": [
        {"type": "body", "rois": [{"type": "body",
                                   "rect": {"x_offset": 0, "width": 40}}]}]})
    check("ширина кадра взята из сообщения", узкий.угол > 0.5, True)

    # Сообщение без человека прошлую отметку не портит: детектор отдаёт кадры
    # десятками в секунду, и в части из них человек мигает.
    было = глаз.угол
    глаз.принять({"targets": []})
    check("пустой кадр отметку не трогает", глаз.угол, было)

    check("подписка на нужный топик",
          глаз.подписка()["topic"], вижу.ТОПИК)

    # --- цель отпускается ------------------------------------------------
    # Номера детектор выдаёт по порядку и рано или поздно повторяет.
    # Держаться за номер, которого не видели полминуты, значит однажды пойти
    # за чужим человеком со случайно совпавшим номером.
    забывчивый = вижу.Глазомер()
    забывчивый.принять({"targets": [{"type": "person", "track_id": 11, "rois": [
        {"type": "body", "rect": {"x_offset": 100, "width": 80}}]}]})
    check("цель взята", забывчивый.держим, 11)
    # Отматываем время назад: цель не видели дольше срока.
    забывчивый._когда -= вижу.ОТПУСКАЕМ_ЧЕРЕЗ + 1.0
    забывчивый.принять({"targets": [{"type": "person", "track_id": 12, "rois": [
        {"type": "body", "rect": {"x_offset": 300, "width": 90}}]}]})
    check("старая отпущена, взята новая", забывчивый.держим, 12)

    # А свежую цель на чужую не меняем, даже если чужая ближе: иначе на кухне
    # робот переключался бы с человека на человека.
    держит = вижу.Глазомер()
    держит.принять({"targets": [{"type": "person", "track_id": 21, "rois": [
        {"type": "body", "rect": {"x_offset": 100, "width": 80}}]}]})
    держит.принять({"targets": [{"type": "person", "track_id": 22, "rois": [
        {"type": "body", "rect": {"x_offset": 300, "width": 400}}]}]})
    check("свежую цель на чужую не меняем", держит.держим, 21)

    держит.забыть()
    check("забыть отпускает", держит.держим, 0)
    check("и взгляд становится несвежим", держит.свежий, False)


def test_range_by_feet() -> None:
    """Расстояние до человека по одной камере — робот учит связь сам.

    Ради чего. Дальномер видит шестьдесят градусов, камера — сто тридцать.
    Человек, шагнувший вбок, для дальномера пропал, и робот мог только
    доворачиваться вслепую, не зная, догонять или притормозить.

    Геометрию камеры мерить линейкой не станем: высота и наклон меняются от
    того, что её задели, и записанные однажды числа устареют МОЛЧА. Вместо
    этого робот собирает пары «пиксель ног — метры с дальномера», пока идёт
    за человеком, и выводит связь сам.
    """
    section("расстояние по ногам")
    import random

    from robot_voice.vision_track import Дальномер_по_ногам, ноги

    # --- ноги это самая нижняя точка скелета -----------------------------
    # Не «щиколотка номер такой-то»: номера точек у разных выпусков детектора
    # разные, а «ниже всех» — это ноги при любом соглашении.
    цель = {"points": [{"type": "body_kps", "point": [
        {"x": 230.0, "y": 265.0}, {"x": 24.0, "y": 448.0},
        {"x": 31.0, "y": 451.6}, {"x": 0.0, "y": 0.0}]}]}
    check("нашли самую нижнюю точку", ноги(цель), 451.6)
    # Ноль детектор ставит там, где точку не нашёл. Считать его ногой значит
    # померить расстояние до верхнего края кадра.
    check("ненайденную точку не считаем", ноги({"points": [
        {"point": [{"x": 0.0, "y": 0.0}]}]}), None)
    check("без скелета честное «не знаю»", ноги({"points": []}), None)

    # --- связь восстанавливается точно ------------------------------------
    k, y0 = 90.0, 200.0          # «настоящая» камера: горизонт на 200-м пикселе
    чисто = [(п, k / (п - y0)) for п in
             (240, 250, 260, 275, 290, 310, 330, 360, 400, 460)]

    точный = Дальномер_по_ногам()
    for пиксель, метры in чисто:
        точный.запомнить(пиксель, метры)
    check("связь выучена", точный.выучен, True)
    check("горизонт найден точно", round(точный.y0), 200)
    check("и расстояние сходится",
          round(точный.сколько(300), 2), round(k / 100, 2))

    # Замеры дальномера шумят на сантиметры — связь обязана это пережить.
    random.seed(1)
    шумный = Дальномер_по_ногам()
    for пиксель, метры in чисто:
        шумный.запомнить(пиксель, метры + random.uniform(-0.03, 0.03))
    check("шум замеров не мешает", шумный.выучен, True)
    check("и ответ остаётся годным",
          abs(шумный.сколько(300) - 0.9) < 0.1, True)

    # --- САМОЕ ВАЖНОЕ: на мусоре не выучивается --------------------------
    # Наименьшие квадраты проведут прямую через что угодно и вернут красивые
    # числа — без единого признака того, что связи нет. Первая версия так и
    # сделала: объявила себя выученной на случайном наборе. Робот, поверивший
    # такому расстоянию, поехал бы на человека уверенно и молча.
    мусор = Дальномер_по_ногам()
    for i, пиксель in enumerate((240, 250, 260, 275, 290, 310, 330, 360, 400, 460)):
        мусор.запомнить(пиксель, 1.0 + (i % 2) * 0.6)
    check("на мусоре не выучивается", мусор.выучен, False)
    check("и молчит, а не выдумывает", мусор.сколько(300), 0.0)

    random.seed(7)
    случай = Дальномер_по_ногам()
    for пиксель in (240, 250, 260, 275, 290, 310, 330, 360, 400, 460):
        случай.запомнить(пиксель, random.uniform(0.4, 2.5))
    check("на случайных числах тоже", случай.выучен, False)

    # --- осторожность в мелочах -------------------------------------------
    мало = Дальномер_по_ногам()
    for пиксель, метры in чисто[:4]:
        мало.запомнить(пиксель, метры)
    check("по четырём парам не выучиваемся", мало.выучен, False)

    # Пары, снятые с одного места, задают прямую с любым наклоном.
    на_месте = Дальномер_по_ногам()
    for i in range(12):
        на_месте.запомнить(300 + i * 0.1, 0.9)
    check("без разбега по расстоянию не выучиваемся", на_месте.выучен, False)

    # За пределами, на которых учились, не отвечаем: прямая, продолженная
    # вдаль, даёт красивые числа и никакого отношения к правде.
    check("слишком далеко — молчим", точный.сколько(y0 + 1), 0.0)
    check("выше горизонта — молчим", точный.сколько(y0 - 10), 0.0)


def test_follow_speed() -> None:
    """Скорость следования — функция от того, насколько далеко видно свободно.

    Раньше здесь стояло одно число, 0.22 м/с, с доводом «догонять человека
    незачем». Довод звучал разумно и был неверен: человек по квартире идёт
    1.0-1.4 м/с, то есть вшестеро быстрее. Робот отставал с первого шага,
    человек уходил из поля зрения, и следование кончалось словами «Больше не
    иду». Не настройка подвела — при такой скорости следование не могло
    работать в принципе.

    Но и одним числом предел не поднять: между появлением препятствия и
    остановкой проходит кадр дальномера, второй кадр для веры, опрос сторожа
    и сам тормозной путь, который растёт КАК КВАДРАТ скорости.
    """
    section("скорость по тормозному пути")
    import math

    from robot_voice import follow

    # --- главное свойство: успеть затормозить ----------------------------
    # Проверяем не числа, а физику: на разрешённой скорости робот обязан
    # уместить время реакции и торможение в то расстояние, что видит.
    for свободно in (0.5, 0.75, 1.0, 1.5, 2.0, 3.5):
        v = follow.скорость_по_виду(свободно)
        путь = (v * follow.ЗАДЕРЖКА_РЕАКЦИИ
                + v * v / (2 * follow.ЗАМЕДЛЕНИЕ))
        место = свободно - follow.ЗАПАС_ДО_ПРЕПЯТСТВИЯ
        check(f"на {свободно:.2f} м успеваем затормозить",
              путь <= место + 1e-6 or v >= follow.СКОРОСТЬ_ПОТОЛОК, True)

    # Вплотную — стоим. Не «медленно», а стоим: там уже нога.
    check("вплотную не едем", follow.скорость_по_виду(0.3), 0.0)
    check("и на самом запасе тоже",
          follow.скорость_по_виду(follow.ЗАПАС_ДО_ПРЕПЯТСТВИЯ), 0.0)

    # Простор не даёт разгоняться без предела: потолок не про физику, а про
    # людей — робот, несущийся по квартире с ребёнком, пугает независимо от
    # того, успеет ли он затормозить.
    check("потолок держится", follow.скорость_по_виду(10.0),
          follow.СКОРОСТЬ_ПОТОЛОК)
    # И потолок всё же быстрее прежнего числа, иначе всё это зря.
    check("быстрее прежних 0.22", follow.СКОРОСТЬ_ПОТОЛОК > 0.22, True)

    # Незнание — повод для осторожности, а не для потолка.
    вперёд, _ = follow.как_ехать(3.0, 0.0, свободно=0.0)
    check("не знаем, что впереди — едем как раньше", вперёд, follow.ОСТОРОЖНО)
    вперёд, _ = follow.как_ехать(3.0, 0.0, свободно=3.0)
    check("видим далеко — едем быстро", вперёд, follow.СКОРОСТЬ_ПОТОЛОК)
    вперёд, _ = follow.как_ехать(3.0, 0.0, свободно=0.6)
    check("видим близко — ползём", 0 < вперёд < follow.ОСТОРОЖНО + 0.15, True)

    # --- поворот тоже зависит от тесноты ----------------------------------
    # Вращение на месте кажется безобидным и таковым не является: робот сзади
    # и по бокам СЛЕП, а углы корпуса при вращении описывают окружность.
    # Человек, стоящий сбоку в двадцати сантиметрах, для дальномера не
    # существует — и получает углом.
    check("в тесноте крутимся медленно",
          follow.поворот_по_виду(0.4), follow.ПОВОРОТ_ОСТОРОЖНО)
    check("на просторе — в полную силу",
          follow.поворот_по_виду(3.0), follow.ПОВОРОТ_МАКС)
    check("не знаем — осторожно",
          follow.поворот_по_виду(0.0), follow.ПОВОРОТ_ОСТОРОЖНО)
    # Но НИКОГДА не ноль: поворот — единственный способ разыскать потерянного
    # человека и единственный способ отвернуться от препятствия. Запретив его,
    # мы получили бы робота, который умеет только стоять.
    for свободно in (0.0, 0.1, 0.3, 0.5, 1.0, 3.0):
        check(f"поворот не запрещён при {свободно:.1f} м",
              follow.поворот_по_виду(свободно) > 0.0, True)
    # И в тесноте поворот действительно ограничивается, а не только скорость.
    _, поворот_тесно = follow.как_ехать(2.0, math.radians(40), свободно=0.4)
    _, поворот_простор = follow.как_ехать(2.0, math.radians(40), свободно=3.0)
    check("в тесноте доворачиваем медленнее",
          поворот_тесно < поворот_простор, True)

    # --- плавность --------------------------------------------------------
    # Без ограничения скорость прыгает ступенькой: у меканума ролики
    # срываются в проскальзывание, одометрия врёт, человеку кажется, что
    # робот дёргается.
    было = 0.0
    for _ in range(3):
        было = follow.придержать(было, 0.55, 0.1, follow.РАЗГОН,
                                 follow.ЗАМЕДЛЕНИЕ_ПЛАВНОЕ)
    check("разгон постепенный", было < 0.2, True)
    check("но не стоит на месте", было > 0.1, True)

    # Тормозить разрешаем быстрее, чем разгоняться: ограничивать торможение
    # ради плавности значит продлевать тормозной путь.
    торм = follow.придержать(0.55, 0.0, 0.1, follow.РАЗГОН,
                             follow.ЗАМЕДЛЕНИЕ_ПЛАВНОЕ)
    разг = follow.придержать(0.0, 0.55, 0.1, follow.РАЗГОН,
                             follow.ЗАМЕДЛЕНИЕ_ПЛАВНОЕ)
    check("тормозим быстрее, чем разгоняемся", (0.55 - торм) > разг, True)
    check("нулевой шаг ничего не ломает",
          follow.придержать(0.3, 0.5, 0.0, 1.0, 1.0), 0.5)


def test_follow_with_camera() -> None:
    """Камера подхватывает там, где дальномер потерял.

    У дальномера шестьдесят градусов и восемь колонок. Шаг человека вбок — и
    он вне поля зрения: робот встаёт и через шесть секунд говорит «Больше не
    иду», хотя человек в двух шагах, просто правее. Ровно это и было в живом
    журнале.

    У камеры сто тридцать градусов и рамка в пикселях — втрое шире и точнее.
    Но метров она не знает, и знать их обязательно: держать дистанцию по
    размеру рамки значит подъезжать вплотную к худому и отставать от полного.
    Поэтому поворот по камере, расстояние по дальномеру.
    """
    section("следую за тобой, глядя камерой")
    import types

    from robot_voice import follow
    from robot_voice import vision_track as вижу

    # Настоящее сообщение с живого робота, укороченное до сути.
    def детекция(x_offset, width=409, номер=4):
        return {"header": {"frame_id": "5148"}, "fps": 30, "targets": [
            {"type": "person", "track_id": номер, "rois": [
                {"type": "body", "confidence": 0.0,
                 "rect": {"x_offset": x_offset, "y_offset": 205,
                          "height": 261, "width": width,
                          "do_rectify": False}}],
             "attributes": [], "points": []}]}

    глаз = вижу.Глазомер()
    глаз.принять(детекция(x_offset=2))
    check("человек слева опознан", глаз.держим, 4)
    check("и пеленг влево", глаз.угол > 0, True)

    # Уверенность у этого детектора ВСЕГДА ноль — так он устроен. Фильтровать
    # по ней значит не видеть никого и никогда.
    check("нулевая уверенность не мешает", глаз.свежий, True)

    # --- камера ведёт, когда дальномер уже не видит ----------------------
    поехали = []
    ros = types.SimpleNamespace(publish_twist=lambda *a: поехали.append(a))
    пусто = [[0.0] * 8 for _ in range(8)]
    тоф = types.SimpleNamespace(
        взгляд=lambda: types.SimpleNamespace(свежий=True, сетка=пусто,
                                             сетка_без_пола=пусто),
        мешает=lambda: "")
    ведомый = follow.Следование(ros, тоф, глаза=глаз)
    check("дальномер и правда никого не видит",
          follow.найти_цель(пусто), None)

    # Раньше здесь следование заканчивалось. Теперь есть камерный пеленг.
    ведомый._стоп.clear()
    ведомый.почему_кончилось = ""
    import threading as th
    поток = th.Thread(target=ведомый._вести, daemon=True)
    поток.start()
    time.sleep(0.6)
    ведомый.хватит("проверка")
    поток.join(timeout=2)
    # publish_twist зовут и без доводов — это команда «стоять».
    повороты = [а[2] for а in поехали if len(а) >= 3 and abs(а[2]) > 1e-6]
    check("робот довернулся к человеку по камере", bool(повороты), True)
    check("и доворачивался влево", all(w > 0 for w in повороты), True)

    # --- робот не жалуется на того, за кем идёт ---------------------------
    # Сторож не знает, что мы кого-то ведём, и честно сообщает про всё ближе
    # тридцати пяти сантиметров. А ближе всех при следовании обычно сам
    # ведомый: человек остановился, робот подкатился — и вот уже «Не могу
    # идти следом, впереди что-то». «Что-то» — это тот, за кем робот идёт.
    ворчун: list[str] = []
    близко = [[0.0] * 8 for _ in range(8)]
    for р in range(3, 6):
        for к in range(3, 6):
            близко[р][к] = follow.СТОЯТЬ_БЛИЖЕ      # человек стоит вплотную
    тоф_ворчит = types.SimpleNamespace(
        взгляд=lambda: types.SimpleNamespace(свежий=True, сетка=близко,
                                             сетка_без_пола=близко,
                                             свободно_впереди=follow.СТОЯТЬ_БЛИЖЕ),
        мешает=lambda: "впереди что-то")
    вплотную = follow.Следование(
        types.SimpleNamespace(publish_twist=lambda *a: None, voltage=12.4),
        тоф_ворчит, говорить=ворчун.append)
    вплотную._стоп.clear()
    поток3 = th.Thread(target=вплотную._вести, daemon=True)
    поток3.start()
    time.sleep(follow.МОЛЧА_НЕ_ЕДЕМ + 0.8)
    вплотную.хватит("проверка")
    поток3.join(timeout=2)
    check("на ведомого не жалуемся",
          [ф for ф in ворчун if "не могу идти" in ф.lower()], [])

    # --- батарея проверяется НА ХОДУ --------------------------------------
    # Следование длится до пяти минут, и батарея за это время садится.
    # Проверка только на входе означала бы, что робот заезжает в разряд и
    # молча встаёт посреди коридора — а выглядит это как поломка.
    сказанное: list[str] = []
    севший = types.SimpleNamespace(
        publish_twist=lambda *a: None,
        voltage=follow.БАТАРЕЯ_МИНИМУМ - 0.3)
    садится = follow.Следование(севший, тоф, говорить=сказанное.append,
                                глаза=глаз)
    садится._стоп.clear()
    поток2 = th.Thread(target=садится._вести, daemon=True)
    поток2.start()
    поток2.join(timeout=2)
    check("на севшей батарее следование прекращается",
          садится.почему_кончилось, "батарея")
    check("и робот об этом говорит",
          any("батаре" in ф.lower() for ф in сказанное), True)

    # Цикл крутится 15 раз в секунду — как и остальное движение. Шасси само
    # тормозит при паузе в /cmd_vel, и редкая публикация означала бы робота,
    # который дёргается: поехал, притормозил, поехал.
    check("цикл 15 раз в секунду", round(1 / follow.ШАГ), 15)

    # --- без камеры всё как было -----------------------------------------
    # Следование обязано работать и без детектора: не запущенный узел ROS не
    # должен означать онемевшую команду.
    слепой = follow.Следование(ros, тоф)
    check("без глаз следование собирается", слепой.глаза, None)


def test_plane() -> None:
    """Пол — плоскость, а не «нижние два ряда».

    Три допущения старых правил ломались на живом роботе, и хуже всех третье:
    при наклоне датчика вниз на 10-15°, как было записано в docs/hardware.md,
    ряд 5 упирается в пол на 33 см — ближе порога стопа в 35 см. Робот,
    собранный строго по инструкции, не ехал вперёд НИКОГДА и жаловался на
    «одно и то же препятствие уже 60 секунд». Препятствием был его пол.

    Плоскость это снимает: наклон выводится, а не задаётся, и пол перестаёт
    быть препятствием при любом наклоне.
    """
    section("пол как плоскость")
    import math

    import numpy as np

    from robot_voice import plane

    def увидеть(наклон=10.0, высота=0.13, предметы=(), предел=3.5):
        """Что увидит датчик с такой геометрией над ровным полом."""
        н = math.radians(наклон)
        R = np.array([[math.cos(н), 0, math.sin(н)],
                      [0, 1, 0],
                      [-math.sin(н), 0, math.cos(н)]])
        мир = plane.направления() @ R.T
        подъём = {(r, c): h / 100.0 for r, c, h in предметы}
        сетка = [[0.0] * 8 for _ in range(8)]
        for r in range(8):
            for c in range(8):
                vz = мир[r, c, 2]
                if vz >= -1e-6:
                    continue            # смотрит выше горизонта — пола не встретит
                d = -(высота - подъём.get((r, c), 0.0)) / vz
                if 0 < d <= предел:
                    сетка[r][c] = round(float(d), 3)
        return сетка

    # --- наклон и высота выводятся, а не задаются -------------------------
    for наклон in (0.0, 5.0, 10.0, 15.0, 20.0):
        п = plane.найти(увидеть(наклон=наклон))
        check(f"плоскость найдена при наклоне {наклон:.0f}°", п is not None, True)
        if п is None:
            continue
        check(f"высота датчика при {наклон:.0f}°", round(п.высота, 2), 0.13)
        check(f"наклон при {наклон:.0f}° узнан", round(п.наклон), наклон)
        check(f"и это похоже на пол при {наклон:.0f}°", п.похожа_на_пол, True)

    # --- ВОТ РАДИ ЧЕГО ВСЁ ЗАТЕВАЛОСЬ ------------------------------------
    # При наклоне 15° ряд 5 видит пол ближе порога стопа. Старый сторож
    # объявлял это препятствием и не пускал вперёд никогда.
    сетка15 = увидеть(наклон=15.0)
    ряд5 = [d for d in сетка15[5] if d]
    check("при наклоне 15° ряд 5 видит пол ближе порога стопа",
          bool(ряд5) and min(ряд5) < 0.35, True)
    # А по плоскости он оказывается ровно полом: высота над ней — ноль.
    п = plane.найти(сетка15)
    точки, живые = plane.точки(сетка15)
    высоты = п.высоты(точки)
    самая = max(abs(float(высоты[r][c])) for r in range(8) for c in range(8)
                if живые[r][c])
    check("но по плоскости это пол, а не препятствие",
          самая < plane.ТОЛЩИНА_ПОЛА, True)

    # --- нога на полу видна, и видна ровно той высоты, что есть ----------
    нога = увидеть(предметы=[(5, 3, 8), (5, 4, 8), (6, 3, 8), (6, 4, 8)])
    п = plane.найти(нога)
    точки, живые = plane.точки(нога)
    высоты = п.высоты(точки)
    check("нога торчит на восемь сантиметров",
          round(float(высоты[5][3]) * 100), 8)
    поднятые = {(r, c) for r in range(8) for c in range(8)
                if живые[r][c] and высоты[r][c] > plane.ТОЛЩИНА_ПОЛА}
    check("и торчит ровно там, где стоит",
          поднятые, {(5, 3), (5, 4), (6, 3), (6, 4)})
    # Наклон при этом всё равно узнан верно: предмет отбрасывается как
    # несогласный, а не портит подгонку. Ради этого и взят отбор большинством.
    check("предмет не сбил плоскость", round(п.наклон), 10)

    # --- порожек в сантиметр полом и остаётся ----------------------------
    # Иначе робот встанет на каждом стыке плитки, и человек выключит защиту.
    порожек = увидеть(предметы=[(6, 3, 1), (6, 4, 1)])
    п = plane.найти(порожек)
    точки, живые = plane.точки(порожек)
    высоты = п.высоты(точки)
    check("сантиметровый порожек не препятствие",
          float(высоты[6][3]) < plane.ТОЛЩИНА_ПОЛА, True)

    # --- пустой кадр: честное «не знаю», а не выдуманная плоскость -------
    check("по пустой сетке плоскости нет",
          plane.найти([[0.0] * 8 for _ in range(8)]), None)
    # Три точки — это ещё не пол: через любые три проходит плоскость, и
    # поверить ей значит поверить случайности.
    жидко = [[0.0] * 8 for _ in range(8)]
    жидко[7][0] = жидко[7][3] = жидко[7][7] = 0.3
    check("по трём точкам плоскость не выдумываем",
          plane.найти(жидко) is None or plane.найти(жидко).своих >= 3, True)

    # --- сторож считает по плоскости, когда она есть ---------------------
    # Ради этого всё и делалось: при наклоне 15° старый сторож видел
    # препятствие в собственном полу и не пускал вперёд НИКОГДА.
    from robot_voice import tof

    def взгляд_на(сетка):
        return tof.Взгляд(сетка, time.time())

    в = взгляд_на(увидеть(наклон=15.0))
    check("пустой пол при наклоне 15° — не препятствие", в.зон_близко, 0)
    check("и ехать по нему можно", в.ехать_можно()[0], True)
    # А нога на нём — препятствие, и без всякой выученной нормы.
    нога15 = увидеть(наклон=15.0,
                     предметы=[(4, 3, 8), (4, 4, 8), (5, 3, 8), (5, 4, 8)])
    в = взгляд_на(нога15)
    check("нога на полу видна без нормы", в.зон_близко >= tof.ЗОН_ДЛЯ_СТОПА, True)
    check("и робот про свою слепоту больше не говорит", в.низ_не_вижу, False)

    # Люстра и притолока — не препятствие: робот под ними проедет.
    сверху = увидеть(наклон=15.0, предметы=[(0, 3, 60), (0, 4, 60),
                                            (1, 3, 60), (1, 4, 60)])
    check("высокое не мешает", взгляд_на(сверху).зон_близко, 0)

    # --- стена перед носом полом не считается ----------------------------
    # Ровная стена — тоже плоскость, и подгонка найдёт её. Но нормаль у неё
    # горизонтальная, и принять её за пол значит поехать в стену.
    стена = [[1.0] * 8 for _ in range(8)]
    п = plane.найти(стена)
    check("стена — плоскость, но не пол",
          п is None or not п.похожа_на_пол, True)


def test_turn_end() -> None:
    """Конец реплики слышен по звуку, а не по тишине.

    Живой журнал ПК: «на 5.0 с звука» подряд, раз за разом. Пять секунд —
    потолок окна команды. Запись обязана кончаться через полтысячи
    миллисекунд тишины, а упирается в предел: в квартире с ребёнком тишины не
    наступает вовсе. Человек сказал «Кузя, сколько времени» за две секунды и
    ждёт ещё три, пока робот пишет комнату, уже всё расслышав.

    Главное свойство, которое здесь и проверяется: определитель умеет резать
    только РАНЬШЕ прежних правил, никогда позже. Значит худший случай равен
    сегодняшнему поведению, а сломанная или отсутствующая модель ничего не
    ухудшает.
    """
    section("конец реплики по звуку")
    import numpy as np

    import subprocess

    from robot_voice import turn_end

    # --- разбор ответа сети ------------------------------------------------
    # Модели этого рода выходят версиями, и версии отдают ответ по-разному:
    # одно число логитом, одно число готовой вероятностью, два числа классами.
    # Гадать по имени файла нельзя — разбираем все три.
    пустышка = turn_end.КонецРеплики.__new__(turn_end.КонецРеплики)

    def вер(числа, логиты=None):
        пустышка.логиты = логиты
        return пустышка._вероятность(np.array(числа, dtype=np.float32))

    check("объявленная вероятность взята как есть",
          round(вер([0.9], логиты=False), 3), 0.9)
    check("объявленный логит посчитан",
          round(вер([0.0], логиты=True), 3), 0.5)
    check("большой логит — уверенное да", вер([20.0], логиты=True) > 0.99, True)
    двое = вер([-2.0, 2.0])
    check("два класса разобраны", двое is not None and двое > 0.98, True)
    check("чужой выход честно неизвестен", вер([1.0, 2.0, 3.0]), None)

    # Самое опасное место всего модуля. Одно число неоднозначно: 0.9 — это и
    # вероятность 0.9 (обрывать пора), и логит 0.9 (на деле 0.71, рано). Приняв
    # логит за вероятность, робот обрежет человека на полуслове.
    #
    # Пока не выяснили — держимся безопасной стороны, то есть считаем логитом.
    # Ошибка сюда стоит доли секунды ожидания, ошибка обратно — фразы.
    check("в незнании считаем логитом",
          round(вер([0.9], логиты=None), 3), round(1 / (1 + 2.718281828 ** -0.9), 3))
    # И выясняем делом: число вне [0, 1] бывает только у логита.
    пустышка.логиты = None
    пустышка._вероятность(np.array([7.0], dtype=np.float32))
    check("увидели логит — запомнили навсегда", пустышка.логиты, True)

    # --- нет модели — нет и вреда -----------------------------------------
    # Это рабочий режим, а не поломка: у человека может не быть файла, и робот
    # обязан продолжать слышать ровно как раньше.
    пустой = turn_end.КонецРеплики(Path(tempfile.mkdtemp()) / "нет.onnx")
    check("без файла не готов", пустой.готов, False)
    check("и говорит почему", "нет файла" in пустой.почему_нет(), True)
    check("не знает, а не выдумывает", пустой.договорил(np.zeros(1600)), None)
    check("и не тратит процессор", пустой.пора_спросить(5.0), False)

    class Заглушка(turn_end.КонецРеплики):
        """Сеть, отвечающая заданным числом. Настоящую сюда не затащить."""

        def __init__(self, ответ, длина=16000) -> None:
            self.частота = 16000
            self.порог = turn_end.ПОРОГ
            self.сессия = object()
            self._вход = "x"
            self._длина = длина
            self._спрошено = 0.0
            self._жалоба = ""
            self.спросили = self.оборвали = 0
            self._мс = 0.0
            self.логиты = False       # заглушка отвечает готовой вероятностью
            # Волной, а не картинкой: эти проверки про отбор хвоста и масштаб,
            # а спектрограмма проверяется отдельно, выше.
            self._мел = None
            self._кадров = 0
            self.ответ = ответ
            self.видел = None

        def _спросить(self, звук):
            # Окно считаем настоящее: ради него половина проверок и написана.
            self.видел = self._окно(звук)
            if isinstance(self.ответ, Exception):
                raise self.ответ
            return self.ответ

    # --- порог ------------------------------------------------------------
    # Планка высокая намеренно. Ошибка «решил, что договорил» обрезает
    # человека на полуслове; ошибка «не решил» стоит всего лишь сегодняшнего
    # ожидания. Цена этих ошибок несоизмерима.
    check("уверенное да — обрываем",
          Заглушка(0.99).договорил(np.zeros(16000)), True)
    check("сомнение — ждём как раньше",
          Заглушка(0.5).договорил(np.zeros(16000)), False)
    check("ровно на пороге — обрываем",
          Заглушка(turn_end.ПОРОГ).договорил(np.zeros(16000)), True)

    # Сеть отказала — молчим и живём по-старому. Ронять из-за ускорителя весь
    # слух робота нельзя: он ускоряет, а не работает.
    сломана = Заглушка(RuntimeError("сеть развалилась"))
    check("отказ сети — не знаю", сломана.договорил(np.zeros(16000)), None)
    check("и больше её не зовём", сломана.готов, False)

    # --- окно -------------------------------------------------------------
    # Берём ХВОСТ записи, а не начало: конец реплики слышен по её концу.
    # И дополняем тишиной СЛЕВА — чтобы конец остался у правого края, там же,
    # где он был у примеров при обучении.
    д = Заглушка(0.99, длина=8)
    д.договорил(np.arange(1, 21, dtype=np.float32) / 100.0)
    хвост = д.видел.ravel()
    check("окно нужной длины", хвост.shape, (8,))
    check("взят хвост, а не начало", round(float(хвост[-1]), 4), 0.2)

    д = Заглушка(0.99, длина=8)
    д.договорил(np.array([0.5, 0.5], dtype=np.float32))
    короткий = д.видел.ravel()
    check("короткое дополнено слева", list(короткий[:6]), [0.0] * 6)
    check("а речь осталась справа", list(короткий[-2:]), [0.5, 0.5])

    # Целые отсчёты приводятся к отрезку [-1, 1]: микрофон отдаёт int16, а
    # сеть учили на нормированном звуке. Подать ей тридцать тысяч вместо
    # единицы — значит спросить про совсем другой сигнал.
    д = Заглушка(0.99, длина=4)
    д.договорил(np.array([16384, -16384, 0, 32767], dtype=np.int16))
    check("целые приведены к единице",
          abs(float(д.видел.ravel()[0]) - 0.5) < 0.01, True)

    # --- как часто спрашивать ---------------------------------------------
    # Чаще четверти секунды — жжём процессор на A55 без пользы: реплика за это
    # время дважды не заканчивается. И не спрашиваем на огрызке короче 0.7 с —
    # там сеть отвечает наугад.
    ч = Заглушка(0.99)
    # --- отчёт в журнал ----------------------------------------------------
    # Без него определитель неотлаживаем: сеть, которая всегда отвечает «нет»,
    # снаружи неотличима от выключенной — робот в обоих случаях просто ждёт
    # тишины. А лечатся эти два случая по-разному, и гадать человеку не из чего.
    молчун = Заглушка(0.1)
    молчун.спросили = turn_end.ОТЧЁТ_КАЖДЫЕ - 1
    сказанное: list[str] = []

    class Слушок(logging.Handler):
        def emit(self, record):
            сказанное.append(record.getMessage())

    жур = logging.getLogger("robot_voice.turn_end")
    ловец = Слушок()
    жур.addHandler(ловец)
    было_уровень = жур.level
    жур.setLevel(logging.INFO)
    try:
        молчун.договорил(np.zeros(16000))
    finally:
        жур.removeHandler(ловец)
        жур.setLevel(было_уровень)
    check("отчёт написан", any("спросили" in с for с in сказанное), True)
    check("и сказано, что не оборвала ни разу",
          any("НИ РАЗУ" in с for с in сказанное), True)

    check("на огрызке не спрашиваем", ч.пора_спросить(0.3), False)
    check("на реплике спрашиваем", ч.пора_спросить(2.0), True)
    check("и тут же второй раз — нет", ч.пора_спросить(2.0), False)

    # --- чем кормить сеть: картинкой, а не волной ------------------------
    # Статьи пишут «модель смотрит на сырую волну», и первая версия послушно
    # подавала волну. Живая модель попросила другого:
    #
    #     вход:  input_features ['s6', 80, 800]
    #
    # Это лог-мел спектрограмма — вход энкодера whisper. Волна туда влезла бы
    # по форме, и сеть уверенно отвечала бы правдоподобными числами о шуме:
    # поломка без ошибки, без молчания и без единого признака снаружи.
    from robot_voice import melspec

    # Шкала мелов бывает двух видов, Slaney и HTK, и они расходятся уже на
    # середине диапазона. Whisper использует Slaney; взять не ту значит подать
    # знакомую по форме, но чужую по содержанию картинку. Две опорные точки
    # проверяются числом, а не на глаз.
    check("килогерц — ровно пятнадцать мелов",
          round(float(melspec.в_мелы(np.array([1000.0]))[0]), 9), 15.0)
    check("восемь килогерц — 45.2456 мела",
          round(float(melspec.в_мелы(np.array([8000.0]))[0]), 4), 45.2456)
    for гц in (0.0, 100.0, 999.9, 1000.0, 4000.0, 8000.0):
        назад = float(melspec.в_герцы(melspec.в_мелы(np.array([гц])))[0])
        check(f"шкала обратима на {гц:.0f} Гц", abs(назад - гц) < 1e-6, True)

    банк = melspec.фильтры()
    check("фильтров восемьдесят на 201 бин", банк.shape, (80, 201))
    check("все веса неотрицательны", bool((банк >= 0).all()), True)
    # Каждый следующий фильтр смотрит выше предыдущего. Если это не так,
    # порядок точек перепутан — а картинка при этом выглядит правдоподобно.
    пики = [int(np.argmax(банк[i])) for i in range(80)]
    check("фильтры идут снизу вверх",
          all(б <= а for б, а in zip(пики, пики[1:])), True)

    считалка = melspec.Спектрограмма()
    check("восемьсот кадров — ровно восемь секунд",
          считалка.отсчётов_для(800), 8 * 16000)
    шум = (np.random.default_rng(1).standard_normal(16000 * 8) * 0.1)
    картинка = считалка.посчитать(шум.astype(np.float32), 800)
    check("картинка нужного размера", картинка.shape, (80, 800))
    # Whisper нормирует так, что числа ложатся примерно в [-1, 1]. Уехавший
    # масштаб — верный признак, что забыт clamp или деление на четыре, и сеть
    # увидит другой мир.
    check("числа в whisper-масштабе",
          -1.5 < float(картинка.min()) and float(картинка.max()) < 1.5, True)
    # Короткая запись дополняется тишиной СЛЕВА: конец реплики обязан остаться
    # у правого края, там же, где он был у примеров при обучении.
    короткая = считалка.посчитать(np.zeros(1600, dtype=np.float32), 800)
    check("короткая запись тоже даёт полную картинку", короткая.shape, (80, 800))

    # И сама обёртка обязана понять по форме входа, что просят картинку.
    картинщик = turn_end.КонецРеплики.__new__(turn_end.КонецРеплики)
    картинщик.частота = 16000
    картинщик._мел = melspec.Спектрограмма(16000, 80)
    картинщик._кадров = 800
    картинщик._длина = картинщик._мел.отсчётов_для(800)
    подано = картинщик._окно(np.zeros(16000, dtype=np.float32))
    check("сети подаётся картинка, а не волна", подано.shape, (1, 80, 800))

    # --- выбор файла модели в скрипте установки-------------------------
    # Имя файла было вшито в скрипт по догадке — 404 на роботе. Заменил на
    # опрос репозитория, и он тоже сломался: программу питону скармливали
    # heredoc'ом, а данные конвейером, оба идут в stdin, heredoc побеждает —
    # разбор читал пустоту. Скрипт при этом не падал, а печатал «не удалось
    # спросить список», и человек шёл проверять сеть, которая была ни при чём.
    #
    # Прошлая проверка этого не поймала, потому что гоняла логику ИНАЧЕ, чем
    # боевой вызов: она передавала код через -c, а данные через stdin — то
    # есть проверяла алгоритм, а обвязку не трогала. Теперь выбор живёт
    # отдельным файлом, и здесь запускается ТОТ ЖЕ файл ТЕМ ЖЕ способом,
    # каким его зовёт скрипт: путь к файлу со списком аргументом.
    корень = Path(__file__).resolve().parent.parent
    выборщик = корень / "scripts" / "pick_turn_model.py"
    скрипт = (корень / "scripts" / "setup_turn_end.sh").read_text(encoding="utf-8")
    check("скрипт зовёт выборщик файлом, а не heredoc'ом",
          "pick_turn_model.py" in скрипт and "<<'PY'\n import json" not in скрипт,
          True)
    check("и отдаёт список файлом, а не конвейером",
          '-o "$LIST_FILE"' in скрипт, True)

    def выбрать(имена):
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False,
                                         encoding="utf-8") as ф:
            json.dump({"siblings": [{"rfilename": и} for и in имена]}, ф)
            путь = ф.name
        готово = subprocess.run([sys.executable, str(выборщик), путь],
                                capture_output=True, text=True)
        return готово.stdout.strip(), готово.returncode

    имя, _ = выбрать(["README.md", "smart-turn-v3.0.onnx",
                      "smart-turn-v3.1-cpu.onnx", "smart-turn-v3.1-gpu.onnx"])
    check("берём процессорную сборку", имя, "smart-turn-v3.1-cpu.onnx")

    имя, _ = выбрать(["smart-turn-v3.0.onnx"])
    check("без cpu-сборки берём обычную", имя, "smart-turn-v3.0.onnx")

    # Одна лишь видеокартная — это не «сойдёт», это молча медленнее: вчетверо
    # тяжелее и на A55 хуже. Лучше честный отказ с показанным списком.
    _, код = выбрать(["smart-turn-v3.1-gpu.onnx"])
    check("одну лишь gpu-сборку не берём", код, 1)

    имя, _ = выбрать(["smart-turn-v3.1-cpu.onnx", "smart-turn-v3.2-cpu.onnx"])
    check("берём версию посвежее", имя, "smart-turn-v3.2-cpu.onnx")

    _, код = выбрать(["README.md"])
    check("без onnx честно отказываемся", код, 1)

    # И через stdin — вторым способом, которым его зовут.
    готово = subprocess.run([sys.executable, str(выборщик), "-"],
                            input=json.dumps({"siblings": [
                                {"rfilename": "smart-turn-v3.1-cpu.onnx"}]}),
                            capture_output=True, text=True)
    check("умеет и с конвейера", готово.stdout.strip(), "smart-turn-v3.1-cpu.onnx")

    # Мусор вместо списка — отказ, а не падение с трассировкой.
    готово = subprocess.run([sys.executable, str(выборщик), "-"],
                            input="<html>404</html>", capture_output=True, text=True)
    check("мусор вместо списка — честный отказ", готово.returncode, 1)

    # --- и главное: только раньше, никогда позже --------------------------
    # Определитель добавляет ОДНО слагаемое в «или», не трогая прежние. Если
    # бы он их заменял, молчащая сеть означала бы робота, который не режет
    # запись вовсе, — то есть онемевшего.
    исходник = Path("voice/robot_voice/audio.py").read_text(encoding="utf-8")
    check("прежние правила на месте",
          "silence >= self.silence_frames" in исходник
          and "len(speech) >= self.command_frames" in исходник, True)
    check("сеть только добавлена в условие",
          "договорил or silence >= self.silence_frames" in исходник, True)


def test_turn_breakdown() -> None:
    """Секундомер раскладывает обмен по звеньям, а не по трём отрезкам.

    «Как будто долго» — самая дорогая жалоба: чинить по ней можно что угодно и
    промахнуться. Три отрезка (тишина / распознавание / ответ) говорят, ЧТО
    долго, но не говорят, ГДЕ: «ответ 2.3 с» — это и префилл модели, и холодный
    старт синтеза, и дорога до пульта, и лечатся они по-разному.
    """
    section("секундомер по звеньям")
    from robot_voice.app import Turn

    записано: list[str] = []

    class Перехват(logging.Handler):
        def emit(self, record):
            записано.append(record.getMessage())

    журнал = logging.getLogger("robot_voice")
    перехват = Перехват()
    журнал.addHandler(перехват)
    уровень = журнал.level
    журнал.setLevel(logging.INFO)
    try:
        обмен = Turn(0.5)
        обмен.recognized()
        обмен.отметить("правила")
        обмен.отметить("первый токен")
        обмен.отметить("синтез")
        обмен.spoke("модель")
        обмен.разложить()
    finally:
        журнал.removeHandler(перехват)
        журнал.setLevel(уровень)

    разбивки = [с for с in записано if с.startswith("по звеньям")]
    check("разбивка написана один раз", len(разбивки), 1)
    строка = разбивки[0] if разбивки else ""
    for звено in ("тишина", "распознал", "правила", "первый токен", "синтез"):
        check(f"звено «{звено}» в разбивке", звено in строка, True)
    # Тишина — это НЕ засечка, а константа настройки: пока отсчитывается
    # порог silence_ms, робот ещё не знает, что фраза кончилась, и секундомер
    # даже не создан. Забыть её — значит недосчитать полсекунды на каждой
    # фразе и удивляться, почему сумма не сходится с ощущением.
    check("тишина посчитана как полтысячи", "тишина 500" in строка, True)

    # Второй вызов молчит: разбивка зовётся из двух мест (правило говорит сама,
    # модель — в finally), и печатать её дважды значит удвоить строки в журнале
    # ровно там, где их и так много.
    обмен.разложить()
    check("дважды не печатает", len(разбивки), 1)

    # --- засечка звука приходит ИЗНУТРИ say, а не после него ---------------
    # Самый коварный из возможных дефектов измерителя: он не падает, не молчит
    # и не врёт очевидно — он показывает правдоподобное число не о том. Первая
    # живая разбивка дала «синтез 2759 мс» на фразе «Сейчас двадцать три часа
    # двадцать одна минута», которую ПК синтезировал за 140 мс. Две с половиной
    # секунды были ДЛИНОЙ РЕЧИ: say ждёт, пока реплика отзвучит, а отметка
    # стояла после его возврата. По такой цифре чинили бы синтез, который
    # исправен.
    сказано: list[tuple[str, bool]] = []

    class Динамик:
        def __init__(self) -> None:
            self.last_said = ""
            self.hushes = 0

        def say(self, text, *, loud=False, on_sound=None):
            # Звук пошёл — и только ПОТОМ реплика доигрывает. Ровно так ведёт
            # себя настоящий Speaker.say, и ровно это ломало измерение.
            if on_sound is not None:
                on_sound()
            сказано.append((text, True))
            return 1

    from robot_voice.app import Voice, _run_direct

    ухо = types.SimpleNamespace(unheard=lambda: b"", mute=lambda говорю="": None,
                                unmute=lambda: None, говорю="")
    голос = Voice(Динамик(), ухо)
    засечки: list[str] = []
    обмен2 = Turn(0.5)
    обмен2.отметить = lambda звено: засечки.append(звено)

    class Правило:
        name = "time_now"
        input_schema: dict = {"properties": {}}

        def __call__(self, args):
            return "Сейчас двадцать три часа двадцать одна минута."

    _run_direct(Правило(), {}, голос, turn=обмен2)
    check("реплика произнесена", [т for т, _ in сказано],
          ["Сейчас двадцать три часа двадцать одна минута."])
    # Инструмент и синтез — РАЗНЫЕ звенья. Пока они были одним, взгляд
    # камерой через облако давал «синтез 5097 мс» на фразе, которую ПК
    # озвучил за двести: чинили бы исправный синтез.
    check("инструмент и звук засечены порознь", засечки, ["инструмент", "синтез"])


def test_speech_streams() -> None:
    """Первое предложение уходит в пульт, пока модель ещё договаривает.

    Раньше реплика копилась целиком и синтез начинался только после
    последнего слова: вся потоковая машинерия не давала ничего, а две-три
    секунды синтеза честно ждали своей очереди за десятью секундами
    генерации. Проверяется тем, что клип приходит ДО close().
    """
    section("речь идёт параллельно с генерацией")
    import http.server
    import threading as th

    from robot_voice import tts

    got: list[bytes] = []
    first = th.Event()

    class Catch(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            n = int(self.headers.get("Content-Length") or 0)
            got.append(self.rfile.read(n))
            first.set()
            body = b'{"listeners": 1}'
            self.send_response(200)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *a):
            pass

    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Catch)
    th.Thread(target=srv.serve_forever, daemon=True).start()
    endpoint = f"http://127.0.0.1:{srv.server_address[1]}/speak"

    folder = Path(tempfile.mkdtemp())
    cache = PhraseCache(folder, "тест")
    # Кладём звук заранее — тогда piper не понадобится, и проверка поедет
    # где угодно, хоть на сборщике без синтеза.
    тишина = b"\x00\x00" * 2205          # 0.1 с при 22050 Гц
    cache.put("Раз.", тишина)
    cache.put("Два.", тишина)

    speech = WebSpeech(["не-запускается"], 22050, endpoint, 1.0, cache=cache)
    try:
        speech.feed("Раз.")
        check("первое предложение ушло, не дожидаясь конца",
              first.wait(timeout=10), True)
        speech.feed("Два.")
        check("обе реплики доехали", (speech.close(), len(got)), (1, 2))

        # --- засечка первого звука ------------------------------------------
        # Она нужна измерителю задержки: снаружи видно только, когда текст
        # ОТДАЛИ синтезу, а от этого момента до первого сэмпла проходит
        # холодный старт piper и дорога до пульта — то есть ровно то, что мы
        # и собираемся сокращать.
        #
        # Проверка живая: ПервыйЗвук — общий предок трёх видов реплики, и
        # наследник, забывший super().__init__(), падает не при создании, а
        # ПОТОМ, в чужом потоке синтеза, на первой же фразе. Наружу это выходит
        # как «робот сказал только первое предложение и замолчал» — поймано
        # ровно так, этой проверкой, на WebSpeech.
        for класс in (tts.Speech, tts.RemoteSpeech, tts.WebSpeech):
            check(f"{класс.__name__} умеет засекать звук",
                  issubclass(класс, tts.ПервыйЗвук), True)

        звуки: list[int] = []
        второй = WebSpeech(["не-запускается"], 22050, endpoint, 1.0, cache=cache)
        второй.on_sound = lambda: звуки.append(1)
        второй.feed("Раз.")
        второй.feed("Два.")
        второй.close()
        # Ровно один раз, а не на каждое предложение: засекается НАЧАЛО речи.
        # Считая каждую фразу, мы бы мерили не задержку, а длину ответа.
        check("звук засечён один раз на реплику", звуки, [1])
        check("это WAV", got[0][:4], b"RIFF")

        # Кэш переживает перезапуск — иначе он бесполезен: робот
        # перезапускается при каждой правке.
        check("кэш на диске", PhraseCache(folder, "тест").get("Раз."), тишина)
        check("чужой голос не подходит",
              PhraseCache(folder, "другой").get("Раз."), None)
    finally:
        srv.shutdown()


def test_pc_url() -> None:
    """Одна настройка на всё: адрес ПК включает и разговор, и распознавание.

    Разнести их по разным строкам легко, а забыть одну — ещё легче, и тогда
    робот молча продолжит распознавать сам, вчетверо медленнее, а человек
    будет думать, что ПК подключён.
    """
    section("адрес ПК включает и разговор, и распознавание")
    import os

    было = {k: os.environ.get(k) for k in
            ("ROBOT_PC_URL", "ROBOT_LOCAL_API_BASE", "ROBOT_STT_URL")}
    try:
        os.environ["ROBOT_PC_URL"] = "http://192.168.0.5:4000/"
        os.environ.pop("ROBOT_LOCAL_API_BASE", None)
        os.environ.pop("ROBOT_STT_URL", None)
        cfg = Config()
        check("разговор", cfg.local_api_base, "http://192.168.0.5:4000")
        check("распознавание", cfg.stt_url, "http://192.168.0.5:4000/stt")
        check("без ключа старт разрешён", (cfg.api_key or "") == "" and
              cfg.check() is None, True)

        # Заданное явно главнее: значит человек знает, зачем разносил.
        os.environ["ROBOT_STT_URL"] = "http://другой:9000/stt"
        check("явный адрес не перебивается", Config().stt_url, "http://другой:9000/stt")
    finally:
        for k, v in было.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v


def test_hidden() -> None:
    """Скрытый от модели инструмент обязан вызываться правилом.

    Схемы инструментов уезжают в каждый запрос и оплачиваются каждый раз,
    поэтому те, что надёжно разбираются правилами, модели не показываются.
    Цена ошибки высокая: скрыть инструмент, до которого правило не достаёт, —
    значит потерять умение совсем, причём молча.
    """
    section("скрытые от модели инструменты")
    store = Path(tempfile.mkdtemp())
    timers = Timers(announce=lambda text, **kw: None, store=store / "timers.json")
    ros = types.SimpleNamespace(voltage=12.4, moving=False, connected=True,
                                drive=lambda *a, **k: None, stop_motion=lambda: None)
    speaker = types.SimpleNamespace(volume=1.0, last_said="",
                                    set_volume=lambda v: None, hush=lambda: None)
    tools = build_tools(ros, timers, speaker=speaker,
                        notes=Notes(store / "notes.json"),
                        set_place=lambda *a: None, player=Player(ГлухойПульт()))
    hidden = {t.name for t in tools if t.hidden}
    phrases = [
        "приостанови таймер", "продолжи таймер", "сбрось все таймеры",
        "что ты умеешь", "говори тише", "замолчи", "повтори",
        "добавь в список молоко", "что в списке", "убери молоко из списка",
        "очисти список",
    ]
    reachable = {m.tool for m in (parse(p) for p in phrases) if m is not None}
    check("до каждого скрытого достают правила", sorted(hidden - reachable), [])
    visible = [t.spec() for t in tools if not t.hidden]
    print(f"   модель видит {len(visible)} инструментов из {len(tools)}, "
          f"{len(json.dumps(visible, ensure_ascii=False))} символов схем "
          f"плюс {len(SYSTEM_PROMPT)} символов промпта")


def test_thinkless() -> None:
    """Размышления модели не должны звучать вслух.

    Локальные модели выводят ход мысли прямо в текст, между <think> и
    </think>. Робот прочитает это вслух — полминуты рассуждений вместо
    ответа. Тег при этом легко разрывается между кусками потока, и именно
    на разрыве такой фильтр обычно и ломается.
    """
    section("размышления модели не звучат вслух")

    def run(chunks: list[str]) -> str:
        said: list[str] = []
        f = Thinkless(said.append)
        for c in chunks:
            f.feed(c)
        f.close()
        return "".join(said)

    check("без размышлений — как есть", run(["Привет", ", Игорь"]), "Привет, Игорь")
    check("размышления вырезаны",
          run(["<think>надо посчитать</think>Восемь часов"]), "Восемь часов")
    # Главный случай: Qwen3 не пишет открывающий тег — он уже в шаблоне
    # запроса, и ответ начинается сразу внутри размышлений.
    check("закрывающий тег без открывающего",
          run(["Надо ответить коротко. ", "Пожалуй, так.", "</think>", "Привет!"]),
          "Привет!")
    check("закрывающий разорван между кусками",
          run(["думаю", "</thi", "nk>", "Готово."]), "Готово.")
    # Длинный ответ без размышлений не должен застрять в придержанном начале.
    длинный = "а" * 500
    check("длинный ответ доходит целиком", run([длинный]), длинный)
    check("тег разорван между кусками",
          run(["<thi", "nk>", "думаю", "</thi", "nk>", "Готово"]), "Готово")
    check("текст до и после",
          run(["Сейчас", "<think>ага</think>", " посмотрю"]), "Сейчас посмотрю")
    check("угловая скобка не от тега",
          run(["Цена < 5 рублей"]), "Цена < 5 рублей")
    check("размышления не закрылись — вслух ничего",
          run(["<think>завис на полуслове"]), "")
    # Хвост, похожий на начало тега, придерживается — но если ответ на нём
    # кончился, его надо договорить, а не проглотить.
    check("недописанный хвост договаривается", run(["Готово<"]), "Готово<")

    # Тот самый случай с живого робота. Первая версия фильтра отпускала начало
    # через триста символов, решив, что размышлений нет, — а их было полторы
    # тысячи, и робот зачитал вслух все. Порога быть не должно вовсе.
    ворох = "Надо ответить коротко. Хотя, возможно, лучше переспросить. " * 30
    check("полторы страницы размышлений не звучат",
          run([ворох, "</think>", "Привет!"]), "Привет!")


def test_thinkless_habit() -> None:
    """Фильтр размышлений должен учиться, иначе он либо режет, либо тормозит.

    Держать начало ответа до </think> — единственный надёжный способ не
    зачитать размышления вслух, но за него платят задержкой: пока тега нет,
    робот молчит. Платить каждую реплику незачем — думает модель вслух или
    нет, это её свойство, а не свойство реплики. Выяснили один раз и дальше
    отдаём поток сразу.
    """
    section("фильтр размышлений учится на первом ответе")

    def run(habit, chunks: list[str]):
        """Возвращает сказанное и то, что прозвучало ДО конца ответа."""
        said: list[str] = []
        f = Thinkless(said.append, habit)
        for c in chunks:
            f.feed(c)
        early = "".join(said)
        f.close()
        return "".join(said), early

    ep = types.SimpleNamespace(name="ПК", thinks=None)
    said, _ = run(ep, ["думаю вслух", "</think>", "Привет!"])
    check("болтун пойман", said, "Привет!")
    check("привычка запомнена", ep.thinks, True)
    # Теперь ждём тег сколько угодно — и до конца ответа не говорим ни слова.
    said, early = run(ep, ["очень длинные размышления " * 50, "</think>", "Да."])
    check("известного болтуна держим до тега", said, "Да.")

    ep = types.SimpleNamespace(name="облако", thinks=None)
    said, early = run(ep, ["Привет, ", "Игорь!"])
    check("молчун распознан", ep.thinks, False)
    check("первый ответ придержан целиком", early, "")
    # А второй уже идёт потоком: робот начинает говорить с первого куска.
    said, early = run(ep, ["Привет, ", "Игорь!"])
    check("дальше говорим сразу", early, "Привет, Игорь!")

    # Модель, которая раньше не думала, вдруг задумалась. Начало уже
    # прозвучало — не вернуть, но остаток размышлений звучать не должен.
    said, _ = run(ep, ["ага, ", "надо подумать", "</think>", "Готово."])
    check("передумавшая модель обрезана", said, "ага, надо подумать" + "Готово.")
    check("привычка пересмотрена", ep.thinks, True)

    # Обратно — не переучиваемся. «Думает» доказано тегом, «не думает» — всего
    # лишь его отсутствием, и один такой ответ ничего не отменяет: иначе
    # фильтр перестанет держать начало и следующие размышления пойдут в речь.
    said, early = run(ep, ["Привет!"])
    check("один ответ без тега не отменяет доказанного", ep.thinks, True)
    check("и держать не перестаём", early, "")


def test_smart() -> None:
    """«Подумай хорошо» уводит ход в облако, а обычная фраза — нет.

    Зоопарк моделей в шесть гигабайт видеопамяти не помещается: пока одна
    отвечает, остальные пришлось бы выгружать, и каждая смена стоила бы
    десятки секунд. Вместо зоопарка — лестница: правила, домашняя модель,
    облако. Не хватило домашней — человек зовёт умного вслух и платит
    осознанно, а не по решению классификатора, который сам ошибается.
    """
    section("позвать умного по просьбе")
    from robot_voice.intents import wants_smart

    check("подумай хорошо", wants_smart("подумай хорошо сколько будет 17 на 23"),
          (True, "сколько будет 17 на 23"))
    check("спроси умного", wants_smart("спроси умного как работает меканум"),
          (True, "как работает меканум"))
    check("напрягись", wants_smart("напрягись, что подарить маме")[0], True)
    check("обычная фраза не трогается",
          wants_smart("расскажи анекдот"), (False, "расскажи анекдот"))
    # «Подумай» в одиночку — продолжение разговора, а не пустой вопрос:
    # спрашивать умного не о чем, но и терять фразу нельзя.
    check("одна просьба без вопроса", wants_smart("подумай"), (True, "подумай"))

    # И сама развилка: при просьбе первым спрашивается платный.
    cfg = Config()
    cfg.local_api_base = "http://пк:4000"
    cfg.api_key = "ключ"
    b = Brain(cfg, [])
    check("обычно первым идёт ПК", [e.paid for e in b._live()], [False, True])
    check("умного просили — первым облако",
          [e.paid for e in b._live(smart=True)], [True, False])


def test_prompt_prefix() -> None:
    """Начало промпта обязано быть одинаковым от фразы к фразе.

    Живой замер: 5212 токенов входа на КАЖДУЮ реплику, и время до первого
    токена — 1020 мс, почти половина всей задержки. Из этих токенов тысяча —
    системный промпт и две с половиной тысячи — схемы двадцати одного
    инструмента.

    Ollama и llama.cpp переиспользуют посчитанный KV-кэш ровно на ту длину, на
    которую совпадает НАЧАЛО промпта. А шаблон Qwen рисует схемы инструментов
    внутри системного блока, следом за его текстом. Подмешаешь туда справку о
    говорящем — она встанет ПЕРЕД схемами, и две с половиной тысячи токенов
    будут считаться заново каждую фразу. Справка же меняется постоянно: в
    журнале говорящий скачет между Игорем, Ромой и «не узнал».

    В облаке всё наоборот: там кэш явный, с отметкой на системном блоке, и
    справка обязана идти ПОСЛЕ отметки — иначе кэш не совпадёт. Поэтому два
    разных поведения, и оба здесь проверяются.
    """
    section("начало промпта не должно шевелиться")
    from robot_voice.brain import Brain, Endpoint

    мозг = Brain.__new__(Brain)
    мозг.cfg = types.SimpleNamespace(max_tokens=1000)
    мозг.specs = [{"name": "drive", "description": "ехать",
                   "input_schema": {"type": "object", "properties": {}}}]

    сообщения = [{"role": "user", "content": "привет"}]
    домашняя = Endpoint(name="ПК", client=None, model="qwen3", effort="",
                        use_cache=False)

    мозг.about = "Это Игорь. Любит чай."
    первый = мозг._params(домашняя, list(сообщения))
    мозг.about = "Это Рома. Ему шесть лет."
    второй = мозг._params(домашняя, list(сообщения))

    check("системный промпт — простая строка",
          isinstance(первый["system"], str), True)
    # Вот главное: от смены говорящего системный блок не шевельнулся, значит
    # и схемы за ним остались на прежних местах.
    check("и он не изменился от смены говорящего",
          первый["system"] == второй["system"], True)
    check("справка уехала в сообщения",
          первый["messages"][0], {"role": "system", "content": "Это Игорь. Любит чай."})
    check("а реплика человека осталась на месте",
          первый["messages"][-1], {"role": "user", "content": "привет"})
    check("у второго говорящего своя справка",
          второй["messages"][0]["content"], "Это Рома. Ему шесть лет.")

    # Без справки лишнего сообщения не появляется: пустая строка «про
    # говорящего» — это не «мы ничего о нём не знаем», это мусор в промпте.
    мозг.about = ""
    пусто = мозг._params(домашняя, list(сообщения))
    check("без справки сообщений не прибавилось", len(пусто["messages"]), 1)

    # В облаке — прежний порядок: справка ПОСЛЕ кэшируемого системного блока.
    облако = Endpoint(name="облако", client=None, model="claude", effort="low",
                      use_cache=True)
    мозг.about = "Это Игорь."
    небо = мозг._params(облако, list(сообщения))
    check("в облаке системный промпт — список блоков",
          isinstance(небо["system"], list), True)
    check("с отметкой кэша на первом",
          небо["system"][0].get("cache_control", {}).get("type"), "ephemeral")
    check("и справкой после неё", небо["system"][-1]["text"], "Это Игорь.")
    check("в сообщения ничего не подмешано", len(небо["messages"]), 1)


def test_endpoints() -> None:
    """ПК основной, облако запасное: выключенный ПК не должен ломать разговор.

    Это главное свойство схемы «мозг на компьютере». Проверять его руками
    неудобно — надо выключать ПК, — а сломать легко: достаточно, чтобы
    исключение поехало не в ту ветку, и робот замолчит навсегда.
    """
    section("ПК основной, облако запасное")

    def answer(text: str):
        """Ответ модели: поток кусков плюс итоговое сообщение."""
        class Stream:
            def __enter__(self): return self
            def __exit__(self, *a): return False
            def __iter__(self):
                yield types.SimpleNamespace(
                    type="content_block_delta",
                    delta=types.SimpleNamespace(type="text_delta", text=text))
            def get_final_message(self):
                return types.SimpleNamespace(
                    content=[types.SimpleNamespace(type="text", text=text)],
                    stop_reason="end_turn",
                    usage=types.SimpleNamespace(input_tokens=100, output_tokens=10))
        return Stream()

    def client(reply):
        """Строка — ответ. None — молчит. Исключение — отвечает, но плохо."""
        def stream(**kw):
            if reply is None:
                raise _no_connection()
            if isinstance(reply, Exception):
                raise reply
            return answer(reply)
        return types.SimpleNamespace(messages=types.SimpleNamespace(stream=stream))

    def brain(pc, cloud) -> Brain:
        cfg = Config()
        cfg.local_api_base = "http://пк:4000"
        cfg.api_key = cfg.local_api_key = "x"
        b = Brain(cfg, [])
        b.endpoints[0].client = client(pc)
        b.endpoints[1].client = client(cloud)
        return b

    cfg_общий = Config()
    b = brain(pc="с ПК", cloud="из облака")
    check("ПК включён — отвечает он", b.reply("привет", lambda s: None), "с ПК")
    check("бесплатный ответ в деньги не пишем", (b.total_in, b.total_out), (0, 0))

    b = brain(pc=None, cloud="из облака")
    check("ПК выключен — отвечает облако",
          b.reply("привет", lambda s: None), "из облака")
    check("платный ответ посчитан", b.total_in > 0, True)
    check("молчащий ПК отложен", b.endpoints[0].down_until > 0, True)
    # Второй раз к ПК не ходим вовсе — иначе каждая фраза ждала бы связи.
    check("выключенный ПК больше не дёргаем",
          [e.name for e in b._live()], [b.endpoints[1].name])

    # ПК ответил, но плохо: модель не скачана в Ollama (404), сама Ollama не
    # запущена (500), опечатка в имени модели (400). Раньше ловился только
    # обрыв связи, и такая ошибка убивала ход целиком — облако не пробовалось
    # ни разу, и робот отвечал «что-то пошло не так» на каждую фразу.
    for кто, сбой in (("модель не скачана", _http_error(404)),
                      ("Ollama не запущена", _http_error(500)),
                      ("опечатка в имени модели", _http_error(400))):
        b = brain(pc=сбой, cloud="из облака")
        check(f"{кто} — отвечает облако",
              b.reply("привет", lambda s: None), "из облака")
        check(f"{кто} — ПК отложен", b.endpoints[0].down_until > 0, True)

    # А вот запрос, неправильный сам по себе, отвергнет кто угодно — и метить
    # из-за него собеседников мёртвыми нельзя. Иначе одна наша ошибка выводит
    # из строя всех разом: следующую минуту робот не спрашивает никого, хотя
    # спросить есть кого. Ровно так и вышло с русскими именами полей в схемах.
    from robot_voice.app import _failure_phrase
    from robot_voice.brain import наша_вина
    схема = _http_error(
        400, "tools.5.custom.input_schema.properties: Property keys should "
             "match pattern '^[a-zA-Z0-9_.-]{1,64}$'")
    b = brain(pc=схема, cloud=схема)
    try:
        b.reply("привет", lambda s: None)
        check("неправильный запрос не проглочен", "ответил", "отказался")
    except Exception as e:
        check("неправильный запрос назван нашей ошибкой", наша_вина(e), True)
    check("ПК не помечен мёртвым из-за нашей ошибки",
          b.endpoints[0].down_until, 0.0)
    check("облако не помечено мёртвым из-за нашей ошибки",
          b.endpoints[1].down_until, 0.0)
    # Шлюз заворачивает чужие ошибки в свои: живьём это пришло как
    # overloaded_error, то есть «перегружен, попробуй позже». По коду и типу
    # такое не отличить — только по тому, на что ошибка показывает пальцем.
    подделка = _http_error(
        529, '{"error":{"message":"Provider returned error","code":400,'
             '"metadata":{"raw":"invalid_request_error: '
             'tools.5.custom.input_schema.properties: ..."}}}')
    check("529 с нашей ошибкой внутри распознан", наша_вина(подделка), True)
    # А это не наша вина: у следующего собеседника всё получится.
    check("опечатка в имени модели — не наша вина",
          наша_вина(_http_error(400, "model: unknown model 'qwen3:4b'")), False)
    check("перегрузка — не наша вина",
          наша_вина(_http_error(529, "Overloaded, try again later")), False)
    # И человеку об этом говорят по-разному: «повтори» тут бесполезно, он
    # повторит и получит то же самое.
    check("про нашу ошибку сказано честно",
          "Повторять бесполезно" in _failure_phrase(схема), True)

    # У домашней модели свой предел ответа, и он маленький. Общий большой —
    # потому что облачная модель размышляет, и размышления идут в тот же счёт.
    # Домашней столько не нужно: на зацикленную фразу она выдала восемь тысяч
    # токенов и говорила полминуты, теряя звук.
    from robot_voice.brain import МЕСТНЫЙ_ПРЕДЕЛ
    b = brain(pc="с ПК", cloud="из облака")
    свой = {e.name.startswith("ПК"): (e.max_tokens or cfg_общий.max_tokens)
            for e in b.endpoints}
    check("у домашней модели предел свой и маленький",
          свой.get(True), МЕСТНЫЙ_ПРЕДЕЛ)
    check("у облака остался общий", свой.get(False), cfg_общий.max_tokens)
    check("и он заметно больше", cfg_общий.max_tokens > МЕСТНЫЙ_ПРЕДЕЛ * 4, True)

    # Без облачного ключа облачного собеседника быть не должно: вместо обрыва
    # связи оттуда прилетит отказ авторизации, и запасного пути не станет.
    cfg = Config()
    cfg.local_api_base = "http://пк:4000"
    cfg.api_key = ""
    cfg.local_api_key = "x"
    check("без ключа облака нет", len(Brain(cfg, []).endpoints), 1)

    b = brain(pc=None, cloud=None)
    try:
        b.reply("привет", lambda s: None)
        check("оба молчат — ошибка наверх", "не упало", "APIConnectionError")
    except Exception as e:
        check("оба молчат — ошибка наверх", type(e).__name__, "APIConnectionError")


def test_brain_money() -> None:
    """Три места, где мозг терял деньги или делал работу дважды."""
    section("мозг: история, кэш, молчание")
    import anthropic
    from robot_voice.brain import Endpoint

    # 1. Сбой посреди хода с инструментами. Инструмент уже сработал
    #    по-настоящему, и если ход не попал в историю, человек повторит
    #    просьбу — и будильник поставится второй раз.
    cfg = Config()
    cfg.api_key = "x"
    cfg.local_api_base = ""
    сделано: list[str] = []
    b = Brain(cfg, [])
    b.tools = {"set_alarm": lambda args: (сделано.append("будильник"),
                                          "Разбужу в семь.")[1]}

    круги = iter([
        types.SimpleNamespace(
            content=[types.SimpleNamespace(type="tool_use", id="t1",
                                           name="set_alarm", input={})],
            stop_reason="tool_use", usage=None),
    ])

    def сбой(messages, on_text, smart=False):
        try:
            return b.endpoints[0], next(круги)
        except StopIteration:
            raise _no_connection()

    b._round = сбой
    try:
        b.reply("разбуди в семь", lambda s: None)
    except Exception:
        pass
    check("инструмент сработал один раз", сделано, ["будильник"])
    check("ход попал в историю, несмотря на сбой",
          any(m.get("role") == "assistant" for m in b.history), True)

    # 2. Кэш промпта выключался на ЛЮБУЮ четырёхсотую и навсегда: полторы
    #    тысячи токенов начинали оплачиваться целиком в каждой реплике.
    ep = Endpoint(name="тест", client=None, model="м", effort="low")
    check("посторонняя ошибка кэш не трогает",
          (Brain._degrade(ep, Exception("prompt is too long")), ep.use_cache),
          (False, True))
    check("отказ именно от кэша — отступаем",
          (Brain._degrade(ep, Exception("cache_control not supported")),
           ep.use_cache), (True, False))
    check("отказ от effort — убираем",
          (Brain._degrade(ep, Exception("unknown field output_config")), ep.effort),
          (True, ""))

    # 3. Отказ модели робот проглатывал молча: строка возвращалась, но никто
    #    её не озвучивал.
    сказано: list[str] = []
    b2 = Brain(cfg, [])
    b2._round = lambda messages, on_text, smart=False: (
        b2.endpoints[0],
        types.SimpleNamespace(content=[], stop_reason="refusal", usage=None))
    b2.reply("что-то нехорошее", сказано.append)
    check("на отказ робот говорит вслух", "".join(сказано).startswith("Извини"), True)


def test_degraded() -> None:
    """Робот обязан сказать, что работает не в полную силу.

    Запасные пути есть у каждого звена, и это хорошо — но проходил их робот
    молча. Снаружи ухудшение выглядит как «стал тупить»: отвечает медленнее,
    хуже слышит, а почему — видно только в журнале по ssh.
    """
    import types as _t

    from robot_voice.app import Watchdog

    section("робот говорит, что ему плохо")
    сказано: list[str] = []
    строки: list[str] = []
    voice = _t.SimpleNamespace(say=сказано.append, status=строки.append)
    ros = _t.SimpleNamespace(voltage=None)
    listener = _t.SimpleNamespace(pump=_t.SimpleNamespace(alive=True))

    # Признак берём у НАСТОЯЩЕГО класса, а не у заглушки. Заглушка тут стояла
    # раньше — и покрывала мёртвый код: свойство «сам_разбираю» было объявлено
    # не на том классе и не работало ни разу за всю жизнь робота, а тест этого
    # не видел, потому что проверял SimpleNamespace с нужным полем.
    from robot_voice.stt import Recognizer as _Recognizer
    from robot_voice.stt import Remote as _Remote

    check("признак «разбираю сам» живёт на том, кто знает про ПК",
          hasattr(_Remote("http://пк/stt", lambda: None), "сам_разбираю"), True)
    # А getattr с умолчанием такую ошибку проглатывает молча — вот как это
    # выглядело: свойство вроде есть, а читается как False.
    check("и читается без исключения",
          getattr(_Remote("http://пк/stt", lambda: None), "сам_разбираю", "нет"),
          False)
    check("у своего распознавания его нет вовсе",
          hasattr(_Recognizer.__new__(_Recognizer), "сам_разбираю"), False)

    слух = _t.SimpleNamespace(сам_разбираю=False)
    мозг = _t.SimpleNamespace(ответил="", endpoints=[
        _t.SimpleNamespace(name="ПК"), _t.SimpleNamespace(name="облако")])
    сторож = Watchdog(ros, voice, listener, recognizer=слух, brain=мозг)

    # Первый заход при живом роботе: сказать «всё хорошо» тому, кто ничего не
    # спрашивал, незачем.
    мозг.ответил = "ПК"
    сторож._запасной_путь()
    check("на здоровом роботе молчит", (сказано, строки), ([], []))

    # ПК замолчал: отвечает облако, речь разбираем сами.
    мозг.ответил = "облако"
    слух.сам_разбираю = True
    сторож._запасной_путь()
    check("сказал вслух один раз", len(сказано), 1)
    check("и назвал оба звена",
          ("разбираю речь сам" in строки[-1], "облако" in строки[-1]),
          (True, True))

    # Пока ничего не изменилось — молчит, а не ноет каждые полминуты.
    сторож._запасной_путь()
    сторож._запасной_путь()
    check("не повторяется", len(сказано), 1)

    # Вернулись на основной путь — это тоже стоит показать, но без голоса.
    мозг.ответил = "ПК"
    слух.сам_разбираю = False
    сторож._запасной_путь()
    check("о возвращении сказано строкой", строки[-1], "всё на своих местах")
    check("но вслух не празднуем", len(сказано), 1)

    # Распознаватель без этого свойства (когда ПК не настроен вовсе) не должен
    # ронять сторожа.
    сторож2 = Watchdog(ros, voice, listener, recognizer=object(), brain=None)
    сторож2._запасной_путь()
    check("без ПК сторож не падает", True, True)

    # Своё распознавание поднимается заранее, а не в тот миг, когда ПК
    # замолчал. Раньше человек в этот момент ждал минуту тишины — и это была
    # ровно та минута, когда ему нужен ответ.
    from robot_voice.stt import Remote

    поднято: list[int] = []

    def сделать_модель():
        поднято.append(1)
        return _t.SimpleNamespace(transcribe=lambda w: "", confidence=0.9)

    слух2 = Remote("http://пк:4000/stt", сделать_модель)
    # И признак «разбираю сам» обязан загораться по-настоящему: ПК не ответил
    # — робот перешёл на свои силы и должен об этом сказать вслух.
    check("пока ПК жив — признак погашен", слух2.сам_разбираю, False)
    слух2._down_until = time.monotonic() + 60
    check("ПК замолчал — признак загорелся", слух2.сам_разбираю, True)
    слух2._down_until = 0.0
    check("до прогрева модель не грузится", поднято, [])
    слух2.прогреть()
    check("прогрев поднял модель", поднято, [1])
    слух2.прогреть()
    check("второй прогрев не грузит снова", поднято, [1])
    # Не поднялась — не беда: поднимем, когда понадобится. Ронять из-за этого
    # весь голос нельзя, прогрев идёт в фоне.
    Remote("http://пк:4000/stt",
           lambda: (_ for _ in ()).throw(RuntimeError("нет модели"))).прогреть()
    check("неудачный прогрев не роняет робота", True, True)


def _http_error(code: int, текст: str = "") -> Exception:
    """Ответ с HTTP-кодом так, как его создаёт SDK.

    Текст важен не меньше кода: по нему робот отличает «запрос неправилен сам
    по себе» от «этот собеседник не смог». Один и тот же 400 бывает и про то,
    и про другое.
    """
    import anthropic
    kinds = {400: "BadRequestError", 404: "NotFoundError",
             500: "InternalServerError", 529: "APIStatusError"}
    cls = getattr(anthropic, kinds[code], None)
    if cls is None:                       # заглушка вместо настоящего SDK
        return anthropic.APIConnectionError()
    try:
        import httpx
        return cls(
            текст or f"код {code}",
            response=httpx.Response(
                code, request=httpx.Request("POST", "http://пк:4000/v1/messages")),
            body=None)
    except Exception:
        return cls.__new__(cls)


def _no_connection() -> Exception:
    """Обрыв связи так, как его создаёт SDK, а где нельзя — как получится."""
    import anthropic
    try:
        import httpx
        return anthropic.APIConnectionError(
            request=httpx.Request("POST", "http://пк:4000/v1/messages"))
    except Exception:
        return anthropic.APIConnectionError()


def test_history() -> None:
    section("обрезка истории диалога")

    def turn(rounds: int) -> list[dict]:
        msgs: list[dict] = [{"role": "user", "content": "текст"}]
        for _ in range(rounds):
            msgs.append({"role": "assistant", "content": [{"type": "tool_use"}]})
            msgs.append({"role": "user", "content": [{"type": "tool_result"}]})
        msgs.append({"role": "assistant", "content": [{"type": "text"}]})
        return msgs

    for rounds, limit in ((0, HISTORY_LIMIT), (3, HISTORY_LIMIT), (6, 14)):
        history: list[dict] = []
        for _ in range(8):
            history = _trim(history + turn(rounds))
        check(f"{rounds} вызовов инструментов за ход: история не растёт",
              len(history) <= limit, True)
        check(f"{rounds} вызовов: история начинается с реплики человека",
              history[0]["role"] == "user" and isinstance(history[0]["content"], str),
              True)


def test_names() -> None:
    """Ищет обращения к тому, что забыли импортировать.

    Такое не ловится ни компиляцией, ни остальными проверками: код падает
    только когда до строки доходит выполнение. Один раз так и вышло —
    `datetime.now()` в стартовом логе при отсутствующем импорте, сервис
    поднимался и падал по кругу триста раз.

    Работает на stdlib: symtable знает, какое имя в функции считается
    глобальным, а какое — локальным.
    """
    import builtins
    import symtable

    section("забытые импорты")
    here = Path(__file__).resolve().parent
    files = sorted((here / "robot_voice").glob("*.py")) + [here / "selftest.py"]
    # Веб-слой и ПК тоже. В режиме browser через веб-сервер идут И микрофон,
    # И динамик: забытый импорт там делает робота разом глухим и немым, а
    # голосовой сервис при этом бодро работает и не жалуется — обрывы звука
    # он считает нормой. На ПК то же самое: мозг молча перестанет отвечать.
    files += sorted((here.parent / "web").glob("*.py"))
    files += sorted((here.parent / "pc").glob("*.py"))

    # Имена, которые питон заводит в каждом модуле сам. В таблице символов их
    # нет, пока в них не пишут, — а обращаться к ним законно.
    dunder = {"__file__", "__name__", "__doc__", "__package__",
              "__spec__", "__loader__", "__builtins__"}

    for path in files:
        top = symtable.symtable(path.read_text(), str(path), "exec")
        known = {s.get_name() for s in top.get_symbols()} | set(dir(builtins)) | dunder
        missing: list[str] = []

        def walk(table, missing=missing, known=known):
            for sym in table.get_symbols():
                if sym.is_global() and sym.get_name() not in known:
                    missing.append(f"{table.get_name()}: {sym.get_name()}")
            for child in table.get_children():
                walk(child)

        for child in top.get_children():
            walk(child)
        check(f"{path.name}: всё импортировано", sorted(set(missing)), [])


def test_dialogue() -> None:
    """Прогон главного цикла целиком: фразы на входе, реплики на выходе.

    Без микрофона, модели и шасси — всё вокруг цикла подменено. Именно здесь
    ловятся ошибки порядка: «отбой» на ходу усыплял робота вместо остановки,
    а «стой» во время переспроса считалось ответом на вопрос.
    """
    section("разговор целиком")
    from robot_voice import app                                  # noqa: E402
    from robot_voice.config import Config                        # noqa: E402

    said: list[str] = []
    moved: list[str] = []

    class FakeListener:
        pump = types.SimpleNamespace(online=True)
        # Обычные фразы, нарезанные по паузе, а не по длине, и имя в них
        # ищется по тексту — как в запасном режиме без ловли на потоке.
        long_chunk = False
        wake_heard = False

        def __init__(self, phrases): self.phrases = phrases
        def utterances(self): return iter([p.encode() for p in self.phrases])
        def mute(self): pass
        def unmute(self): pass

    class FakeVoice:
        speaker = types.SimpleNamespace(stream=lambda **kw: None, last_said="")
        def say(self, text, **kw): said.append(text); return 1
        def heard(self, text): pass
        def hold(self): return contextlib_nullcontext()
        def quiet(self): return contextlib_nullcontext()

    import contextlib as _c
    contextlib_nullcontext = _c.nullcontext

    class FakeBrain:
        last_talk = 0.0
        # Какие инструменты позваны на последнем ходу. По этому списку цикл
        # отличает поездку от рассказа о поездке, поэтому у заглушки он тоже
        # должен быть — иначе проверка молча уходит в исключение.
        def __init__(self): self.asked: list[str] = []; self.позвал: list[str] = []
        def reply(self, text, on_text, smart=False):
            self.asked.append(text)
            on_text("Отвечаю модели.")
            return "Отвечаю модели."
        def reset(self): pass

    class FakeRos:
        """Едет ровно до команды «стоп» — как настоящее шасси."""

        voltage, connected = 12.4, True

        @property
        def moving(self): return bool(moved) and moved[-1] == "drive"
        def drive(self, *a, **k): moved.append("drive")
        def stop_motion(self): moved.append("stop")

    ros = FakeRos()
    timers = Timers(announce=lambda t, **k: 1,
                    store=Path(tempfile.mkdtemp()) / "t.json")
    addressed = app.Addressed()
    tools = build_tools(ros, timers, addressed=addressed)

    phrases = [
        "Кузя вперёд",             # по имени — едет
        "прямо",                   # без имени — не поедет
        "Кузя отбой",              # это команда остановки, а не прощание
        "Кузя поставь таймер на пять минут",
        "отмена",                  # снимает только что поставленный таймер
        "Кузя что ты умеешь",
        "Кузя расскажи про космос",   # это к модели
        "спасибо",                 # прощание
        "вперёд",                  # уже спит — не реагирует
    ]
    brain = FakeBrain()
    cfg = Config()
    # Строгий порядок: имя обязательно на КАЖДОЙ команде движения. По
    # умолчанию он мягче (см. ниже), но выключать строгость человек вправе, и
    # она должна работать.
    cfg.motion_name_once = False
    app._listen_loop(cfg, FakeListener(phrases), types.SimpleNamespace(
        transcribe=lambda wav: wav.decode()), brain, FakeVoice(), tools, addressed)

    check("поехал по имени", said[0].startswith("Еду вперёд"), True)
    check("без имени не поехал", said[1], "Позови меня по имени — тогда поеду.")
    check("«отбой» остановил, а не усыпил", said[2], "Остановился.")
    check("колёса действительно встали", moved[-1], "stop")
    check("таймер поставлен", said[3], "Поставил таймер на пять минут.")
    check("«отмена» сняла таймер", said[4], "Отменил таймер.")
    check("таймеров не осталось", timers.remaining(), {})
    check("умения — из правила", said[5].startswith("Я умею ездить"), True)
    check("разговор ушёл модели", brain.asked, ["расскажи про космос"])
    check("попрощался", said[-1], "Ага, зови.")
    # Реплика модели идёт мимо voice.say — потоком, поэтому её в said нет.
    check("после прощания молчит", len(said), 7)

    # --- второй сценарий: шум, чужой разговор и движение через модель ---
    said.clear()
    moved.clear()
    addressed = app.Addressed()
    tools2 = build_tools(ros, timers, addressed=addressed)
    by_name = {t.name: t for t in tools2}

    # Модель, которая пытается поехать, не спросив имени.
    class DrivingBrain(FakeBrain):
        def reply(self, text, on_text, smart=False):
            self.asked.append(text)
            self.позвал = ["drive"]
            answer = by_name["drive"]({"direction": "вперёд"})
            on_text(answer)
            said.append(answer)     # чтобы увидеть, что ответил инструмент
            return answer

    phrases = [
        "Кузя который час",        # проснулись по имени
        "...",                     # мусор от Whisper — «не расслышал»
        "...",                     # второй подряд — молчим
        "а я вчера ходил в магазин и купил там очень много всякой всячины",
        "поезжай на кухню",        # без имени, через модель — ехать нельзя
    ]
    app._listen_loop(cfg, FakeListener(phrases), types.SimpleNamespace(
        transcribe=lambda wav: wav.decode()), DrivingBrain(), FakeVoice(),
        tools2, addressed)

    check("на мусор ответил один раз", said.count("Не расслышал."), 1)
    check("длинная чужая фраза не ушла модели",
          any("магазин" in s for s in said), False)
    check("модель без имени не поехала", said[-1],
          "Позови меня по имени — тогда поеду.")
    check("колёса не тронулись", moved, [])

    # --- третий сценарий: имя не надо повторять в начатом разговоре ---
    #
    # Живая жалоба: «команды по движению делает через раз». Человек говорит
    # «Кузя, вперёд», робот едет, а через три секунды на «теперь назад»
    # слышит «позови меня по имени» — хотя звал секунду назад. Послабление
    # даётся только команде, разобранной ПРАВИЛОМ: «поезжай на кухню» уходит
    # модели, и там имя по-прежнему обязательно (это проверено выше).
    said.clear()
    moved.clear()
    addressed = app.Addressed()
    tools3 = build_tools(ros, timers, addressed=addressed)
    cfg3 = Config()
    app._listen_loop(cfg3, FakeListener([
        "Кузя вперёд",             # по имени — едет
        "метр назад",              # без имени, но правилом и в разговоре
        "два круга вокруг себя",   # и круги тоже
    ]), types.SimpleNamespace(transcribe=lambda wav: wav.decode()),
        FakeBrain(), FakeVoice(), tools3, addressed)

    check("по имени поехал", said[0].startswith("Еду вперёд"), True)
    check("и следом без имени тоже", said[1], "Еду назад метр.")
    check("круги сделал, а не рассказал о них", said[2], "Кручусь два круга.")

    # --- четвёртый сценарий: пустое «да» в окне разговора ---
    #
    # Живая жалоба: «нету живого диалога». В открытом окне слышно всё, что
    # звучит в комнате, и человеческое «да» кому-то другому уходило модели.
    # Та отвечала тем, чем отвечают на пустоту: «Понял, Игорь. Готов к
    # следующему. Что нужно?» — три казённые фразы на ровном месте. Живой
    # человек на чужое «да» молчит.
    said.clear()
    addressed = app.Addressed()
    tools4 = build_tools(ros, timers, addressed=addressed)
    молчун = FakeBrain()
    app._listen_loop(cfg3, FakeListener([
        "Кузя который час",
        "да",                      # не роботу — молчим
        "ага",                     # и на это тоже
    ]), types.SimpleNamespace(transcribe=lambda wav: wav.decode()),
        молчун, FakeVoice(), tools4, addressed)
    check("пустое «да» не ушло модели", молчун.asked, [])

    # Но если робот только что сам спросил — «да» это ответ ему, и молчать
    # в этом месте было бы хуже прежнего.
    спросили = FakeVoice()
    спросили.speaker = types.SimpleNamespace(stream=lambda **kw: None,
                                             last_said="Поставить таймер?")
    отвечающий = FakeBrain()
    app._listen_loop(cfg3, FakeListener(["Кузя да"]),
                     types.SimpleNamespace(transcribe=lambda wav: wav.decode()),
                     отвечающий, спросили, tools4, addressed)
    check("а ответ на вопрос робота дошёл", отвечающий.asked, ["да"])


def test_music_queue() -> None:
    """Очередь треков: кончился — ставим следующий, битый — пропускаем.

    Обратного канала от пульта к роботу нет, есть счётчик доигранных песен.
    Всё, что может пойти не так, идёт не так именно вокруг него: ссылка не
    открылась, пульт сообщил «доиграл» раньше, чем мы успели запомнить, от
    чего считать, — и музыка молча вставала на первой же песне.
    """
    section("очередь треков")
    пульт, ya = ГлухойПульт(), ФальшивыйЯндекс()
    player = Player(пульт, ya)

    треки = [ФальшивыйТрек(i) for i in range(3)]
    check("первый трек назван", player.очередь(треки, "genre:jazz", "п1"),
          "Кто-то — Песня 0")
    check("станции сообщили, что включились", ya.отзывы[0], "начали")
    check("пульт получил трек",
          [п for п, _ in пульт.команды if п == "/speak/track"], ["/speak/track"])

    # Пульт доиграл песню — счётчик вырос, робот обязан поставить следующую.
    пульт.счётчик += 1
    player._tick()
    check("после конца играет следующий", player.название, "Кто-то — Песня 1")
    check("ротору сказали, что трек дослушали",
          any(о.startswith("доиграл") for о in ya.отзывы), True)

    # Битая ссылка не должна останавливать вечер.
    плохой = ФальшивыйЯндекс(битые={"7:1"})
    player2 = Player(ГлухойПульт(), плохой)
    check("битый трек пропущен",
          player2.очередь([ФальшивыйТрек(7), ФальшивыйТрек(8)]),
          "Кто-то — Песня 8")

    # Отметку счётчика надо брать ДО отправки трека: иначе мгновенная ошибка
    # проигрывания принимается за исходное значение и следующая песня
    # не наступает никогда.
    п3 = ГлухойПульт()
    п3.счётчик = 5
    player3 = Player(п3, ФальшивыйЯндекс())
    player3.очередь([ФальшивыйТрек(1), ФальшивыйТрек(2)])
    п3.счётчик = 6                       # пульт сразу сказал «не пошло»
    player3._tick()
    check("мгновенная ошибка не останавливает очередь",
          player3.название, "Кто-то — Песня 2")

    # Станция досыпает треков, пока очередь не опустела.
    п4 = ГлухойПульт()
    ya4 = ФальшивыйЯндекс()
    player4 = Player(п4, ya4)
    player4.очередь([ФальшивыйТрек(1)], "user:onyourwave", "п1")
    было = ya4.партии
    for _ in range(4):          # доигрываем всё, что станция уже дала
        п4.счётчик += 1
        player4._tick()
    check("станция подсыпала треков", ya4.партии > было, True)
    check("музыка не кончилась", player4.играет, True)

    # Веб-сервер перезапустили — счётчик начал считать с нуля. Без этого его
    # ноль никогда не стал бы больше нашей семёрки, и музыка встала бы навсегда.
    п6 = ГлухойПульт()
    п6.счётчик = 7
    player6 = Player(п6, ФальшивыйЯндекс())
    player6.очередь([ФальшивыйТрек(1), ФальшивыйТрек(2)])
    п6.счётчик = 0                       # сервер перезапустился
    player6._tick()
    check("перезапуск сервера не двигает трек", player6.название, "Кто-то — Песня 1")
    п6.счётчик = 1                       # а вот теперь песня и правда кончилась
    player6._tick()
    check("после перезапуска очередь снова идёт",
          player6.название, "Кто-то — Песня 2")

    # Вкладку закрыли — «доиграл» не придёт никогда. Без запаса по времени
    # музыка встала бы намертво до следующей команды голосом.
    п5 = ГлухойПульт()
    player5 = Player(п5, ФальшивыйЯндекс())
    player5.очередь([ФальшивыйТрек(1), ФальшивыйТрек(2)])
    player5._потолок = 0.0                # как будто песня давно кончилась
    player5._tick()
    check("молчащий пульт не вешает музыку", player5.название, "Кто-то — Песня 2")

    check("выключил — не играет", player.выключить(), "Выключил.")
    check("выключать нечего", player.выключить(), "Музыка и так не играет.")

    # Первая песня не должна обрываться. Сторож в фоне решает, что трек завис,
    # по времени начала; пока его выставлял только сам трек, всё время похода
    # за ссылкой очередь выглядела зависшей — и первая песня перебивалась
    # второй. Воспроизводится только на роботе, включённом дольше четверти
    # часа: на свежем счётчик монотонных часов ещё мал. Поэтому — руками.
    import threading

    from robot_voice import music as _music

    class МедленныйЯндекс(ФальшивыйЯндекс):
        """Ссылку отдаёт не сразу — как настоящая сеть."""

        def __init__(self) -> None:
            super().__init__()
            self.пошёл = threading.Event()
            self.отпустить = threading.Event()

        def link(self, трек):
            self.пошёл.set()
            self.отпустить.wait(5)
            return super().link(трек)

    п6, ya6 = ГлухойПульт(), МедленныйЯндекс()
    player6 = Player(п6, ya6)
    часы = _music.time.monotonic
    # Робот, включённый больше четверти часа. На живом это всегда так: служба
    # крутится сутками. На свежем счётчике беда не воспроизводится вовсе, и
    # именно поэтому её никто не видел в проверках.
    _music.time.monotonic = lambda: часы() + 3600
    try:
        очередь = threading.Thread(
            target=player6.очередь, args=([ФальшивыйТрек(1), ФальшивыйТрек(2)],))
        очередь.start()
        ya6.пошёл.wait(5)                    # робот ушёл за ссылкой первой песни
        player6._tick()                      # сторож смотрит, не зависло ли
        ya6.отпустить.set()
        очередь.join(5)
    finally:
        _music.time.monotonic = часы
    check("не оборвал первую песню", player6.название, "Кто-то — Песня 1")
    check("в пульт ушла одна песня",
          [п for п, _ in п6.команды].count("/speak/track"), 1)

    # «Выключи», сказанное пока робот идёт за ссылкой, должно отменять трек.
    # Иначе музыка играет, а робот уверен, что выключил, — и на «что играет»
    # отвечает «ничего», и микрофон остаётся в шумном режиме навсегда.
    п7, ya7 = ГлухойПульт(), МедленныйЯндекс()
    player7 = Player(п7, ya7)
    player7._очередь = [ФальшивыйТрек(9)]
    player7.режим = "треки"
    поход = threading.Thread(target=player7.дальше, kwargs={"вслух": False})
    поход.start()
    ya7.пошёл.wait(5)                        # робот ушёл за ссылкой
    check("выключил посреди похода", player7.выключить(), "Выключил.")
    ya7.отпустить.set()                      # ссылка вернулась — но поздно
    поход.join(5)
    check("трек после «выключи» в пульт не уехал",
          [п for п, _ in п7.команды].count("/speak/track"), 0)
    check("робот не считает, что играет", player7.название, "")


def test_music_volume() -> None:
    """Громкость музыки — отдельно от громкости голоса.

    «Кузя, убавь музыку» на живом роботе кончилось тем, что он её выключил:
    правило про громкость знало только про голос, а под «убавь» подошло
    выключение. Теперь решает инструмент — по тому, играет ли что-нибудь.
    """
    section("громкость музыки")
    store = Path(tempfile.mkdtemp())
    timers = Timers(announce=lambda text, **kw: None, store=store / "timers.json")
    ros = types.SimpleNamespace(voltage=12.4, moving=False, connected=True,
                                drive=lambda *a, **k: None, stop_motion=lambda: None)
    громкость = {"голос": 1.0}
    speaker = types.SimpleNamespace(
        volume=1.0, last_said="", hush=lambda: None,
        set_volume=lambda v: громкость.__setitem__("голос", v))
    пульт = ГлухойПульт()
    player = Player(пульт, ФальшивыйЯндекс())
    tools = {t.name: t for t in build_tools(ros, timers, speaker=speaker,
                                            player=player)}

    # Музыка молчит — «тише» относится к голосу робота.
    tools["music_volume"]({"изменение": "тише"})
    check("без музыки тише говорит робот", громкость["голос"] < 1.0, True)

    # «Включи радио» — это радио, а не Яндекс. Без этого просьба про радио
    # уезжала в «Мою волну», а «включи радио Рекорд» искало в Яндексе песни
    # со словом «Рекорд» в названии.
    # Не нашлось — значит не нашлось. На живом роботе «включи музыку Грот»
    # без Яндекса кончилось тем, что модель подставила сначала «Группа крови»,
    # потом «джаз», и человеку заиграл джаз вместо того, что он просил.
    без_яндекса = Player(ГлухойПульт())          # только радио, как у Игоря
    сам = {t.name: t for t in build_tools(ros, timers, speaker=speaker,
                                          player=без_яндекса)}
    from robot_voice import radio as radio_api
    было_find = radio_api.find
    radio_api.find = lambda что, **kw: None
    try:
        отказ = сам["play_music"]({"что": "Грот"})
        check("отказ называет причину", "Яндекс" in отказ, True)
        check("отказ запрещает подбирать замену", "НЕ подбирай" in отказ, True)
        check("ничего не заиграло", без_яндекса.играет, False)
    finally:
        radio_api.find = было_find

    # По названию правилами, не моделью. На живом роботе «включи группу
    # Краски» уходило модели, а та, наученная прошлыми отказами, отвечала «не
    # найдено в моих источниках», ни разу не вызвав инструмент: Яндекс был
    # подключён и работал, волна играла, а по названию — ничего.
    for фраза, ждём in (("включи группу краски", "краски"),
                        ("включи группу король и шут", "король и шут"),
                        ("включи грота", "грота"),
                        ("поставь короля и шута", "короля и шута"),
                        ("включи альбом кино", "кино"),
                        ("включи песню грот", "грот")):
        м = parse(фраза)
        check(f"«{фраза}» разбирается правилом",
              (м.tool if м else None, (м.args.get("что") if м else None)),
              ("play_music", ждём))

    # Местоимения и частицы именем исполнителя не бывают. Без этой проверки
    # «включи это» и «поставь его» уходили искать в Яндексе слово «это».
    for фраза in ("включи это", "поставь его", "включи меня", "поставь сюда",
                  "включи давай", "поставь пожалуйста", "включи снова"):
        check(f"«{фраза}» — не название", parse(фраза), None)

    # И не хватает лишнего: всё это дома включают руками, музыки тут нет.
    for фраза in ("включи свет", "включи телевизор", "включи фонарик",
                  "включи камеру", "поставь чайник", "включи вентилятор",
                  "включи свет в зале", "включи громче", "включи тише"):
        м = parse(фраза)
        check(f"«{фраза}» — не музыка",
              м.tool if м else None,
              None if "громче" not in фраза and "тише" not in фраза else "volume")

    m = parse("включи радио рекорд")
    check("радио названо явно", m.args.get("источник"), "радио")
    radio_api.find = lambda что, **kw: ("Рекорд", "http://тест/поток.mp3")
    try:
        check("по слову «радио» идём в радио, а не в Яндекс",
              tools["play_music"]({"что": "рекорд", "источник": "радио"}),
              "Включаю Рекорд.")
        check("играет поток, а не очередь треков", player.режим, "поток")
    finally:
        radio_api.find = было_find

    player.очередь([ФальшивыйТрек(1)])
    было = player.громкость_
    # Считаем от этой точки, а не за весь тест: команду /speak/volume уже
    # положил сюда включённый трек строкой выше, и проверка «есть ли она
    # где-нибудь» оставалась зелёной, даже когда громкость до пульта не
    # доходила вовсе.
    пульт.команды.clear()
    check("с музыкой тише становится музыка",
          tools["music_volume"]({"изменение": "тише"}), "Сделал тише, 6 из 10.")
    check("голос не тронут", player.громкость_ < было, True)
    check("пульту ушла ровно громкость",
          [п for п, _ in пульт.команды], ["/speak/volume"])
    check("и с новым значением",
          [т for п, т in пульт.команды if п == "/speak/volume"], ["0.60"])

    for _ in range(10):
        player.тише()
    check("тише бесконечно нельзя", player.тише(),
          "Тише уже некуда. Сейчас 1 из 10.")
    # Прижим проверяем по самой громкости, а не только по сказанному вслух:
    # фразу подрезает свойство «ступень», поэтому прижим в на_ступень можно
    # было снести, и проверка бы этого не заметила.
    player.на_ступень(50)
    check("выше десяти не пускаем", player.громкость_, 1.0)
    player.на_ступень(-7)
    check("ниже единицы не пускаем", round(player.громкость_, 2), 0.1)
    for _ in range(10):
        player.громче()
    check("громче бесконечно нельзя", player.громче(),
          "Громче уже некуда. Сейчас 10 из 10.")

    # Десятибалльная шкала: «убавь до двух» человек говорит, «ноль шестьдесят
    # пять» — нет. Раньше числа передать было нечем, и модель отвечала «звук
    # уменьшен до двух», не тронув громкость.
    check("ступень числом", tools["music_volume"]({"изменение": "тише",
                                                   "уровень": 3}),
          "Сделал тише, 3 из 10.")
    check("доля пересчиталась", player.громкость_, 0.3)
    check("выше десяти не пускаем",
          tools["music_volume"]({"изменение": "громче", "уровень": 99}),
          "Сделал громче, 10 из 10.")
    check("ниже единицы не пускаем",
          tools["music_volume"]({"изменение": "тише", "уровень": 0 - 5}),
          "Сделал тише, 1 из 10.")
    player.на_ступень(8)
    check("«на два» — это подвинуть, а не поставить",
          tools["music_volume"]({"изменение": "тише", "шаг": 2}),
          "Сделал тише, 6 из 10.")
    check("«до двух» — это поставить",
          tools["music_volume"]({"изменение": "тише", "уровень": 2}),
          "Сделал тише, 2 из 10.")

    # Под музыку голое «сделай тише» — про музыку. Свой голос робот и так
    # приглушает, пока играет песня, а человек имеет в виду песню.
    player.на_ступень(7)
    check("«сделай тише» под музыку — про музыку",
          tools["volume"]({"change": "тише"}), "Сделал тише, 6 из 10.")
    check("«говори тише» — всё-таки про голос",
          tools["volume"]({"change": "тише", "про_голос": True}),
          "Хорошо, буду тише.")

    check("что играет", tools["what_is_playing"]({}), "Играет Кто-то — Песня 1.")


def test_noisy_ear() -> None:
    """Под музыку робот должен быть придирчивее к тому, что считать фразой.

    На живом роботе включённое радио ломало распознавание: детектор речи
    принимал музыку за речь, каждая пауза уезжала на ПК отдельным куском и
    возвращалась пустой. Уверенность на настоящих фразах падала с −0.25 до
    −0.75, и «Кузя» превращался в «Кульзу».
    """
    section("шум под музыку")
    from robot_voice import audio

    l = audio.Listener.__new__(audio.Listener)
    l._start, l._min_speech, l._noisy = 2, 15, False
    check("в тишине порог обычный",
          (l.start_frames, l.min_speech_frames), (2, 15))
    l.background(True)
    check("под музыку начать труднее", l.start_frames, 4)
    # А вот длину фразы поднимать нельзя: «стоп» — это меньше полусекунды
    # речи, и удвоенный порог выбросил бы ровно ту команду, ради которой всё
    # и останавливается. Музыкальный мусор в логе был длинный, по три секунды,
    # так что пользы от этого порога всё равно не было бы.
    check("длину фразы музыка не трогает", l.min_speech_frames, 15)
    l.background(False)
    check("музыку выключили — порог вернулся",
          (l.start_frames, l.min_speech_frames), (2, 15))

    # Одиночный щелчок под музыку начинать запись не должен, а короткое
    # «стоп» — должно, и под музыку тоже.
    check("щелчок под музыку не начинает запись",
          прогон_фраз([(False, 20), (True, 3), (False, 40)], шумно=True), [])
    check("короткое «стоп» под музыку слышно",
          len(прогон_фраз([(False, 20), (True, 20), (False, 40)], шумно=True)), 1)


def test_counting() -> None:
    """Счёт, секундомер и жребий — то, чего модель не умеет честно."""
    from robot_voice import counting as c

    section("счёт, секундомер и жребий")

    check("проценты", c.вслух(c.посчитать("15/100*2000")), "300")
    # Ноль в границе — настоящий ноль, а не «границу не назвали». Через «or»
    # он превращался в единицу, и «от нуля до трёх» нуля не давало никогда.
    выпало = {c.число(0, 3) for _ in range(200)}
    check("ноль в жребий попадает", "0." in выпало, True)
    check("за верхнюю границу не вылезаем",
          выпало <= {"0.", "1.", "2.", "3."}, True)
    check("скобки", c.вслух(c.посчитать("(3+4)*2")), "14")
    check("дробь без хвоста нулей", c.вслух(c.посчитать("7.5*2")), "15")
    check("дробь запятой", c.вслух(c.посчитать("10/4")), "2,5")
    for плохое, почему in (("1/0", "деление на ноль"),
                           ("2**100000", "неподъёмная степень"),
                           ("__import__('os')", "запуск кода"),
                           ("", "пусто")):
        try:
            c.посчитать(плохое)
            check(f"{почему} — отказ", "посчитал", "отказался")
        except ValueError:
            check(f"{почему} — отказ", True, True)

    # Секундомер на поддельных часах: настоящие сделали бы тест то зелёным,
    # то красным в зависимости от загрузки машины.
    тик = iter([0, 5, 5, 5, 12, 12, 12, 12]).__next__
    с = c.Секундомер(часы=тик)
    check("пуск", с.пуск(), "Пошёл.")
    check("на ходу считает", с.вслух(), "пять секунд")
    check("стоп называет время", с.стоп(), "Остановил, пять секунд.")
    check("после стопа не растёт", с.сколько(), "Секундомер остановлен: пять секунд.")
    check("сброс", с.сброс(), "Сбросил.")
    check("сброшенный молчит", с.сколько(), "Секундомер не запущен.")

    # Один линейный сценарий защит не сторожит: их можно было снести целиком,
    # и проверка осталась бы зелёной. Дома же путаются постоянно — говорят
    # «засеки» дважды или «стоп» на незапущенном.
    с2 = c.Секундомер(часы=тик)
    check("стоп без пуска", с2.стоп(), "Секундомер не запущен.")
    check("сброс на нуле", с2.сброс(), "Секундомер и так на нуле.")
    с2.пуск()
    check("второй пуск не сбрасывает счёт", с2.пуск().startswith("Секундомер уже идёт"), True)
    было = с2.секунд
    check("и не обнулил накопленное", с2.секунд >= было, True)
    с2.стоп()
    check("второй стоп говорит, что уже стоит",
          с2.стоп().startswith("Секундомер и так стоит"), True)
    check("после стопа время помнится", с2.сколько().startswith("Секундомер остановлен"), True)

    # Имя исполнителя вслух называют в косвенном падеже: «включи Грота»,
    # «поставь Короля и Шута». Требовалось точное совпадение с именительным, и
    # вечер уезжал в поиск по трекам — то есть в каверы и трибьюты.
    from robot_voice.yandex import _то_же_имя
    for имя, спросили, ждём in (
        ("Грот", "грота", True), ("Грот", "грот", True),
        ("Король и Шут", "короля и шута", True),
        ("Виктор Цой", "виктора цоя", True),
        ("Ленинград", "ленинграда", True), ("Земфира", "земфиру", True),
        # А свободнее нельзя: «поставь спокойную музыку» находило группу
        # «Спокойной ночи», и весь вечер играла она.
        ("Спокойной ночи", "спокойную музыку", False),
        ("Кино", "кинотеатр", False), ("Сплин", "спину", False),
    ):
        check(f"«{спросили}» — это {имя}?" , _то_же_имя(имя, спросили), ждём)

    # Жребий: проверяем не «выпало семь», а что бросок настоящий — иначе
    # проверка была бы про генератор случайных чисел, а не про робота.
    выпало = {c.монетка() for _ in range(200)}
    check("монетка падает на обе стороны", выпало, {"Орёл.", "Решка."})
    числа = {c.кубик() for _ in range(300)}
    check("кубик даёт все шесть", len(числа), 6)
    check("грани сверх шести названы", c.кубик(20, бросок=lambda a, b: 17), "17 из 20.")
    check("перепутанные границы не ломают",
          c.число(10, 1, бросок=lambda a, b: (a, b)), "(1, 10).")
    check("выбор из пустого", c.выбрать([]), "Не из чего выбирать.")
    check("выбор из одного", c.выбрать(["чай"]), "Выбирать не из чего, только чай.")

    # И то же самое голосом — иначе каждая такая фраза шла бы платной модели.
    for фраза, инструмент, аргументы in (
        ("засеки время", "stopwatch", {"действие": "пуск"}),
        ("сколько прошло", "stopwatch", {"действие": "сколько"}),
        ("останови секундомер", "stopwatch", {"действие": "стоп"}),
        ("подбрось монетку", "random_pick", {"вид": "монетка"}),
        ("кинь кубик", "random_pick", {"вид": "кубик", "сверху": 6}),
        ("загадай число от 1 до 100", "random_pick",
         {"вид": "число", "снизу": 1, "сверху": 100}),
        ("посчитай 2+2", "calculate", {"выражение": "2 + 2"}),
        ("сколько будет пять умножить на три", "calculate",
         {"выражение": "5 * 3"}),
        ("20% от 5000", "calculate", {"выражение": "20/100*5000"}),
    ):
        м = parse(фраза)
        check(f"«{фраза}» разбирается правилом",
              (м.tool, м.args) if м else None, (инструмент, аргументы))

    # Меры: падежей у них много («в метре», «в минутах», «пять футов»), и
    # перечислять их списком — верный способ забыть один. Ищем по основе.
    check("сантиметры в метре", c.перевести(1, "метре", "сантиметров"),
          "100 сантиметров.")
    check("дробный ответ в родительном", c.перевести(1, "миля", "километров"),
          "1,61 километра.")
    check("падежи мер", c.перевести(2, "часа", "минутах"), "120 минут.")
    check("номинал не забыт", c.перевести(3, "футах", "метрах"), "0,91 метра.")
    check("разные рода не мешаем", c.перевести(1, "метр", "килограммов"),
          "Длина в вес не перевести.")
    check("незнакомая мера названа", c.перевести(5, "попугаев", "метров"),
          "Не знаю такой меры — попугаев.")
    # Мелочь не должна округляться в ноль: миллиметр в километрах — одна
    # миллионная, а робот уверенно говорил «ноль километров».
    check("мелкая мера не ноль", c.перевести(1, "миллиметр", "километров"),
          "0,000001 километра.")
    check("грамм в тоннах", c.перевести(1, "грамм", "тонн"), "0,000001 тонны.")
    # У мили общее начало всех трёх форм — «мил», и по нему мерой считалось
    # любое слово с таким началом. «Переведи 500 миллиграмм» отвечало милями.
    check("миллиграмм не миля", c.найти_меру("миллиграмм"), None)
    check("милиция не миля", c.найти_меру("милиция"), None)
    check("миля осталась мерой", c.найти_меру("мили")[2][0], "миля")
    check("миллилитр остался мерой", c.найти_меру("миллилитр")[2][0], "миллилитр")

    # Показателя степени мало: у «(два в тысячной) в тысячной» он всего тысяча,
    # а в ответе триста тысяч цифр — такое не сказать и не напечатать.
    for выражение in ("2**500**500", "(2**1000)**1000"):
        try:
            c.посчитать(выражение)
            check(f"«{выражение}» отклонено", "посчитал", "отказ")
        except ValueError:
            check(f"«{выражение}» отклонено", "отказ", "отказ")
    # А то, что помещается, считается и произносится без падения: раньше
    # большое целое уезжало в форматирование через float и роняло OverflowError.
    check("большое целое произносится", c.вслух(2 ** 200)[:6], "160693")

    # Время в другом городе модель не знает вовсе: смещение она выдумает, а
    # текущего момента у неё нет. Часы есть только у робота.
    from datetime import datetime, timedelta, timezone
    полдень = datetime(2026, 8, 3, 12, 0, tzinfo=timezone.utc)
    check("время в Москве", c.время_в("москве", полдень), "В Москве сейчас пятнадцать часов ровно.")
    # Модель зовёт инструмент именительным падежом, и робот говорил вслух
    # «в Москва сейчас». Падеж берём из таблицы, а не из услышанного.
    check("именительный падеж от модели", c.время_в("москва", полдень),
          "В Москве сейчас пятнадцать часов ровно.")
    check("Нью-Йорк пишется с большой", c.время_в("нью-йорк", полдень),
          "В Нью-Йорке сейчас восемь часов ровно.")
    check("время во Владивостоке",
          c.время_в("владивостоке", полдень),
          "Во Владивостоке сейчас двадцать два часа ровно.")
    check("город не из списка", c.время_в("зурбаган", полдень), "")

    # Летнее время. Смещением в часах это не решается: половину года оно врёт,
    # и врёт тихо. Проверяем на двух датах — в августе Лондон на час впереди
    # Гринвича, в январе совпадает с ним.
    зима = datetime(2026, 1, 3, 12, 0, tzinfo=timezone.utc)
    check("Лондон летом", c.время_в("лондоне", полдень),
          "В Лондоне сейчас тринадцать часов ровно.")
    check("Лондон зимой", c.время_в("лондоне", зима),
          "В Лондоне сейчас двенадцать часов ровно.")
    check("Нью-Йорк летом", c.время_в("нью-йорке", полдень),
          "В Нью-Йорке сейчас восемь часов ровно.")
    # А в России летнего времени нет с четырнадцатого года — Москва обязана
    # ответить одинаково в обе даты.
    check("Москва не переводит часы",
          c.время_в("москве", полдень) == c.время_в("москве", зима), True)

    # Деньги считаем по сегодняшнему курсу, а не по таблице мер: в метре
    # сантиметров всегда сто, а доллар вчерашним не бывает.
    from robot_voice import lookup
    было_get = lookup._get
    lookup._get = lambda url, **kw: {"Valute": {
        "USD": {"Value": 80.0, "Nominal": 1},
        "JPY": {"Value": 52.0, "Nominal": 100}}}
    try:
        check("доллары в рубли", lookup.convert_money(100, "долларов", "рубли"),
              "8000 рублей.")
        check("рубли в доллары", lookup.convert_money(800, "рублей", "доллары"),
              "Десять долларов.")
        check("номинал у иены учтён",
              lookup.convert_money(10000, "йен", "рублей"), "5200 рублей.")
        check("метры деньгами не считаем",
              lookup.convert_money(5, "метров", "рублей"), "")
    finally:
        lookup._get = было_get

    for фраза, инструмент in (("сколько времени в москве", "time_now"),
                              ("который час в лондоне", "time_now"),
                              ("переведи 200 граммов в фунты", "convert_units"),
                              ("сколько сантиметров в метре", "convert_units"),
                              ("переведи 100 долларов в рубли", "convert_units")):
        м = parse(фраза)
        check(f"«{фраза}» разбирается правилом", м.tool if м else None, инструмент)

    # Форма фразы у этих та же самая, отличаются только слова — поэтому
    # правило спрашивает словарь мер и городов, а не гадает по виду. Иначе
    # «сколько лет в году» разбиралось как перевод мер, а «сколько времени в
    # пути» — как время в городе Пути.
    for фраза in ("сколько времени в пути", "который час в дороге",
                  "сколько лет в году", "сколько человек в комнате",
                  "сколько дней в отпуске"):
        check(f"«{фраза}» — не правило", parse(фраза), None)

    # Ноль минут — это не таймер на шесть секунд, а недопонятая просьба:
    # звонил он раньше, чем человек успевал договорить.
    store = Path(tempfile.mkdtemp())
    timers = Timers(announce=lambda text, **kw: None, store=store / "t.json")
    ros = types.SimpleNamespace(voltage=12.4, moving=False, connected=True,
                                drive=lambda *a, **k: None, stop_motion=lambda: None)
    t = {x.name: x for x in build_tools(ros, timers)}
    check("таймер на ноль минут", t["set_timer"]({"minutes": 0}),
          "На сколько ставить таймер?")
    check("таймер в минус", t["set_timer"]({"minutes": -5}),
          "На сколько ставить таймер?")
    check("таймер на сутки", t["set_timer"]({"minutes": 100000})[:19],
          "Дольше десяти часов")


def test_rules_reach_tools() -> None:
    """Каждое правило должно попадать в существующий инструмент.

    Имя из Match ищется среди Tool по строке, и опечатка тут не падает, а
    молча уводит фразу платной модели: правило сработало, инструмента нет,
    в логе — обычное «правилами не разобрал». Ровно так и вышло бы при
    переименовании play_radio → play_music, если забыть одну из двух сторон.
    """
    import re as _re

    from robot_voice.people import People

    section("правила достают до инструментов")
    store = Path(tempfile.mkdtemp())
    timers = Timers(announce=lambda text, **kw: None, store=store / "timers.json")
    ros = types.SimpleNamespace(voltage=12.4, moving=False, connected=True,
                                drive=lambda *a, **k: None, stop_motion=lambda: None)
    speaker = types.SimpleNamespace(volume=1.0, last_said="",
                                    set_volume=lambda v: None, hush=lambda: None)
    # Собираем робота во всей полноте: часть инструментов появляется только
    # вместе с пультом, списком или людьми, и без них проверка бы соврала.
    tools = build_tools(ros, timers, speaker=speaker,
                        notes=Notes(store / "notes.json"),
                        people=People(store / "люди.json"), who=lambda: "Игорь",
                        home=lambda: (54.7, 20.5), set_place=lambda *a: None,
                        addressed=lambda: True, player=Player(ГлухойПульт()),
                        # Глаза тоже: без них не собирается look_around, и
                        # проверка объявила бы правило про взгляд битым.
                        eyes=types.SimpleNamespace(
                            посмотреть=lambda вопрос="": "вижу стол"),
                        # И дальномер: без него не собирается path_check, к
                        # которому теперь идёт правило про дорогу.
                        tof=types.SimpleNamespace(
                            беда="",
                            взгляд=lambda: types.SimpleNamespace(
                                свежий=True, впереди=2.0, слева=2.0, справа=2.0,
                                ехать_можно=lambda: (True, ""))))
    есть = {t.name for t in tools}

    исходник = (Path(__file__).resolve().parent / "robot_voice" / "intents.py"
                ).read_text(encoding="utf-8")
    зовут = set(_re.findall(r"Match\(\s*\"([a-z_]+)\"", исходник))
    check("все имена из правил существуют", sorted(зовут - есть), [])

    # Правила писались под одну реплику, а распознавание отдаёт всё, что успело
    # прозвучать: в один кусок попадает по два-три предложения. С живого
    # робота — «— Выключи музыку. — Нет.» ушло модели, та ответила «Музыку не
    # выключал, не слышал», и музыка осталась играть. Правило при этом было на
    # месте и прекрасно разбирало «выключи музыку».
    from robot_voice.app import _разобрать
    for фраза, ждём in (("выключи музыку", "stop_music"),
                        ("— Выключи музыку. — Нет.", "stop_music"),
                        ("Да, я в зал. Выключи музыку.", "stop_music"),
                        ("Кузя! Стоп.", "stop")):
        правило, _ = _разобрать(фраза)
        check(f"«{фраза}» разбирается", правило and правило.tool, ждём)
    # А безобидный разговор от этого командой стать не должен.
    # Голое «выключи» — чаще всего про музыку. С живого робота: человек дважды
    # сказал его, имея в виду песню, модель дважды позвала остановку движения и
    # ответила «ты и так стоишь», пока музыка играла. Что имелось в виду, видно
    # только по тому, играет ли что-нибудь, поэтому решает инструмент.
    for фраза in ("выключи", "выключай", "вырубай"):
        правило, _ = _разобрать(фраза)
        check(f"«{фраза}» — про музыку", правило and правило.tool, "stop_music")
    # Распознавание коверкает глаголы движения: «проезь», «проежай». Правило на
    # них не срабатывало, фраза уходила модели — две секунды вместо нуля.
    for фраза in ("проезь вперёд метр", "проежай вперёд метр",
                  "проедь вперёд метр"):
        правило, _ = _разобрать(фраза)
        check(f"«{фраза}» — движение", правило and правило.tool, "drive")

    for фраза in ("не надо ничего выключать", "привет как дела",
                  "мы вчера ходили гулять, было здорово"):
        правило, цепочка = _разобрать(фраза)
        check(f"«{фраза}» — не команда", (правило, цепочка), (None, None))

    # Инструменты музыки не должны зависеть от того, куда идёт ГОЛОС робота.
    # Условие audio_out == "browser" вокруг проигрывателя стоило вечера на
    # живом роботе: перевели голос на свой динамик — и робот стал отвечать «у
    # меня нет такой функции», имея под рукой работающее радио, а «убавь
    # громкость» говорил «уменьшена», не изменив ничего.
    from robot_voice.app import _собрать_проигрыватель
    for куда in ("browser", "local"):
        cfg = types.SimpleNamespace(
            yandex_token="", audio_out=куда,
            web_endpoint="http://127.0.0.1:8000/speak")
        плеер = _собрать_проигрыватель(
            cfg, types.SimpleNamespace(get=lambda k, d=None: d, set=lambda *a: None),
            types.SimpleNamespace(background=lambda шумно: None))
        check(f"проигрыватель есть при audio_out={куда}", плеер is not None, True)
    # И раз он есть всегда — правило громкости всегда достаёт до инструмента.
    check("громкость музыки собрана", "music_volume" in есть, True)

    # Музыка должна играть туда же, куда голос. Пока голос шёл во вкладку, там
    # же играла и музыка; с колонкой на роботе вкладка стала лишним звеном —
    # робот честно ставил песню и рапортовал «включаю», а человек не слышал
    # ничего, потому что вкладка закрыта.
    from robot_voice.music import Колонка, Pult
    for куда, ожидаем in (("browser", Pult), ("local", Колонка)):
        cfg = types.SimpleNamespace(
            yandex_token="", audio_out=куда, spk_device="plughw:0,0",
            music_device="", web_endpoint="http://127.0.0.1:8000/speak")
        плеер = _собрать_проигрыватель(
            cfg, types.SimpleNamespace(get=lambda k, d=None: d, set=lambda *a: None),
            types.SimpleNamespace(background=lambda шумно: None))
        # Без mpv в колонку играть нечем — тогда честно остаётся пульт.
        ждём = ожидаем if (куда == "browser" or Колонка.есть()) else Pult
        check(f"audio_out={куда} — играем через {ждём.__name__}",
              isinstance(плеер.пульт, ждём), True)

    # Музыке можно свою карту: голосовая может не тянуть её физически.
    # ReSpeaker Lite умеет ровно 16 кГц — речи хватает, музыке это потолок в
    # восемь килогерц по полосе, и лечится он только другой картой.
    if Колонка.есть():
        cfg = types.SimpleNamespace(
            yandex_token="", audio_out="local", spk_device="plughw:0,0",
            music_device="plughw:1,0", web_endpoint="http://127.0.0.1:8000/speak")
        плеер = _собрать_проигрыватель(
            cfg, types.SimpleNamespace(get=lambda k, d=None: d, set=lambda *a: None),
            types.SimpleNamespace(background=lambda шумно: None))
        check("музыка идёт на свою карту", плеер.пульт.device, "plughw:1,0")

    # Обе стороны обязаны отвечать на одни и те же вызовы: Player не должен
    # знать, во вкладку он играет или в колонку.
    check("колонка умеет то же, что пульт",
          sorted(м for м in ("поток", "трек", "громкость", "сыграно")
                 if not callable(getattr(Колонка(""), м, None))), [])

    # Проверять наличие файла мало: на живом роботе mpv поставился и падал с
    # «undefined symbol» — фирменные драйверы против стандартной сборки. По
    # which() он выглядел исправным, и музыка молча уходила в никуда.
    for игрок in Колонка.ИГРОКИ:
        команда = Колонка("plughw:0,0", игрок=игрок)._команда("http://радио")
        check(f"{игрок}: адрес последним", команда[-1], "http://радио")
        check(f"{игрок}: запускается собой", команда[0], игрок)
    # Громкость должна доезжать до команды, а не теряться по дороге: «сделай
    # тише» обязано звучать тише хотя бы со следующего трека.
    тихая = Колонка("", игрок="ffplay")
    тихая._громкость = 0.3
    check("ffplay: громкость в проценты", "30" in тихая._команда("х"), True)
    тихая = Колонка("", игрок="mpg123")
    тихая._громкость = 0.5
    check("mpg123: громкость долей шкалы", "16384" in тихая._команда("х"), True)

    # Схемы должны быть такими, какими их принимает API. Здесь это стоило
    # целого вечера: одно русское имя поля отклоняет ВЕСЬ список инструментов
    # разом, а не только свой инструмент, — то есть любой запрос к модели.
    # Робот при этом слышит и всё понимает, но ответить не может ничем, а в
    # журнале лежит «tools.5.custom.input_schema.properties» и номер, по
    # которому ещё надо догадаться, о ком речь.
    имя_поля = _re.compile(r"^[a-zA-Z0-9_.-]{1,64}$")
    имя_инструмента = _re.compile(r"^[a-zA-Z0-9_-]{1,64}$")
    плохие: list[str] = []
    for t in tools:
        схема = t.spec()["input_schema"]
        if not имя_инструмента.fullmatch(t.spec()["name"]):
            плохие.append(f"{t.name}: имя инструмента")
        поля = list((схема.get("properties") or {}).keys())
        поля += list(схема.get("required") or [])
        плохие += [f"{t.name}.{поле}" for поле in поля
                   if not имя_поля.fullmatch(поле)]
    check("имена полей в схемах API примет", sorted(set(плохие)), [])

    # И обратно: то, что модель пришлёт этими именами, должно доехать до наших
    # функций с русскими параметрами. Перевод идёт по схеме самого инструмента,
    # а не по общему списку: у volume поле и так зовётся change по-английски, и
    # общая замена чинила одно, ломая соседнее.
    по_имени = {t.name: t for t in tools}
    check("time_now берёт город латиницей",
          "Москв" in по_имени["time_now"]({"city": "москва"}), True)
    check("calculate берёт выражение латиницей",
          по_имени["calculate"]({"expression": "15/100*2000"}), "300")
    check("convert_units берёт меры латиницей",
          по_имени["convert_units"]({"amount": 2, "from_unit": "метра",
                                     "to_unit": "сантиметры"}),
          "200 сантиметров.")
    check("random_pick берёт варианты латиницей",
          по_имени["random_pick"]({"kind": "выбор",
                                   "options": ["чай", "кофе"]})
          in ("чай.", "кофе."), True)
    check("volume не путает своё change с чужим",
          по_имени["volume"]({"change": "тише"}).startswith("Не понял"), False)
    # Правила зовут те же инструменты русскими именами — этот путь ломать
    # нельзя, он основной и до модели вообще не доходит.
    check("правила по-прежнему зовут по-русски",
          по_имени["random_pick"]({"вид": "монетка"}) in ("Орёл.", "Решка."),
          True)


def test_ears_default_by_device() -> None:
    """Эхоподавление по умолчанию зависит от того, чем открыли пульт.

    На компьютере пульт открывают в наушниках, и подавлять эхо вредно: оно
    съедает и голос человека. На телефоне наушников нет, микрофон и динамик в
    одном корпусе — без подавления звук идёт сплошняком, робот не видит пауз и
    выбрасывает всё как «непрерывный звук дольше 20 с». На живом роботе с
    телефона так не разобралось ни одной фразы.

    Проверка статическая и намеренно грубая: она не про то, как ведёт себя
    браузер, а про то, что умолчание вообще осталось зависимым от устройства.
    Вернуть его к «всегда наушники» — значит снова оглушить телефон.
    """
    section("наушники по умолчанию — по устройству")

    страница = (Path(__file__).resolve().parent.parent / "web" / "pult.html"
                ).read_text(encoding="utf-8")
    check("умолчание смотрит на указатель",
          "pointer: coarse" in страница, True)
    check("выбор человека сохраняется",
          "localStorage.setItem('earsOn'" in страница, True)
    # Три строки выше переживали ровно ту правку, от которой поставлены:
    # перевернуть умолчание можно было, не тронув ни одной. Поэтому проверяем
    # сам знак: на грубом указателе — телефон — эхоподавление обязано быть
    # включено, на точном — выключено.
    место = страница.find("pointer: coarse")
    хвост = страница[место:место + 400]
    check("на телефоне подавление включено",
          "earsOn = " in хвост and "!" not in хвост.split("earsOn = ")[1][:6], True)


def test_duck() -> None:
    """Приглушение музыки под речь — числами, а не на слух.

    Считаем ту же петлю, что живёт в pult.html, но постоянные берём из самой
    страницы: если их поправят, эта проверка посчитает по новым и покраснеет.
    Устройство петли она при этом не сторожит — за него отвечает прогон в живом
    браузере, который в постоянные проверки не унести.

    Ловится здесь то, чего не видно глазами: приглушение кормило само себя.
    Убавили музыку — фон уехал вниз вслед за ней — музыка вернулась на полную —
    это прочиталось как «заговорили» — убавили снова. В тишине музыка качалась
    восемь секунд из десяти. А когда фон всё-таки успевал выучиться, порог
    уходил выше единицы, то есть выше физического предела шкалы, и приглушение
    не срабатывало ни разу за всю фразу.
    """
    import re as _re

    section("приглушение музыки под речь")
    страница = (Path(__file__).resolve().parent.parent / "web" / "pult.html"
                ).read_text(encoding="utf-8")

    def число(имя: str) -> float:
        совпало = _re.search(rf"\b{имя}\s*=\s*([0-9.]+)", страница)
        if совпало is None:
            raise AssertionError(f"в pult.html не нашлось {имя}")
        return float(совпало.group(1))

    ТИХО = число("RADIO_QUIET")
    ВВЕРХ, ВНИЗ = число("FLOOR_UP"), число("FLOOR_DOWN")
    БЫСТРО, УЧИМ = число("FLOOR_FAST"), число("FLOOR_LEARN")
    РАЗ = число("VOICE_OVER")
    ЗАПАС_МИН, ЗАПАС_МАКС = число("ЗАПАС_МИН"), число("ЗАПАС_МАКС")
    ДЕРЖИМ, ПОДРЯД = число("DUCK_HOLD"), число("VOICE_RUN")
    БЛОК, ПОЛНАЯ = 85, 0.7

    def прогон(музыка: float, речь_от: float, речь_до: float,
               секунд: float, учить: bool) -> int:
        """Доля времени с приглушённой музыкой за последние десять секунд."""
        фон, подряд, держим_до = 0.02, 0, 0.0
        учим_до = УЧИМ if (учить and музыка) else 0.0
        приглушено = всего = 0
        t = 0.0
        while t < секунд * 1000:
            тихо = t < держим_до
            громкость = min(ТИХО, ПОЛНАЯ) if тихо else ПОЛНАЯ
            голос = 0.45 if речь_от < t < речь_до else 0.0
            слышно = min(1.0, музыка * (громкость / ПОЛНАЯ) + голос + 0.01)
            доля = max(0.05, громкость / ПОЛНАЯ) if музыка else 1.0
            учимся = t < учим_до
            приведённый = слышно / доля
            фон += ((приведённый - фон)
                    * ((БЫСТРО if учимся else ВВЕРХ)
                       if приведённый > фон else ВНИЗ))
            ожидаем = фон * доля
            запас = min(ЗАПАС_МАКС, max(ЗАПАС_МИН, ожидаем * (РАЗ - 1)))
            подряд = подряд + 1 if (слышно > ожидаем + запас and not учимся) else 0
            if подряд >= ПОДРЯД:
                держим_до = t + ДЕРЖИМ
            if t > секунд * 1000 - 10000:
                всего += 1
                приглушено += тихо
            t += БЛОК
        return round(100 * приглушено / всего)

    нет = 10 ** 9
    # Тишина: музыка играет, в комнате никого. Приглушать нечего и незачем.
    for уровень in (0.08, 0.25, 0.40):
        check(f"тишина под музыку {уровень}: не качается",
              прогон(уровень, нет, нет, 60, учить=False) <= 5, True)
    check("тишина после честного пуска музыки",
          прогон(0.25, нет, нет, 60, учить=True) <= 5, True)

    # Речь поверх музыки — то единственное, ради чего всё это написано.
    for уровень in (0.15, 0.25, 0.40):
        check(f"речь поверх музыки {уровень}: приглушает",
              прогон(уровень, 54000, 60000, 60, учить=True) >= 40, True)

    # Длинная фраза. Пока фон поднимался за восемь секунд, собственная речь
    # затягивала его наверх и музыка возвращалась на полную посреди разговора —
    # ровно то, от чего в комментарии над постоянными и защищаются.
    check("длинная фраза держит музыку тихой всё время",
          прогон(0.0, 2000, 20000, 20, учить=False) >= 85, True)
    check("выбор человека сильнее умолчания",
          "выбранное === null" in страница, True)


def test_ws_proxy() -> None:
    """Мостик до rosbridge через сервер пульта.

    Нужен из-за https: страница по https не имеет права открыть ws:// —
    браузер блокирует это как смешанное содержимое, и молча. То есть, включив
    https ради микрофона на телефоне, мы бы разом сломали езду, ничего не
    заметив: джойстик перестал бы двигать робота, а в логе было бы пусто.

    Проверяем главное: рукопожатие подписано правильно и кадры доходят в обе
    стороны без правок. Переливаем байтами, потому что роли совпадают —
    браузер шлёт клиентские кадры, которых rosbridge и ждёт, а обратно идут
    серверные, которых ждёт браузер.
    """
    import base64 as _b64
    import hashlib as _hash
    import os as _os
    import socket as _sock
    import threading as _thr

    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import wsproxy

    section("мостик до rosbridge")

    МАГИЯ = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

    def кадр(данные: bytes) -> bytes:
        return bytes([0x81, len(данные)]) + данные

    def поддельный_ros(гнездо: _sock.socket) -> None:
        соединение, _ = гнездо.accept()
        буфер = b""
        while b"\r\n\r\n" not in буфер:
            кусок = соединение.recv(4096)
            if not кусок:
                return
            буфер += кусок
        ключ = ""
        for строка in буфер.split(b"\r\n"):
            if строка.lower().startswith(b"sec-websocket-key:"):
                ключ = строка.split(b":", 1)[1].strip().decode()
        подпись = _b64.b64encode(
            _hash.sha1((ключ + МАГИЯ).encode()).digest()).decode()
        соединение.sendall(
            (f"HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\n"
             f"Connection: Upgrade\r\nSec-WebSocket-Accept: {подпись}\r\n\r\n"
             ).encode())
        соединение.sendall(кадр(b"privet"))
        пришло = соединение.recv(4096)
        # Снимаем маску и отправляем обратно: так видно, что кадр дошёл целым.
        длина, маска = пришло[1] & 0x7F, пришло[2:6]
        тело = пришло[6:6 + длина]
        соединение.sendall(
            кадр(bytes(б ^ маска[i % 4] for i, б in enumerate(тело))))

    ros = _sock.socket()
    ros.setsockopt(_sock.SOL_SOCKET, _sock.SO_REUSEADDR, 1)
    ros.bind(("127.0.0.1", 0))
    ros.listen(1)
    wsproxy.ROS_HOST, wsproxy.ROS_PORT = "127.0.0.1", ros.getsockname()[1]
    _thr.Thread(target=поддельный_ros, args=(ros,), daemon=True).start()

    браузер, изнанка = _sock.socketpair()
    ключ = _b64.b64encode(_os.urandom(16)).decode()
    заголовки = {"Sec-WebSocket-Key": ключ, "Upgrade": "websocket",
                 "Connection": "Upgrade"}
    check("вебсокет опознан", wsproxy.это_вебсокет(заголовки), True)
    check("обычный запрос не опознан",
          wsproxy.это_вебсокет({"Connection": "keep-alive"}), False)

    мост = _thr.Thread(target=wsproxy.проводить, args=(изнанка, заголовки),
                       daemon=True)
    мост.start()

    браузер.settimeout(10)
    ответ = b""
    while b"\r\n\r\n" not in ответ:
        ответ += браузер.recv(4096)
    голова, _, хвост = ответ.partition(b"\r\n\r\n")
    ждём = _b64.b64encode(_hash.sha1((ключ + МАГИЯ).encode()).digest()).decode()
    check("ответ 101", b"101" in голова.split(b"\r\n")[0], True)
    check("подпись рукопожатия верна", ждём.encode() in голова, True)

    привет = хвост or браузер.recv(4096)
    check("первое слово rosbridge дошло", привет[2:2 + (привет[1] & 0x7F)], b"privet")

    маска = _os.urandom(4)
    слово = b"ping"
    браузер.sendall(bytes([0x81, 0x80 | len(слово)]) + маска
                    + bytes(б ^ маска[i % 4] for i, б in enumerate(слово)))
    эхо = браузер.recv(4096)
    check("кадр дошёл до rosbridge целым",
          эхо[2:2 + (эхо[1] & 0x7F)], b"ping")

    браузер.close()
    ros.close()

    # Без ключа рукопожатия соединение должно закрыться понятной ошибкой, а не
    # повиснуть: браузер в этом случае показал бы «соединение прервано».
    браузер2, изнанка2 = _sock.socketpair()
    wsproxy.проводить(изнанка2, {"Upgrade": "websocket"})
    браузер2.settimeout(5)
    check("без ключа — 400", b"400" in браузер2.recv(4096), True)
    браузер2.close()

    # Чужая страница к рулю не подходит. До мостика эту дорогу закрывал сам
    # браузер: с https обычный ws:// запрещён как смешанное содержимое. Мостик
    # её открывает, и закрыть обратно должны мы.
    for заголовки, ждём, имя in (
        ({"Host": "робот:8443"}, True, "свой скрипт без Origin"),
        ({"Host": "робот:8443", "Origin": "https://робот:8443"}, True, "своя страница"),
        ({"Host": "192.168.1.5:8443", "Origin": "http://зло.рф"}, False, "чужой сайт"),
        ({"Host": "192.168.1.5:8443", "Origin": "https://192.168.1.50:8443"},
         False, "похожий адрес"),
        ({"Host": "робот:8443", "Origin": "null"}, False, "страница из песочницы"),
    ):
        check(f"мостик: {имя}", wsproxy.свой(заголовки), ждём)

    браузер3, изнанка3 = _sock.socketpair()
    wsproxy.проводить(изнанка3, {"Upgrade": "websocket", "Host": "робот:8443",
                                 "Sec-WebSocket-Key": "0123456789abcdef0123==",
                                 "Origin": "http://зло.рф"})
    браузер3.settimeout(5)
    check("чужой странице — 403", b"403" in браузер3.recv(4096), True)
    браузер3.close()


def test_tls() -> None:
    """Бумаги для https. Ломается это тихо: микрофон с телефона отказывает.

    Всё здесь проверяется настоящим openssl. Если его в системе нет —
    проверять нечего, и честнее сказать это вслух, чем показать зелёное.
    """
    import os as _os
    import shutil as _sh
    import socket
    import subprocess
    import tempfile as _tmp

    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import tls

    section("сертификат для пульта")
    if _sh.which("openssl") is None:
        check("openssl в системе есть", False, True)
        return

    было_адреса, было_серт, было_ключ = tls.адреса, tls.СЕРТ, tls.КЛЮЧ
    дом = Path(_tmp.mkdtemp())
    try:
        tls.адреса = lambda: ["127.0.0.1", "192.168.1.55"]
        бумаги, беда = tls.выписать(дом)
        check("выписали без жалоб", (bool(бумаги), беда), (True, ""))
        check("адреса попали в бумагу", sorted(tls._san_из_сертификата()),
              ["127.0.0.1", "192.168.1.55"])
        check("ключ читаем только нами", oct(tls.КЛЮЧ.stat().st_mode)[-3:], "600")
        # Имя с «.local» — единственное, что переживает смену адреса. По нему
        # телефон находит робота в домашней сети сам, как находит принтер.
        # Без него ссылка на пульт умирает при каждом переезде.
        готово = subprocess.run(
            ["openssl", "x509", "-in", str(tls.СЕРТ), "-noout", "-ext",
             "subjectAltName"], capture_output=True, text=True, timeout=10)
        имя = socket.gethostname()
        check("в бумаге есть имя робота с .local",
              f"DNS:{имя}.local" in готово.stdout, True)
        check("и localhost — для ssh-туннеля",
              "DNS:localhost" in готово.stdout, True)

        # Новый адрес — начало старого. Подстрокой «192.168.1.5» находилась
        # внутри «192.168.1.55», бумага считалась годной, и браузер потом
        # ругался на несовпадение, а человек думал, что сломался пульт.
        tls.адреса = lambda: ["127.0.0.1", "192.168.1.5"]
        check("переезд на адрес-начало замечен",
              tls._годен(["127.0.0.1", "192.168.1.5"]), False)
        tls.выписать(дом)
        check("бумагу перевыписали", sorted(tls._san_из_сертификата()),
              ["127.0.0.1", "192.168.1.5"])

        # openssl пропал, а бумаги на месте: https поднимать есть чем.
        путь = _os.environ.get("PATH", "")
        _os.environ["PATH"] = str(дом / "нет-такого")
        try:
            бумаги2, беда2 = tls.выписать(дом)
            check("без openssl берём готовые бумаги",
                  (bool(бумаги2), беда2), (True, ""))
        finally:
            _os.environ["PATH"] = путь

        # openssl живой, но отказывает — человеку надо сказать, чем именно.
        # Раньше это объявлялось как «нет openssl», и он шёл ставить пакет,
        # который уже стоял.
        корзина = дом / "bin"
        корзина.mkdir()
        (корзина / "openssl").write_text(
            '#!/bin/sh\necho "req: Unrecognized flag addext" >&2\nexit 1\n')
        (корзина / "openssl").chmod(0o755)
        пусто = Path(_tmp.mkdtemp())
        _os.environ["PATH"] = str(корзина)
        try:
            бумаги3, беда3 = tls.выписать(пусто)
            check("отказ openssl назван своими словами",
                  (бумаги3, "Unrecognized flag" in беда3), (None, True))
        finally:
            _os.environ["PATH"] = путь
            _sh.rmtree(пусто, ignore_errors=True)
    finally:
        tls.адреса, tls.СЕРТ, tls.КЛЮЧ = было_адреса, было_серт, было_ключ
        _sh.rmtree(дом, ignore_errors=True)


def test_навыки() -> None:
    """То, чему робот научился сам, — и чего ему в этом нельзя.

    У робота два слоя понимания: правила разбирают фразу за двадцать пять
    миллисекунд, модель делает всё остальное за секунды. Оба умеют ровно то,
    что в них заложено, и между ними дыра: на непривычной просьбе модель
    выкрутится один раз, а на второй будет выкручиваться заново. Робот
    выполняет, но не научается.

    Навык — НЕ НОВЫЙ КОД, а сохранённая последовательность вызовов тех же
    инструментов. Отсюда главное свойство: навык не может ничего, чего робот
    не умеет одной командой, и все сторожа остаются на местах. Проверяется
    здесь в первую очередь именно это — что в навык нельзя положить лишнего.
    """
    section("навыки")
    from robot_voice import skills

    with tempfile.TemporaryDirectory() as дом:
        файл = Path(дом) / "навыки.json"
        н = skills.Навыки(файл)
        шаг = [{"инструмент": "route", "аргументы": {"steps": [], "name": "круг"}}]

        # --- что в навык класть нельзя ------------------------------------
        # Белый список, а не чёрный: новый инструмент по умолчанию НЕ попадает
        # в навыки, пока кто-то не подумал, что будет, если звать его вслепую
        # по десять раз.
        check("навык, создающий навыки, не берём",
              "переписывающий себя" in
              н.проверить([{"инструмент": "remember_skill", "аргументы": {}}]),
              True)
        check("стирающее без спроса не берём",
              "стирает без спроса" in
              н.проверить([{"инструмент": "notes_clear", "аргументы": {}}]),
              True)
        check("«стоп» внутри навыка бессмыслен",
              bool(н.проверить([{"инструмент": "stop", "аргументы": {}}])), True)
        check("незнакомый инструмент не берём",
              bool(н.проверить([{"инструмент": "выдумка", "аргументы": {}}])), True)
        check("а движение — берём", н.проверить(шаг), "")
        check("пустой навык не навык", bool(н.проверить([])), True)
        check("длиннее предела не берём",
              bool(н.проверить(шаг * (skills.ШАГОВ + 1))), True)

        # --- зацепки ------------------------------------------------------
        # «Иди» подошло бы к половине фраз в доме, и навык перехватывал бы
        # чужие команды — причём молча, потому что до модели дело бы просто
        # не дошло.
        check("однословной зацепки мало",
              bool(н.запомнить("круг", ["иди"], шаг)), True)
        check("а внятной — хватает",
              н.запомнить("обход квартиры",
                          ["обойди квартиру", "исследуй квартиру"], шаг), "")

        # --- поиск --------------------------------------------------------
        check("по своей фразе находится",
              (н.найти("исследуй квартиру") or {}) and
              н.найти("исследуй квартиру").имя, "обход квартиры")
        check("и внутри длинной фразы тоже",
              н.найти("Кузя, обойди квартиру пожалуйста").имя, "обход квартиры")
        check("а на чужую не откликается", н.найти("включи музыку"), None)
        # Границы слов обязательны: без них «дом» нашлось бы в «домофоне».
        н.запомнить("полив", ["полей цветы"], шаг)
        check("часть слова зацепкой не считается",
              н.найти("пополейте там что-нибудь"), None)

        # При нескольких подходящих берём ту зацепку, что длиннее: она точнее.
        н.запомнить("обход с рассказом", ["обойди квартиру и расскажи"], шаг)
        check("длинная зацепка точнее короткой",
              н.найти("обойди квартиру и расскажи").имя, "обход с рассказом")

        # --- переживает перезапуск ----------------------------------------
        снова = skills.Навыки(файл)
        check("навыки переживают перезапуск", len(снова.все), 3)
        check("и находятся после него",
              снова.найти("исследуй квартиру").имя, "обход квартиры")

        # Тем же именем — замена, а не двойник. Робот, у которого два «обхода
        # квартиры», выберет случайный, и человек не поймёт, почему сегодня
        # иначе.
        снова.запомнить("обход квартиры", ["обойди квартиру"], шаг)
        check("тем же именем — замена", len(снова.все), 3)

        # --- забывание ----------------------------------------------------
        check("забывается по имени", снова.забыть("полив"), "полив")
        # Именно по той фразе, которой навык зовут СЕЙЧАС: замена выше
        # оставила у «обхода квартиры» одну зацепку из двух, и старая
        # больше не его.
        check("и по фразе, которой звали",
              снова.забыть("обойди квартиру"), "обход квартиры")
        check("несуществующий не забывается", снова.забыть("ерунда"), None)

        # --- счёт срывов ---------------------------------------------------
        # Один срыв — случайность (человек передумал), два — совпадение, три
        # — навык плохой. Робот сам предложит его забыть: иначе плохой навык
        # живёт вечно и незаметно.
        третий = skills.Навыки(Path(дом) / "ещё.json")
        третий.запомнить("проба", ["сделай пробу"], шаг)
        навык = третий.все[0]
        check("первый срыв терпим", третий.отметить(навык, True), False)
        check("второй тоже", третий.отметить(навык, True), False)
        check("на третьем предлагаем забыть", третий.отметить(навык, True), True)
        check("удачный вызов счёт обнуляет",
              третий.отметить(навык, False) or навык.сбоев, 0)
        check("а число вызовов растёт", навык.звали, 4)


def test_навык_целиком() -> None:
    """Выученное умение доезжает до колёс — вся цепочка, а не только склад.

    Хранилище проверено отдельно (test_навыки). Здесь другое: узнаётся ли
    фраза, зовутся ли настоящие инструменты, обрывается ли умение на «стоп»
    и считается ли срыв. Между складом и колёсами четыре стыка, и каждый из
    них — место, где всё выглядит исправным и не работает.
    """
    section("навык доезжает до колёс")
    import types

    from robot_voice import skills
    from robot_voice.app import навык_на_фразу

    with tempfile.TemporaryDirectory() as дом:
        н = skills.Навыки(Path(дом) / "н.json")
        н.запомнить("обход комнаты",
                    ["обойди комнату", "исследуй комнату"],
                    [{"инструмент": "route",
                      "аргументы": {"steps": [{"move": "вперёд"}], "name": "круг"}},
                     {"инструмент": "look_around", "аргументы": {}}])

        позвали: list[tuple] = []
        сказано: list[str] = []

        class Поддельный:
            def __init__(self, имя): self.name = имя; self.input_schema = {}
            def __call__(self, доводы):
                позвали.append((self.name, доводы))
                return f"сделал {self.name}"

        by_name = {и: Поддельный(и) for и in ("route", "look_around")}
        голос = types.SimpleNamespace(
            say=lambda ф, **k: сказано.append(ф),
            listener=types.SimpleNamespace(unheard=lambda: b""))

        # --- чужая фраза умение не будит --------------------------------
        check("на чужую фразу умение молчит",
              навык_на_фразу(н, "включи музыку", by_name, голос), False)
        check("и инструментов не звало", позвали, [])

        # --- своя фраза выполняется целиком ------------------------------
        check("своя фраза узнана",
              навык_на_фразу(н, "Кузя, обойди комнату", by_name, голос), True)
        check("оба шага выполнены", [и for и, _ in позвали],
              ["route", "look_around"])
        check("и доводы шага доехали",
              позвали[0][1]["name"], "круг")
        check("робот отчитался за каждый шаг", len(сказано), 2)
        check("вызов засчитан", н.все[0].звали, 1)
        check("и срывом не считается", н.все[0].сбоев, 0)

        # --- «стоп» между шагами обрывает --------------------------------
        # Шаги — это те же поездки, и между ними человек должен успеть
        # сказать «стоп». Иначе выученное умение становится единственным
        # местом, где робота нельзя остановить голосом.
        позвали.clear()
        сказано.clear()
        стоп_голос = types.SimpleNamespace(
            say=lambda ф, **k: сказано.append(ф),
            listener=types.SimpleNamespace(unheard=lambda: b"RIFF....wav"))
        шасси = types.SimpleNamespace(moving=True, stop_motion=lambda: None)
        слух = types.SimpleNamespace(transcribe=lambda wav: "стоп")
        check("умение выполнено... точнее, начато",
              навык_на_фразу(н, "исследуй комнату", by_name, стоп_голос,
                             recognizer=слух, ros=шасси), True)
        check("но оборвалось на первом же шаге",
              [и for и, _ in позвали], ["route"])
        check("и срыв записан", н.все[0].сбоев, 1)

        # --- три срыва подряд — робот сам об этом говорит ----------------
        # Иначе плохое умение живёт вечно и незаметно: это ровно тот род
        # тихой поломки, из-за которого робот однажды перестаёт слушаться и
        # никто не знает почему.
        сказано.clear()
        навык_на_фразу(н, "исследуй комнату", by_name, стоп_голос,
                       recognizer=слух, ros=шасси)
        навык_на_фразу(н, "исследуй комнату", by_name, стоп_голос,
                       recognizer=слух, ros=шасси)
        check("на третьем срыве робот предлагает забыть",
              any("забудь" in ф.lower() for ф in сказано), True)
        check("но сам не забывает — решает человек", len(н.все), 1)

        # --- пропавший инструмент не роняет робота -----------------------
        # Между версиями инструмент может исчезнуть, и умение, собранное на
        # старой, начнёт звать пустоту.
        н2 = skills.Навыки(Path(дом) / "н2.json")
        н2.запомнить("древнее", ["сделай древнее"],
                     [{"инструмент": "drive", "аргументы": {}}])
        check("умение с пропавшим инструментом не падает",
              навык_на_фразу(н2, "сделай древнее", {}, голос), True)
        check("и считается сорвавшимся", н2.все[0].сбоев, 1)


def test_детектор_не_отбирает_порт() -> None:
    """Детектор людей больше не отбирает у пульта порт 8000.

    Штатный mono2d_body_detection.launch.py поднимает пять узлов, и пятый —
    websocket.launch.py, а тот запускает NGINX НА ПОРТУ 8000. На 8000 живёт
    пульт.

    В комментариях к нашим скриптам было записано «безвредно, просто заливает
    вывод красным». Неправда, и дорогая. Пока детектор запускали руками на
    минуту, беда не показывалась. А когда его включили службой навсегда:
    nginx занял порт раньше пульта (robot-body стартует Before=robot-web),
    пульт не смог подняться, ушёл в вечный перезапуск, и в браузере отвечал
    чужой «404 Not Found, nginx/1.22.0». Снаружи это выглядит как «пульт
    сломался», и человек идёт чинить пульт, который цел.

    Хуже: nginx ДЕМОНИЗИРУЕТСЯ. Он не потомок службы, `systemctl stop
    robot-body` его не убивает, и он переживает и остановку детектора, и
    перезапуск пульта.
    """
    section("детектор не отбирает порт у пульта")
    корень = Path(__file__).resolve().parent.parent

    наш = (корень / "scripts" / "mono2d_no_web.launch.py").read_text(
        encoding="utf-8")
    check("свой launch есть", bool(наш), True)
    # Смотрим на КОД, а не на объяснения: в шапке этого файла и websocket, и
    # CAM_TYPE упоминаются нарочно — там написано, почему их там нет.
    код = "\n".join(с for с in наш.splitlines()
                    if not с.lstrip().startswith("#"))
    check("странички просмотра в нём нет", "websocket" in код, False)
    for пакет in ("hobot_shm", "hobot_usb_cam", "hobot_codec",
                  "mono2d_body_detection"):
        check(f"а {пакет} — есть", пакет in код, True)
    # Камера задана явно. У них при незаданной CAM_TYPE молча выбирается mipi,
    # то есть камера, которой у нас нет, — и детектор видел бы черноту.
    check("камера выбрана явно, а не по CAM_TYPE", "CAM_TYPE" in код, False)

    for имя in ("body_service.sh", "body_detect.sh"):
        текст = (корень / "scripts" / имя).read_text(encoding="utf-8")
        check(f"{имя} зовёт свой launch",
              "mono2d_no_web.launch.py" in текст, True)
        # Их launch не должен запускаться ниоткуда: строка запуска именно с
        # именем пакета — это ровно та беда.
        check(f"{имя} не зовёт их",
              "launch mono2d_body_detection mono2d_body_detection" in текст,
              False)

    # --- пульт говорит, кто занял порт ------------------------------------
    # Молча падать с кодом 1 нельзя: systemd перезапустит, счётчик накрутится,
    # а человек будет смотреть на чужой 404 и чинить целый пульт.
    sys.path.insert(0, str(корень / "web"))
    import server as сервер

    живая = ('LISTEN 0 511 0.0.0.0:8000 0.0.0.0:* '
             'users:(("nginx",pid=20193,fd=5),("nginx",pid=20192,fd=5))')
    check("виновник назван по имени и pid",
          сервер.разобрать_ss(живая, 8000), "nginx (pid 20193), nginx (pid 20192)")
    check("чужой порт не приписываем", сервер.разобрать_ss(живая, 8080), "")
    check("и на мусоре не падаем", сервер.разобрать_ss("ерунда", 8000), "")


def test_карта_на_пульте() -> None:
    """Карту, которую робот держит в памяти, видно на пульте.

    Дальномер показывает восемь колонок ПРЯМО СЕЙЧАС и только вперёд. Карта —
    всё, что робот видел за последние полминуты, сведённое по одометрии:
    включая то, что уже за спиной. Именно по ней он решает, можно ли сдать
    назад и есть ли место развернуться. Посмотреть на неё было нельзя ничем:
    она жила в памяти службы и наружу не выходила.

    Едет она тем же путём, что и сетка дальномера, — через файл. Пульт живёт
    в другом процессе, в память робота ему не залезть, а заводить ради
    картинки ещё один сетевой канал значит завести ещё один способ всё
    сломать. Отсюда и главная проверка этого файла: РОБОТ И ПУЛЬТ ОБЯЗАНЫ
    ПОНИМАТЬ ЕГО ОДИНАКОВО. Файл общий, а код разный — они друг друга не
    импортируют.
    """
    section("карта на пульте")
    import re

    from robot_voice import mapping

    карта = mapping.Карта()

    # --- сжатие и разжатие ------------------------------------------------
    # Клеток сто двадцать на сто двадцать. Списком чисел это тридцать пять
    # килобайт JSON на кадр — и дело не в сети, а в том, что плата тратила бы
    # на сборку этой строки больше, чем на саму карту.
    def разжать(строка: str, сколько: int) -> list[int]:
        """То же, что делает пульт. Здесь — чтобы сверить с ним побайтно."""
        клетки: list[int] = []
        for счёт, знак in re.findall(r"(\d+)(.)", строка):
            код = 1 if знак == "#" else (-1 if знак == "." else 0)
            клетки.extend([код] * int(счёт))
        return клетки[:сколько]

    пустая = карта.для_пульта()
    check("пустая карта сжимается в один кусок", пустая["клетки"], "14400 ")
    check("и разжимается обратно в пустоту",
          set(разжать(пустая["клетки"], 14400)), {0})

    # Настоящая карта: стена в метре впереди.
    сетка = [[0.0] * 8 for _ in range(8)]
    for р in mapping.РЯДЫ:
        for к in range(8):
            сетка[р][к] = 1.0
    # Несколько кадров, а не один: клетка становится занятой не с первого
    # замера — в этом весь смысл лог-шансов. Одиночное «занято» не должно
    # рисовать стену, которой нет.
    for _ in range(5):
        карта.добавить(сетка, (0.0, 0.0, 0.0))

    полная = карта.для_пульта()
    было = карта.картинка()["клетки"]
    стало = разжать(полная["клетки"], len(было))
    check("сжатая карта совпадает с несжатой до клетки", стало, было)
    check("и весит на порядок меньше",
          len(полная["клетки"]) * 10 < len(str(было)), True)
    check("занятые клетки в ней есть", 1 in стало, True)
    check("и свободные тоже", -1 in стало, True)

    # Поза нужна ОБЯЗАТЕЛЬНО: без курса карта бесполезна — по ней не понять,
    # что значит «впереди».
    check("поза робота отдаётся", полная["поза"], [0.0, 0.0, 0.0])
    check("и габарит, чтобы нарисовать его в масштабе",
          полная["радиус"], mapping.РАДИУС_КОРПУСА)

    # --- файл: робот пишет, сервер читает ---------------------------------
    with tempfile.TemporaryDirectory() as дом:
        файл = Path(дом) / "map.json"
        check("карта выложилась", карта.выложить(файл, не_чаще=0.0), True)
        данные = json.loads(файл.read_text())
        check("в файле есть отметка времени", "когда" in данные, True)
        check("и клетки", данные["клетки"], полная["клетки"])

        # Чаще, чем просили, не пишем: четырнадцать тысяч клеток три раза в
        # секунду — это ровно тот случай, когда карточку стирают ради того,
        # что живёт полсекунды.
        check("второй раз подряд не пишем",
              карта.выложить(файл, не_чаще=60.0), False)

    # --- робот и сервер сходятся на файле ---------------------------------
    # Файл общий, а код разный: web/ и robot_voice/ друг друга не импортируют.
    # Разъедься эти две строки — и пульт молча показывал бы пустоту, а робот
    # так же молча писал бы в никуда.
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import server as сервер

    check("робот и сервер пишут-читают один файл",
          сервер.КАРТА_ФАЙЛ, mapping.ФАЙЛ_КАРТЫ)
    check("и это память, а не карточка",
          mapping.ФАЙЛ_КАРТЫ.startswith("/run/"), True)
    # Старую карту сервер обязан отвергнуть. Нарисованная комната, которой
    # уже нет, хуже пустого места: человек ей поверит.
    check("сервер знает, когда карта протухла", сервер.КАРТА_СТАРЕЕТ > 0, True)

    # --- пульт понимает те же поля ----------------------------------------
    # Сервер умеет, а страница нет — этот класс ошибок в проекте уже стоил
    # вечера. Проверка дешёвая: все поля, которые отдаёт робот, страница
    # обязана знать по имени.
    страница = (Path(__file__).resolve().parent.parent
                / "web" / "pult.html").read_text(encoding="utf-8")
    for поле in ("клетки", "клеток", "клетка", "поза", "угол", "радиус"):
        check(f"пульт читает поле «{поле}»", f".{поле}" in страница, True)
    check("пульт ходит за картой", "'/map'" in страница, True)
    check("и рисует три состояния, а не два",
          страница.count("не знаю") + страница.count("не смотрел") > 0, True)


def test_пульт_не_быстрее_тормозов() -> None:
    """Ползунок пульта не разгоняет робота быстрее, чем тот умеет тормозить.

    Пульт публикует в /cmd_vel НАПРЯМУЮ, минуя оба сторожа: и тот, что смотрит
    в дальномер на ходу вперёд, и тот, что судит слепые направления по карте.
    Это сделано намеренно и правильно — иначе не работала бы кнопка СТОП, —
    но означает, что скорость с пульта ничем, кроме самого ползунка, не
    ограничена.

    А ползунок давал 0.80 м/с. Число ниоткуда и вчетверо больше того, с какой
    скоростью робот ездит сам. По собственным постоянным проекта: время
    реакции цепочки 0.4 с, замедление 0.8 м/с² — на 0.8 м/с это 0.32 м за
    время реакции плюс 0.40 м торможения, итого 0.72 м. Порог, на котором
    сторож кричит «стоп», — 0.35 м. То есть с пульта робота можно было
    разогнать вдвое быстрее, чем он способен остановиться.
    """
    section("пульт не быстрее тормозов")
    import re

    from robot_voice import follow, tof

    страница = (Path(__file__).resolve().parent.parent
                / "web" / "pult.html").read_text(encoding="utf-8")

    ползунок = re.search(r'id="lim"[^>]*max="(\d+)"', страница)
    check("ползунок в пульте найден", ползунок is not None, True)
    потолок = int(ползунок.group(1)) / 100 if ползунок else 9.9
    check("и не выше того, что робот держит для себя",
          потолок <= follow.СКОРОСТЬ_ПОТОЛОК + 1e-9, True)

    # И то же самое из физики, а не из совпадения двух чисел: тормозной путь
    # на этой скорости обязан помещаться в порог, на котором сторож кричит
    # «стоп». Иначе робот физически не успевает.
    путь = (потолок * follow.ЗАДЕРЖКА_РЕАКЦИИ
            + потолок * потолок / (2 * follow.ЗАМЕДЛЕНИЕ))
    check(f"тормозной путь {путь:.2f} м помещается в поле зрения",
          путь <= tof.ПРЕДЕЛ_ДАЛЬНОСТИ, True)
    # Строгую проверку «влезает в СТОП_БЛИЖЕ» не ставим и говорим почему:
    # на пульте человек смотрит на робота сам и тормозит глазами, а сторож
    # для этого пути и не задуман. Задуман предел, который не даёт разогнать
    # робота вдвое быстрее его тормозов, — и он теперь есть.


def test_pult_and_server_agree() -> None:
    """Сервер умеет, а страница нет — этот класс ошибок стоил целого вечера.

    Радио тогда не заиграло трижды подряд: сервер уже знал про поток, пульт
    ещё нет; потом браузер держал вчерашнюю страницу; потом кодек оказался не
    тот. Проверка дешёвая: все события, которые сервер рассылает, должны
    разбираться в пульте, а все адреса, куда стучится пульт, — существовать
    на сервере.
    """
    import re as _re

    section("пульт и сервер договорились")
    web = Path(__file__).resolve().parent.parent / "web"
    сервер = (web / "server.py").read_text(encoding="utf-8")
    пульт = (web / "pult.html").read_text(encoding="utf-8")

    события = set(_re.findall(r"SPEECH\.broadcast\(\{\"([^\"]+)\"", сервер))
    незнакомые = sorted(k for k in события
                        if f"data.{k}" not in пульт and f"data['{k}']" not in пульт)
    check("каждое событие сервера разбирается пультом", незнакомые, [])

    адреса = set(_re.findall(r"fetch\('(/[a-z/]+)'", пульт))
    несуществующие = sorted(a for a in адреса if f'"{a}"' not in сервер)
    check("каждый адрес пульта есть на сервере", несуществующие, [])


def test_chain() -> None:
    """Составные команды движения — правилами, а не моделью.

    На живом роботе «метр вперёд и метр назад» ушло домашней модели, и та
    ответила «Приехал вперёд. Теперь назад. Готов к следующему!», не позвав ни
    одного инструмента. Робот не сдвинулся, а человек услышал отчёт о двух
    поездках. Составные команды моделям такого размера не даются, поэтому
    разбираем их сами.
    """
    from robot_voice.intents import ДВИЖЕНИЕ, parse_chain, просят_ехать

    section("цепочки движений")

    цепь = parse_chain("Метр вперёд и метр назад.")
    check("«метр вперёд и метр назад» разобрано в два движения",
          [(m.tool, m.args) for m in цепь or []],
          [("drive", {"direction": "вперёд", "distance": 1.0}),
           ("drive", {"direction": "назад", "distance": 1.0})])

    # «Направо» у робота на меканум-колёсах — это движение боком, а не
    # разворот: так же понимает его и одиночное правило.
    цепь = parse_chain("проедь вперёд на два метра, потом направо")
    check("«вперёд на два метра, потом направо» — тоже цепочка",
          [(m.tool, m.args) for m in цепь or []],
          [("drive", {"direction": "вперёд", "distance": 2.0}),
           ("drive", {"direction": "вправо"})])

    цепь = parse_chain("развернись и метр вперёд")
    check("разворот с поездкой в одной фразе",
          [(m.tool, m.args) for m in цепь or []],
          [("turn", {"direction": "влево", "degrees": 180.0}),
           ("drive", {"direction": "вперёд", "distance": 1.0})])

    # Самое важное: цепочкой считаем ТОЛЬКО движения. Иначе длительность
    # таймера «два часа и тридцать минут» развалилась бы на два таймера.
    check("таймер с «и» внутри цепочкой не считается",
          parse_chain("поставь таймер на 2 часа и 30 минут"), None)
    check("разговор с «и» внутри цепочкой не считается",
          parse_chain("расскажи про кошек и собак"), None)
    check("одиночная команда — не цепочка", parse_chain("вперёд"), None)

    # --- «стоп» между шагами цепочки --------------------------------------
    # Второй шаг ждёт, пока доедет первый, и ждёт он В ГЛАВНОМ ПОТОКЕ:
    # Ros._пустить делает join на предыдущем движении. Замерено 3.6 секунды на
    # «метр вперёд и метр назад». Всё это время генератор фраз не крутится, и
    # «стоп» обычным путём не проходит — мгновенный слой идёт через тот же
    # генератор, а перебивание живёт только пока робот говорит.
    #
    # Хуже: пропущенный «стоп» не опаздывал, а УНИЧТОЖАЛСЯ. Следующая реплика
    # вызывает unmute, а тот выбрасывает всё накопленное — вместе с криком,
    # ради которого тридцатисекундный хвост и заведён.
    from robot_voice.app import _run_direct

    сказанное: list[str] = []
    остановлен: list[str] = []
    голос = types.SimpleNamespace(
        say=lambda ф, **k: сказанное.append(ф),
        # Байтовый литерал — только ASCII: кириллица в нём не компилируется.
        listener=types.SimpleNamespace(unheard=lambda: b"RIFF....wav"))
    шасси = types.SimpleNamespace(moving=True,
                                  stop_motion=lambda: остановлен.append("стоп"))
    слух = types.SimpleNamespace(transcribe=lambda wav: "стоп")

    class Инструмент:
        name = "drive"
        input_schema: dict = {}

        def __call__(self, args):
            return "Еду вперёд."

    прервали = _run_direct(Инструмент(), {"direction": "вперёд"}, голос,
                           recognizer=слух, ros=шасси)
    check("«стоп» между шагами услышан", прервали, True)
    check("и колёса остановлены", остановлен, ["стоп"])
    check("и робот об этом сказал",
          any("останов" in ф.lower() for ф in сказанное), True)

    # Зеркально: тишина в хвосте цепочку не рвёт и распознавания не стоит.
    считали: list[bytes] = []
    тихий = types.SimpleNamespace(
        say=lambda ф, **k: None,
        listener=types.SimpleNamespace(unheard=lambda: b""))
    молчун = types.SimpleNamespace(
        transcribe=lambda wav: считали.append(wav) or "стоп")
    check("на тишине цепочка идёт дальше",
          _run_direct(Инструмент(), {"direction": "вперёд"}, тихий,
                      recognizer=молчун, ros=шасси), False)
    check("и распознавание за тишину не платим", считали, [])

    # И без слуха тоже работает как раньше: правило может звать инструмент и
    # там, где ни распознавателя, ни шасси нет.
    check("без слуха ничего не ломается",
          _run_direct(Инструмент(), {"direction": "вперёд"}, тихий), False)

    # Расстояние впереди направления: так говорят не реже, а правило этого
    # не знало, и фраза уходила модели.
    check("«метр вперёд» разбирается и в одиночку",
          (parse("метр вперёд").tool, parse("метр вперёд").args),
          ("drive", {"direction": "вперёд", "distance": 1.0}))
    check("«полметра назад» тоже",
          parse("полметра назад").args,
          {"direction": "назад", "distance": 0.5})
    check("«два метра влево» тоже",
          parse("два метра влево").args,
          {"direction": "влево", "distance": 2.0})

    # Круги. «Сделай два круга» отвечало «Два круга сделано» — и не крутилось.
    check("«сделай два круга вокруг себя» — это 720 градусов",
          parse("сделай два круга вокруг себя").args.get("degrees"), 720.0)
    check("«круг» без числа — один оборот",
          parse("сделай круг").args.get("degrees"), 360.0)

    # Признак «требуют ехать»: по нему ответ придерживается до конца хода,
    # чтобы враньё про поездку не прозвучало вслух.
    check("«поезжай вперёд» — требование ехать",
          просят_ехать("поезжай вперёд"), True)
    check("«развернись» — тоже", просят_ехать("Кузя, развернись"), True)
    check("«два дня назад» — не требование ехать",
          просят_ехать("это было два дня назад"), False)
    check("«что там впереди» — не требование ехать",
          просят_ехать("а что там впереди"), False)

    # route входит в движение наравне с drive: по этому списку решается, поехал
    # робот на самом деле или только рассказал о поездке. Забыть его тут —
    # значит на «проедь зигзагом» получить «Не понял, куда ехать» поверх уже
    # начавшейся поездки.
    # --- робот не должен говорить, что едет, если он не едет ---------------
    # Живой случай: рядом работал телевизор, оттуда прозвучало «Преследование.
    # Нет никакого смысла плакать. Пришла пора действовать», разговорное окно
    # было открыто — и робот ответил «Понял, иду за тобой». Никуда он не пошёл:
    # имени не звучало, и сторож движения инструмент бы не пустил.
    #
    # Прежняя проверка это пропускала, потому что смотрела на ПРОСЬБУ: ехать
    # никто не просил, сверять нечего. А соврал робот всё равно — про то, что
    # якобы едет за человеком по квартире.
    from robot_voice.intents import ПОЕХАЛ, обещает_движение

    for обещание in ("Понял, иду за тобой.", "Следую за тобой.",
                     "Еду вперёд на метр.", "Приехал.", "Разворачиваюсь."):
        check(f"«{обещание}» — обещание ехать", обещает_движение(обещание), True)
    for мирное in ("Больше не иду.", "Я умею ездить по квартире.",
                   "Волны — когда колёса крутятся.", "Хорошая погода."):
        check(f"«{мирное}» — не обещание", обещает_движение(мирное), False)

    # Следование считается движением при проверке «а поехал ли», но НЕ входит
    # в ДВИЖЕНИЕ. Разница принципиальная: ДВИЖЕНИЕ даёт освобождение от имени в
    # открытом разговоре, и запись туда следования означала бы, что робот
    # пойдёт за любым, кто скажет «за мной». Включая телевизор — он уже один
    # раз за ним пошёл.
    check("следование считается поездкой", "follow_me" in ПОЕХАЛ, True)
    check("но имени не отменяет", "follow_me" in ДВИЖЕНИЕ, False)

    check("движение — это drive, turn, stop и route", sorted(ДВИЖЕНИЕ),
          ["drive", "route", "stop", "turn"])
    from robot_voice.intents import ЦЕПОЧКОЙ
    check("а цепочкой правил route не собирается", "route" in ЦЕПОЧКОЙ, False)


def test_stop_stops_everything() -> None:
    """«Стоп» и «хватит» — это «прекрати всё», а не только тормоз колёс.

    С живого робота: под играющую песню человек сказал «Кузя, стоп», услышал
    «Я и так стою» — и музыка продолжила играть. Пришлось отдельной фразой
    просить выключить её. Слово «стоп» человек говорит, когда хочет тишины
    целиком, и разбирать его на составляющие должен робот, а не человек.
    """
    section("«стоп» прекращает всё")
    store = Path(tempfile.mkdtemp())
    timers = Timers(announce=lambda text, **kw: None, store=store / "t.json")

    def собрать(едет: bool, играет: bool):
        выключено = []
        ros = types.SimpleNamespace(
            voltage=12.4, moving=едет, busy=едет, connected=True,
            drive=lambda *a, **k: None, stop_motion=lambda: None)
        player = types.SimpleNamespace(
            играет=играет,
            выключить=lambda: выключено.append(True) or "Выключил.")
        tools = {t.name: t for t in build_tools(ros, timers, player=player)}
        return tools["stop"].run(), выключено

    ответ, выключено = собрать(едет=True, играет=True)
    check("ехал и играло — встали и замолчали", bool(выключено), True)
    check("и сказано про оба", ответ, "Остановился, музыку выключил.")

    ответ, выключено = собрать(едет=False, играет=True)
    check("стоял, но играло — музыку выключили", bool(выключено), True)
    check("коротко", ответ, "Выключил.")

    ответ, выключено = собрать(едет=True, играет=False)
    check("ехал без музыки — про музыку молчим", bool(выключено), False)
    check("обычный ответ", ответ, "Остановился.")

    ответ, выключено = собрать(едет=False, играет=False)
    check("нечего прекращать", ответ, "Я и так стою.")
    check("и музыку не трогали", bool(выключено), False)


def test_instant_ignores_stale() -> None:
    """Мгновенный приказ не должен зависеть от прошлой фразы.

    Уверенность, говорящий и метка слепка пишутся только внутри transcribe, а
    мгновенный приказ его не зовёт. Без явного обнуления там оставалась
    предыдущая фраза: шум с уверенностью −1.4 отбрасывался, поле оставалось
    −1.4, и следующий за ним «Кузя, стоп» выбрасывался как мусор — при едущем
    роботе. Проверяем по исходнику: сценарий целиком не воспроизвести, а
    молчаливый откат этой правки стоит слишком дорого.
    """
    section("мгновенный приказ не берёт чужое")
    исходник = (Path(__file__).resolve().parent
                / "robot_voice" / "app.py").read_text(encoding="utf-8")

    check("мгновенный путь помечен отдельно",
          "мгновенный = bool(getattr(listener" in исходник, True)
    check("уверенность на нём не берётся",
          "sure = None if мгновенный else" in исходник, True)
    check("говорящий тоже",
          'who = "" if мгновенный else' in исходник, True)
    check("и метка слепка",
          'метка = "" if мгновенный else' in исходник, True)

    # Отмена и прощание звучат по имени, когда разговор уже остыл. awake
    # считается ДО разбора обращения и в этот момент всегда ложен, поэтому
    # девяностосекундное окно отмены на деле равнялось десяти секундам.
    check("отмена работает и по имени",
          "(awake or по_имени) and undo.take" in исходник, True)
    check("прощание тоже",
          "(awake or по_имени) and _is_sleep_word" in исходник, True)


def test_sentence_cap() -> None:
    """Робот не должен говорить дольше, чем нужно.

    Промпт просит одну-две фразы, но четырёхмиллиардная модель запреты держит
    плохо: на живом роботе «Кузя, ты тут?» получило три реплики подряд, а из
    тринадцати ответов за вечер девять кончались вопросом «а что дальше?».
    Цена не только в занудстве — пока робот договаривает, микрофон заглушён, и
    сказанное человеком в этот момент выбрасывается.
    """
    section("робот не заговаривается")
    import contextlib as _c

    from robot_voice.app import _respond

    contextlib_nullcontext = _c.nullcontext

    сказано: list[str] = []

    class Речь:
        def feed(self, s): сказано.append(s)
        def close(self): return 1

    class Голос:
        speaker = types.SimpleNamespace(stream=lambda **kw: Речь(), last_said="")
        def say(self, t, **kw): сказано.append(t); return 1
        def hold(self): return contextlib_nullcontext()
        def quiet(self): return contextlib_nullcontext()
        def status(self, t): pass

    class Мозг:
        позвал: list = []
        last_talk = 0.0

        def reply(self, команда, on_text, smart=False):
            for кусок in ("Привет! ", "Готов помочь! ", "Что хочешь сейчас? "):
                on_text(кусок)
            return "Привет! Готов помочь! Что хочешь сейчас?"

    _respond("привет", Мозг(), Голос(), предел_фраз=2)
    check("сказано ровно две фразы", len(сказано), 2)
    check("и это первые две", сказано[0].strip(), "Привет!")
    check("третья не прозвучала",
          any("хочешь сейчас" in ф for ф in сказано), False)

    сказано.clear()
    _respond("привет", Мозг(), Голос(), предел_фраз=1)
    check("предел в одну фразу тоже держится", len(сказано), 1)


def test_silence_when_not_mine() -> None:
    """Чужая речь получает молчание, а не «ты говоришь не со мной».

    С живого робота: в открытом разговоре он услышал чужую беседу, сходил в
    облако за семнадцать тысяч токенов и объявил вслух «Похоже, ты говоришь не
    со мной». То есть влез в разговор, которого не касался, да ещё и за деньги.
    Молчание тут — единственный верный ответ, и модели нужно слово, которым
    его попросить.
    """
    section("не мне — молчу")
    import contextlib as _c

    from robot_voice.app import _respond
    from robot_voice.config import МИМО

    check("модель знает, чем промолчать", МИМО in SYSTEM_PROMPT, True)
    # И про болтливость. С живого робота, вечер с ребёнком: на каждую фразу
    # робот отвечал двумя, и вторая была пустой — «Всё в порядке!»,
    # «Дружим!», «Что хочешь сказать?». Человек слушает это молча, с
    # заглушённым микрофоном, и перебить не может.
    check("промпт требует одной фразы", "ОДНА фраза" in SYSTEM_PROMPT, True)
    check("и называет пустые концовки по именам",
          "Чем ещё помочь" in SYSTEM_PROMPT, True)
    check("и что вслух это говорить нельзя",
          "Молчание — тоже ответ" in SYSTEM_PROMPT, True)

    сказано: list[str] = []

    class Речь:
        def feed(self, ф): сказано.append(ф)
        def close(self): return 1

    class Голос:
        speaker = types.SimpleNamespace(stream=lambda **kw: Речь(), last_said="")
        def say(self, т, **kw): сказано.append(т); return 1
        def hold(self): return _c.nullcontext()
        def quiet(self): return _c.nullcontext()
        def status(self, т): pass

    class Мозг:
        позвал: list = []
        last_talk = 0.0
        ответ = МИМО

        def reply(self, команда, вслух, smart=False):
            вслух(self.ответ + " ")
            return self.ответ

    мозг = Мозг()
    _respond("что там по агентам и функционалу", мозг, Голос())
    check("вслух не сказано ничего", сказано, [])

    сказано.clear()
    мозг.ответ = "Привет."
    _respond("кузя привет", мозг, Голос())
    check("а обычный ответ звучит", [ф.strip() for ф in сказано], ["Привет."])


def test_no_narration() -> None:
    """Робот не отчитывается о том, чего не сделал.

    Проверяем два независимых заслона. Первый — в постоянной части промпта не
    должно быть готовых фраз об исполненном действии: как только там появились
    «Приехал», «Готово», «Развернулся» в качестве примеров живой речи, модель
    стала произносить их ВМЕСТО вызова инструмента. Второй — сам код: ответ на
    команду движения придерживается, пока не станет видно, позван ли drive.
    """
    section("никакой отчётности вместо дела")

    for фраза in ("«Приехал»", "«Развернулся»", "«Готово»"):
        check(f"в промпте нет готового отчёта {фраза}",
              фраза in SYSTEM_PROMPT, False)
    check("в промпте сказано, что слова не заменяют инструмент",
          "соврать" in SYSTEM_PROMPT, True)
    check("и что на два действия зовут два инструмента",
          "два инструмента" in SYSTEM_PROMPT, True)

    источник = (Path(__file__).resolve().parent
                / "robot_voice" / "app.py").read_text(encoding="utf-8")
    check("ответ на команду движения придерживается",
          "intents.просят_ехать(command)" in источник, True)
    check("и проверяется, позван ли инструмент движения",
          "brain.позвал" in источник, True)
    # То же и с музыкой. С живого робота: «Кузя, включи музыку» приехало как
    # «Друзья, включи музыку», правило из-за лишнего слова не сработало, фраза
    # ушла модели — и та ответила «Включаю музыку на твой вкус», не позвав ни
    # одного инструмента. Тишина, а человек уверен, что играет.
    check("ответ про музыку тоже придерживается",
          "intents.просят_музыку(command)" in источник, True)
    check("и проверяется, позван ли инструмент музыки",
          "intents.МУЗЫКА" in источник, True)


def test_one_voice() -> None:
    """Голос не должен меняться от фразы к фразе.

    Кэш готовых фраз назывался тем голосом, что записан в настройках робота, а
    выбирается голос на ПК ключом --voice. После смены голоса на ПК заготовки
    («Да?», «Не расслышал.») продолжали звучать прежним голосом, а всё
    остальное — новым: человек слышал, как посреди разговора прорезается
    чужой голос, и понять причину было нельзя.
    """
    import io as _io
    import wave as _wave

    from robot_voice.tts import PC_DOWN, PC_DOWN_FIRST, RemoteVoice

    section("один голос на весь разговор")

    def wav(байт: int = 480) -> bytes:
        буфер = _io.BytesIO()
        with _wave.open(буфер, "wb") as w:
            w.setnchannels(1)
            w.setsampwidth(2)
            w.setframerate(24000)
            w.writeframes(b"\0" * байт)
        return буфер.getvalue()

    class Ответ:
        def __init__(self, голос: str) -> None:
            self.headers = {"X-Voice": голос}
            self._тело = wav()

        def read(self) -> bytes:
            return self._тело

        def __enter__(self):
            return self

        def __exit__(self, *_a):
            return False

    class Здоровье:
        def __init__(self, голос: str) -> None:
            self._тело = json.dumps({"голос_чей": голос}).encode()

        def read(self) -> bytes:
            return self._тело

        def __enter__(self):
            return self

        def __exit__(self, *_a):
            return False

    with tempfile.TemporaryDirectory() as tmp:
        кэш = PhraseCache(Path(tmp), "пк-неизвестно")
        пк = RemoteVoice("http://пк", "", кэш)
        голос = {"чей": "eugene"}

        def запрос(req, timeout=0):
            адрес = req if isinstance(req, str) else req.full_url
            return (Здоровье(голос["чей"]) if адрес.endswith("/health")
                    else Ответ(голос["чей"]))

        старый = tts_urlopen(запрос)
        try:
            первый = пк.raw("Да?")
            check("голос ПК узнан", пк.голос, "eugene")
            check("кэш назван по нему", кэш.voice, "пк-eugene")
            check("звук получен", bool(первый), True)
            check("и лёг в кэш", кэш.get("Да?") == первый, True)

            # Меняем голос на ПК — так делает человек, перезапуская сервер с
            # другим --voice. Заготовка старого голоса всплыть не должна, даже
            # если эта фраза давно лежит в кэше и до ПК не доходит.
            голос["чей"] = "aidar"
            пк._голос_в = 0.0            # прошло пять минут
            пк.raw("Да?")
            check("кэш переименован вслед за голосом", кэш.voice, "пк-aidar")
            check("заготовка прежнего голоса больше не всплывает",
                  PhraseCache(Path(tmp), "пк-eugene").get("Да?") is not None
                  and кэш.voice == "пк-aidar", True)
        finally:
            tts_urlopen(старый)

    # Осечка связи не должна уводить робота на свой piper на целую минуту:
    # голоса разные, и минута чужого голоса слышна отчётливо.
    check("первая осечка стоит недолго", PC_DOWN_FIRST <= 10.0, True)
    check("но выключенный ПК всё равно доберётся до минуты",
          PC_DOWN >= 60.0, True)


def tts_urlopen(новый):
    """Подменяет urlopen внутри tts.py и возвращает прежний."""
    from robot_voice import tts as _tts

    старый = _tts.urllib.request.urlopen
    _tts.urllib.request.urlopen = новый
    return старый


def test_shell_ascii() -> None:
    """В shell-скриптах имена переменных — только латиницей.

    Третьи грабли того же рода. Сначала кириллица в адресе запроса и в
    заголовках HTTP, потом в границе многочастного потока, теперь в имени
    переменной shell. Общее у них одно: система принимает только латиницу, а
    отказ выглядит не как отказ.

    Здесь особенно подло: shell читает «СЛЕПОК=...» как имя команды и пишет
    «command not found» в стандартную ошибку, после чего невозмутимо идёт
    дальше с пустыми значениями. Скрипт не падает, проверка внутри него
    остаётся на месте и выглядит рабочей — а не делает ничего.
    """
    section("в shell — только латиница")
    import re

    корень = Path(__file__).resolve().parent.parent
    плохие: list[str] = []
    for путь in sorted((корень / "scripts").glob("*.sh")):
        for номер, строка in enumerate(путь.read_text().splitlines(), 1):
            голая = строка.split("#", 1)[0]
            # Присваивание в начале строки или после for/while/read.
            for имя in re.findall(r"(?:^|\s|;)([A-Za-zА-Яа-яЁё_][^\s=]*)=", голая):
                if not имя.isascii():
                    плохие.append(f"{путь.name}:{номер}: {имя}")
    check("русских имён переменных нет", плохие, [])


def test_look_rule() -> None:
    """«Что ты видишь» идёт прямо к камере, минуя модель.

    Через модель тот же вопрос выходит вдвое дольше: четырёхмиллиардная
    модель на ПК читает промпт сначала чтобы решить «надо посмотреть», потом
    чтобы пересказать увиденное. На живом роботе это девять секунд вместо
    пяти, и пересказ вдобавок теряет подробности — предел в две фразы
    срезает как раз хвост описания, а у взгляда хвост и есть содержание.

    Правило тут ускоритель, а не единственная дорога: не узнало фразу — она
    уйдёт модели, и та всё равно посмотрит. Поэтому промах в сторону «не
    поймал» дёшев, а «поймал лишнее» — обиден, и проверка держит обе стороны.
    """
    section("взгляд по правилу")
    from robot_voice import intents

    for фраза in ("что ты видишь", "что видишь", "кого ты видишь",
                  "что там видно", "что перед тобой", "оглядись", "осмотрись",
                  "кто здесь", "кто передо мной", "видишь меня",
                  "сколько пальцев", "сколько пальцев ты видишь"):
        m = intents.parse(фраза)
        check(f"«{фраза}» — к камере", m.tool if m else None, "look_around")
        # Вопрос доезжает до камеры: «сколько пальцев» и «что видишь» —
        # разные вопросы к одной картинке.
        check(f"«{фраза}» — вопрос сохранён", (m.args or {}).get("question"), фраза)

    # Голое «посмотри» вопроса не содержит: пустой вопрос камера заменит
    # своим описанием обстановки, а «посмотри» как вопрос к зрячей модели
    # означал бы что угодно.
    m = intents.parse("посмотри")
    check("«посмотри» — без вопроса", (m.tool, m.args), ("look_around", {}))

    # Про дорогу спрашиваем ДАЛЬНОМЕР, а не камеру. Он отвечает за сотую
    # долю секунды против двух у облака и видит в темноте — для «можно ли
    # ехать» нужно расстояние, а не рассуждение о предметах.
    for фраза in ("что впереди", "свободен ли путь", "путь свободен",
                  "свободна ли дорога", "чисто ли впереди",
                  "можно ли проехать", "не врежешься", "есть ли препятствия",
                  "куда можно поехать"):
        m = intents.parse(фраза)
        check(f"«{фраза}» — к дальномеру", m.tool if m else None, "path_check")
        check(f"«{фраза}» — без лишних доводов", m.args, {})

    # А это к камере не относится, и описывать комнату в ответ — глупость.
    for фраза in ("ты видишь в этом смысл", "что ты думаешь",
                  "посмотри расписание", "кто такой пушкин",
                  "можно ли курить", "видишь ли ты разницу"):
        m = intents.parse(фраза)
        check(f"«{фраза}» — не камера", (m.tool if m else "—") != "look_around", True)

    # «Иди за мной» — правилом, а не моделью: фразу говорят на ходу, уже
    # развернувшись, и две секунды раздумий человек проводит, оглядываясь.
    # Список глаголов длинный не от жадности: «едь за мной» правило когда-то
    # пропустило, ход ушёл модели, и робот просто не поехал.
    for фраза in ("иди за мной", "едь за мной", "езжай за мной",
                  "поезжай за мной", "поехали за мной", "пошли за мной",
                  "следуй за мной", "двигай за мной", "катись за мной",
                  "идем со мной", "пойдем за мной", "ступай за мной",
                  "за мной", "со мной", "держись рядом", "проводи меня"):
        m = intents.parse(фраза)
        check(f"«{фраза}» — иду следом", m.tool if m else None, "follow_me")

    # Но не всё подряд: «иди спать» — не команда ехать за человеком.
    for фраза in ("иди спать", "поехали домой", "за мной кто-то стоит",
                  "проводи гостя"):
        m = intents.parse(фраза)
        check(f"«{фраза}» — не следование",
              (m.tool if m else "—") != "follow_me", True)



def test_tof() -> None:
    """Дальномер: разбор кадра, метры и решение «ехать нельзя».

    Проверяется без железа — датчик на сборочной машине не воткнёшь, а
    ошибиться в разборе двух байт на зону легче лёгкого. Всё, что можно
    отделить от порта, отделено: разбор кадра и осмысление сетки — обычные
    функции над байтами.
    """
    import os

    section("дальномер")
    from robot_voice import tof

    # --- кадр ответа ---------------------------------------------------
    сетка = []
    for ряд in range(8):
        for кол in range(8):
            # Расстояния в сантиметрах: ряд 0 далеко, ряд 7 близко (пол).
            см = 350 - ряд * 40
            сетка += [см & 0xFF, (см >> 8) & 0xFF]
    ответ = bytes([tof.УДАЧА, tof.CMD_ALL_DATA,
                   len(сетка) & 0xFF, (len(сетка) >> 8) & 0xFF]) + bytes(сетка)
    разбор = tof.разобрать(ответ)
    check("кадр разобран", разбор is not None and разбор[0], tof.CMD_ALL_DATA)
    метры = tof.в_метры(разбор[1])
    check("восемь рядов по восемь", (len(метры), len(метры[0])), (8, 8))
    check("сантиметры стали метрами", метры[0][0], 3.5)
    check("нижний ряд ближе", метры[7][0], 0.7)

    # Отказ платы — это не данные. Раньше такое легко принять за нули и
    # затормозить посреди пустого коридора.
    отказ = bytes([tof.ОТКАЗ, tof.CMD_ALL_DATA, 0, 0])
    check("отказ отличается от данных", tof.разобрать(отказ), (tof.CMD_ALL_DATA, b""))
    check("обрывок кадра отвергнут", tof.разобрать(b"\x53\x02"), None)
    check("чужие байты отвергнуты", tof.разобрать(b"\x00\x01\x02\x03"), None)

    # --- осмысление ------------------------------------------------------
    def взгляд(*, впереди_см: int, свежий: bool = True, зон: int = 4,
               подряд: int = tof.КАДРОВ_ПОДРЯД) -> "tof.Взгляд":
        сетка = [[3.5] * 8 for _ in range(8)]
        for i in range(зон):
            сетка[2 + i // 8][i % 8] = впереди_см / 100.0
        return tof.Взгляд(сетка, time.monotonic() if свежий else 0.0,
                          подряд=подряд)

    можно, почему = взгляд(впереди_см=200).ехать_можно()
    check("два метра — едем", (можно, почему), (True, ""))

    можно, почему = взгляд(впереди_см=20).ехать_можно()
    check("двадцать сантиметров — стоим", можно, False)
    # Фраза человеческая и без чисел: её произносят вслух. Числа нужны в
    # журнале, а вслух робот должен говорить как робот, а не как отчёт.
    check("и сказано человеческим языком", "впереди что-то" in почему, True)

    # Молчащий датчик — НЕ разрешение ехать. Отказ при отказе: робот, который
    # едет вслепую, потому что датчик отвалился, опаснее стоящего.
    можно, почему = взгляд(впереди_см=200, свежий=False).ехать_можно()
    check("молчащий датчик запрещает ехать", (можно, почему), (False, "не вижу дорогу"))

    # Одиночная зона — НЕ препятствие. У ToF на кромке предмета луч попадает
    # между двумя глубинами и возвращает что угодно; стоп по такому «летающему
    # пикселю» тормозил бы робота посреди пустого коридора несколько раз в
    # минуту. Человек быстро научился бы такой стоп отключать — а это хуже,
    # чем не иметь его вовсе.
    можно, _ = взгляд(впереди_см=20, зон=1).ехать_можно()
    check("одна зона близко — не повод стоять", можно, True)
    можно, _ = взгляд(впереди_см=20, зон=tof.ЗОН_ДЛЯ_СТОПА).ехать_можно()
    check("три зоны — уже повод", можно, False)

    # И одного кадра мало. Помеха живёт один кадр, стена — все; без этого
    # условия единичный всплеск на трёх соседних зонах останавливал бы робота
    # так же уверенно, как настоящая стена.
    можно, _ = взгляд(впереди_см=20, зон=4, подряд=1).ехать_можно()
    check("один кадр — ещё не стена", можно, True)

    # --- нога на полу -----------------------------------------------------
    # Робот наехал человеку на ногу. Сторож при этом работал исправно: он
    # смотрит на ряды 2–5, середину поля зрения, а нижние ряды исключает
    # намеренно — там пол, и считать его препятствием нельзя. Но нога стоит
    # НА ПОЛУ, то есть ровно в исключённых рядах. Отличить её от пола можно
    # только зная, где пол: предмет — пол ближе нормы, обрыв — дальше.
    def на_полу(норма_м: float, замер_м: float, колонки) -> "tof.Взгляд":
        сетка = [[3.5] * 8 for _ in range(8)]
        норма = [[0.0] * 8 for _ in range(8)]
        for р in tof.ОБРЫВ_РЯДЫ:
            for к in range(8):
                норма[р][к] = норма_м
                сетка[р][к] = норма_м if к not in колонки else замер_м
        return tof.Взгляд(сетка, time.monotonic(), пол=норма,
                          подряд=tof.КАДРОВ_ПОДРЯД)

    чистый_пол = на_полу(1.0, 1.0, ())
    check("пустой пол — не препятствие", чистый_пол.зон_на_полу, 0)
    check("и ехать по нему можно", чистый_пол.ехать_можно()[0], True)

    нога = на_полу(1.0, 0.5, (3, 4))
    check("нога на полу видна", нога.зон_на_полу, 2 * len(tof.ОБРЫВ_РЯДЫ))
    check("и попадает в общий счёт",
          нога.зон_близко >= tof.ЗОН_ДЛЯ_СТОПА, True)
    можно, почему = нога.ехать_можно()
    check("и робот из-за неё стоит", (можно, bool(почему)), (False, True))

    # Но только если она на пути. Тапок у стены в полуметре вбок — не повод
    # стоять: крайние колонки смотрят на двадцать шесть градусов в сторону.
    сбоку = на_полу(1.0, 0.7, (0, 7))
    check("лежащее сбоку не мешает", сбоку.зон_на_полу, 0)

    # Без выученной нормы — ноль, и это честно: не зная, где пол, ногу от
    # пола не отличить, и гадать мы не вправе. Но и молчать нельзя.
    вслепую = tof.Взгляд(нога.сетка, time.monotonic(),
                         подряд=tof.КАДРОВ_ПОДРЯД)
    check("без нормы пола низа не видим", вслепую.зон_на_полу, 0)
    check("и робот об этом знает", вслепую.низ_не_вижу, True)
    check("а с нормой — не слепой", нога.низ_не_вижу, False)

    # Больше половины зон пустые — это солнце в окне. Уцелевшие лучи описывают
    # не комнату, а собственное везение, и «свободно» по ним объявлять нельзя.
    слепой = [[0.0] * 8 for _ in range(8)]
    for к in range(8):
        слепой[0][к] = 2.0
    ослеп = tof.Взгляд(слепой, time.monotonic())
    check("слепота видна снаружи", ослеп.слепой, True)
    # Но движение она НЕ запрещает: пустая сетка означает либо слепоту, либо
    # простор дальше трёх с половиной метров, а различить их изнутри нельзя.
    # Приняв простор за слепоту, робот встанет посреди гостиной — и человек
    # отключит датчик совсем, что хуже любой слепоты.
    check("но ехать не запрещает", ослеп.ехать_можно()[0], True)

    # --- разбор строкового вида ------------------------------------------
    # Прошивка может сыпать строками сама, без запросов. Понимаем оба вида.
    строки = "\n".join("y%d:" % р + ",".join(["1500"] * 8) for р in range(8))
    сетка_с = tof.строками(строки)
    check("строчный вид разобран", сетка_с is not None and сетка_с[0][0], 1.5)
    # 4000 — это «не измерил», а НЕ четыре метра. Спутать их значит принять
    # промах за свободный путь.
    промах = "\n".join("y%d:" % р + ",".join(["4000"] * 8) for р in range(8))
    check("четыре тысячи — это промах, не метры",
          tof.строками(промах)[0][0], tof.НЕ_ИЗМЕРИЛ)
    check("чужой текст не разбирается", tof.строками("привет\nкак дела"), None)

    # Сетка 4×4 — те же строки, только четыре по четыре. Понимать её
    # обязательно, а не «на всякий случай»: 4×4 отдаёт вчетверо больше света
    # на зону и видит там, где 8×8 молчит. Это единственный рычаг дальности,
    # который у нас есть, и без разбора переход на него выглядел бы как
    # ослепший робот.
    четыре = "\n".join("y%d:" % р + ",".join(str(300 + р * 100) for _ in range(4))
                       for р in range(4))
    мельче = tof.строками(четыре)
    check("сетка 4×4 разбирается", мельче is not None, True)
    check("и растянута до восьми на восемь",
          (len(мельче), len(мельче[0])), (8, 8))
    # Каждая зона 4×4 накрывает квадрат два на два: поле зрения то же самое,
    # просто крупнее. Весь остальной код об этом не знает и знать не должен.
    check("верхние два ряда — первая строка 4×4",
          (мельче[0][0], мельче[1][0]), (0.3, 0.3))
    check("а следующие два — вторая", мельче[2][0], 0.4)
    check("обрывок из трёх чисел отвергнут",
          tof.строками("y0:1,2,3\ny1:4,5,6"), None)
    # В каком разрешении плата — видно только по сырому тексту: после
    # растяжения 4×4 и 8×8 неразличимы. А знать это нужно, потому что от
    # разрешения зависит дальность, и это единственный рычаг, который у нас
    # есть. Без такой проверки человек отвечает на вопрос «какой сейчас
    # режим», считая одинаковые числа в соседних колонках.
    check("восемь рядов опознаны", tof.сколько_строк(строки), 8)
    check("четыре ряда тоже", tof.сколько_строк(четыре), 4)
    check("чужой текст — не сетка", tof.сколько_строк("привет"), 0)

    # --- сглаживание ------------------------------------------------------
    шум = [[1.5] * 8 for _ in range(8)]
    шум[3][3] = 0.1                       # одиночный выброс
    гладко = tof.сгладить(шум)
    check("выброс сглажен", гладко[3][3], 1.5)
    # «Не знаю» не превращается в число: усреднить с ним значит выдумать.
    редкий = [[tof.НЕ_ИЗМЕРИЛ] * 8 for _ in range(8)]
    check("пустое остаётся пустым", tof.сгладить(редкий)[0][0], tof.НЕ_ИЗМЕРИЛ)

    # И ровно поэтому сглаживания НЕТ на пути к решению «ехать или нет».
    # Медиана убирает не выбросы, а препятствия: предмет шириной в одну зону —
    # ножка стула, ножка стола, косяк двери — растворяется в соседях без
    # следа. Проверка живая: колонка по 0.32 при пустой комнате должна дожить
    # до решения, а через сгладить() она не доживает.
    ножка = [[2.0] * 8 for _ in range(8)]
    for р in range(8):
        ножка[р][0] = 0.32
    check("медиана стирает ножку стола", tof.сгладить(ножка)[3][0], 2.0)

    датчик = tof.Дальномер.__new__(tof.Дальномер)
    датчик.ищем_обрыв = False
    датчик.пол = tof.Пол()
    датчик.свои = set()
    датчик._замок = threading.Lock()
    датчик._подряд = датчик._обрыв_подряд = 0
    датчик._мешает_с = 0.0
    датчик._жаловался_на_вечное = False
    датчик._выложено = 0.0
    датчик._не_выложил = False
    датчик.разворот = False          # здесь проверяется не разворот
    датчик._на_разворот = []
    датчик._зеркало = датчик._вверхногами = датчик._поперёк = False
    датчик._прочитано = time.monotonic() + 3600   # галки не перечитывать
    for _ in range(tof.КАДРОВ_ПОДРЯД):
        датчик._принять([ряд[:] for ряд in ножка])
    check("а робот её видит", датчик.взгляд().ехать_можно()[0], False)

    # Нога доходит до решения, а не только до свойства. Проверка сквозная
    # намеренно: сама по себе зон_на_полу считалась правильно и раньше, а
    # робот всё равно наезжал — счётчик кадров подряд считался ОТДЕЛЬНОЙ
    # формулой, в которую ни коридор, ни нижние ряды не попали. Стоп требует
    # обоих условий, значит стопа не было. Здесь ловится именно это.
    ноги = tof.Дальномер.__new__(tof.Дальномер)
    ноги.__dict__.update(датчик.__dict__)
    ноги.пол = tof.Пол()
    ноги.пол.норма = [[0.0] * 8 for _ in range(8)]
    ноги.ищем_обрыв = True
    ноги._подряд = ноги._обрыв_подряд = 0
    сетка_ног = [[3.5] * 8 for _ in range(8)]
    for р in tof.ОБРЫВ_РЯДЫ:
        for к in range(8):
            ноги.пол.норма[р][к] = 1.0
            сетка_ног[р][к] = 0.5 if к in (3, 4) else 1.0
    check("норма пола дошла до взгляда", ноги._норма_пола() is not None, True)
    for _ in range(tof.КАДРОВ_ПОДРЯД):
        ноги._принять([ряд[:] for ряд in сетка_ног])
    можно, почему = ноги.взгляд().ехать_можно()
    check("нога на полу останавливает робота", можно, False)
    check("а не выглядит обрывом", "пола нет" in почему, False)
    # И зеркальная проверка: без нормы тот же кадр робота не останавливает —
    # но робот про свою слепоту знает и обязан о ней сказать.
    слепые = tof.Дальномер.__new__(tof.Дальномер)
    слепые.__dict__.update(датчик.__dict__)
    слепые.пол = tof.Пол()
    слепые.ищем_обрыв = False
    слепые._подряд = слепые._обрыв_подряд = 0
    for _ in range(tof.КАДРОВ_ПОДРЯД):
        слепые._принять([ряд[:] for ряд in сетка_ног])
    check("без нормы ту же ногу не видим", слепые.взгляд().ехать_можно()[0], True)
    check("и говорим об этом честно", слепые.низ_не_вижу(), True)
    check("а с нормой молчим", ноги.низ_не_вижу(), False)

    # И с НАЙДЕННОЙ ПЛОСКОСТЬЮ тоже молчим, даже без выученной нормы.
    #
    # Раньше «нет нормы — значит не вижу низа» было правдой, и перестало ею
    # быть в тот день, когда пол начали искать плоскостью: предмет на полу —
    # это просто точка над ней. Робот, повторяющий на каждую поездку «под
    # ноги я не смотрю» при том, что смотрит, обесценивает предупреждение
    # ровно к тому дню, когда оно окажется настоящим.
    import math as _m

    from robot_voice import plane

    оси = plane.направления()
    накл = _m.radians(12.0)
    пол_в_кадре = [[0.0] * 8 for _ in range(8)]
    for р in range(8):
        for к in range(8):
            x, y, z = оси[р][к]
            zп = -x * _m.sin(накл) + z * _m.cos(накл)
            if zп < -1e-6:
                д = -0.13 / zп
                if 0.05 < д <= 3.5:
                    пол_в_кадре[р][к] = д
    с_плоскостью = tof.Дальномер.__new__(tof.Дальномер)
    с_плоскостью.__dict__.update(датчик.__dict__)
    с_плоскостью.пол = tof.Пол()               # нормы нет намеренно
    с_плоскостью.ищем_обрыв = False
    с_плоскостью._подряд = с_плоскостью._обрыв_подряд = 0
    for _ in range(tof.КАДРОВ_ПОДРЯД):
        с_плоскостью._принять([ряд[:] for ряд in пол_в_кадре])
    check("плоскость в кадре нашлась",
          с_плоскостью.взгляд().плоскость is not None, True)
    check("и про слепой низ робот больше не причитает",
          с_плоскостью.низ_не_вижу(), False)

    # Сетка выкладывается наружу файлом. Это не удобство, а безопасность:
    # порт нельзя читать вдвоём, и пробник, открывший его при живом роботе,
    # делил бы байты пополам — то есть портил датчик ровно в тот момент,
    # когда человек его проверяет.
    with tempfile.TemporaryDirectory() as дом:
        было = os.environ.get("HOME")
        os.environ["HOME"] = дом
        try:
            датчик._выложено = 0.0
            датчик._принять([ряд[:] for ряд in ножка])
            выложено = json.loads(
                (Path(дом) / ".robot-ai" / tof.ФАЙЛ_СЕТКИ).read_text())
        finally:
            if было is None:
                del os.environ["HOME"]
            else:
                os.environ["HOME"] = было
    check("сетка выложена наружу", выложено["сетка"][3][0], 0.32)
    # Время — обычное, а не monotonic: читать будет ДРУГОЙ процесс, и
    # сравнивать ему надо со своими часами, а не с чужим счётчиком от загрузки.
    check("и помечена временем, понятным снаружи",
          abs(выложено["когда"] - time.time()) < 5, True)

    # --- где верх ---------------------------------------------------------
    # Плата подписывает ряды «y0…y7» и нигде не говорит, какой из них верхний.
    # А от этого зависит защита от лестницы: перепутав, робот ищет обрыв в
    # потолке — и находит там пустоту, то есть тормозит на ровном месте, или,
    # наоборот, не находит настоящий обрыв.
    #
    # Определяем по полу: он всегда ближе внизу и уходит вдаль кверху. Но
    # именно здесь я один раз уже ошибся, и проверка написана вокруг этой
    # ошибки.
    def съёмкой(сетка):
        return [[р[:] for р in сетка] for _ in range(20)]

    пол = [[0.30 + р * 0.04] * 8 for р in range(8)]
    check("пол лесенкой — сетка перевёрнута", tof.куда_смотрит(съёмкой(пол)), True)
    check("зеркальный случай", tof.куда_смотрит(съёмкой(пол[::-1])), False)
    шумный = [ряд[:] for ряд in пол]
    шумный[3], шумный[4] = шумный[4], шумный[3]
    check("один шаг против хода — всё ещё пол",
          tof.куда_смотрит(съёмкой(шумный)), True)

    # Ровная стена: судить не по чему. Догадка тут хуже честного незнания —
    # она молча меняет смысл всех нижних рядов.
    check("пола не видно — не гадаем",
          tof.куда_смотрит(съёмкой([[1.5] * 8 for _ in range(8)])), None)

    # А ВОТ ЭТО — самый частый случай на живом роботе, и раньше он получал
    # отказ. У правильно наклонённого датчика верхние ряды уходят в комнату
    # дальше предела дальности и молчат ЗАКОННО: это норма, а не слепота.
    # Нижние при этом мерят пол в каждом кадре. Робот на этом объявлял «пола
    # не вижу» и выключал защиту от лестницы — то есть сдавался ровно в том
    # случае, ради которого всё затевалось.
    наклонён = [[tof.НЕ_ИЗМЕРИЛ] * 8 for _ in range(8)]
    for р in (5, 6, 7):
        наклонён[р] = [0.32 - (р - 5) * 0.06] * 8
    check("низ мерит, верх молчит — это низ внизу",
          tof.куда_смотрит(съёмкой(наклонён)), False)
    check("и зеркальный случай тоже понятен",
          tof.куда_смотрит(съёмкой(наклонён[::-1])), True)
    # Но пустой край НАПРОТИВ далёкого края — не пол, а неизвестно что.
    # Просто пустой край бывает и от чёрного ковра, и от солнца; пустой край
    # напротив БЛИЗКОГО пола бывает только оттого, что там верх.
    далёкий = [[tof.НЕ_ИЗМЕРИЛ] * 8 for _ in range(8)]
    for р in (5, 6, 7):
        далёкий[р] = [2.6] * 8
    check("далёкий край полом не считается",
          tof.куда_смотрит(съёмкой(далёкий)), None)

    # А ЭТО — та самая ошибка. Пятно перед датчиком (рука, стул, коробка)
    # даёт разные края, и по одной только разнице краёв я принял его за пол и
    # уверенно объявил, где верх. В следующем замере наклон оказался обратным
    # при неподвижном датчике — то есть в одном из двух случаев я мерил руку.
    # Пол — это ЛЕСЕНКА, плоскость под углом, и между краями у неё
    # монотонный рост. У пятна между краями нет ничего.
    пятно = [[tof.НЕ_ИЗМЕРИЛ] * 8 for _ in range(8)]
    for р in range(2, 6):
        for к in range(2, 6):
            пятно[р][к] = 0.30 + (р - 2) * 0.02
    check("пятно перед датчиком за пол не сходит",
          tof.куда_смотрит(съёмкой(пятно)), None)
    плоская = [[0.42] * 8 for _ in range(8)]
    плоская[0] = [0.25] * 8
    плоская[7] = [0.60] * 8
    check("края разные, середина плоская — тоже не пол",
          tof.куда_смотрит(съёмкой(плоская)), None)

    # --- три галки разворота дают все восемь положений ---------------------
    # Плата подписывает строки «y0:…y7:» и нигде не говорит, что такое y —
    # строка или колонка. Разведка дала различающий признак: у наклонённого
    # вниз датчика молчащие зоны обязаны идти СТРОКАМИ (нижние бьют в пол под
    # скользящим углом, верхние уходят за предел дальности). У нас они шли
    # колонками — а это ровно то, во что превращается строчная картина, если
    # читать сетку поперёк.
    исходная = [[р * 10.0 + к for к in range(8)] for р in range(8)]

    def развёрнутая(зеркало, вверхногами, поперёк):
        д = tof.Дальномер.__new__(tof.Дальномер)
        д.свои = set()
        д.разворот = False
        д.ищем_обрыв = False
        д.пол = tof.Пол()
        д._замок = threading.Lock()
        д._подряд = д._обрыв_подряд = 0
        д._мешает_с = 0.0
        д._жаловался_на_вечное = False
        д._выложено = 0.0
        д._не_выложил = True
        д._прочитано = time.monotonic() + 3600
        д._зеркало, д._вверхногами, д._поперёк = зеркало, вверхногами, поперёк
        д._принять([ряд[:] for ряд in исходная])
        return д.взгляд().сетка

    check("без галок сетка как есть", развёрнутая(0, 0, 0)[1][2], 12.0)
    check("зеркально меняет колонки", развёрнутая(1, 0, 0)[1][2], 15.0)
    check("вверх ногами меняет ряды", развёрнутая(0, 1, 0)[1][2], 62.0)
    check("поперёк меняет местами то и другое", развёрнутая(0, 0, 1)[1][2], 21.0)
    check("и все три вместе", развёрнутая(1, 1, 1)[1][2], 56.0)
    # Восемь сочетаний — восемь РАЗНЫХ сеток: иначе какое-то положение было бы
    # недостижимо, и человек крутил бы галки, не добившись своего.
    все = {tuple(tuple(р) for р in развёрнутая(з, в, п))
           for з in (0, 1) for в in (0, 1) for п in (0, 1)}
    check("восемь галочных сочетаний — восемь разных сеток", len(все), 8)

    # --- свои же зоны -----------------------------------------------------
    # На живой плате два верхних ряда показали 0.06 и 0.08 во всех двухстах
    # кадрах с разбросом в сантиметр. Сцена так не выглядит; так выглядит
    # железо, привинченное к датчику. Шестнадцать таких зон означают вечное
    # «препятствие» и робота, который не поедет никуда.
    def съёмка(стена: float) -> list:
        """Сорок кадров: кронштейн, неподвижная стена сбоку и дышащая комната."""
        кадры = []
        for н in range(40):
            кадр = [[2.0] * 8 for _ in range(8)]
            for к in range(8):
                кадр[0][к] = 0.06 + (н % 2) * 0.005   # кронштейн: не дышит
                кадр[1][к] = 0.08 + (н % 2) * 0.005
                # А это комната: близко, но дышит — шум датчика, тень от
                # лампы, дрожание самого робота.
                кадр[4][к] = 0.20 + (н % 8) * 0.02
            for р in range(8):
                кадр[р][0] = стена + (н % 2) * 0.005  # стена сбоку: тоже не дышит
            кадры.append(кадр)
        return кадры

    # Стена стоит на месте ровно так же, как кронштейн: по одному замеру они
    # неразличимы, и оба выглядят своей деталью.
    до = съёмка(0.27)
    # Семь и семь от кронштейна (нулевую колонку в обоих рядах перекрыла
    # стена) плюс восемь стены — двадцать две зоны, и по этой съёмке они
    # неразличимы между собой.
    check("по одному замеру неподвижны и стена, и кронштейн",
          len(tof._постоянные(до)), 7 + 7 + 8)

    # Решает поворот. Своё железо повёрнуто вместе с датчиком и осталось на
    # том же расстоянии; стена ушла.
    после = съёмка(0.44)
    свои = tof.свои_зоны(до, после)
    check("кронштейн опознан", sorted({р for р, _ in свои}), [0, 1])
    # Главное в этой проверке. Признать стену своей деталью — значит велеть
    # роботу её не замечать, а это ошибка, которой не видно вообще ничем: он
    # не тормозит и ни на что не жалуется, просто однажды едет в стену.
    check("стена своей не стала", any(к == 0 for _, к in свои), False)
    check("осталось ровно две строки по семь", len(свои), 14)
    # Дышащая комната не проходит и первый признак.
    check("живая комната своей не считается", any(р == 4 for р, _ in свои), False)
    # Далёкое неподвижное — тоже не деталь: за полметра своих деталей не бывает.
    check("далёкое неподвижное не в счёт", any(р == 7 for р, _ in свои), False)
    # Без второго замера — пустой список, а не догадка. Список своих зон
    # ОТКЛЮЧАЕТ защиту, и лучше его не иметь, чем иметь неверный.
    check("без поворота ничего не записывается", tof.свои_зоны(до), [])

    with tempfile.TemporaryDirectory() as каталог:
        путь = Path(каталог) / "tof_blind.json"
        tof.сохранить_своих(свои, путь)
        check("список переживает перезапуск",
              tof.загрузить_своих(путь), set(свои))
    check("нет файла — нет и списка",
          tof.загрузить_своих(Path("/несуществующее/tof_blind.json")), set())

    # --- обрыв ------------------------------------------------------------
    # Единственное, чего лидар не умеет физически: увидеть, что пола дальше
    # нет. Лидар мерит в своей плоскости, ступеньку вниз он не видит вовсе, а
    # лестница в квартире одна и падение с неё окончательное.
    with tempfile.TemporaryDirectory() as каталог:
        пол = tof.Пол(Path(каталог) / "tof_floor.json")
        ровно = [[2.0] * 8 for _ in range(8)]
        for р in tof.ОБРЫВ_РЯДЫ:
            for к in range(8):
                ровно[р][к] = 0.8          # пол под уклоном, восемьдесят см
        for _ in range(tof.УЧИТЬ_КАДРОВ - 1):
            пол.учить(ровно)
        check("пол ещё не выучен", пол.норма, None)
        check("последний кадр доучивает", пол.учить(ровно), True)
        check("норма — то, что видели", пол.норма[7][0], 0.8)
        # Нижние ряды, упирающиеся в пол, обязаны отвечать почти все: пол
        # близко и матов, мерить его — самое лёгкое, что есть. Ответила
        # половина или меньше — «полом» запомнилось что-то другое, и робот
        # обязан сказать об этом, а не молча вооружиться неверной нормой.
        # На живом роботе так и вышло: шесть зон из шестнадцати, и по картинке
        # с камеры видно, что это ровная вертикальная полоса — стена справа, а
        # не пол. Обрыв по такой норме искался бы В СТЕНЕ: она никуда не
        # денется, значит обрыва не будет никогда, и робот спокойно уедет с
        # лестницы, считая себя защищённым. Пустая защита хуже отсутствующей —
        # на неё полагаются.
        мало = tof.Пол(Path(каталог) / "мало.json")
        редкий = [[tof.НЕ_ИЗМЕРИЛ] * 8 for _ in range(8)]
        for к in range(3):
            редкий[6][к] = редкий[7][к] = 0.8
        for _ in range(tof.УЧИТЬ_КАДРОВ):
            мало.учить(редкий)
        check("редкий пол НЕ запоминается", мало.норма, None)
        # Верхние ряды в норму не идут: они смотрят в комнату, а не в пол.
        check("верх в норму не попал", пол.норма[0][0], tof.НЕ_ИЗМЕРИЛ)

        check("ровный пол — не обрыв", пол.обрыв(ровно), 0)

        # Ступенька вниз: луч уходит дальше, чем был пол.
        ступенька = [ряд[:] for ряд in ровно]
        for к in range(3):
            ступенька[7][к] = 2.4
        check("пол ушёл вдаль — обрыв", пол.обрыв(ступенька) >= tof.ОБРЫВ_ЗОН, True)

        # И второй вид обрыва, более частый: за краем луч не возвращается
        # вовсе. Ноль здесь — не «расстояние ноль», а «ничего нет», и
        # принять его за пол значит поехать со ступеньки.
        пропал = [ряд[:] for ряд in ровно]
        for к in range(3):
            пропал[7][к] = tof.НЕ_ИЗМЕРИЛ
        check("пол пропал — тоже обрыв", пол.обрыв(пропал) >= tof.ОБРЫВ_ЗОН, True)

        # Одна зона — не обрыв, ровно по той же причине, что одна зона не
        # стена: у ToF одиночный промах это норма, а не событие.
        одна = [ряд[:] for ряд in ровно]
        одна[7][0] = 3.0
        check("одна зона — не обрыв", одна and пол.обрыв(одна) < tof.ОБРЫВ_ЗОН, True)

        # Норма переживает перезапуск: переучивать её каждый раз опасно —
        # однажды робот включится у самой ступеньки и запомнит нормой пустоту.
        пол.ориентация = (False, False, False, True)
        пол.сохранить()
        снова = tof.Пол(Path(каталог) / "tof_floor.json")
        check("пол помнится с прошлого раза", снова.загрузить(), True)
        check("и та же самая норма", снова.норма[7][0], 0.8)
        # Вместе с нормой помнится ВСЯ ориентация, в которой она снята. Одного
        # признака из четырёх не хватало: человек ставил галку «поперёк», робот
        # разворачивал сетку — и брал к ней норму, снятую боком. То есть искал
        # обрыв не там, куда смотрит, и выглядело это исправной работой.
        check("и ориентация вместе с ней",
              снова.ориентация, (False, False, False, True))
        # Норма без записанной ориентации — норма неизвестно откуда. Такую
        # нельзя ни принять, ни поправить: остаётся не верить.
        (Path(каталог) / "старая.json").write_text(
            json.dumps({"норма": [[0.9] * 8 for _ in range(8)]}))
        старая = tof.Пол(Path(каталог) / "старая.json")
        старая.загрузить()
        check("у безымянной ориентации её нет", старая.ориентация, None)

    # Решение про обрыв идёт РАНЬШЕ решения про стену: стену объезжают, с
    # лестницы падают один раз.
    у_края = tof.Взгляд([[2.0] * 8 for _ in range(8)], time.monotonic(),
                        обрыв=tof.КАДРОВ_ПОДРЯД)
    можно, почему = у_края.ехать_можно()
    check("обрыв запрещает ехать", можно, False)
    check("и сказано, что это обрыв", "пола нет" in почему, True)
    # Один кадр — не обрыв: пол мигнул, а робот встал бы намертво.
    check("один кадр обрыва — не повод",
          tof.Взгляд([[2.0] * 8 for _ in range(8)], time.monotonic(),
                     обрыв=1).ехать_можно()[0], True)

    # Ноль — это «не измерил», а не «расстояние ноль». Стекло и зеркала
    # возвращают именно ноль, и принять его за упор в стену значит намертво
    # затормозить робота посреди комнаты.
    пусто = tof.Взгляд([[tof.НЕ_ИЗМЕРИЛ] * 8 for _ in range(8)], time.monotonic())
    check("ничего не измерено — не препятствие", пусто.ехать_можно()[0], True)
    check("и расстояние честно нулевое", пусто.впереди, tof.НЕ_ИЗМЕРИЛ)

    # --- протокол переспрашивается, а не выбирается навсегда --------------
    # На живом роботе это уже случилось. Пробник вслепую перебрал двоичные
    # команды, одна из них выключила плате автоотдачу, RP2040 это запомнил — и
    # драйвер, решивший при запуске «плата молчит, буду спрашивать кадрами»,
    # остался в неверном режиме навсегда. В журнале это выглядело как
    # исправно работающая служба, которая ничего не видит.
    было = tof.ПЕРЕСПРОСИТЬ_ЧЕРЕЗ
    tof.ПЕРЕСПРОСИТЬ_ЧЕРЕЗ = 0.1
    try:
        читатель = tof.Дальномер.__new__(tof.Дальномер)
        читатель.устройство = "стенд"
        читатель._беда = ""
        читатель._стоп = threading.Event()
        читатель._открыть = lambda: 0
        # Устройства на сборочной машине нет, а внешняя петля без него
        # честно ждёт его появления — вечно. Здесь проверяется не поиск
        # устройства, а выбор протокола.
        читатель.доступен = lambda: True
        выбрано: list[str] = []

        def распознать(fd):
            # Плата молчит два круга, потом оживает и снова сыплет строки.
            режим = "кадры" if len(выбрано) < 2 else "строки"
            выбрано.append(режим)
            return режим

        читатель._распознать = распознать
        читатель._читать_кадрами = lambda fd: time.sleep(0.01)
        читатель._читать_строками = lambda fd: читатель._стоп.set()
        читатель._читать()
    finally:
        tof.ПЕРЕСПРОСИТЬ_ЧЕРЕЗ = было
    check("режим переспрашивается, а не залипает", выбрано,
          ["кадры", "кадры", "строки"])

    # --- кадр команды байт в байт как у вендора ---------------------------
    # Здесь я ошибся молча и дорого. Число в двух байтах после заголовка — это
    # длина аргументов ПЛЮС ЕДИНИЦА: команда считается вместе с ними. Я слал
    # на единицу меньше, и прошивка, ожидая лишний байт, дочитывала его из
    # НАЧАЛА СЛЕДУЮЩЕГО ПАКЕТА — то есть съедала чужой заголовок и получала
    # команду с мусорными аргументами. Отдельный запрос при этом выглядит
    # правильно; ломает его только соседство со следующим.
    #
    # Эталон взят из DFRobot_MatrixLidar.cpp, setRangingMode: length = 4,
    # argsNumL = (length + 1), args = {0, 0, 0, matrix}. Матрица ЧЕТВЁРТЫМ
    # аргументом, а не первым, — вторая половина той же ошибки.
    check("кадр смены режима совпадает с вендорским",
          tof._кадр(tof.CMD_CONFIG, tof.аргументы_режима(tof.РЕЖИМ_8X8)).hex(" "),
          "55 00 05 01 00 00 00 08")
    check("и для сетки 4×4",
          tof._кадр(tof.CMD_CONFIG, tof.аргументы_режима(tof.РЕЖИМ_4X4)).hex(" "),
          "55 00 05 01 00 00 00 04")
    check("запрос без аргументов — длина всё равно единица",
          tof._кадр(tof.CMD_ALL_DATA).hex(" "), "55 00 01 02")

    # --- имя устройства --------------------------------------------------
    # Рядом на ttyACM живёт контроллер приводов: обращаться по номеру нельзя.
    os.environ["ROBOT_TOF_DEVICE"] = "/dev/особый-дальномер"
    try:
        check("настройка перебивает поиск", tof.найти_устройство(),
              "/dev/особый-дальномер")
    finally:
        del os.environ["ROBOT_TOF_DEVICE"]



def test_fusion() -> None:
    """Сплав камеры и дальномера: плотная картина в честных метрах.

    Здесь проверяется чистая математика, и это удача: железа не нужно, а
    ошибиться в ней легче всего. Главная ловушка — подгонять в метрах вместо
    обратных величин: связь отклика модели с расстоянием линейна именно в
    обратных, и в метрах близкие точки перетягивают на себя всю прямую.
    """
    section("сплав камеры и дальномера")
    import numpy as np
    from robot_voice import fusion

    # --- куда смотрят зоны ------------------------------------------------
    точки = fusion.зоны_в_пиксели(640, 480)
    check("сетка восемь на восемь", (len(точки), len(точки[0])), (8, 8))
    # Центральные зоны — у центра кадра.
    сx = (точки[3][3][0] + точки[3][4][0]) / 2
    сy = (точки[3][3][1] + точки[4][3][1]) / 2
    check("центр сетки в центре кадра", (round(сx), round(сy)), (320, 240))
    # Слева направо — по возрастанию, сверху вниз — тоже.
    check("зоны идут слева направо",
          [точки[3][к][0] for к in range(8)] ==
          sorted(точки[3][к][0] for к in range(8)), True)
    check("зоны идут сверху вниз",
          [точки[р][3][1] for р in range(8)] ==
          sorted(точки[р][3][1] for р in range(8)), True)
    # Дальномер уже камеры: 63 градуса против 130, значит середина кадра.
    ширина_захвата = точки[0][7][0] - точки[0][0][0]
    check("сетка накрывает середину, а не весь кадр",
          100 < ширина_захвата < 300, True)

    # --- подгонка ---------------------------------------------------------
    # Отклик модели связан с расстоянием как rel = 3·(1/м) + 5. Значит
    # обратное преобразование: 1/м = (rel − 5)/3, то есть a = 1/3, b = −5/3.
    метры = [0.5, 0.8, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 1.2, 1.8]
    отклик = [3.0 * (1.0 / м) + 5.0 for м in метры]
    a, b, принято = fusion.подогнать(отклик, метры)
    check("масштаб найден", round(a, 4), round(1 / 3, 4))
    check("сдвиг найден", round(b, 4), round(-5 / 3, 4))
    check("приняты все точки", принято, len(метры))

    # Одна зона соврала вдесятеро — обычный МНК утащил бы прямую за ней.
    кривой = list(отклик)
    кривой[4] = отклик[4] * 10
    a2, b2, принято2 = fusion.подогнать(кривой, метры)
    check("промах отброшен", принято2, len(метры) - 1)
    check("и масштаб уцелел", round(a2, 3), round(1 / 3, 3))

    # --- привязка целой картинки ------------------------------------------
    # Настоящая сцена: слева метр, справа три, плавно.
    высота, ширина = 48, 64
    правда = np.zeros((высота, ширина))
    for x in range(ширина):
        правда[:, x] = 1.0 + 2.0 * x / (ширина - 1)
    # Модель выдаёт это же, но в своих единицах и со сдвигом.
    отклик_карты = 7.0 * (1.0 / правда) + 2.0

    сетка_тоф = [[0.0] * 8 for _ in range(8)]
    точки_м = fusion.зоны_в_пиксели(ширина, высота)
    for р in range(8):
        for к in range(8):
            x, y = точки_м[р][к]
            сетка_тоф[р][к] = float(правда[y, x])

    карта, почему = fusion.в_метры(отклик_карты, сетка_тоф, точки_м)
    check("карта получена", карта is not None, True)
    if карта is not None:
        ошибка = float(np.max(np.abs(карта - правда)))
        check("метры восстановлены", ошибка < 0.01, True)

    # --- когда привязать нечем -------------------------------------------
    пусто = [[0.0] * 8 for _ in range(8)]
    карта2, почему2 = fusion.в_метры(отклик_карты, пусто, точки_м)
    check("без опор карты нет", карта2, None)
    check("и сказано, почему", "опорных точек" in почему2, True)

    # Три зоны — мало. Две точки задают прямую, но любая помеха из этих трёх
    # становится законом для всего кадра.
    мало = [[0.0] * 8 for _ in range(8)]
    for к in range(3):
        x, y = точки_м[3][к]
        мало[3][к] = float(правда[y, x])
    карта3, _ = fusion.в_метры(отклик_карты, мало, точки_м)
    check("трёх опор недостаточно", карта3, None)

    # --- профиль занятости ------------------------------------------------
    профиль = fusion.занятость(правда, порог=5.0)
    check("восемь колонок", len(профиль), 8)
    check("слева ближе, справа дальше", профиль[0] < профиль[7], True)

    # Незнание остаётся незнанием: принять его за свободу — это уехать в
    # стеклянную дверь.
    неизвестно = np.zeros((высота, ширина))
    check("пустая карта не обещает свободы",
          fusion.занятость(неизвестно), [0.0] * 8)



def test_tof_guard() -> None:
    """Дальномер запрещает ехать в стену — и только вперёд.

    Решение принимается на месте, без модели: она отвечает секундами, а робот
    на 0.3 м/с за секунду проезжает треть метра. Спрашивать у неё разрешения
    значит узнавать ответ после события.
    """
    section("дальномер держит колёса")
    import types

    from robot_voice import tof as tof_mod

    store = Path(tempfile.mkdtemp())
    поехали: list[tuple] = []
    ros = types.SimpleNamespace(
        voltage=12.4, moving=False, connected=True, busy=False,
        drive=lambda *a, **k: поехали.append((a, k)),
        run_route=lambda шаги: поехали.append((tuple(шаги), {})),
        stop_motion=lambda: None)

    def робот(впереди: float, свежий: bool = True):
        взгляд = types.SimpleNamespace(
            свежий=свежий, впереди=впереди, слева=впереди, справа=впереди,
            ехать_можно=lambda: ((True, "") if свежий and (впереди <= 0 or впереди >= 0.3)
                                 else (False, "не вижу дорогу" if not свежий
                                       else "впереди что-то справа")))
        def мешает() -> str:
            if not свежий:
                return ""          # молчащий датчик НЕ запирает робота
            можно, почему = взгляд.ехать_можно()
            return "" if можно else почему

        тоф = types.SimpleNamespace(беда="", взгляд=lambda: взгляд,
                                    мешает=мешает)
        return {t.name: t for t in build_tools(
            ros, Timers(announce=lambda text, **kw: None,
                        store=store / f"t{впереди}{свежий}.json"),
            addressed=lambda: True, tof=тоф)}

    # Стена в двадцати сантиметрах — вперёд нельзя.
    инстр = робот(0.20)
    поехали.clear()
    ответ = инстр["drive"]({"direction": "вперёд", "distance": 1.0})
    check("вперёд в стену не поехали", поехали, [])
    check("и сказано, почему", "впереди что-то" in ответ.lower(), True)

    # А назад — можно: датчик смотрит вперёд и про то, что сзади, не знает.
    # Запрещать по незнанию значит выдавать его за опасность.
    поехали.clear()
    инстр["drive"]({"direction": "назад", "distance": 0.5})
    check("назад пускаем", len(поехали), 1)

    # Два метра — езжай.
    инстр = робот(2.0)
    поехали.clear()
    инстр["drive"]({"direction": "вперёд", "distance": 1.0})
    check("по свободному пути едем", len(поехали), 1)

    # Молчащий датчик движение НЕ запрещает: робот жил без него и должен
    # жить дальше. Отказ по отсутствию данных остановил бы его навсегда,
    # стоит выдернуть провод.
    инстр = робот(2.0, свежий=False)
    поехали.clear()
    инстр["drive"]({"direction": "вперёд", "distance": 1.0})
    check("молчащий датчик не запирает робота", len(поехали), 1)

    # Зато на вопрос отвечает честно, а не выдумывает простор.
    check("и про молчание говорит вслух",
          "молчит" in инстр["path_check"]({}).lower(), True)

    # --- «свободна ли дорога» не отвечает про собственный пол -------------
    # Робот противоречил сам себе в одном и том же кадре: пустая ровная
    # комната, штатный наклон 12° при высоте 13 см — «свободно впереди»
    # 3.5 м, «ехать можно» да, а на вопрос человека «Впереди препятствие в
    # 0.3 метра». Человек слышал это, глядя на робота, который преспокойно
    # едет. Та же цифра уходила в журнал и портила разбор настоящих бед.
    import math as _mm

    from robot_voice import plane as _пл
    from robot_voice import tof as _тоф

    _оси = _пл.направления()
    _накл = _mm.radians(12.0)
    пустая = [[0.0] * 8 for _ in range(8)]
    for _р in range(8):
        for _к in range(8):
            _x, _y, _z = _оси[_р][_к]
            _xп = _x * _mm.cos(_накл) + _z * _mm.sin(_накл)
            _zп = -_x * _mm.sin(_накл) + _z * _mm.cos(_накл)
            _д = []
            if _zп < -1e-6:
                _д.append(-0.13 / _zп)
            if _xп > 1e-6:
                _д.append(3.0 / _xп)
            _живые = [м for м in _д if 0.05 < м <= 3.5]
            пустая[_р][_к] = min(_живые) if _живые else 0.0

    комната = types.SimpleNamespace(
        беда="",
        взгляд=lambda: _тоф.Взгляд(пустая, time.monotonic()),
        мешает=lambda: "",
        низ_не_вижу=lambda: False)
    в_комнате = {и.name: и for и in build_tools(
        ros, Timers(announce=lambda text, **kw: None,
                    store=store / "пустая.json"),
        addressed=lambda: True, tof=комната)}
    ответ = в_комнате["path_check"]({})
    check("в пустой комнате робот не видит стены в 30 см",
          "стена" in ответ.lower(), False)
    check("а докладывает про настоящую стену в трёх метрах",
          "3.0" in ответ or "3.1" in ответ, True)
    check("и называет это свободой", "свободно" in ответ.lower(), True)

    # И то же самое с другой стороны: пол больше не стирает НАСТОЯЩУЮ стену.
    # Подгонка по всему кадру ошибалась тем сильнее, чем ближе стена, — на
    # полутора метрах наклон уезжал на четыре градуса, а это одиннадцать
    # сантиметров высоты на той же дальности. Стена оказывалась «в пределах
    # толщины пола» и стиралась целиком. Ищем теперь по ближним точкам.
    близкая = [[0.0] * 8 for _ in range(8)]
    for _р in range(8):
        for _к in range(8):
            _x, _y, _z = _оси[_р][_к]
            _xп = _x * _mm.cos(_накл) + _z * _mm.sin(_накл)
            _zп = -_x * _mm.sin(_накл) + _z * _mm.cos(_накл)
            _д = []
            if _zп < -1e-6:
                _д.append(-0.13 / _zп)
            if _xп > 1e-6:
                _д.append(1.5 / _xп)
            _живые = [м for м in _д if 0.05 < м <= 3.5]
            близкая[_р][_к] = min(_живые) if _живые else 0.0
    взгляд_стена = _тоф.Взгляд(близкая, time.monotonic())
    check("наклон датчика выведен точно, стена не сбивает",
          abs(взгляд_стена.плоскость.наклон - 12.0) < 0.5, True)
    check("и стена в полутора метрах видна",
          1.3 < взгляд_стена.впереди < 1.8, True)

    # И это должно быть ДЁШЕВО: плоскость считается каждый кадр и кормит
    # собой всё — стоп, предел скорости, поиск человека, карту. Перебор
    # тройками был написан тремя вложенными циклами, и сто двадцать троек по
    # четыре вызова numpy на крошечных массивах — это накладные расходы, а не
    # работа. На плате робота выходило под тридцать миллисекунд на кадр.
    _засечка = time.perf_counter()
    for _ in range(50):
        _пл.найти(близкая)
    _мс = (time.perf_counter() - _засечка) / 50 * 1000
    check(f"подгонка плоскости укладывается в миллисекунду ({_мс:.2f} мс)",
          _мс < 1.0, True)

    # --- про слепое пятно под колёсами говорим вслух ----------------------
    # Робот наехал человеку на ногу. Нога стоит на полу, то есть в нижних
    # рядах сетки, а отличить её от самого пола можно только зная, где пол.
    # Норма пола учится не всегда: датчик смотрит слишком высоко, робот стоит
    # на столе. Пока её нет, низ — слепое пятно целиком, и человек имеет
    # право узнать об этом ДО поездки, а не после.
    слепой_низ = types.SimpleNamespace(
        беда="", взгляд=lambda: types.SimpleNamespace(свежий=True),
        мешает=lambda: "", низ_не_вижу=lambda: True)
    инстр = {t.name: t for t in build_tools(
        ros, Timers(announce=lambda text, **kw: None,
                    store=store / "низ.json"),
        addressed=lambda: True, tof=слепой_низ)}
    поехали.clear()
    ответ = инстр["drive"]({"direction": "вперёд", "distance": 1.0})
    check("вперёд всё равно едем", len(поехали), 1)
    check("но про слепой низ сказали", "под ноги" in ответ, True)
    # Не на каждую команду: предупреждение, звучащее всякий раз, перестают
    # слышать через день — и тогда оно уже ничего не защищает.
    ответ = инстр["drive"]({"direction": "вперёд", "distance": 1.0})
    check("а второй раз подряд — молчим", "под ноги" in ответ, False)
    # И только про движение вперёд: назад робот и с нормой едет вслепую,
    # приплетать сюда пол — сбивать человека с толку.
    check("назад про низ не говорим",
          "под ноги" in инстр["drive"]({"direction": "назад"}), False)

    # А когда пол выучен — молчим совсем.
    зрячий_низ = types.SimpleNamespace(
        беда="", взгляд=lambda: types.SimpleNamespace(свежий=True),
        мешает=lambda: "", низ_не_вижу=lambda: False)
    инстр = {t.name: t for t in build_tools(
        ros, Timers(announce=lambda text, **kw: None,
                    store=store / "низ2.json"),
        addressed=lambda: True, tof=зрячий_низ)}
    check("с выученным полом не пугаем зря",
          "под ноги" in инстр["drive"]({"direction": "вперёд"}), False)

    # И то же правило действует НА ХОДУ, а не только перед командой. Раньше
    # оно было записано дважды и разъехалось: проверка молчание прощала, а
    # сторож обрывал поездку на первой миллисекунде. Пока плата отвечала,
    # разницы видно не было; стоило ей зависнуть — и сломанный датчик запер
    # робота наглухо, объявляя вслух «дальномер молчит» на каждую просьбу.
    from robot_voice.tof import Дальномер

    немой = Дальномер.__new__(Дальномер)
    немой._замок = threading.Lock()
    немой._взгляд = tof_mod.Взгляд([[0.0] * 8 for _ in range(8)], 0.0)
    check("молчащий датчик не мешает ехать", немой.мешает(), "")

    видит = Дальномер.__new__(Дальномер)
    видит._замок = threading.Lock()
    стена = [[2.0] * 8 for _ in range(8)]
    for к in range(4):
        стена[3][к] = 0.2
    видит._взгляд = tof_mod.Взгляд(стена, time.monotonic(),
                                   подряд=tof_mod.КАДРОВ_ПОДРЯД)
    check("а увиденная стена — мешает", "впереди что-то" in видит.мешает(), True)
    # Вслух — без чисел: числа уходят в журнал.
    check("и без цифр в голосе",
          any(з.isdigit() for з in видит.мешает()), False)

    # --- в маршруте только вперёд ----------------------------------------
    # Дальномер смотрит вперёд. На маршруте робот едет до полутора минут, и
    # человек в это время не рулит, а смотрит со стороны: назад и боком робот
    # ехал бы вслепую, не видя ни стены, ни лестницы. Прямая команда «проедь
    # назад» при этом работает как работала — там человек сказал это, глядя
    # на робота, секунду назад.
    инстр = робот(2.0)
    поехали.clear()
    ответ = инстр["route"]({"steps": [{"move": "вперёд", "distance": 0.5},
                                      {"move": "назад", "distance": 0.5}]})
    check("задний ход в маршруте отклонён", "вслепую" in ответ, True)
    ответ = инстр["route"]({"steps": [{"move": "влево", "distance": 0.5},
                                      {"turn": "вправо"}]})
    check("боком в маршруте тоже нельзя", "вслепую" in ответ, True)
    # А вперёд с поворотами — обычная фигура, её никто не трогал.
    ответ = инстр["route"]({"steps": [{"move": "вперёд", "distance": 0.5},
                                      {"turn": "вправо", "degrees": 90}]})
    check("вперёд с поворотом — можно", "шага" in ответ, True)

    # И маршрут в стену не начинается вовсе: иначе робот сперва подтвердит
    # вслух «делаю круг, двенадцать шагов», а потом встанет на первом колене.
    ответ = робот(0.20)["route"]({"steps": [{"move": "вперёд"},
                                            {"turn": "влево"}]})
    check("маршрут в стену не начинаем", "впереди что-то" in ответ.lower(), True)


def test_reflex() -> None:
    """Сторож пути: дальномер обрывает поездку ВО ВРЕМЯ движения.

    Это главное отличие от проверки перед командой. Проверка перед командой
    отвечает на вопрос «свободно ли сейчас», а поездка на три метра длится
    пятнадцать секунд, и человек за это время успевает встать на пути. Робот,
    проверивший дорогу один раз и дальше едущий вслепую, опаснее робота без
    датчика: тот хотя бы ничего не обещал.
    """
    section("сторож обрывает поездку на ходу")
    from robot_voice.ros import Ros

    ros = Ros.__new__(Ros)          # без сети: нам нужен только _motion_loop
    ros._lock = threading.Lock()
    ros._motion_cancel = threading.Event()
    ros._odom = None
    ros._odom_at = 0.0
    ros._свои_нули = 0
    ros._не_ушло = 0
    ros._кричали_про_связь = False
    ros.прервано = ""
    ros.объявить = None
    ros.сторож = None
    ros.сторож_вслепую = None
    команды: list[tuple] = []
    # True, как у настоящего _send: он возвращает «ушло ли». Ответить здесь
    # ложью значило бы проверять поведение при оборванной связи, думая, что
    # проверяешь сторожа.
    ros._send = lambda сообщение: bool(команды.append(
        (сообщение["msg"]["linear"]["x"], сообщение["msg"]["angular"]["z"])) or True)

    # Свободно — доезжаем сами.
    ros.сторож = lambda: (True, "")
    команды.clear()
    ros._motion_loop(0.2, 0.0, 0.0, 0.2)
    check("свободный путь не обрывается", ros.прервано, "")
    check("и колёса крутились", any(x > 0 for x, _ in команды), True)

    # Стена — обрываемся, и последнее слово в топик обязано быть нулём:
    # шасси держит последнюю скорость, пока ему не скажут иначе.
    сказано: list[str] = []
    ros.сторож = lambda: (False, "впереди препятствие в 0.2 м")
    ros.объявить = сказано.append
    ros.прервано = ""
    команды.clear()
    ros._motion_loop(0.2, 0.0, 0.0, 5.0)
    check("сторож оборвал поездку", "препятствие" in ros.прервано, True)
    check("ни одного ненулевого хода", [x for x, _ in команды if x], [])
    check("и человеку сказано вслух", bool(сказано) and "Стою" in сказано[0], True)

    # Назад сторож не судит: датчик смотрит вперёд и про то, что сзади, не
    # знает ничего. Запрет по незнанию — это выдача незнания за опасность.
    ros.прервано = ""
    команды.clear()
    ros._motion_loop(-0.2, 0.0, 0.0, 0.2)
    check("назад сторож не мешает", ros.прервано, "")
    check("и назад мы правда ехали", any(x < 0 for x, _ in команды), True)

    # Разворот на месте — тоже не его дело: робот не приближается ни к чему.
    ros.прервано = ""
    команды.clear()
    ros._motion_loop(0.0, 0.0, 1.0, 0.2)
    check("разворот сторож не мешает", ros.прервано, "")

    # Маршрут отменяется ЦЕЛИКОМ, а не одним коленом: продолжить его со
    # следующего шага значит поехать по фигуре, которой уже нет, мимо
    # препятствия, которого робот не объезжал.
    ros.сторож = lambda: (False, "впереди препятствие в 0.2 м")
    ros.прервано = ""
    ros._motion = None
    шагов = [{"x": 0.2, "y": 0.0, "wz": 0.0, "duration": 0.1},
             {"x": 0.0, "y": 0.0, "wz": 1.0, "duration": 0.1},
             {"x": 0.2, "y": 0.0, "wz": 0.0, "duration": 0.1}]
    команды.clear()
    ros._route_loop(шагов)
    # Первый шаг оборвался, значит поворота второго шага не было вовсе.
    check("маршрут отменён целиком", [wz for _, wz in команды if wz], [])


def test_camera() -> None:
    """Камера робота: один владелец, кадры из потока, честная жалоба.

    Проверяется на поддельном ffmpeg — настоящей камеры на сборочной машине
    нет, а разбирать поток на кадры надо уметь одинаково.
    """
    import os

    section("камера робота")
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import camera as кам

    двор = Path(tempfile.mkdtemp())

    # Поддельная камера: выдаёт два целых кадра и молчит.
    поддельный = двор / "ffmpeg"
    поддельный.write_text(
        # Подделка ведёт себя как настоящая камера: сыплет кадры без
        # остановки, пока её не убьют. Иначе проверка ловила бы не то —
        # на выходе процесса последний кадр намеренно стирается, а спящая
        # подделка вдобавок держала бы трубу открытой потомком.
        #
        # Первые два кадра уходят ОДНОЙ записью, и это не мелочь. Двумя
        # отдельными читающий поток видел сперва только «odin», и проверка
        # «достался последний» зависела от того, кто успел раньше: на
        # неторопливой машине проходила, на быстрой машине сборки — падала.
        # Двадцать байт в трубу пишутся неделимо, поэтому разбор всегда
        # находит оба кадра сразу и последним остаётся «dva».
        "#!/bin/sh\n"
        "printf '\\377\\330odin\\377\\331\\377\\330dva\\377\\331'\n"
        "while :; do sleep 0.2; printf '\\377\\330dva\\377\\331'; done\n")
    поддельный.chmod(0o755)
    старый_путь = os.environ.get("PATH", "")
    os.environ["PATH"] = f"{двор}:{старый_путь}"
    try:
        глаз = кам.Камера(устройство=str(поддельный))  # лишь бы файл существовал
        check("камера считается доступной", глаз.доступна(), True)
        кадр = глаз.кадр(ждать=5.0)
        # Берём ПОСЛЕДНИЙ кадр, а не первый: показывать надо то, что перед
        # роботом сейчас, а не то, что было в начале записи.
        check("достался последний целый кадр", кадр, b"\xff\xd8dva\xff\xd9")
        глаз.закрыть()

        # Нет устройства — честный отказ, а не пустой кадр без объяснения.
        слепой = кам.Камера(устройство=str(двор / "нет-такого"))
        check("отсутствие камеры видно сразу", слепой.доступна(), False)
        check("кадра нет", слепой.кадр(ждать=0.5), b"")
        check("причина названа", "нет устройства" in слепой.беда, True)
    finally:
        os.environ["PATH"] = старый_путь

    # Камера, которую перестали спрашивать, обязана отпуститься ПО-НАСТОЯЩЕМУ.
    # На живом роботе она не отпускалась: поток уходил читать ругань ffmpeg у
    # ещё живого процесса и вис там навсегда — read() ждёт конца файла, а тот
    # наступит лишь с его смертью. Снаружи это выглядело так: ffmpeg жив и
    # держит устройство, последний кадр не стёрт, и пульт показывал ровно одну
    # картинку, застрявшую с прошлого раза.
    os.environ["PATH"] = f"{двор}:{старый_путь}"
    было_простой = кам.ПРОСТОЙ
    кам.ПРОСТОЙ = 0.3
    try:
        живучий = кам.Камера(устройство=str(поддельный))
        check("кадр взяли", живучий.кадр(ждать=5.0), b"\xff\xd8dva\xff\xd9")
        процесс = живучий._proc
        # Ждём простоя: никто больше не спрашивает.
        сдался = False
        for _ in range(60):
            time.sleep(0.1)
            if процесс.poll() is not None:
                сдался = True
                break
        check("ffmpeg действительно убит, а не брошен", сдался, True)
        # Поле обнуляет читающий поток, разблокированный смертью процесса, —
        # мгновением позже. Ждём его, а не гадаем.
        for _ in range(50):
            if живучий._proc is None:
                break
            time.sleep(0.1)
        check("и поле процесса очищено", живучий._proc, None)
        # И камера поднимается заново, а не остаётся мёртвой навсегда.
        check("следующий кадр поднимает её снова",
              живучий.кадр(ждать=5.0), b"\xff\xd8dva\xff\xd9")
        живучий.закрыть()
    finally:
        кам.ПРОСТОЙ = было_простой
        os.environ["PATH"] = старый_путь

    # Имя устройства берётся из настройки, если она задана.
    os.environ["ROBOT_CAMERA_DEVICE"] = "/dev/особая"
    try:
        check("настройка перебивает поиск", кам.найти_устройство(), "/dev/особая")
    finally:
        del os.environ["ROBOT_CAMERA_DEVICE"]


def _поддельный_anthropic():
    """Модуль-заглушка вместо SDK: настоящий ключ для проверок не нужен."""
    import types as _t

    ответ = _t.SimpleNamespace(
        content=[_t.SimpleNamespace(type="text", text="вижу стол")],
        usage=_t.SimpleNamespace(input_tokens=1500, output_tokens=20),
    )

    class Anthropic:
        def __init__(self, **kw):
            self.messages = _t.SimpleNamespace(create=lambda **k: ответ)

    return _t.SimpleNamespace(Anthropic=Anthropic)


def test_vision() -> None:
    """Глаза робота: кадр берём у веб-сервера, разглядывает ПК.

    Проверяется главное: если разглядеть кадр некому, робот говорит об этом
    вслух, а не молчит и не выдумывает. Молчаливый отказ здесь опаснее
    обычного — мост на ПК роняет картинку без единой ошибки, и модель,
    не увидев ничего, уверенно расскажет, что перед роботом.
    """
    import base64
    import http.server
    import threading as thr

    section("глаза робота")
    from robot_voice.camera import Глаза

    КАДР = b"\xff\xd8jpeg\xff\xd9"

    class Ответчик(http.server.BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def do_GET(self):
            if self.path != "/camera/snapshot":
                self.send_response(404); self.send_header("Content-Length", "0")
                self.end_headers(); return
            self.send_response(200)
            self.send_header("Content-Type", "image/jpeg")
            self.send_header("Content-Length", str(len(КАДР)))
            self.end_headers()
            self.wfile.write(КАДР)

        def do_POST(self):
            длина = int(self.headers.get("Content-Length") or 0)
            запрос = json.loads(self.rfile.read(длина).decode("utf-8"))
            # Кадр обязан доехать целым и в base64 — на этом ломался мост.
            дошло = base64.b64decode(запрос["кадр"]) == КАДР
            ответ = json.dumps(
                {"текст": "вижу стол" if дошло else "кадр не дошёл"},
                ensure_ascii=False).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(ответ)))
            self.end_headers()
            self.wfile.write(ответ)

        def log_message(self, *a):
            pass

    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Ответчик)
    thr.Thread(target=srv.serve_forever, daemon=True).start()
    адрес = f"http://127.0.0.1:{srv.server_address[1]}"
    try:
        глаза = Глаза(web_url=адрес, pc_url=адрес)
        check("кадр забрали у веб-сервера", глаза.снимок(), КАДР)
        check("ПК разглядел и ответил", глаза.посмотреть("что там"), "вижу стол")

        # ПК молчит, облака нет — робот обязан сказать это словами.
        слепой = Глаза(web_url=адрес, pc_url="http://127.0.0.1:1")
        сказал = слепой.посмотреть()
        check("про отказ сказано вслух", "компьютер не ответил" in сказал, True)

        # Камеры нет вовсе — тоже вслух, и это не то же самое сообщение.
        безглазый = Глаза(web_url="http://127.0.0.1:1", pc_url=адрес)
        check("про отсутствие кадра сказано отдельно",
              "камера не отдала кадр" in безглазый.посмотреть(), True)

        # Нет зрячей модели на ПК — спрашиваем его РОВНО ОДИН раз. Ответ до
        # перезапуска не изменится, а каждый лишний заход стоит человеку
        # секунды тишины: на живом роботе это была ровно секунда из десяти.
        отказчик = Глаза(web_url=адрес, pc_url=адрес + "/нет-зрения")
        стуков = [0]
        настоящий = отказчик._спросить_пк

        def считать(кадр, вопрос):
            стуков[0] += 1
            отказчик._пк_без_зрения = True      # как после 502 «не ответила»
            return ""

        отказчик._спросить_пк = считать
        отказчик.посмотреть()
        отказчик.посмотреть()
        отказчик.посмотреть()
        check("к ПК без зрения стучимся один раз", стуков[0], 1)

        # А обычный обрыв запоминать нельзя: он проходит сам, и робот остался
        # бы без домашнего зрения на весь сеанс из-за одной осечки.
        сбойный = Глаза(web_url=адрес, pc_url="http://127.0.0.1:1")
        сбойный.посмотреть()
        check("случайный отказ ПК не отлучает от него навсегда",
              сбойный._пк_без_зрения, False)

        # Смотрит младшая модель, а не та, которой разговаривают: на живом
        # роботе взгляд опусом стоил двенадцать секунд молчания. Нет младшей
        # — отступаем на старшую, а не остаёмся без ответа.
        облачный = Глаза(web_url=адрес, pc_url="", api_key="ключ",
                         model="старшая", vision_model="младшая")
        звали: list[str] = []

        def подделка(кадр, вопрос, модель):
            звали.append(модель)
            return "" if модель == "младшая" else "увидел стол"

        облачный._облаком = подделка
        check("отступили на модель разговора",
              облачный.посмотреть(), "увидел стол")
        check("сначала спросили младшую", звали, ["младшая", "старшая"])

        # Расход за взгляд обязан куда-то попасть: кадр стоит примерно как
        # полторы тысячи слов, и молча тратить их нельзя.
        счёт: list[tuple] = []
        считающий = Глаза(web_url=адрес, pc_url="", api_key="ключ",
                          model="м", vision_model="м",
                          учёт=lambda откуда, вход, выход: счёт.append(
                              (откуда, вход, выход)))
        sys.modules["anthropic"] = _поддельный_anthropic()
        try:
            check("облако ответило", считающий.посмотреть(), "вижу стол")
            check("расход записан", счёт, [("м", 1500, 20)])
        finally:
            sys.modules.pop("anthropic", None)
    finally:
        srv.shutdown()


def test_camera_stream() -> None:
    """Поток камеры забираем так же, как его забирает браузер.

    Проверка появилась не от хорошей жизни: границу кадров сначала назвали
    русским словом, и весь ответ падал при отправке — заголовки HTTP
    кодируются в latin-1. Снимок при этом работал, статус говорил «ok», а
    видео в пульте просто не шло, и по журналу было не понять почему.

    Ловится это только тем, что кто-то действительно сходит по адресу:
    ограда «наружу — только латиница» смотрит на словари заголовков в
    robot_voice и такую запись не видит в принципе.
    """
    section("поток камеры")
    import http.client
    import http.server
    import threading as thr

    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import camera as камера_модуль
    import server as сервер

    КАДР = b"\xff\xd8jpeg\xff\xd9"

    class ПоддельнаяКамера:
        устройство = "/dev/поддельная"
        беда = ""

        def доступна(self):
            return True

        def кадр(self, ждать=0.0):
            return КАДР

        def поток(self, пределом=60.0):
            for _ in range(3):
                yield КАДР

        def закрыть(self):
            pass

    было_камера, было_источник = сервер.КАМЕРА, сервер.CAMERA_SOURCE
    сервер.КАМЕРА, сервер.CAMERA_SOURCE = ПоддельнаяКамера(), "usb"
    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), сервер.Handler)
    thr.Thread(target=srv.serve_forever, daemon=True).start()
    порт = srv.server_address[1]
    try:
        связь = http.client.HTTPConnection("127.0.0.1", порт, timeout=10)
        связь.request("GET", "/camera")
        try:
            ответ = связь.getresponse()
        except Exception as e:            # noqa: BLE001
            # Обрыв без ответа — это и есть та самая поломка: заголовок не
            # закодировался, и сервер уронил соединение. Говорим словами, а
            # не трассировкой, иначе в отчёте не видно, что именно сломалось.
            check("поток не оборвался на заголовках", f"обрыв: {e}", "поток идёт")
            return
        тип = ответ.getheader("Content-Type") or ""
        check("поток отдан", ответ.status, 200)
        check("тип — многочастный", тип.startswith("multipart/x-mixed-replace"), True)
        # Главное: заголовок обязан пережить кодирование в latin-1.
        check("заголовок уходит без обрыва", тип.isascii(), True)
        тело = ответ.read()
        check("кадр доехал целым", КАДР in тело, True)
        связь.close()

        # Снимок — тем же путём, но одним куском.
        связь = http.client.HTTPConnection("127.0.0.1", порт, timeout=10)
        связь.request("GET", "/camera/snapshot")
        ответ = связь.getresponse()
        check("снимок отдан", (ответ.status, ответ.read()), (200, КАДР))
        связь.close()

        # Раздача НЕ должна заканчиваться сама по себе. Раньше в ней стоял
        # предел в минуту, после которого соединение просто закрывалось:
        # браузер оставался с последним кадром, и человек видел зависшее
        # видео, которое оживало только перезагрузкой страницы. Камеру
        # освобождает не этот предел, а сторож — он смотрит, спрашивают ли
        # кадры, — так что предел ничего не охранял и исправно ломал показ.
        import inspect

        сама = inspect.signature(камера_модуль.Камера.поток)
        check("у раздачи нет предела по времени",
              сама.parameters["пределом"].default, 0.0)

        # А вот автопереподключения по img.complete в пульте быть НЕ должно.
        # Признак ненадёжный: браузер помечает ресурс завершённым и на живом
        # потоке, после первой же части. Сторож на нём пересоздавал картинку
        # каждые несколько секунд, и между сносом старой и первым кадром новой
        # человек видел черноту — лечение хуже болезни.
        страница = (Path(__file__).resolve().parent.parent
                    / "web" / "pult.html").read_text()
        # Ищем сам вызов переподключения, а не слова про него: объяснение,
        # почему сторожа больше нет, содержит те же слова, и проверка по ним
        # ловила бы собственный комментарий.
        check("сторож потока убран из пульта",
              "включитьВидео(видеоБаза)" in страница, False)
        check("но объяснение, почему, осталось в коде",
              "БОЛЬШЕ НЕТ" in страница, True)
        check("зато молчит, когда вкладку не смотрят",
              "document.hidden" in страница, True)
    finally:
        srv.shutdown()
        сервер.КАМЕРА, сервер.CAMERA_SOURCE = было_камера, было_источник


def test_depth_to_eyes() -> None:
    """Расстояния доезжают до зрячей модели вместе с картинкой.

    Ради этого вся возня с дальномером и затевалась. Модель по одной картинке
    видит, что стул ближе стены, но метров не знает и знать не может: масштаба
    у одного глаза нет. Спросишь «далеко ли стул» — ответит уверенно и наугад.
    Дальномер метры знает, но не знает, что перед ним стул. Складываем их
    самым дешёвым способом: просто говорим модели, где в кадре сколько метров.
    """
    section("глубина в глазах")
    import os

    from robot_voice import camera as камера_модуль

    сетка = [[0.0] * 8 for _ in range(8)]
    for р in range(3, 8):
        for к in range(2, 7):
            сетка[р][к] = 0.40 + р * 0.05
    текст = камера_модуль.подсказка_дальномера(сетка)
    check("расстояния описаны словами", "ДАЛЬНОМЕР" in текст, True)
    check("и числа на месте", "0.55" in текст, True)
    # Главное в подсказке — оговорка про край кадра. У камеры 130 градусов, у
    # дальномера 60: числа есть только про середину. Без этой оговорки модель
    # приписывает расстояние предметам с краю, тем увереннее, чем меньше знает.
    check("сказано, какую часть кадра накрывает", "% по ширине" in текст, True)
    check("и запрещено выдумывать про остальное", "не выдумывай" in текст, True)

    # Мерить нечего — молчим. Пустая таблица прочерков только сбивает.
    check("пустая сетка ничего не добавляет",
          камера_модуль.подсказка_дальномера([[0.0] * 8 for _ in range(8)]), "")

    # И то же самое через настоящие Глаза: молчащий дальномер не должен
    # приписывать к вопросу вчерашние метры.
    import types

    свежий = types.SimpleNamespace(
        взгляд=lambda: types.SimpleNamespace(свежий=True, сетка=сетка))
    немой = types.SimpleNamespace(
        взгляд=lambda: types.SimpleNamespace(свежий=False, сетка=сетка))
    check("живой дальномер добавляет расстояния",
          "ДАЛЬНОМЕР" in камера_модуль.Глаза(tof=свежий)._про_расстояния(), True)
    check("молчащий — ничего не добавляет",
          камера_модуль.Глаза(tof=немой)._про_расстояния(), "")
    check("без дальномера тоже ничего",
          камера_модуль.Глаза()._про_расстояния(), "")

    # Прицел сохраняется ПО-НАСТОЯЩЕМУ, через HTTP, как это делает пульт.
    # Проверка появилась после того, как ручка оказалась ниже двух заслонов —
    # белого списка и запрета «только с самого робота», — и была недостижима
    # в принципе. Человек видел «не вышло: 400» и объяснить не мог. Прямой
    # вызов записать_прицел этого не ловит: он и так работает.
    import http.client as _http
    import http.server as _hs
    import threading as _thr

    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import server as _сервер

    было_дома = os.environ.get("HOME")
    with tempfile.TemporaryDirectory() as дом2:
        os.environ["HOME"] = дом2
        srv2 = _hs.ThreadingHTTPServer(("127.0.0.1", 0), _сервер.Handler)
        _thr.Thread(target=srv2.serve_forever, daemon=True).start()
        try:
            связь = _http.HTTPConnection("127.0.0.1", srv2.server_address[1],
                                         timeout=10)
            связь.request("POST", "/tof/aim", json.dumps(
                {"x": 0.5, "y": 0.5, "ш": 0.4, "в": 0.8,
                 "зеркало": True, "вверхногами": False}))
            ответ = связь.getresponse()
            тело = ответ.read()
            связь.close()
            check("пульт может сохранить прицел", ответ.status, 200)
            check("и галка доехала до файла",
                  json.loads(тело)["прицел"]["зеркало"], True)
            # И обратно тем же путём.
            связь = _http.HTTPConnection("127.0.0.1", srv2.server_address[1],
                                         timeout=10)
            связь.request("GET", "/tof/aim")
            назад = json.loads(связь.getresponse().read())
            связь.close()
            check("и читается обратно", (назад["ш"], назад["зеркало"]), (0.4, True))
        finally:
            srv2.shutdown()
            if было_дома is None:
                os.environ.pop("HOME", None)
            else:
                os.environ["HOME"] = было_дома

    # Пульт и робот обязаны понимать прицел одинаково: файл у них общий, а
    # код разный — они живут в разных процессах и друг друга не импортируют.
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import server as сервер

    from robot_voice import tof as tof_модуль

    check("имя файла прицела совпадает у всех троих",
          {сервер.ФАЙЛ_ПРИЦЕЛА, камера_модуль.ФАЙЛ_ПРИЦЕЛА,
           tof_модуль.ФАЙЛ_ПРИЦЕЛА}, {"tof_aim.json"})
    check("и умолчание совпадает",
          сервер._по_умолчанию(), камера_модуль.ПРИЦЕЛ_ПО_УМОЛЧАНИЮ)

    было = os.environ.get("HOME")
    with tempfile.TemporaryDirectory() as дом:
        os.environ["HOME"] = дом
        try:
            сервер.записать_прицел({"x": 0.4, "y": 0.6, "ш": 0.3, "в": 0.5,
                                    "зеркало": False, "вверхногами": False,
                                    "поперёк": False})
            check("что записал пульт, то робот и прочёл",
                  камера_модуль.прицел(),
                  {"x": 0.4, "y": 0.6, "ш": 0.3, "в": 0.5,
                   "зеркало": False, "вверхногами": False, "поперёк": False})
            свой = камера_модуль.подсказка_дальномера(сетка)
            check("и область в подсказке считается по нему",
                  "от 25% до 55% по ширине" in свой, True)

            # Как сетка лежит относительно картинки — тоже общее знание.
            # Плата нигде не говорит, с какой стороны у неё первая колонка, а
            # по полу это не определить: он одинаков слева и справа. Зато
            # человеку видно за минуту, и его ответ обязан дойти до робота.
            check("по умолчанию ничего не развёрнуто",
                  tof_модуль.как_лежит(), (False, False, False))
            сервер.записать_прицел({"x": 0.5, "y": 0.5, "ш": 0.5, "в": 0.5,
                                    "зеркало": True, "вверхногами": True,
                                    "поперёк": True})
            check("галки из пульта доходят до драйвера",
                  tof_модуль.как_лежит(), (True, True, True))
            check("и возвращаются в пульт как есть",
                  (сервер.прицел()["зеркало"], сервер.прицел()["вверхногами"]),
                  (True, True))
        finally:
            if было is None:
                os.environ.pop("HOME", None)
            else:
                os.environ["HOME"] = было


def test_follow() -> None:
    """«Иди за мной»: пеленг и дистанцию даёт дальномер, камера не нужна.

    Восемь колонок на шестьдесят градусов — семь с половиной градусов на
    колонку, точнее, чем нужно колёсам. Зрячая модель для этого не годится
    вовсе: она отвечает секундами, а за секунду человек уходит на метр.
    """
    section("иду за тобой")
    import math

    from robot_voice import follow

    def сетка(**зоны):
        г = [[0.0] * 8 for _ in range(8)]
        for к, (расстояние, рядов) in зоны.items():
            for р in range(рядов):
                г[р][int(к[1:])] = расстояние
        return г

    # Человек прямо перед роботом: колонки 3 и 4, полтора метра.
    прямо = сетка(к3=(1.5, 5), к4=(1.5, 5))
    цель = follow.найти_цель(прямо)
    check("цель найдена", цель is not None, True)
    расстояние, угол, зон = цель
    check("расстояние взято ближайшее", расстояние, 1.5)
    check("и угол почти ноль", abs(math.degrees(угол)) < 4, True)

    # Человек слева: колонки 1 и 2. Влево — угол положительный, как в ROS.
    слева = follow.найти_цель(сетка(к1=(1.2, 5), к2=(1.2, 5)))
    check("слева — угол положительный", слева[1] > 0, True)
    справа = follow.найти_цель(сетка(к5=(1.2, 5), к6=(1.2, 5)))
    check("справа — отрицательный", справа[1] < 0, True)
    check("и по величине одинаково",
          abs(abs(слева[1]) - abs(справа[1])) < 1e-6, True)

    # Одна зона — не человек, а блик или угол мебели.
    check("одна зона целью не считается",
          follow.найти_цель(сетка(к3=(1.0, 1))), None)
    # Дальше двух с половиной метров цель не берём: там датчик и так почти
    # ничего не возвращает, и «человеком» станет стена.
    check("далёкое пятно не цель",
          follow.найти_цель(сетка(к3=(3.0, 5), к4=(3.0, 5))), None)
    check("пустая сетка — цели нет",
          follow.найти_цель([[0.0] * 8 for _ in range(8)]), None)

    # Ищем ПО КОЛОНКАМ, а не по зонам. Человек в сетке — вертикальная полоса.
    # Если считать центр тяжести всего близкого, робот поедет ровно между
    # человеком и косяком двери, потому что среднее между ними посередине.
    двое = сетка(к0=(1.0, 6), к7=(1.0, 6))
    _, угол_двое, _ = follow.найти_цель(двое)
    check("между двумя пятнами не едем",
          abs(math.degrees(угол_двое)) > 15, True)

    # --- закон движения ---------------------------------------------------
    вперёд, поворот = follow.как_ехать(2.0, 0.0)
    check("далеко — едем вперёд", вперёд > 0, True)
    check("и не быстрее предела", вперёд <= follow.СКОРОСТЬ_МАКС, True)

    вперёд, _ = follow.как_ехать(follow.ДЕРЖАТЬ, 0.0)
    check("на своей дистанции стоим", вперёд, 0.0)

    # Ближе некуда — стоим, но НЕ ПЯТИМСЯ. Назад робот едет вслепую, а сзади
    # у следования чаще всего тот, кто подошёл посмотреть.
    вперёд, _ = follow.как_ехать(0.4, 0.0)
    check("вплотную — стоим, а не пятимся", вперёд, 0.0)
    check("задний ход не выдаётся никогда",
          all(follow.как_ехать(д / 10, у / 10)[0] >= 0
              for д in range(1, 30) for у in range(-10, 11)), True)

    # Круто в сторону — сперва доворачиваем. Иначе робот описывает дугу мимо
    # человека и теряет его на краю поля зрения.
    вперёд, поворот = follow.как_ехать(2.0, math.radians(25))
    check("на крутом угле сперва поворот", вперёд, 0.0)
    check("и поворот в сторону цели", поворот > 0, True)
    check("поворот не быстрее предела",
          abs(follow.как_ехать(2.0, math.radians(60))[1]) <= follow.ПОВОРОТ_МАКС,
          True)

    # --- поведение целиком ------------------------------------------------
    import types

    команды: list[tuple] = []
    ros = types.SimpleNamespace(
        publish_twist=lambda x=0.0, y=0.0, wz=0.0: команды.append((x, y, wz)))
    вид = {"сетка": прямо, "свежий": True}
    # сетка_без_пола обязана быть и здесь: следование берёт цель ТОЛЬКО из
    # неё. Сетки в этой проверке рисованные, пола в них нет вовсе, поэтому
    # чистая и сырая совпадают.
    тоф = types.SimpleNamespace(
        мешает=lambda: "",
        взгляд=lambda: types.SimpleNamespace(свежий=вид["свежий"],
                                             сетка=вид["сетка"],
                                             сетка_без_пола=вид["сетка"]))
    сказано: list[str] = []
    вед = follow.Следование(ros, тоф, говорить=сказано.append)

    check("не идём, пока не позвали", вед.идёт, False)
    ответ = вед.начать()
    check("пошли", вед.идёт, True)
    check("и сказали об этом", "Иду за тобой" in ответ, True)
    time.sleep(0.45)
    check("колёса крутятся", any(x > 0 for x, _, _ in команды), True)
    check("вбок не едем никогда", [y for _, y, _ in команды if y], [])

    # Цель пропала — колёса встают В ТОТ ЖЕ МИГ, а не доезжают по инерции.
    команды.clear()
    вид["сетка"] = [[0.0] * 8 for _ in range(8)]
    time.sleep(0.35)
    check("потеряли — сразу стоп",
          all(x == 0 and wz == 0 for x, _, wz in команды), True)

    check("«хватит» останавливает", вед.хватит("проверка"), True)
    check("и следование правда кончилось", вед.идёт, False)
    check("а второй раз останавливать нечего", вед.хватит(), False)

    # Без дальномера не беремся вовсе: робот, поехавший искать человека,
    # которого не видит, — это робот, поехавший неизвестно куда.
    пустой = follow.Следование(ros, None)
    check("без дальномера отказ", "не могу" in пустой.начать().lower(), True)


def test_mapping() -> None:
    """Карта проходимости: дальномер + колёса + время.

    Главная мысль, ради которой всё: лидар получает триста шестьдесят градусов
    за оборот своего зеркала, а робот — за оборот СЕБЯ. Восемь колонок, десять
    кадров в секунду, шесть секунд разворота — около пятисот замеров по кругу,
    сравнимо с LD19. Разница во времени, а не в количестве.
    """
    section("карта вокруг робота")
    import math

    from robot_voice import mapping

    def стена_впереди(метров: float):
        г = [[0.0] * 8 for _ in range(8)]
        for р in mapping.РЯДЫ:
            for к in range(8):
                г[р][к] = метров
        return г

    карта = mapping.Карта()

    # --- плоский скан из сетки -------------------------------------------
    лучи = карта.лучи(стена_впереди(1.0))
    check("восемь колонок — восемь лучей", len(лучи), 8)
    check("расстояние взято как есть", лучи[0][1], 1.0)
    # Углы разложены по полю зрения, слева направо, симметрично. Сравниваем с
    # допуском: округление до десятых на 26.25 попадает ровно на границу и
    # зависит от того, как считался косинус.
    край = mapping.ПОЛЕ * 3.5 / 8
    check("крайние лучи по краям поля",
          abs(math.degrees(лучи[0][0]) - край) < 0.1, True)
    check("и второй край зеркально",
          abs(math.degrees(лучи[-1][0]) + край) < 0.1, True)

    # Колонка без замеров в скан НЕ попадает. Отсутствие замера — это «не
    # знаю», а не «свободно до бесконечности»: записать туда свободу значит
    # выдумать проход там, где стекло.
    дырявая = стена_впереди(1.0)
    for р in mapping.РЯДЫ:
        дырявая[р][3] = 0.0
    check("пустая колонка выпадает из скана", len(карта.лучи(дырявая)), 7)

    # Берём МИНИМУМ по рядам: робот объезжает препятствие целиком, а не его
    # среднюю высоту.
    торчит = стена_впереди(2.0)
    торчит[mapping.РЯДЫ[0]][4] = 0.4
    check("в колонке берётся ближайшее",
          min(д for _, д in карта.лучи(торчит)), 0.4)

    # --- накопление -------------------------------------------------------
    карта = mapping.Карта()
    # Робот стоит в начале координат и смотрит вдоль оси X. Стена в метре.
    for i in range(12):
        карта.добавить(стена_впереди(1.0), (0.0, 0.0, 0.0), когда=i * 0.1)
    check("стена в метре отмечена занятой", карта.занято(1.0, 0.0), True)
    check("а полметра до неё — свободно", карта.занято(0.5, 0.0), False)
    # За стеной робот ничего не видел, и там обязано остаться «не знаю», а не
    # «свободно»: иначе на карте появится проход сквозь стену.
    картинка = карта.картинка()
    клетки = картинка["клетки"]
    кx = int((1.5 - картинка["угол"][0]) / картинка["клетка"])
    кy = int((0.0 - картинка["угол"][1]) / картинка["клетка"])
    check("за стеной — не знаю, а не свободно",
          клетки[кy * картинка["клеток"] + кx], 0)

    # --- поворот заменяет вращение лидара --------------------------------
    # Робот крутится на месте маленькими шагами, стена вокруг на метре.
    круг = mapping.Карта()
    шагов = 90
    for i in range(шагов):
        курс = 2 * math.pi * i / шагов
        круг.добавить(стена_впереди(1.0), (0.0, 0.0, курс), когда=i * 0.1)
    видно = sum(1 for з in круг.картинка()["клетки"] if з)
    check("после оборота карта не пуста", видно > 200, True)
    # И стена нашлась со всех сторон, а не только спереди.
    check("стена найдена сзади", круг.занято(-1.0, 0.0), True)
    check("и сбоку", круг.занято(0.0, 1.0), True)

    # --- когда не копим ---------------------------------------------------
    # Робот провернулся между кадрами быстрее, чем мерит: замер относится к
    # позе, которой уже нет, и привязывать его не к чему. Лучше потерять
    # кадр, чем размазать стену дугой — размазанная потом не стирается.
    быстрый = mapping.Карта()
    быстрый.добавить(стена_впереди(1.0), (0.0, 0.0, 0.0), когда=0.0)
    взято = быстрый.добавить(стена_впереди(1.0), (0.0, 0.0, math.radians(30)),
                             когда=0.1)
    check("рывок поворота не засчитан", взято, False)
    check("и рывок хода тоже",
          быстрый.добавить(стена_впереди(1.0), (0.5, 0.0, math.radians(30)),
                           когда=0.2), False)

    # --- забывание --------------------------------------------------------
    # Стул унесли — с карты он обязан уйти. Иначе робот вечно объезжает то,
    # чего нет, и человек перестаёт верить карте целиком.
    забывчивая = mapping.Карта()
    for i in range(12):
        забывчивая.добавить(стена_впереди(1.0), (0.0, 0.0, 0.0), когда=i * 0.1)
    check("сперва занято", забывчивая.занято(1.0, 0.0), True)
    # Проходит две минуты, робот стоит и ничего не видит.
    забывчивая.добавить([[0.0] * 8 for _ in range(8)], (0.0, 0.0, 0.0),
                        когда=120.0)
    check("через две минуты забыто", забывчивая.занято(1.0, 0.0), False)

    # --- карта едет за роботом -------------------------------------------
    едущая = mapping.Карта()
    for i in range(60):
        x = i * 0.05
        едущая.добавить(стена_впереди(1.0), (x, 0.0, 0.0), когда=i * 0.5)
    check("робот остался внутри карты",
          all(0 <= к < едущая.клеток
              for к in едущая._в_клетки(*едущая.поза[:2])), True)


def test_tof_in_pult() -> None:
    """Сетка дальномера доезжает до пульта — по-настоящему, через HTTP.

    Проверка сквозная не из педантизма. Здесь сходятся три процесса: голосовая
    служба пишет файл, веб-сервер его читает, страница рисует. Разъехаться они
    могут молча — в имени файла, во времени, в форме ответа, — и снаружи это
    выглядит как пустая панель, про которую не понять, дальномер сломался или
    показ.
    """
    section("дальномер в пульте")
    import http.client
    import http.server
    import os
    import threading as thr

    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "web"))
    import server as сервер

    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), сервер.Handler)
    thr.Thread(target=srv.serve_forever, daemon=True).start()
    порт = srv.server_address[1]

    def спросить() -> dict:
        связь = http.client.HTTPConnection("127.0.0.1", порт, timeout=10)
        связь.request("GET", "/tof")
        ответ = связь.getresponse()
        тело = json.loads(ответ.read())
        связь.close()
        return тело

    было = os.environ.get("HOME")
    with tempfile.TemporaryDirectory() as дом:
        os.environ["HOME"] = дом
        try:
            check("без файла — честный отказ", спросить()["есть"], False)

            # Пишем сетку РУКАМИ ДРАЙВЕРА, а не своим json.dumps: иначе
            # проверка подтвердит согласие теста с самим собой, а не двух
            # настоящих сторон.
            from robot_voice import tof as tof_mod

            датчик = tof_mod.Дальномер.__new__(tof_mod.Дальномер)
            датчик._выложено = 0.0
            датчик._не_выложил = False
            сетка = [[1.5] * 8 for _ in range(8)]
            сетка[3][3] = 0.2
            датчик._выложить(сетка)

            ответ = спросить()
            check("сетка доехала до пульта", ответ["есть"], True)
            check("и в ней то, что записал драйвер", ответ["сетка"][3][3], 0.2)
            check("порог стопа тоже приехал", ответ["стоп"], tof_mod.СТОП_БЛИЖЕ)

            # Протухшую сетку отдавать нельзя. Позавчерашняя комната,
            # показанная как сегодняшняя, хуже пустой панели: пустой не верят,
            # а картинке верят.
            файл = Path(дом) / ".robot-ai" / tof_mod.ФАЙЛ_СЕТКИ
            данные = json.loads(файл.read_text())
            данные["когда"] = time.time() - 60
            файл.write_text(json.dumps(данные))
            протухла = спросить()
            check("протухшую не показываем", протухла["есть"], False)
            check("и сказано, почему", "не сейчас" in протухла["почему"], True)
        finally:
            if было is None:
                os.environ.pop("HOME", None)
            else:
                os.environ["HOME"] = было
            srv.shutdown()

    # Пульт и сервер должны звать одно и то же одинаково.
    страница = (Path(__file__).resolve().parent.parent / "web" / "pult.html").read_text()
    check("страница ходит за сеткой", "fetch('/tof')" in страница, True)
    check("и знает про «не измерил»", "не измерил" in страница, True)

    # Ловушка, на которой я уже попался. Атрибут hidden задаёт display:none с
    # НУЛЕВОЙ специфичностью, и любое наше правило с display его молча
    # перебивает: спрятанное продолжает показываться, причём не на своём
    # месте. В пульте так вылезли и наложение, и ползунки при снятой галке.
    # Пока в стилях есть display, это правило обязано быть.
    check("hidden в пульте побеждает display",
          "[hidden] { display: none !important; }" in страница, True)

    # Видео нельзя выдавить панелями. Раньше это стерегли предельным
    # размером сетки и нижним пределом высоты видео: панели стояли столбиком
    # и сжимали картинку, пока однажды не сжали в ноль — сетка есть, видео
    # нет. Теперь стеречь нечего, потому что причины нет: видео занимает всю
    # сцену, а панели лежат НА нём слоями и в общем потоке не участвуют.
    #
    # Проверяем поэтому не прежние подпорки, а само устройство — иначе при
    # возврате к столбику беда вернётся вместе с ним.
    видео = страница.split("#videoBox {")[1].split("}")[0]
    check("видео занимает сцену целиком", "position: absolute" in видео, True)
    check("и растянуто по всем краям", "inset: 0" in видео, True)
    хад = страница.split("#hud {")[1].split("}")[0]
    check("телеметрия лежит поверх, а не в потоке",
          "position: absolute" in хад, True)
    check("и её ширина ограничена", "width: 232px" in хад, True)

    # Сетка на видео включена СРАЗУ. За этим и просили: раньше её надо было
    # включить галочкой, а галочка жила в панели ниже, и про неё не знали.
    check("наложение сетки включено по умолчанию",
          'id="tofOverOn" checked' in страница, True)
    # И убирается одним касанием, не открывая настроек.
    check("и убирается чипом рядом с картинкой",
          'class="чип"' in страница and 'id="tofOverOn"' in страница, True)

    # Всё, что настраивают редко, — за одной кнопкой. Раньше прицел сетки,
    # адрес камеры и три галочки разворота лежали на главном экране.
    check("ящик настроек есть", 'id="settings"' in страница, True)
    check("и открывается одной кнопкой", 'id="gearBtn"' in страница, True)
    for настройка in ("camUrl", "aimX", "aimMirror", "aimSave"):
        внутри = страница.split('id="settings"')[1].split("</div>\n\n<script")[0]
        check(f"«{настройка}» переехала в настройки", настройка in внутри, True)

    # --- клавиатура ------------------------------------------------------
    # Пульт открывают и с ноутбука, а мышью виртуальный джойстик — это одна
    # рука на одну ось: боком и разворотом сразу уже не поедешь.
    check("клавишами можно ехать", "const КЛАВИШИ" in страница, True)
    for клавиша in ("KeyW", "KeyS", "KeyA", "KeyD", "KeyQ", "KeyE",
                    "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"):
        check(f"{клавиша} назначена", клавиша in страница, True)

    # Два источника на одну команду — это робот, едущий в среднее
    # направление. Ровно ту беду мы только что чинили у самого робота;
    # повторять её в браузере незачем.
    check("пока палец на джойстике, клавиши молчат",
          "if (джойстикЗанят()) return;" in страница, True)
    # Ушли из вкладки с зажатой клавишей — keyup не придёт НИКОГДА, и робот
    # уедет. Это не мелочь: он поедет и будет ехать.
    check("уход из вкладки отпускает клавиши",
          "window.addEventListener('blur'" in страница, True)
    # Зажатый W после стопа тронул бы робота на следующем же круге.
    check("аварийный стоп отпускает и клавиши",
          страница.count("зажаты.clear()") >= 2, True)
    # По диагонали ход нормируется по кругу: иначе W+A дают предел в полтора
    # раза, а предел на то и предел.
    check("диагональ не быстрее предела", "Math.hypot(x, y)" in страница, True)
    # В поле ввода адреса камеры буквы должны набираться, а не ехать.
    check("в полях ввода клавиши не едут",
          "matches('input, textarea')" in страница, True)


def main() -> int:
    for test in (test_rules, test_numbers, test_when, test_timers,
                 test_alarms, test_survives_restart, test_alarm_rules,
                 test_weather, test_notes, test_repair, test_looped, test_made_up, test_speakable, test_people, test_notes_about_people, test_meeting, test_auto_meeting, test_ascii_out, test_wake_word, test_not_for_me, test_remote_voice,
                 test_unsure_does_not_drive,
                 test_odometry, test_motion_queue, test_route,
                 test_порожек_не_обрыв, test_одометрия_замолчала,
                 test_слежка_упреждает, test_карта_помнит_за_спиной,
                 test_глаза_и_пеленг_не_одно, test_следование_видит_пол,
                 test_кто_крутит_колёса, test_мёртвая_рука,
                 test_no_broken_promise, test_chain, test_stop_stops_everything, test_instant_ignores_stale, test_sentence_cap, test_silence_when_not_mine, test_no_narration,
                 test_one_voice,
                 test_slicing, test_stop_while_thinking,
                 test_wake_stream, test_sound_cards, test_speech_streams,
                 test_turn_breakdown, test_turn_end, test_barge_in,
                 test_plane, test_vision_track, test_follow_with_camera,
                 test_follow_speed, test_range_by_feet,
                 test_pc_url, test_hidden,
                 test_music_queue, test_music_volume, test_noisy_ear,
                 test_counting, test_rules_reach_tools, test_ws_proxy,
                 test_degraded,
                 test_duck,
                 test_tls,
                 test_навыки, test_навык_целиком, test_падение,
                 test_жесты, test_жесты_подняты_в_запуске, test_вещи,
                 test_наклон_меряет_свой_шум, test_цепочка_насквозь,
                 test_поток_связи_не_заклинить, test_выключатели,
                 test_дневник, test_следование_не_ждёт_на_речи,
                 test_кровать_сбоку_не_мешает,
                 test_камера_ведёт_дальномер_меряет,
                 test_расстояние_по_росту,
                 test_планировщик_объезжает,
                 test_планировщик_считает_ту_дугу_по_которой_поедет,
                 test_застряли_и_молчим,
                 test_сделано_пока_колёса_едут,
                 test_позвали_по_имени_молчать_нельзя,
                 test_детектор_не_отбирает_порт,
                 test_карта_на_пульте, test_пульт_не_быстрее_тормозов,
                 test_pult_and_server_agree,
                 test_thinkless, test_thinkless_habit,
                 test_smart, test_prompt_prefix, test_endpoints, test_brain_money,
                 test_history,
                 test_names, test_dialogue, test_camera, test_vision, test_camera_stream, test_shell_ascii, test_tof, test_fusion, test_tof_guard, test_reflex, test_follow, test_mapping, test_tof_in_pult, test_depth_to_eyes,
                 test_look_rule):
        test()
        print("   ...")
    if FAILED:
        print(f"\nРАЗОШЛОСЬ: {len(FAILED)}")
        for item in FAILED:
            print(f"  ✗ {item}")
        return 1
    print("\nВсё сошлось.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
